			panel.add(itemIcon(r.getIconItem(), r.getLabel(), 20), BorderLayout.WEST);
			panel.add(smallLabel(r.getShownLabel(), Texts.isQuiet(r) ? Theme.TEXT_MUTED : Color.WHITE), BorderLayout.CENTER);
