		JPanel right = new JPanel(new BorderLayout(6, 0));
		clear(right);
		boolean have = r.isComplete();
		right.add(smallLabel(have ? Texts.haveText(r) : gotOfExpected(r),
			Texts.isQuiet(r) ? Theme.TEXT_MUTED : Color.WHITE), BorderLayout.CENTER);
