		JLabel shown = smallLabel(value, valueColor);
		right(shown);
		shown.setVerticalAlignment(SwingConstants.TOP);
		row.add(shown, BorderLayout.CENTER);
		for (JComponent c : new JComponent[]{row, name, shown})
		{
			c.setToolTipText(tip);
