package com.expecteddrops.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;
import net.runelite.client.ui.ColorScheme;

/**
 * The dry-to-spooned scale with a dot where you are: five coloured bands in the Luck gauge view, or
 * (in lists, where the scale repeats on every row) one neutral track with a tick at the middle.
 * The dot's place and the verdict word carry the meaning, the colours only echo it.
 */
class LuckStrip extends JComponent
{
	static final double[] BANDS = {0, 0.1, 0.35, 0.65, 0.9, 1};
	private static final Color TRACK = new Color(72, 72, 72);
	private static final Color MIDDLE = new Color(120, 120, 120);
	private double luck = Double.NaN;
	private boolean bands = true;

	LuckStrip()
	{
		setPreferredSize(new Dimension(80, 14));
		setOpaque(false);
	}

	/** False for the neutral track used in lists. */
	void setBands(boolean bands)
	{
		this.bands = bands;
		repaint();
	}

	void setLuck(double luck)
	{
		this.luck = luck;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth() - 8;
		int y = getHeight() / 2;
		if (!bands)
		{
			g.setColor(TRACK);
			g.fillRect(4, y - 1, w, 2);
			g.setColor(MIDDLE);
			g.fillRect(4 + w / 2, y - 4, 1, 8);
		}
		for (int i = 0; bands && i < BANDS.length - 1; i++)
		{
			double mid = (BANDS[i] + BANDS[i + 1]) / 2;
			g.setColor(Palette.blend(Palette.luck(mid), ColorScheme.DARKER_GRAY_COLOR, 0.35));
			int x0 = 4 + (int) Math.round(BANDS[i] * w);
			int x1 = 4 + (int) Math.round(BANDS[i + 1] * w);
			g.fillRect(x0, y - 2, x1 - x0, 4);
		}
		if (!Double.isNaN(luck))
		{
			int x = 4 + (int) Math.round(luck * w);
			g.setColor(Palette.luck(luck).brighter());
			g.fillOval(x - 4, y - 4, 9, 9);
			g.setColor(Color.WHITE);
			g.drawOval(x - 4, y - 4, 9, 9);
		}
		g.dispose();
	}
}

package com.expecteddrops.ui;

import com.onrate.engine.tracking.HistoryPoint;
import java.util.ArrayList;
import java.util.List;

/**
 * Which part of the luck history the graph draws. Every point is the whole account's luck on one day, so a window
 * only zooms in on the same line; it is never the luck of those days alone. Pure: today is passed in.
 */
final class LuckWindow
{
	private LuckWindow()
	{
	}

	/** First day of a window of {@code days} calendar days that ends on {@code today}. */
	static long start(long today, int days)
	{
		return today - days + 1;
	}

	/** How many calendar days the history spans, first to last point; 0 without points. */
	static long span(List<HistoryPoint> history)
	{
		if (history == null || history.isEmpty())
		{
			return 0;
		}
		return history.get(history.size() - 1).getDay() - history.get(0).getDay() + 1;
	}

	/**
	 * The points to draw for the days {@code from} to {@code to}: the last point before {@code from} first (so the line
	 * starts where it stood and stays flat), then the points inside the window. Points after {@code to} are left out.
	 * {@code history} is oldest first, as saved.
	 */
	static List<HistoryPoint> select(List<HistoryPoint> history, long from, long to)
	{
		List<HistoryPoint> out = new ArrayList<>();
		if (history == null)
		{
			return out;
		}
		HistoryPoint before = null;
		for (HistoryPoint p : history)
		{
			if (p.getDay() < from)
			{
				before = p;
			}
			else if (p.getDay() <= to)
			{
				out.add(p);
			}
		}
		if (before != null)
		{
			out.add(0, before);
		}
		return out;
	}

	/** How many of the selected points lie inside the window (the first one is a carry-in when it is before {@code from}). */
	static int inside(List<HistoryPoint> selected, long from)
	{
		int n = 0;
		for (HistoryPoint p : selected)
		{
			if (p.getDay() >= from)
			{
				n++;
			}
		}
		return n;
	}
}

package com.expecteddrops.ui;

import java.awt.Color;
import net.runelite.client.ui.ColorScheme;

/**
 * Luck colours: red (dry) to yellow to green (spooned), or orange to grey to blue for
 * colour-blind players.
 */
public final class Palette
{
	static final Color BAD = new Color(170, 40, 30);
	static final Color MID = new Color(170, 150, 20);
	static final Color GOOD = new Color(46, 160, 67);

	static final Color CB_BAD = new Color(220, 120, 20);
	static final Color CB_MID = new Color(140, 140, 140);
	static final Color CB_GOOD = new Color(40, 110, 200);

	private static volatile boolean colourBlind;

	private Palette()
	{
	}

	private static volatile Color customBad;
	private static volatile Color customMid;
	/** True while the Custom scheme is picked: its colours are the player's own, so text on them is lifted. */
	private static volatile boolean customScheme;


	/** WCAG contrast ratio between two colours (1 to 21). */
	static double contrast(Color a, Color b)
	{
		double la = luminance(a);
		double lb = luminance(b);
		return (Math.max(la, lb) + 0.05) / (Math.min(la, lb) + 0.05);
	}

	private static double luminance(Color c)
	{
		return 0.2126 * linear(c.getRed()) + 0.7152 * linear(c.getGreen()) + 0.0722 * linear(c.getBlue());
	}

	private static double linear(int v)
	{
		double s = v / 255.0;
		return s <= 0.03928 ? s / 12.92 : Math.pow((s + 0.055) / 1.055, 2.4);
	}

	public static void setColourBlind(boolean on)
	{
		colourBlind = on;
	}

	/**
	 * Picks the colours for dry to spooned. The ready-made sets keep spooned green (the
	 * colour-blind one has its own blue); Custom takes the player's dry and on rate colours.
	 */
	public static void setScheme(LuckColours scheme, Color dry, Color onRate)
	{
		LuckColours s = scheme == null ? LuckColours.CLASSIC : scheme;
		colourBlind = s == LuckColours.COLOUR_BLIND;
		customScheme = s == LuckColours.CUSTOM;
		switch (s)
		{
			case PURPLE_AMBER:
				customBad = new Color(110, 60, 170);
				customMid = new Color(200, 150, 30);
				break;
			case PINK_GREY:
				customBad = new Color(210, 90, 140);
				customMid = new Color(140, 140, 140);
				break;
			case MONO:
				customBad = new Color(110, 110, 110);
				customMid = new Color(150, 150, 150);
				break;
			case CUSTOM:
				customBad = dry;
				customMid = onRate;
				break;
			default:
				customBad = null;
				customMid = null;
				break;
		}
	}

	/** Colour for a luck percentile 0..1 (grey when unknown). */
	public static Color luck(double luck)
	{
		if (Double.isNaN(luck))
		{
			return ColorScheme.MEDIUM_GRAY_COLOR;
		}
		Color bad = customBad != null ? customBad : colourBlind ? CB_BAD : BAD;
		Color mid = customMid != null ? customMid : colourBlind ? CB_MID : MID;
		Color good = colourBlind ? CB_GOOD : GOOD;
		if (luck < 0.5)
		{
			return blend(bad, mid, luck / 0.5);
		}
		return blend(mid, good, (luck - 0.5) / 0.5);
	}

	/**
	 * The verdict colour on a boss page: the dry and spooned bands (a third of players each) are
	 * toned down, so only very dry and very spooned get the full colour.
	 */
	static Color verdict(double luck)
	{
		Color c = luck(luck);
		boolean mild = !Double.isNaN(luck) && (luck >= 0.10 && luck < 0.35 || luck > 0.65 && luck <= 0.90);
		return mild ? blend(c, new Color(170, 170, 170), 0.3) : c;
	}

	/** The weakest text contrast (WCAG AA) the Custom scheme's text is lifted to. */
	static final double TEXT_CONTRAST = 4.5;

	/**
	 * A luck colour for text. The ready-made sets are returned as they are; a Custom colour is
	 * lifted towards white until it reads at {@link #TEXT_CONTRAST}:1 on the panel's lightest
	 * card, so a dark pick stays legible. Only text uses this: bars, rings and dots keep the
	 * exact colour the player chose.
	 */
	public static Color text(Color c)
	{
		if (!customScheme || c == null)
		{
			return c;
		}
		Color lifted = c;
		for (int i = 1; i <= 20 && contrast(lifted, Theme.SURFACE_RAISED) < TEXT_CONTRAST; i++)
		{
			lifted = blend(c, Color.WHITE, i / 20.0);
		}
		return lifted;
	}

	/** The "you have it" colour. */
	public static Color good()
	{
		return colourBlind ? CB_GOOD : GOOD;
	}

	static Color blend(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t));
	}

	/** A quiet background in the hue of a luck colour (the pill under a verdict). */
	static Color tint(Color c)
	{
		return blend(Theme.SURFACE, c, 0.2);
	}

	/** Text on a {@link #tint}: the luck colour, lifted a little so it stays readable. */
	static Color onTint(Color c)
	{
		return readable(text(blend(c, Color.WHITE, 0.22)), tint(c));
	}

	/** False draws text colours as before the contrast fix; only the pixel comparison with the original panel turns it off. */
	static volatile boolean readableText = true;

	/**
	 * Text in {@code fg} that can be read on {@code bg}: {@code fg} itself when it already has a 4.5:1 contrast,
	 * otherwise lifted toward white as little as needed. Text only: the luck colours themselves (bars, dots,
	 * graph lines) are not changed.
	 */
	static Color readable(Color fg, Color bg)
	{
		if (!readableText || contrast(fg, bg) >= MIN_TEXT_CONTRAST)
		{
			return fg;
		}
		for (int step = 1; step <= 100; step++)
		{
			Color c = blend(fg, Color.WHITE, step / 100.0);
			if (contrast(c, bg) >= MIN_TEXT_CONTRAST)
			{
				return c;
			}
		}
		return Color.WHITE;
	}

	static final double MIN_TEXT_CONTRAST = 4.5;

	/** Luck-coloured text on a list row or tile (the panel's {@link Theme#SURFACE}). */
	static Color onRow(Color c)
	{
		return readable(text(c), Theme.SURFACE);
	}

	static Color withAlpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}
}

package com.expecteddrops.ui;

import javax.swing.SwingUtilities;

import java.awt.BasicStroke;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.JPanel;
import net.runelite.client.ui.FontManager;

/**
 * A small on/off slider with the word "Pets": whether pets count in "Closest to green log". Quiet on
 * purpose, like {@link ViewChip}: the word is grey until it is on, and the knob sits left (off) or right (on).
 */
final class PetsSwitch extends JPanel
{
	private static final int HEIGHT = 22;
	private static final int TRACK_W = 22;
	private static final int TRACK_H = 12;
	private static final int GAP = 5;
	private static final int AFTER = 6;

	private final Consumer<Boolean> onChange;
	private boolean on;

	PetsSwitch(Consumer<Boolean> onChange)
	{
		this.onChange = onChange;
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setFont(FontManager.getRunescapeSmallFont());
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					toggle();
				}
			}
		});
		update();
	}

	boolean isOn()
	{
		return on;
	}

	void setOn(boolean on)
	{
		if (on != this.on)
		{
			this.on = on;
			update();
		}
	}

	private void toggle()
	{
		on = !on;
		update();
		onChange.accept(on);
	}

	private void update()
	{
		setToolTipText(on ? "Pets count in the time" : "Pets are left out of the time");
		if (getAccessibleContext() != null)
		{
			getAccessibleContext().setAccessibleName("Pets: " + (on ? "on" : "off"));
		}
		FontMetrics fm = getFontMetrics(getFont());
		// the trailing gap to the View button is part of the slider, so nothing shifts while it is hidden
		Dimension size = new Dimension(fm.stringWidth("Pets") + GAP + TRACK_W + 2 + AFTER, HEIGHT);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		revalidate();
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int h = getHeight();
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(on ? Theme.TEXT : Theme.TEXT_MUTED);
		g.drawString("Pets", 0, (h - fm.getHeight()) / 2 + fm.getAscent());
		int x = fm.stringWidth("Pets") + GAP;
		int y = (h - TRACK_H) / 2;
		g.setColor(on ? Theme.PROGRESS : Theme.TRACK);
		g.fillRoundRect(x, y, TRACK_W - 1, TRACK_H - 1, TRACK_H, TRACK_H);
		g.setColor(on ? Theme.PROGRESS.brighter() : Theme.OUTLINE);
		g.setStroke(new BasicStroke(1f));
		g.drawRoundRect(x, y, TRACK_W - 1, TRACK_H - 1, TRACK_H, TRACK_H);
		int knob = TRACK_H - 4;
		g.setColor(on ? Theme.TEXT : Theme.QUIET_MARK);
		g.fillOval(on ? x + TRACK_W - knob - 3 : x + 2, y + 2, knob, knob);
		g.dispose();
	}
}

package com.expecteddrops.ui;

import java.awt.event.MouseAdapter;
import java.awt.event.MouseMotionAdapter;

import com.onrate.engine.tracking.RaidInsights;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.event.MouseEvent;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.JComponent;
import javax.swing.ToolTipManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Your last raids of one mode, one dot each: your points (or that raid's purple chance), an
 * white line for the average of the last {@link #AVERAGE} raids, and a purple diamond for a raid
 * that brought a unique.
 */
class RaidPointsGraph extends JComponent
{
	/** How many raids the graph shows, newest last. */
	static final int SHOWN = 40;
	/** The average line averages this many raids. */
	static final int AVERAGE = 10;
	private static final int HEIGHT = 110;
	private static final int PAD_LEFT = 30;
	private static final int PAD_RIGHT = 6;
	private static final int PAD_TOP = 6;
	private static final int PAD_BOTTOM = 14;
	private static final Color DOT = new Color(150, 150, 150);
	private static final DateTimeFormatter DATE = DateTimeFormatter.ofPattern("d MMM yyyy", Locale.ENGLISH);

	private List<RaidInsights.Point> points = new ArrayList<>();
	private boolean chance;
	private int hover = -1;

	RaidPointsGraph()
	{
		setPreferredSize(new Dimension(100, HEIGHT));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, HEIGHT));
		setAlignmentX(LEFT_ALIGNMENT);
		ToolTipManager.sharedInstance().registerComponent(this);
		addMouseMotionListener(new MouseMotionAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				setHover(nearest(e.getX()));
			}
		});
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseExited(MouseEvent e)
			{
				setHover(-1);
			}
		});
	}

	@Override
	public javax.accessibility.AccessibleContext getAccessibleContext()
	{
		if (accessibleContext == null)
		{
			accessibleContext = new AccessibleJComponent()
			{
			};
			accessibleContext.setAccessibleName(accessibleName(chance));
		}
		return accessibleContext;
	}

	/** The screen-reader name for the graph: it follows the mode (points or purple chance). */
	static String accessibleName(boolean chance)
	{
		return (chance ? "Your purple chance per raid" : "Your points per raid") + " over your last raids, all modes together";
	}

	/**
	 * The raids to draw (only those with a value are kept, the last {@link #SHOWN}), as points or as
	 * purple chance.
	 */
	void setPoints(List<RaidInsights.Point> all, boolean chance)
	{
		this.chance = chance;
		getAccessibleContext().setAccessibleName(accessibleName(chance));
		List<RaidInsights.Point> kept = new ArrayList<>();
		for (RaidInsights.Point p : all)
		{
			if (!Double.isNaN(value(p)) && value(p) > 0)
			{
				kept.add(p);
			}
		}
		points = kept.subList(Math.max(0, kept.size() - SHOWN), kept.size());
		hover = -1;
		repaint();
	}

	/** How many raids are drawn. */
	int shown()
	{
		return points.size();
	}

	private double value(RaidInsights.Point p)
	{
		return chance ? p.getChance() : p.getPoints();
	}

	/** Average of the raid at {@code i} and the ones before it, up to {@link #AVERAGE}. */
	double average(int i)
	{
		double sum = 0;
		int n = 0;
		for (int j = Math.max(0, i - AVERAGE + 1); j <= i; j++)
		{
			sum += value(points.get(j));
			n++;
		}
		return n == 0 ? Double.NaN : sum / n;
	}

	private void setHover(int index)
	{
		if (index != hover)
		{
			hover = index;
			repaint();
		}
	}

	private int nearest(int x)
	{
		int best = -1;
		for (int i = 0; i < points.size(); i++)
		{
			if (best < 0 || Math.abs(xFor(i) - x) < Math.abs(xFor(best) - x))
			{
				best = i;
			}
		}
		return best;
	}

	private int plotWidth()
	{
		return Math.max(1, getWidth() - PAD_LEFT - PAD_RIGHT);
	}

	private int plotHeight()
	{
		return Math.max(1, getHeight() - PAD_TOP - PAD_BOTTOM);
	}

	private int xFor(int i)
	{
		return points.size() <= 1 ? PAD_LEFT + plotWidth() / 2 : PAD_LEFT + (int) Math.round(i * (double) plotWidth() / (points.size() - 1));
	}

	/** Top of the scale: a round step above the highest raid. */
	private double top()
	{
		double max = 0;
		for (RaidInsights.Point p : points)
		{
			max = Math.max(max, value(p));
		}
		double step = step();
		return Math.max(step, Math.ceil(max / step) * step);
	}

	/** The step between the scale's lines: 10k points or 2% purple chance. */
	private double step()
	{
		return chance ? 0.02 : 10_000;
	}

	private int yFor(double v, double top)
	{
		return PAD_TOP + (int) Math.round((1 - v / top) * plotHeight());
	}

	private String label(double v)
	{
		return chance ? String.format(Locale.ROOT, "%.0f%%", v * 100) : String.format(Locale.ROOT, "%.0fk", v / 1000);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(ColorScheme.DARKER_GRAY_COLOR);
		g.fillRect(0, 0, getWidth(), getHeight());
		if (points.isEmpty())
		{
			g.dispose();
			return;
		}
		double top = top();
		double step = step();
		// the scale: a faint line and its label every step, at most four
		int lines = (int) Math.round(top / step);
		int every = Math.max(1, (int) Math.ceil(lines / 4.0));
		g.setFont(FontManager.getRunescapeSmallFont());
		for (int k = every; k <= lines; k += every)
		{
			int y = yFor(k * step, top);
			g.setColor(Theme.DIVIDER);
			g.drawLine(PAD_LEFT, y, PAD_LEFT + plotWidth(), y);
			g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
			g.drawString(label(k * step), 2, y + 4);
		}
		g.setColor(ColorScheme.LIGHT_GRAY_COLOR);
		int baseline = getHeight() - 2;
		g.drawString("older", PAD_LEFT, baseline);
		String newest = "newest";
		g.drawString(newest, PAD_LEFT + plotWidth() - g.getFontMetrics().stringWidth(newest), baseline);

		if (hover >= 0 && hover < points.size())
		{
			g.setColor(new Color(255, 255, 255, 70));
			g.drawLine(xFor(hover), PAD_TOP, xFor(hover), PAD_TOP + plotHeight());
		}
		for (int i = 0; i < points.size(); i++)
		{
			RaidInsights.Point p = points.get(i);
			int x = xFor(i);
			int y = yFor(value(p), top);
			if (p.isPurple())
			{
				g.setColor(Theme.RAID_PURPLE);
				g.fillPolygon(new Polygon(new int[]{x, x + 4, x, x - 4}, new int[]{y - 4, y, y + 4, y}, 4));
			}
			else
			{
				g.setColor(i == hover ? Color.WHITE : DOT);
				g.fillOval(x - 2, y - 2, 5, 5);
			}
		}
		g.setColor(Theme.TEXT);
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		for (int i = 1; i < points.size(); i++)
		{
			g.drawLine(xFor(i - 1), yFor(average(i - 1), top), xFor(i), yFor(average(i), top));
		}
		g.dispose();
	}

	@Override
	public String getToolTipText(MouseEvent event)
	{
		if (points.isEmpty())
		{
			return null;
		}
		RaidInsights.Point p = points.get(nearest(event.getX()));
		long saved = p.getSavedMillis();
		String date = saved > 0 ? Instant.ofEpochMilli(saved).atZone(ZoneId.systemDefault()).format(DATE) : "";
		// a Tombs raid from Raid Data Tracker has no reliable raid number, only its date
		Tip tip = new Tip(p.getRaid().getKc() > 0
			? String.format(Locale.ROOT, "Raid %,d", p.getRaid().getKc()) + (date.isEmpty() ? "" : " · " + date)
			: date.isEmpty() ? "A raid" : date);
		if (p.getRaid().getPart() != null)
		{
			tip.row("Mode", p.getRaid().getPart());
		}
		if (p.getPoints() > 0)
		{
			tip.row("Your points", Texts.formatPoints(p.getPoints()));
		}
		if (!Double.isNaN(p.getChance()))
		{
			tip.row("Purple chance", String.format(Locale.ROOT, "%.1f%%", p.getChance() * 100));
		}
		if (p.getRaid().getTeamSize() > 0)
		{
			tip.row("Team", ExpectedDropsPanel.teamWord(p.getRaid().getTeamSize()));
		}
		if (p.getRaid().getRaidLevel() >= 0)
		{
			tip.row("Raid level", String.valueOf(p.getRaid().getRaidLevel()));
		}
		if (p.isPurple())
		{
			tip.row(p.getUniques().size() == 1 ? "Unique" : "Uniques", String.join(", ", p.getUniques()), Theme.RAID_PURPLE);
		}
		return tip.small();
	}
}

package com.expecteddrops.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.BasicStroke;
import javax.swing.JComponent;

/**
 * A thin bar: the fill is what you received, the white line is what you should have by now.
 */
class TargetBar extends JComponent
{
	private static final Color TRACK = Theme.TRACK;
	private double fill;
	private double marker = -1;
	private Color color = Color.GRAY;
	private boolean quiet;

	TargetBar()
	{
		setPreferredSize(new Dimension(100, 10));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 10));
		setOpaque(false);
	}

	/** A quiet bar (nothing expected yet) has a slimmer track and a grey tick instead of a white one. */
	void setQuiet(boolean quiet)
	{
		this.quiet = quiet;
		int height = quiet ? 8 : 10;
		setPreferredSize(new Dimension(100, height));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		repaint();
	}

	/** Fractions of the bar width; marker below 0 hides the line. */
	void set(double fill, double marker, Color color)
	{
		this.fill = Math.max(0, Math.min(1, fill));
		this.marker = marker;
		this.color = color;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		int w = getWidth();
		int h = getHeight();
		g.setColor(TRACK);
		g.fillRect(0, 2, w, h - 4);
		g.setColor(color);
		g.fillRect(0, 2, (int) Math.round(w * fill), h - 4);
		if (marker >= 0)
		{
			int x = (int) Math.round(Math.min(1, marker) * (w - 2));
			g.setColor(quiet ? Theme.QUIET_MARK : Color.WHITE);
			g.setStroke(new BasicStroke(2));
			g.drawLine(x + 1, 0, x + 1, h);
		}
		g.dispose();
	}
}

