/**
 * The panel's words and numbers: small functions that turn stats into short text. Kept apart
 * from the Swing code so they are easy to read and test.
 */
final class Texts
{
	private Texts()
	{
	}

	/**
	 * Trip card: how long since the last completion, and when the trip ends by itself. {@code unitOne} is
	 * the boss's word for one ("kill", "raid", "chest"...), {@code limitMinutes} the idle limit.
	 */
	static String tripIdle(long idleMinutes, long limitMinutes, String unitOne)
	{
		if (idleMinutes < 2)
		{
			return "Last " + unitOne + " just now";
		}
		return limitMinutes > idleMinutes
			? String.format(Locale.ROOT, "Idle %d min \u00b7 ends in %d min", idleMinutes, limitMinutes - idleMinutes)
			: String.format(Locale.ROOT, "Idle %d min", idleMinutes);
	}

	/** Trip card: tooltip of the "New trip" button, with the boss's word for one ("kill", "raid", "chest"...). */
	static String tripResetTip(String unitOne)
	{
		return "The next " + unitOne + " starts a new trip. A trip also ends after 30 minutes without a " + unitOne + " "
			+ "(2 hours for raids, the Inferno and the Fight Caves).";
	}

	/**
	 * The collection log line: what is left to open, never what is done. {@code killedBosses} counts bosses
	 * (not pages) you killed whose page is not loaded yet; {@code done} of {@code total} log pages are loaded.
	 * Null when nothing is left, because the line is then hidden.
	 */
	static String setupHeader(int killedBosses, int done, int total)
	{
		if (killedBosses > 0)
		{
			return String.format(Locale.ROOT, "%,d boss%s you killed not loaded yet", killedBosses, killedBosses == 1 ? "" : "es");
		}
		int left = total - done;
		if (total < 1 || left < 1)
		{
			return null;
		}
		if (done <= 0)
		{
			return String.format(Locale.ROOT, "Collection log: 0 of %,d page%s opened", total, total == 1 ? "" : "s");
		}
		return String.format(Locale.ROOT, "Collection log: %,d page%s not opened yet", left, left == 1 ? "" : "s");
	}

	/** Boss page: a log page of this boss was opened but could not be read. */
	static final String LOG_PAGE_UNREADABLE = "Log page opened but not readable. The game may have changed; please report it.";

	static final String LOG_PAGE_UNREADABLE_TIP = "On Rate could not read this page, so your numbers are unchanged. "
		+ "A missing read does not mean zero drops. To clear this boss on purpose, use \"Reset this boss\u2026\". "
		+ "You can report it on On Rate's GitHub page.";

	static final String SETUP_UNREADABLE_TIP = "On Rate could not read it, so your numbers are unchanged. "
		+ "A missing read does not mean zero drops. You can report it on On Rate's GitHub page.";

	/**
	 * Boss page hover of a raid: how many raids of a mode used their own points instead of the setting.
	 * For Tombs of Amascut the game sends the exact points; only the raids where they didn't come
	 * ({@code estimated} of the {@code measured}) used On Rate's estimate.
	 */
	static String raidPointsLine(String family, String part, int measured, int estimated)
	{
		String raids = String.format(Locale.ROOT, "%,d %s raid%s", measured, part, measured == 1 ? "" : "s");
		if ("fractured".equals(family))
		{
			return raids + " used your share of the damage (On Rate's estimate) instead of the setting.";
		}
		if (!"toa".equals(family) || estimated <= 0)
		{
			return raids + " used your points instead of the setting.";
		}
		if (estimated >= measured)
		{
			return raids + " used your estimated points instead of the setting: the game's exact points didn't come, "
				+ "so On Rate worked them out from your hits.";
		}
		return raids + String.format(Locale.ROOT, " used your points instead of the setting: the exact points the game "
			+ "sent, or On Rate's estimate for the %,d where they didn't come.", estimated);
	}

	/**
	 * Boss page note of a raid: after a mode's chance for raids without points, where it came from when
	 * it is your own average instead of the setting. Older raids may have gone differently, so it says so.
	 */
	static String learnedNote(String raid, int raids)
	{
		if (raids <= 0)
		{
			return "";
		}
		boolean team = raid != null && (raid.startsWith("tob") || "fractured".equals(raid));
		return String.format(Locale.ROOT, " (%s over your last %d raids; you may have raided differently before)",
			team ? "your usual team" : "your average", raids);
	}

	/**
	 * A raid item hover row for one of your setups: "1 in 1,450 raids · 1 per ~790 h", without the hour
	 * part when {@code perHour} is NaN (not enough timed raids).
	 */
	static String itemSetupText(double perRaid, double perHour)
	{
		String raid = "1 in " + String.format(Locale.ROOT, "%,d", Math.round(1 / perRaid)) + " raids";
		if (Double.isNaN(perHour) || perHour <= 0)
		{
			return raid;
		}
		double hours = 1 / perHour;
		String h = hours < 10 ? String.format(Locale.ROOT, "%.1f", hours)
			: String.format(Locale.ROOT, "%,d", Math.round(hours));
		return raid + " · 1 per ~" + h + " h";
	}

	/** A forecast table cell: raids ("1,236"), or a dash when the items can't all drop at these chances. */
	static String raidsText(long raids)
	{
		return raids < 0 ? "—" : String.format(Locale.ROOT, "%,d", raids);
	}

	/** The same in hours at your average raid time ("~741 h"); a dash when unknown. */
	static String hoursText(long raids, long avgMillis)
	{
		if (raids < 0 || avgMillis <= 0)
		{
			return "—";
		}
		return String.format(Locale.ROOT, "~%,d h", Math.round(raids * avgMillis / 3_600_000.0));
	}

	/** A chance as "1 in 805"; a dash when it can't happen. */
	static String oneIn(double chance)
	{
		return !(chance > 0) ? "—" : String.format(Locale.ROOT, "1 in %,d", Math.round(1 / chance));
	}

	/** What's missing from a raid's log page: "4 uniques + pet", "1 unique", "Pet only". */
	static String missingText(int uniques, boolean pet)
	{
		if (uniques == 0)
		{
			return pet ? "Pet only" : "Nothing";
		}
		return uniques + (uniques == 1 ? " unique" : " uniques") + (pet ? " + pet" : "");
	}

	/**
	 * A Time page row's "where the time comes from" line, as the engine words it, with "wiki rate" said
	 * as the wiki's kill speed: next to drop chances, "rate" reads as the drop rate. The engine's own
	 * text stays as it is (the parity tests compare it with the original).
	 */
	static String timeBasis(String basis)
	{
		if (basis == null)
		{
			return null;
		}
		return basis.replace("Wiki rate:", "Wiki kill speed:").replace("else the wiki rate)", "else the wiki's kill speed)");
	}

	/** Account page before any RuneLite profile is loaded. */
	static final String LOG_IN_FIRST = "Log in to see your account.";

	static final String LOADING_ACCOUNT = "Loading your account…";

	/**
	 * ProfileStore#load failed: nothing is saved until a load works, so the saved data stays as it was.
	 * The next login (or profile change) tries again.
	 */
	static final String LOAD_FAILED = "On Rate couldn't load this account's saved data. It saves nothing until it loads, "
		+ "so your saved data stays as it was. Log out and in again to try again. If it keeps happening, please tell us on Discord.";

	/** The account page's note while no account is loaded. */
	static String profileNote(ExpectedDropsPanel.ProfileState state)
	{
		switch (state)
		{
			case LOADING:
				return LOADING_ACCOUNT;
			case FAILED:
				return LOAD_FAILED;
			default:
				return LOG_IN_FIRST;
		}
	}

	/** The big word on the account page while no account is loaded. */
	static String profileVerdict(ExpectedDropsPanel.ProfileState state)
	{
		switch (state)
		{
			case LOADING:
				return "Loading";
			case FAILED:
				return "Couldn't load";
			default:
				return "Not logged in";
		}
	}

	/**
	 * Setup area: RuneLite's Loot Tracker plugin is off. At every boss with Loot Tracker names (Tracker#onLoot)
	 * all new uniques come only from it, first copies included; only the bosses without (The Gauntlet, Obor,
	 * Bryophyta, Jad, Zuk) get first copies from the collection log message. Kill counts and pets come from chat.
	 */
	static final String LOOT_TRACKER_OFF = "Loot Tracker is off, so new drops at most bosses won't be recorded.";

	static final String LOOT_TRACKER_OFF_TIP = "On Rate reads drops at most bosses from RuneLite's Loot Tracker plugin, "
		+ "first copies included. Kill counts and pets still count from chat. The Gauntlet, Obor, Bryophyta, Jad and Zuk "
		+ "aren't affected: their new items come from the collection log message. Turn the Loot Tracker on in the "
		+ "Configuration panel and this note goes away.";

	/**
	 * The "Reset this boss" question: what is gone for good, and what opening the collection log page
	 * brings back. HTML, for a dialog.
	 */
	static String resetConfirm(String bossName)
	{
		return "<html><body style='width: 260px'>Forget everything On Rate tracked for " + bossName + "?"
			+ "<br><br><b>Gone for good.</b> Syncing the collection log can't bring these back: History, "
			+ "raid points, counted team sizes, dry streaks, fastest and longest gaps, drops you added by hand, "
			+ "Doom levels, Colosseum claims, items you left out and which milestone messages were sent."
			+ "<br><br><b>Can be synced again.</b> The kill count and item counts come back when you open "
			+ "its collection log page.</body></html>";
	}

	/** The buttons of the reset question. Cancel, the last one, is the default. */
	static final String[] RESET_OPTIONS = {"Reset", "Cancel"};

	/**
	 * The one line in the setup area when log pages were opened but could not be read, or null when
	 * there is nothing to say (the normal case).
	 */
	static String setupProblem(List<String> pages, boolean headerUnreadable)
	{
		if (!headerUnreadable && pages.isEmpty())
		{
			return null;
		}
		String which = !headerUnreadable && pages.size() == 1 ? "The \"" + pages.get(0) + "\" log page"
			: "A collection log page";
		return which + " was opened but could not be read. The game may have changed; please report it.";
	}

	/** "today", "yesterday", "3 days ago" for a time in milliseconds. */
	static String daysAgo(long time, long now)
	{
		if (time <= 0)
		{
			// added by hand from memory: the kill count is known, the date isn't
			return "date unknown";
		}
		long days = ChronoUnit.DAYS.between(
			Instant.ofEpochMilli(time).atZone(ZoneId.systemDefault()).toLocalDate(),
			Instant.ofEpochMilli(now).atZone(ZoneId.systemDefault()).toLocalDate());
		return days <= 0 ? "today" : days == 1 ? "yesterday" : String.format(Locale.ROOT, "%,d days ago", days);
	}

	/**
	 * How lucky one drop was: "quicker than 99.9% of players (1 in 1,000)" when it came before the
	 * drop rate says, "slower than 94% of players" when after, "" when the wait isn't known exactly.
	 * The "1 in N" is how many players are as quick (or as slow) as you; it is left out when it is
	 * under 1 in 10.
	 */
	static String dropLuck(KillEntry.DropEntry d)
	{
		if (d.getMultiple() == null || d.isAtLeast())
		{
			return "";
		}
		// older versions saved a multiple rounded to two decimals: 0.00 is only known to be under 0.005
		return waitLuck(d.getMultiple());
	}

	/** {@link #dropLuck} for a wait of {@code multiple} times the drop rate (also a wait still going on). */
	static String waitLuck(double multiple)
	{
		boolean floor = multiple == 0;
		double m = floor ? 0.005 : multiple;
		if (m == 1)
		{
			return "right on the drop rate";
		}
		boolean quick = m < 1;
		// players slower than you (quick) or as slow as you (slow), and as quick as you or quicker
		double behind = Math.exp(-m);
		double oneIn = quick ? 1 / (1 - behind) : 1 / behind;
		String text = (quick ? "quicker than " : "slower than ") + shareText(quick ? behind : 1 - behind) + " of players";
		if (oneIn >= 10)
		{
			text += " (1 in " + (floor ? "200+" : oneInText(oneIn)) + ")";
		}
		return text;
	}

	/** {@link #dropLuck} for a list row: "1 in 34 players this quick", "1 in 30 players wait this long". */
	static String dropLuckShort(KillEntry.DropEntry d)
	{
		return d.getMultiple() == null || d.isAtLeast() ? "" : waitLuckShort(d.getMultiple(), false);
	}

	/**
	 * Short luck wording for a list row. {@code ongoing}: the wait isn't over yet ("1 in 16 still
	 * waiting"). Under 1 in 10 it falls back to "quicker/slower than 74%".
	 */
	static String waitLuckShort(double multiple, boolean ongoing)
	{
		boolean floor = multiple == 0;
		double m = floor ? 0.005 : multiple;
		if (m == 1)
		{
			return "right on the drop rate";
		}
		boolean quick = m < 1;
		double behind = Math.exp(-m);
		double oneIn = quick ? 1 / (1 - behind) : 1 / behind;
		if (oneIn >= 10)
		{
			String n = floor ? "200+" : oneInText(oneIn);
			return quick ? "1 in " + n + " players this quick"
				: ongoing ? "1 in " + n + " still waiting" : "1 in " + n + " players wait this long";
		}
		return (quick ? "quicker than " : "slower than ") + shareText(quick ? behind : 1 - behind);
	}

	private static String shareText(double share)
	{
		return share >= 0.9995 ? ">99.9%" : share >= 0.995 ? String.format(Locale.ROOT, "%.1f%%", share * 100)
			: share < 0.005 ? "<1%" : String.format(Locale.ROOT, "%.0f%%", share * 100);
	}

	/** 3 significant digits: 25, 1,030, 41,200. */
	private static String oneInText(double n)
	{
		double scale = Math.pow(10, Math.max(0, Math.floor(Math.log10(n)) - 2));
		return String.format(Locale.ROOT, "%,.0f", Math.round(n / scale) * scale);
	}

	/** "after 7 kills (0.1x)", "your first one", or "" when the gap is unknown. */
	static String afterText(KillEntry.DropEntry d, String unit)
	{
		if (d.isFirst())
		{
			return "your first one";
		}
		if (d.getSince() == null)
		{
			return d.isEntered() ? "added by you" : "";
		}
		if (d.isAtLeast())
		{
			return String.format(Locale.ROOT, "after %,d+ %ss", d.getSince(), unit);
		}
		return String.format(Locale.ROOT, "after %,d %s%s", d.getSince(), unit, d.getSince() == 1 ? "" : "s")
			+ (d.getMultiple() == null ? "" : " (" + formatMultiple(d.getMultiple()) + ")");
	}

	/**
	 * "Vorkath 437", or for a page with several bosses the one that dropped it with its own
	 * kill count ("Callisto 96"); raid modes other than Normal get a short tag ("CoX CM 12").
	 */
	static String whereText(BossDefinition boss, String bossName, KillEntry kill)
	{
		if (boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null)
		{
			if (boss.getRaid() == null)
			{
				return String.format(Locale.ROOT, "%s %,d", kill.getPart(), kill.getPartKc());
			}
			if (!"Normal".equals(kill.getPart()))
			{
				return String.format(Locale.ROOT, "%s %s %,d", bossName, shortMode(kill.getPart()), kill.getPartKc());
			}
			return String.format(Locale.ROOT, "%s %,d", bossName, kill.getPartKc());
		}
		return String.format(Locale.ROOT, "%s %,d", bossName, kill.getKc());
	}

	/**
	 * Where a saved kill happened, for hover rows: the page's boss, or for a page with several
	 * bosses the one it was ("Corrupted Gauntlet", "Artio"), or a raid with its mode ("Tombs of Amascut, Expert Mode").
	 */
	static String whereName(BossDefinition boss, String bossName, KillEntry kill)
	{
		if (boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null)
		{
			if (boss.getRaid() == null)
			{
				return kill.getPart();
			}
			// a raid with one mode needs no "Normal"
			return boss.getParts().size() == 1 ? bossName : bossName + ", " + kill.getPart();
		}
		return bossName;
	}

	/** The kill count of a saved kill as a number: the mode's or boss's own on a page with several, else the page's. */
	static String killCount(BossDefinition boss, KillEntry kill)
	{
		boolean own = boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null;
		return String.format(Locale.ROOT, "%,d", own ? kill.getPartKc() : kill.getKc());
	}

	/**
	 * The kill count of a saved kill without the boss, for hover rows: "437", or with the mode or
	 * boss of a combined page and its own count ("Challenge Mode 12", "Artio 40").
	 */
	static String killValue(BossDefinition boss, KillEntry kill)
	{
		if (boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null)
		{
			return String.format(Locale.ROOT, "%s %,d", kill.getPart(), kill.getPartKc());
		}
		return String.format(Locale.ROOT, "%,d", kill.getKc());
	}

	/** {@link #killValue} with what is counted in front when there is no mode: "Raid 115", "Kill 437". */
	static String killText(BossDefinition boss, KillEntry kill)
	{
		boolean mode = boss != null && boss.hasParts() && kill.getPart() != null && kill.getPartKc() != null;
		return mode ? killValue(boss, kill)
			: capital(boss == null ? "kill" : Tracker.unitOne(boss)) + " " + killValue(boss, kill);
	}

	static String shortMode(String part)
	{
		switch (part)
		{
			case "Challenge Mode":
				return "CM";
			case "Hard Mode":
				return "HM";
			case "Entry Mode":
				return "Entry";
			case "Expert Mode":
				return "Expert";
			default:
				return part;
		}
	}

	static String formatPoints(int points)
	{
		return points >= 10_000 ? String.format(Locale.ROOT, "%.1fk", points / 1000.0) : String.format(Locale.ROOT, "%,d", points);
	}

	/** "Vorkath", "Vorkath and Zulrah", "Vorkath, Zulrah and Cerberus". */
	public static String joinAnd(List<String> names)
	{
		if (names.size() <= 1)
		{
			return String.join("", names);
		}
		return String.join(", ", names.subList(0, names.size() - 1)) + " and " + names.get(names.size() - 1);
	}

	static String lowerFirst(String text)
	{
		return text.isEmpty() ? text : Character.toLowerCase(text.charAt(0)) + text.substring(1);
	}

	/** "2.6×" since the last unique, "1.2×+" when the last one came before On Rate, "-" when unknown. */
	static String streakText(RowStats row)
	{
		double m = row.getStreakMultiple();
		if (Double.isNaN(m) || !row.isStreakExact() && row.getStreak() != null && row.getStreak() == 0)
		{
			// unknown, or the last one came before On Rate and nothing was killed since
			return "-";
		}
		return formatMultiple(m) + (row.isStreakExact() ? "" : "+");
	}

	/**
	 * Luck in plain words: "About 1 in 6 players is this dry (or drier)". Around the middle it
	 * just says you're about average.
	 */
	public static String plainLuck(double luck)
	{
		if (Double.isNaN(luck))
		{
			return null;
		}
		if (luck >= 0.4 && luck <= 0.6)
		{
			return "About average for your kill count";
		}
		if (luck < 0.5)
		{
			long n = Math.max(2, Math.round(1 / Math.max(luck, 0.0001)));
			return String.format(Locale.ROOT, "About 1 in %,d players is this dry (or drier)", n);
		}
		long n = Math.max(2, Math.round(1 / Math.max(1 - luck, 0.0001)));
		return String.format(Locale.ROOT, "About 1 in %,d players is this lucky (or luckier)", n);
	}

	/** Chance of at least one more in the next {@code kills}, at {@code rate} per kill. */
	public static double nextChance(double rate, int kills)
	{
		return rate <= 0 ? 0 : -Math.expm1(-rate * kills);
	}

	/**
	 * For something you don't have yet, how far past the drop rate you are, the way players
	 * count it: "2.1\u00d7 the drop rate without one" (1\u00d7 is on rate, 2\u00d7 dry, 3\u00d7 very dry).
	 * Null when you have one, or nothing is expected.
	 */
	static String rateMultipleLine(RowStats row)
	{
		String multiple = rateMultiple(row);
		return multiple == null ? null : multiple + (row.isAny() ? " without a unique" : " without one");
	}

	/** {@link #rateMultipleLine} without its ending, for a hover row: "2.1× the drop rate". */
	static String rateMultiple(RowStats row)
	{
		// the drop rates times the kills: a capped pet still counts in full here
		double multiple = row.getUncappedExpected();
		if (row.getReceived() > 0 || row.isComplete() || !(multiple > 0))
		{
			return null;
		}
		return String.format(Locale.ROOT, "%s the %s rate", formatMultiple(multiple), row.isAny() ? "unique" : "drop");
	}

	/** The dry streak as a footnote line, or null when unknown. */
	static String streakNote(RowStats row, String unit)
	{
		// with none yet, rateMultipleLine already says how far past the rate you are
		if (row.getStreak() == null || row.getReceived() == 0 && row.isStreakExact())
		{
			return null;
		}
		if (!row.isStreakExact() && row.getStreak() == 0)
		{
			return "Dry streak: your last one came before On Rate, so it counts from your next " + unit + ".";
		}
		String kills = String.format(Locale.ROOT, "%,d %s%s", row.getStreak(), unit, row.getStreak() == 1 ? "" : "s");
		double m = row.getStreakMultiple();
		boolean multiple = !Double.isNaN(m) && row.getRate() > 0;
		if (!row.isStreakExact())
		{
			// only a minimum is known: the last one came before On Rate
			return "Dry streak: at least " + kills + (multiple ? String.format(Locale.ROOT, " (%s the drop rate or more)", formatMultiple(m)) : "")
				+ ". Your last one came before On Rate started tracking.";
		}
		return String.format(Locale.ROOT, "Dry streak: %s %s", kills, row.isAny() ? "since your last unique" : "since your last one")
			+ (multiple ? String.format(Locale.ROOT, " (%s the drop rate)", formatMultiple(m)) : "") + ".";
	}

	/** Two-column table of completions per delve level, like the Doom plugin's header. */
	static String levelTable(Map<Integer, Integer> levels)
	{
		StringBuilder sb = new StringBuilder("<html><table cellpadding=0 cellspacing=0>");
		int half = (BossDefinition.DELVE_LEVELS + 1) / 2;
		for (int i = 1; i <= half; i++)
		{
			sb.append("<tr>").append(levelCell(i, levels.get(i)));
			int j = i + half;
			if (j <= BossDefinition.DELVE_LEVELS)
			{
				sb.append("<td width=12></td>").append(levelCell(j, levels.get(j)));
			}
			sb.append("</tr>");
		}
		return sb.append("</table></html>").toString();
	}

	/** "184 raids · 182 Normal · 2 CM" or "Callisto 96 · Artio 624", short enough for the header. */
	static String partLine(Map<String, Integer> parts, boolean raid, int total)
	{
		List<String> shown = new ArrayList<>();
		for (Map.Entry<String, Integer> e : parts.entrySet())
		{
			if (e.getValue() > 0)
			{
				String name = raid ? shortMode(e.getKey()) : e.getKey().replace("Dagannoth ", "");
				shown.add(raid ? String.format(Locale.ROOT, "%,d %s", e.getValue(), name) : String.format(Locale.ROOT, "%s %,d", name, e.getValue()));
			}
		}
		if (raid)
		{
			shown.add(0, String.format(Locale.ROOT, "%,d raids", total));
		}
		return String.join(" \u00b7 ", shown);
	}

	/** "Callisto 96 · Artio 624" or "182 Normal · 2 Challenge Mode"; parts with 0 are left out. */
	static String partTable(Map<String, Integer> parts, boolean raid)
	{
		List<String> shown = new ArrayList<>();
		for (Map.Entry<String, Integer> e : parts.entrySet())
		{
			if (e.getValue() > 0)
			{
				shown.add(raid ? String.format(Locale.ROOT, "%,d %s", e.getValue(), e.getKey()) : String.format(Locale.ROOT, "%s %,d", e.getKey(), e.getValue()));
			}
		}
		return "<html><body style='width: 165px'>" + String.join(" \u00b7 ", shown) + "</body></html>";
	}

	/** Kill count per boss on a combined page, e.g. "Dagannoth Rex: 436". */
	static String levelCell(int level, Integer count)
	{
		return String.format(Locale.ROOT, "<td><font color='#ffffff'>Level %s:</font></td><td align=right>&nbsp;%,d</td>",
			BossDefinition.delveLevelLabel(level), count == null ? 0 : count);
	}

	static String formatExpected(double expected)
	{
		if (expected >= 100)
		{
			return String.format(Locale.ROOT, "%.0f", expected);
		}
		if (expected >= 10)
		{
			return String.format(Locale.ROOT, "%.1f", expected);
		}
		return String.format(Locale.ROOT, "%.2f", expected);
	}

	static String formatMultiple(double m)
	{
		if (m < 0.1)
		{
			return String.format(Locale.ROOT, "%.2f\u00d7", m);
		}
		return m < 10 ? String.format(Locale.ROOT, "%.1f\u00d7", m) : String.format(Locale.ROOT, "%.0f\u00d7", m);
	}

	static String formatPercent(double p)
	{
		if (p > 0.999)
		{
			return ">99.9%";
		}
		return String.format(Locale.ROOT, "%.1f%%", p * 100);
	}

	static String initials(String name)
	{
		StringBuilder sb = new StringBuilder();
		for (String part : name.split("[\\s(]+"))
		{
			if (!part.isEmpty() && Character.isLetterOrDigit(part.charAt(0)) && sb.length() < 3)
			{
				sb.append(Character.toUpperCase(part.charAt(0)));
			}
		}
		return sb.toString();
	}

	/**
	 * A luck percentile as a whole percentage for "luckier than ...": "<1%" and ">99%" at the
	 * ends, so a very dry 0.3% doesn't read as "luckier than 0%" (nobody is drier).
	 */
	static String pct(double luck)
	{
		double p = luck * 100;
		if (p < 0.5)
		{
			return "<1%";
		}
		if (p >= 99.5)
		{
			return ">99%";
		}
		return String.format(Locale.ROOT, "%.0f%%", p);
	}

	/**
	 * Short line under a verdict: how common your result is among players at your kill count.
	 * "74% have none" when you have none, else "1 in 3 as dry" or "1 in 6 as lucky" (also for a
	 * bit dry and a bit spooned), or "about average" when the verdict is "On rate". Matches the tie-aware verdict (see Luck#tieAware).
	 */
	static String luckShort(double[] shares, int received)
	{
		if (shares == null)
		{
			return "";
		}
		double fewer = shares[0];
		double same = shares[1];
		if (received <= 0 || fewer <= 1e-12)
		{
			if (same >= 0.995)
			{
				return ">99% have none";
			}
			if (same >= 0.5)
			{
				return String.format(Locale.ROOT, "%.0f%% have none", same * 100);
			}
			return String.format(Locale.ROOT, "only 1 in %,d has none", Math.max(2, Math.round(1 / Math.max(same, 0.0001))));
		}
		return luckShort(Luck.tieAware(fewer, same));
	}

	/**
	 * The tile wording as a bracket for the end of a hover sentence: " (1 in 3 as dry)", or "" when
	 * there is nothing to add ("about average", or no shares).
	 */
	static String luckShortNote(double[] shares, int received)
	{
		String text = luckShort(shares, received);
		return text.isEmpty() || text.equals("about average") ? "" : " (" + text + ")";
	}

	/** The same from the luck value alone (GP value, the luck graph). */
	static String luckShort(double luck)
	{
		if (Double.isNaN(luck))
		{
			return "";
		}
		if (Verdict.isOnRate(luck))
		{
			// "On rate": the same band as the verdict (a bit dry and a bit spooned get their 1 in N)
			return "about average";
		}
		if (luck < 0.5)
		{
			return luck < 0.0001 ? "<1 in 10,000 as dry"
				: String.format(Locale.ROOT, "1 in %,d as dry", Math.max(2, Math.round(1 / luck)));
		}
		return 1 - luck < 0.0001 ? "<1 in 10,000 as lucky"
			: String.format(Locale.ROOT, "1 in %,d as lucky", Math.max(2, Math.round(1 / (1 - luck))));
	}

	/**
	 * Below this many expected uniques a boss page says "Too early" instead of a verdict: a
	 * handful of kills can't tell dry from lucky.
	 */
	static final double TOO_EARLY_BELOW = Verdict.TOO_EARLY_BELOW;

	/**
	 * A row with nothing to read yet: none got and under {@link #TOO_EARLY_BELOW} expected. Its verdict is
	 * always "On rate" (see {@code Luck.of}), so lists draw it quietly without hiding anything
	 * dry. Never "Any unique".
	 */
	static boolean isQuiet(RowStats r)
	{
		return r != null && !r.isAny() && r.getReceived() == 0 && r.getExpected() < TOO_EARLY_BELOW;
	}

	/**
	 * The verdict word for a finished trip in the Recent list: "Too early" under
	 * {@link #TOO_EARLY_BELOW} expected uniques (a handful of kills can't tell dry from lucky), else the
	 * usual verdict word. Null when nothing was expected.
	 */
	static String tripVerdict(double luck, double expected)
	{
		if (Double.isNaN(luck) || expected <= 0)
		{
			return null;
		}
		return expected < TOO_EARLY_BELOW ? "Too early" : Verdict.labelOf(luck);
	}

	/** A trip's length as "3 min" or "1h 22m"; "under 1 min" when shorter than a minute. */
	static String tripLength(long millis)
	{
		long minutes = Math.max(0, millis / 60_000);
		if (minutes < 1)
		{
			return "under 1 min";
		}
		return minutes >= 60 ? String.format(Locale.ROOT, "%dh %02dm", minutes / 60, minutes % 60) : minutes + " min";
	}

	/** First line of a trip row: "96 kills \u00b7 3 uniques" (units as the boss calls them, e.g. "kills" or "raids"). */
	static String tripCounts(int kills, String units, int uniques)
	{
		String unit = kills == 1 && units.endsWith("s") ? units.substring(0, units.length() - 1) : units;
		return String.format(Locale.ROOT, "%,d %s \u00b7 %s", kills, unit,
			uniques == 0 ? "no uniques" : uniques == 1 ? "1 unique" : uniques + " uniques");
	}

	/**
	 * "got / expected" for a row, as boss pages show it: "0 / 2.60", "3 / 1.20". Expected is the average a
	 * player would have by now at the drop rates, not a number owed. A cap (a pet is 1, Warm gloves 3) only
	 * limits what counts as got; the expected number is the row's own, as in every other view.
	 */
	static String gotOfExpected(RowStats r)
	{
		return String.format(Locale.ROOT, "%,d / %s", r.getReceived(), formatExpected(r.getExpected()));
	}

	/** What a row says once you have every copy that counts: "have it", "have both", "have all 3". */
	static String haveText(RowStats r)
	{
		switch (r.getCap())
		{
			case 0:
			case 1:
				return "have it";
			case 2:
				return "have both";
			default:
				return "have all " + r.getCap();
		}
	}

	/** How far out a dry or lucky item must be to be worth a sentence: 8 in 10 players. */
	static final double NOTABLE_SHARE = 0.80;
	/** An item you don't have yet is worth a sentence once this many players would have it. */
	static final double NOTABLE_CHANCE = 0.60;

	/**
	 * One true sentence for under an "On rate" verdict: the item furthest from average, or null
	 * when nothing stands out. The driest item ("drier than 88% of players"), an item most
	 * players would have by now while you don't ("6 in 10 players would have a Tumeken's shadow
	 * by now"), or the luckiest item ("luckier than 97% of players"), whichever is furthest out.
	 */
	static String notableLine(List<RowStats> items)
	{
		RowStats best = null;
		double bestShare = 0;
		boolean bestLucky = false;
		for (RowStats r : items)
		{
			double[] shares = r == null || r.isAny() ? null : r.getShares();
			if (shares == null)
			{
				continue;
			}
			double fewer = r.getReceived() <= 0 ? 0 : shares[0];
			double more = Math.max(0, 1 - fewer - shares[1]);
			// none yet: a sentence once most players would have one; else 8 in 10 out
			double dryNeeded = r.getReceived() <= 0 ? NOTABLE_CHANCE : NOTABLE_SHARE;
			if (more >= dryNeeded && more > bestShare)
			{
				best = r;
				bestShare = more;
				bestLucky = false;
			}
			if (fewer >= NOTABLE_SHARE && fewer > bestShare)
			{
				best = r;
				bestShare = fewer;
				bestLucky = true;
			}
		}
		if (best == null)
		{
			return null;
		}
		String name = best.getLabel();
		if (bestLucky)
		{
			return String.format(Locale.ROOT, "Luckiest: %s, luckier than %s of players.", name, sharePct(bestShare));
		}
		if (best.getReceived() <= 0)
		{
			// with none, the players who have more are the ones who'd have one by now
			String players = bestShare < 0.95
				? String.format(Locale.ROOT, "%d in 10 players", (int) Math.floor(bestShare * 10))
				: sharePct(bestShare) + " of players";
			return String.format(Locale.ROOT, "%s would have %s by now.", players, withArticle(name));
		}
		return String.format(Locale.ROOT, "Driest: %s, drier than %s of players.", name, sharePct(bestShare));
	}

	/** An item this close to its expected count (a quarter either way) is "about on rate" for its own line. */
	static final double CLOSE_TO_EXPECTED = 0.25;

	/**
	 * The true sentences the line under the verdict takes turns with, in a fixed order: the
	 * {@link #notableLine} first (it may be about a dry item; nothing after it is), then neutral facts. Every
	 * fact needs enough data behind it (half a unique expected, as for "Too early"), and none says a drop is
	 * due or coming.
	 *
	 * @param items  the items of the page (a boss's drops, or the account's highlighted items)
	 * @param bosses the account's boss rows on the account overview, or null on a boss page
	 * @param countLuck the luck of the uniques verdict, NaN when unknown
	 * @param valueLuck the luck of the GP value verdict, NaN when it isn't shown
	 * @param what "uniques", or "purples" at a raid
	 */
	static List<String> notableLines(List<RowStats> items, List<RowStats> bosses, double countLuck, double valueLuck,
		String what)
	{
		return notableLines(items, bosses, countLuck, valueLuck, what, Collections.emptyList());
	}

	/** The same, with the page's own facts (the log forecast, the average pace) after the first ones. */
	static List<String> notableLines(List<RowStats> items, List<RowStats> bosses, double countLuck, double valueLuck,
		String what, List<String> pageFacts)
	{
		List<String> facts = new ArrayList<>();
		String first = notableLine(items);
		if (first != null)
		{
			facts.add(first);
		}
		facts.addAll(pageFacts);
		// the two verdicts on different sides: what that means, in words
		Verdict count = Verdict.of(countLuck);
		Verdict value = Verdict.of(valueLuck);
		if (count != null && value != null && count.isDry() && value.isSpooned())
		{
			facts.add("Fewer " + what + " than expected, but more valuable ones.");
		}
		else if (count != null && value != null && count.isSpooned() && value.isDry())
		{
			facts.add("More " + what + " than expected, but less valuable ones.");
		}
		if (bosses == null)
		{
			// the item closest to its expected count, when one is close
			RowStats close = null;
			double closest = CLOSE_TO_EXPECTED;
			int have = 0;
			int total = 0;
			for (RowStats r : items)
			{
				if (r == null || r.isAny())
				{
					continue;
				}
				total++;
				if (r.getReceived() > 0 || r.isComplete())
				{
					have++;
				}
				if (r.getReceived() >= 1 && r.getExpected() >= TOO_EARLY_BELOW)
				{
					double off = Math.abs(r.getReceived() - r.getExpected()) / r.getExpected();
					if (off <= closest)
					{
						closest = off;
						close = r;
					}
				}
			}
			if (close != null)
			{
				facts.add(String.format(Locale.ROOT, "%s: %,d got, %s expected.", close.getLabel(),
					close.getReceived(), formatExpected(close.getExpected())));
			}
			if (total >= 2 && have > 0)
			{
				facts.add(have == total && total == 2 ? "You have both " + what + " here."
					: have == total ? String.format(Locale.ROOT, "You have all %d %s here.", total, what)
					: String.format(Locale.ROOT, "You have %d of the %d %s here.", have, total, what));
			}
		}
		else
		{
			// how the bosses split, and which one gave the most
			int dry = 0;
			int on = 0;
			int lucky = 0;
			RowStats most = null;
			for (RowStats b : bosses)
			{
				Verdict v = b == null || b.getExpected() < TOO_EARLY_BELOW ? null : Verdict.of(b.getLuck());
				if (v == null)
				{
					continue;
				}
				if (v.isDry())
				{
					dry++;
				}
				else if (v.isSpooned())
				{
					lucky++;
				}
				else
				{
					on++;
				}
				if (b.getReceived() > 0 && (most == null || b.getReceived() > most.getReceived()))
				{
					most = b;
				}
			}
			if (dry + on + lucky >= 2)
			{
				facts.add(String.format(Locale.ROOT, "Of %d bosses: %d drier than average, %d on rate, %d luckier.",
					dry + on + lucky, dry, on, lucky));
			}
			if (most != null)
			{
				facts.add(String.format(Locale.ROOT, "Most %s: %s, %,d.", what, most.getLabel(), most.getReceived()));
			}
		}
		return facts;
	}

	/**
	 * The log forecast as a sentence. With the pet still missing it gives both: "Rest of the log, 50% chance:
	 * 1,520 more kills (~790 h) with the pet, 1,010 (~520 h) without." Else one figure: "Rest of the log: 50%
	 * chance within 1,010 more kills (~520 h)." A chance, not a promise, and the same whatever came before. Null
	 * when nothing is missing or it can't be done.
	 *
	 * @param withPet    kills (or raids) after which half of players with these chances would have everything,
	 *                   the pet included
	 * @param withoutPet the same without the pet (equal to {@code withPet} when the pet isn't missing)
	 * @param petMissing whether the pet is still missing
	 * @param seconds    seconds per kill, NaN when unknown (then no hours)
	 * @param units      "kills", "raids"
	 * @param onlyItem   the one item still missing (the pet when it's the last), or null when there are more
	 */
	static String logLeftLine(long withPet, long withoutPet, boolean petMissing, double seconds, String units, String onlyItem)
	{
		if (withPet <= 0)
		{
			return null;
		}
		if (petMissing && withoutPet > 0 && withoutPet < withPet)
		{
			return String.format(Locale.ROOT, "Rest of the log, 50%% chance: %,d more %s%s with the pet, %,d%s without.",
				withPet, units, aboutTime(withPet * seconds), withoutPet, aboutTime(withoutPet * seconds));
		}
		String what = onlyItem == null ? "Rest of the log" : "Last item for the log, " + onlyItem;
		return String.format(Locale.ROOT, "%s: 50%% chance within %,d more %s%s.", what, withPet, units,
			aboutTime(withPet * seconds));
	}

	/**
	 * The average pace: "On average one unique every 82 kills (~9.5 h)." Each kill is its own roll, so this
	 * is the same after a long wait as after a drop. Null when nothing is expected.
	 *
	 * @param perKill uniques expected per kill
	 * @param seconds seconds per kill, NaN when unknown (then no hours)
	 * @param units   "kills", "raids"
	 * @param one     "unique", "purple"
	 */
	static String averagePaceLine(double perKill, double seconds, String units, String one)
	{
		if (!(perKill > 0))
		{
			return null;
		}
		double every = 1 / perKill;
		String count = every >= 10 ? String.format(Locale.ROOT, "%,d", Math.round(every))
			: String.format(Locale.ROOT, "%.1f", every);
		return String.format(Locale.ROOT, "On average one %s every %s %s%s.", one, count, units,
			aboutTime(every * seconds));
	}

	/** " (~790 h)", " (~9.5 h)", " (~40 min)", or "" when the time isn't known. */
	static String aboutTime(double seconds)
	{
		if (!(seconds > 0) || Double.isInfinite(seconds))
		{
			return "";
		}
		double hours = seconds / 3600;
		if (hours < 1)
		{
			return String.format(Locale.ROOT, " (~%d min)", Math.max(1, Math.round(hours * 60)));
		}
		if (hours < 10)
		{
			return String.format(Locale.ROOT, " (~%.1f h)", hours);
		}
		return String.format(Locale.ROOT, " (~%,d h)", Math.round(hours));
	}

	/**
	 * For the "Unique value" hover: the item most of the value comes from, when one item is at
	 * least half of it ("Most of it is the Crystal tool seed (95%)."), else null.
	 */
	static String mainValueSource(List<String> names, List<Double> values)
	{
		double total = 0;
		int best = -1;
		for (int i = 0; i < values.size(); i++)
		{
			double v = Math.max(0, values.get(i));
			total += v;
			if (best < 0 || v > values.get(best))
			{
				best = i;
			}
		}
		if (best < 0 || total <= 0 || values.get(best) / total < 0.5)
		{
			return null;
		}
		return String.format(Locale.ROOT, "Most of it is the %s (%.0f%%).", names.get(best), Math.floor(values.get(best) / total * 100));
	}

	/** "a Tumeken's shadow", "an Elder maul", "Bandos boots" (a pair or a set takes none). */
	static String withArticle(String name)
	{
		if (name.isEmpty())
		{
			return name;
		}
		if (name.endsWith("s") && !name.endsWith("'s"))
		{
			return name;
		}
		return ("AEIOUaeiou".indexOf(name.charAt(0)) >= 0 ? "an " : "a ") + name;
	}

	/**
	 * For hovers: how your result compares with players at your kill count, as a percentage.
	 * Always told from the side that holds most players, so the number is over 50%: "drier than
	 * 67%" (67% have more), "luckier than 83%" (83% have fewer), and "74% have none" when you
	 * and most players have none. Players with exactly your count are on neither side. "About
	 * average" when neither side is a majority. Past 95% the "1 in N" is added: "drier than
	 * 99.91% (1 in 1,205)".
	 */
	static String luckPercent(double[] shares, int received)
	{
		if (shares == null)
		{
			return "";
		}
		double fewer = received <= 0 ? 0 : shares[0];
		double same = shares[1];
		double more = Math.max(0, 1 - fewer - same);
		if (more > 0.5)
		{
			return side("drier", more);
		}
		if (fewer > 0.5)
		{
			return side("luckier", fewer);
		}
		if (received <= 0)
		{
			return same >= 0.995 ? ">99% have none" : String.format(Locale.ROOT, "%.0f%% have none", same * 100);
		}
		return "about average";
	}

	/** The same from the luck value alone (GP value, the luck graph). */
	static String luckPercent(double luck)
	{
		if (Double.isNaN(luck))
		{
			return "";
		}
		if (luck < 0.495)
		{
			return side("drier", 1 - luck);
		}
		if (luck > 0.505)
		{
			return side("luckier", luck);
		}
		return "about average";
	}

	/** "drier than 67%", with "(1 in 33)" added past 95%: how rare a result this far out is. */
	private static String side(String word, double share)
	{
		String text = word + " than " + sharePct(share);
		if (share < 0.95)
		{
			return text;
		}
		double rest = 1 - share;
		return text + (rest < 0.0001 ? " (<1 in 10,000 players)"
			: String.format(Locale.ROOT, " (1 in %,d players)", Math.max(2, Math.round(1 / rest))));
	}

	/**
	 * A majority share as a percentage: whole numbers like the hover's split ("67%", "97%"), then
	 * decimals rounded down so it never reaches 100% ("99.4%", "99.91%").
	 */
	static String sharePct(double share)
	{
		double p = share * 100;
		if (share < 0.99)
		{
			return String.format(Locale.ROOT, "%d%%", Math.round(p));
		}
		if (share < 0.999)
		{
			return String.format(Locale.ROOT, "%.1f%%", Math.floor(p * 10) / 10);
		}
		return String.format(Locale.ROOT, "%.2f%%", Math.min(99.99, Math.floor(p * 100) / 100));
	}

	/**
	 * The full split for a hover: "74% of players have none by now, 26% have one or more", or
	 * "18% of players have fewer, 15% as many, 67% more". Null when nothing is expected.
	 */
	static String sharesLine(double[] shares, int received)
	{
		if (shares == null)
		{
			return null;
		}
		double fewer = shares[0];
		double same = shares[1];
		double more = Math.max(0, 1 - fewer - same);
		if (received <= 0 || fewer <= 1e-12)
		{
			return String.format(Locale.ROOT, "%s of players have none by now, %s have one or more", pct(same), pct(more));
		}
		return String.format(Locale.ROOT, "%s of players have fewer, %s as many%s", pct(fewer), pct(same),
			more < 0.0005 ? "" : ", " + pct(more) + " more");
	}

	/** Marks for a unique count clearly above / below expected (a plain +/- when the font has no triangles). */
	static final String MARK_MORE = "\u25b2";
	static final String MARK_FEWER = "\u25bc";

	/**
	 * The mark after a Recent unique count: more than expected (luck above the Verdict band) or fewer (below it),
	 * and nothing inside the band, when luck or expected is unknown, or nothing was expected. Neutral on purpose:
	 * no word, and no "too early" gate, because the hover gives the expected number.
	 */
	static String uniquesMark(double luck, double expected, boolean triangles)
	{
		if (Double.isNaN(luck) || expected <= 0 || (luck >= Verdict.DRY_BELOW && luck <= Verdict.SPOONED_ABOVE))
		{
			return "";
		}
		boolean more = luck > Verdict.SPOONED_ABOVE;
		return triangles ? (more ? MARK_MORE : MARK_FEWER) : (more ? "+" : "-");
	}

	/** First letter upper case, for a short line used on its own. */
	static String capital(String text)
	{
		return text == null || text.isEmpty() ? text : Character.toUpperCase(text.charAt(0)) + text.substring(1);
	}

	/**
	 * Makes "<1%" or "<1 in 10,000" safe inside Swing HTML, which drops a "<" before a digit
	 * (it reads it as the start of a tag). Real tags like {@code <br>} are left alone.
	 */
	static String html(String text)
	{
		return text == null ? null : text.replaceAll("<(?=[0-9])", "&lt;");
	}
}

package com.expecteddrops.ui;

import java.awt.Font;
import net.runelite.client.ui.FontManager;
import java.util.Locale;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Component;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.Icon;
import net.runelite.client.ui.ColorScheme;

/**
 * Every interface colour, spacing step and text width in one place. Luck colours are not here:
 * they live in {@link Palette} and are used for luck and nothing else.
 *
 * <ul>
 * <li>{@link #TEXT}: names, labels and headings</li>
 * <li>{@link #TEXT_MUTED}: secondary text, and the lowest grey any text may use</li>
 * <li>{@link #ACCENT}: selection, focus and hover (tab underlines, the focus ring, link hovers). Never
 * for notices or decoration: orange is also the "dry" end of the luck colours</li>
 * </ul>
 */
public final class Theme
{
	public static final Color TEXT = Color.WHITE;
	public static final Color TEXT_MUTED = ColorScheme.LIGHT_GRAY_COLOR;
	public static final Color ACCENT = ColorScheme.BRAND_ORANGE;

	public static final Color PANEL = ColorScheme.DARK_GRAY_COLOR;
	public static final Color SURFACE = ColorScheme.DARKER_GRAY_COLOR;
	public static final Color SURFACE_RAISED = new Color(45, 45, 45);
	public static final Color SURFACE_SELECTED = new Color(61, 61, 61);
	public static final Color TRACK = new Color(55, 55, 55);
	public static final Color TRACK_DARK = new Color(26, 26, 26);
	public static final Color OUTLINE = new Color(70, 70, 70);
	/** The thin line between label / value rows in a tooltip. */
	public static final Color DIVIDER = new Color(60, 60, 60);
	/** The expected-by-now tick on a quiet item row (nothing expected yet): visible, but not white. */
	public static final Color QUIET_MARK = new Color(150, 150, 150);
	/** Bars that show progress, not luck: no verdict colours on them. */
	public static final Color PROGRESS = new Color(90, 106, 122);
	/** Raid "purples": the game's own colour for raid uniques. */
	public static final Color RAID_PURPLE = new Color(192, 112, 255);

	/** Spacing: a hairline gap between rows, a small and a medium step. */
	public static final int HAIR = 2;
	public static final int S = 4;
	public static final int M = 8;

	/** Wrapped text inside the panel, and the two tooltip widths. */
	public static final int TEXT_WIDTH = 165;
	public static final int TIP_SHORT = 180;
	public static final int TIP_WIDE = 240;

	/** Wrapped text inside a boxed card, which has less room than the page, and the width of a dialog. */
	public static final int CARD_TEXT_WIDTH = 148;
	public static final int DIALOG_WIDTH = 240;

	private Theme()
	{
	}

	/** HTML that wraps at {@code width} pixels. */
	public static String wrap(String html, int width)
	{
		return "<html><body style='width: " + width + "px'>" + html + "</body></html>";
	}

	/** {@code #rrggbb} for a colour, for use inside HTML text. */
	public static String hex(Color c)
	{
		return String.format(Locale.ROOT, "#%06x", c.getRGB() & 0xFFFFFF);
	}

	/** A small "i" in a circle, in front of information lines (not warnings, not luck). */
	public static Icon infoIcon()
	{
		return new Icon()
		{
			@Override
			public void paintIcon(Component c, Graphics graphics, int x, int y)
			{
				Graphics2D g = (Graphics2D) graphics.create();
				g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
				g.setColor(TEXT_MUTED);
				g.setStroke(new BasicStroke(1f));
				g.drawOval(x, y + 1, 10, 10);
				g.fillRect(x + 5, y + 5, 1, 4);
				g.fillRect(x + 5, y + 3, 1, 1);
				g.dispose();
			}

			@Override
			public int getIconWidth()
			{
				return 11;
			}

			@Override
			public int getIconHeight()
			{
				return 12;
			}
		};
	}


	/** Item and secondary numbers in lists: the regular weight, so names stay the bold ones. */
	static Font numberFont()
	{
		return FontManager.getRunescapeFont();
	}

	/** The font of the verdicts at the top ("On rate") and of the names and numbers in the lists. */
	static Font rowFont()
	{
		return FontManager.getRunescapeBoldFont().deriveFont(Font.PLAIN, 16f);
	}

	/** The verdict in the tiles at the top ("Very spooned"): bold and a little bigger than the lists. */
	static Font verdictFont()
	{
		return FontManager.getRunescapeBoldFont().deriveFont(18f);
	}
}

package com.expecteddrops.ui;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import java.awt.Color;
import java.util.ArrayList;
import java.util.List;

/**
 * One layout for every tooltip: a bold title, a few facts, and an optional grey footnote.
 * Facts are lines of text, or label / value rows with a thin line between them:
 * <pre>new Tip("Vorkath's head").row("Drop rate", "1/50 per kill").note("Counted from ...").wide()</pre>
 * Lines and rows show in the order they were added; rows next to each other form one table.
 */
@AllArgsConstructor(access = AccessLevel.PACKAGE)
final class Tip
{
	private final String title;
	/** Lines (a String) and rows (a String[] of label and value), in order. */
	private final List<Object> parts = new ArrayList<>();
	private final List<String> notes = new ArrayList<>();

	Tip line(String html)
	{
		if (html != null && !html.isEmpty())
		{
			parts.add(Texts.html(html));
		}
		return this;
	}

	/** A line in a colour (a verdict, or grey for a subtitle). */
	Tip line(String text, Color color)
	{
		if (text == null || text.isEmpty())
		{
			return this;
		}
		return line("<font color='" + Theme.hex(color) + "'>" + text + "</font>");
	}

	/** A grey label on the left, its value on the right. Skipped when the value is empty. */
	Tip row(String label, String value)
	{
		if (value != null && !value.isEmpty())
		{
			parts.add(new String[]{Texts.html(label), Texts.html(value)});
		}
		return this;
	}

	/** A row whose value is in a colour (a verdict). */
	Tip row(String label, String value, Color color)
	{
		if (value == null || value.isEmpty())
		{
			return this;
		}
		return row(label, "<font color='" + Theme.hex(color) + "'>" + value + "</font>");
	}

	/**
	 * A thin bar split into the players with fewer, as many as you (in {@code you}, the verdict colour)
	 * and more. Skipped when the split is unknown.
	 */
	Tip split(double[] shares, int received, Color you)
	{
		if (shares == null)
		{
			return this;
		}
		double fewer = received <= 0 ? 0 : shares[0];
		double same = shares[1];
		double more = Math.max(0, 1 - fewer - same);
		StringBuilder sb = new StringBuilder("<table width='100%' cellpadding='0' cellspacing='0' style='margin-top: 3px'><tr>");
		cell(sb, fewer, Theme.DIVIDER.brighter());
		cell(sb, same, you);
		cell(sb, more, Palette.blend(you, Color.WHITE, 0.5));
		parts.add(sb.append("</tr></table>").toString());
		return this;
	}

	/** One part of {@link #split}: at least 1% wide when there is any of it, so a sliver still shows. */
	private static void cell(StringBuilder sb, double share, Color color)
	{
		if (share < 0.0005)
		{
			return;
		}
		int pct = Math.max(1, (int) Math.round(share * 100));
		sb.append("<td width='").append(pct).append("%' bgcolor='").append(Theme.hex(color))
			.append("' style='font-size: 4px'>&nbsp;</td>");
	}

	/** Grey text at the bottom: where a number comes from, or a caveat. */
	Tip note(String html)
	{
		if (html != null && !html.isEmpty())
		{
			notes.add(Texts.html(html));
		}
		return this;
	}

	/** For details (item and value tooltips). */
	String wide()
	{
		return build(Theme.TIP_WIDE);
	}

	/** For short hints. */
	String small()
	{
		return build(Theme.TIP_SHORT);
	}

	private String build(int width)
	{
		String muted = Theme.hex(Theme.TEXT_MUTED);
		// a line above every row: it parts the rows from each other and from the text above
		String cell = "style='border-top: 1px solid " + Theme.hex(Theme.DIVIDER) + "'";
		StringBuilder sb = new StringBuilder();
		if (title != null)
		{
			sb.append("<b>").append(title).append("</b>");
		}
		boolean inTable = false;
		for (Object part : parts)
		{
			if (part instanceof String[])
			{
				if (!inTable)
				{
					sb.append("<table width='100%' cellpadding='2' cellspacing='0' style='margin-top: 3px; margin-bottom: 3px'>");
					inTable = true;
				}
				String[] row = (String[]) part;
				sb.append("<tr><td nowrap ").append(cell).append("><font color='").append(muted).append("'>")
					.append(row[0]).append("</font></td><td align='right' ").append(cell).append(">")
					.append(row[1]).append("</td></tr>");
				continue;
			}
			if (inTable)
			{
				sb.append("</table>");
				inTable = false;
			}
			else if (sb.length() > 0 && !endsWithTable(sb))
			{
				sb.append("<br>");
			}
			sb.append(part);
		}
		if (inTable)
		{
			sb.append("</table>");
		}
		if (!notes.isEmpty())
		{
			// a table ends its own line
			sb.append(sb.length() == 0 || endsWithTable(sb) ? "" : "<br>").append("<font color='").append(muted).append("'>");
			sb.append(String.join("<br>", notes)).append("</font>");
		}
		return Theme.wrap(sb.toString(), width);
	}

	private static boolean endsWithTable(StringBuilder sb)
	{
		return sb.length() >= 8 && sb.substring(sb.length() - 8).equals("</table>");
	}
}

package com.expecteddrops.ui;

import java.util.ArrayList;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.util.List;
import java.awt.RenderingHints;
import java.awt.geom.RoundRectangle2D;

import java.awt.Color;
import java.awt.Component;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.FontManager;

/** One verdict tile: a small title, the verdict word, and the numbers behind it. */
class VerdictTile extends JPanel
{
	private final JLabel key = new FullWidthLabel();
	private final JLabel word = new FullWidthLabel();
	private final JLabel numbers = new FullWidthLabel();
	private final LuckPill luck = new LuckPill();
	/** The colour of the top edge: the verdict's colour. */
	private Color accent = Theme.TEXT_MUTED;
	/** The verdict word and the two small lines as set, before any wrapping (see {@link #doLayout}). */
	private String wordText = "";
	private String numbersText = "";
	private String luckText = "";

	VerdictTile(String title)
	{
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setOpaque(false);
		setBorder(new EmptyBorder(Theme.M, Theme.M, Theme.M - 1, Theme.S + 1));
		key.setText(title);
		key.setFont(FontManager.getRunescapeSmallFont());
		key.setForeground(Theme.TEXT_MUTED);
		// the verdict is what On Rate is about: a size up from the lists
		word.setFont(Theme.verdictFont());
		numbers.setFont(FontManager.getRunescapeSmallFont());
		numbers.setForeground(Theme.TEXT_MUTED);
		numbers.setBorder(new EmptyBorder(0, 0, Theme.S, 0));
		for (JLabel l : new JLabel[]{key, word, numbers})
		{
			l.setAlignmentX(LEFT_ALIGNMENT);
		}
		luck.setAlignmentX(LEFT_ALIGNMENT);
		add(key);
		add(word);
		add(numbers);
		add(luck);
	}

	/** The card: a quiet gradient, a hairline outline and a coloured top edge. */
	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.SURFACE_RAISED, w, h, Theme.SURFACE));
		g.fillRoundRect(0, 0, w - 1, h - 1, 8, 8);
		g.setColor(Theme.OUTLINE);
		g.drawRoundRect(0, 0, w - 1, h - 1, 8, 8);
		// the coloured edge, clipped to the card's rounded corners
		g.setClip(new RoundRectangle2D.Float(0, 0, w - 1, h - 1, 8, 8));
		g.setColor(accent);
		g.fillRect(0, 0, w, 2);
		g.dispose();
	}

	/**
	 * A label that takes the whole width of the tile. A plain label is never wider than its text was when it
	 * was last measured, which is too narrow once the verdict word grows or the line wraps in {@link #doLayout}.
	 */
	private static final class FullWidthLabel extends JLabel
	{
		@Override
		public Dimension getMaximumSize()
		{
			return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
		}
	}

	/**
	 * Verdict size by default; smaller only when a long word ("Very spooned") doesn't fit the tile.
	 * A word too wide even at the smallest size ("Extremely spooned") goes back to full size on two lines.
	 */
	private static final float WORD_SIZE = 18f;
	private static final float WORD_MIN_SIZE = 14f;

	/**
	 * The tile is about 98px wide for text when the panel has its scrollbar. Two things in it can be
	 * wider: "Very spooned" in the full size needs 102 ("Extremely spooned" 141, still 113 at the
	 * smallest size, so it takes two lines), and "only 1 in 10,000 has none" needs 127. The
	 * verdict word steps down a point at a time until it fits (and back up when it does); the small
	 * lines wrap onto a second line instead of ending in "...".
	 */
	@Override
	public void doLayout()
	{
		super.doLayout();
		int room = getWidth() - getInsets().left - getInsets().right;
		if (room <= 0)
		{
			return;
		}
		boolean changed = false;
		String text = wordText;
		if (text != null && !text.isEmpty())
		{
			float size = WORD_SIZE;
			Font base = Theme.verdictFont();
			while (size > WORD_MIN_SIZE && word.getFontMetrics(base.deriveFont(size)).stringWidth(text) > room)
			{
				size -= 1f;
			}
			boolean twoLines = word.getFontMetrics(base.deriveFont(size)).stringWidth(text) > room;
			if (twoLines)
			{
				size = WORD_SIZE;
			}
			if (word.getFont().getSize2D() != size)
			{
				word.setFont(base.deriveFont(size));
				changed = true;
			}
			if (twoLines)
			{
				changed |= wrapIfLong(word, text, room);
			}
			else if (!text.equals(word.getText()))
			{
				word.setText(text);
				changed = true;
			}
		}
		changed |= wrapIfLong(numbers, numbersText, room);
		changed |= wrapIfLong(luck, luckText, room - 17);
		if (changed)
		{
			// a label that wrapped (or shrank) needs a different height: lay the tile and its row out again,
			// or the second line is cut off. Later, not now: a revalidate made while the tile is being laid
			// out is wiped when that layout pass ends (Swing marks the tile valid again afterwards)
			SwingUtilities.invokeLater(this::revalidate);
		}
	}

	/**
	 * Shows {@code plain} as it is, or broken into lines of at most {@code room} pixels when it would be cut off.
	 * The breaks are made here, from the label's own font: a CSS width in an HTML label is not in pixels
	 * (it comes out about a third wider and varies with the screen).
	 */
	private static boolean wrapIfLong(JLabel label, String plain, int room)
	{
		if (plain == null || plain.isEmpty())
		{
			return false;
		}
		String text = wrapIfLong(plain, label.getFontMetrics(label.getFont()), room, 0);
		if (!text.equals(label.getText()))
		{
			label.setText(text);
			return true;
		}
		return false;
	}

	/**
	 * {@code plain} as it is when it fits {@code room} pixels in the font of {@code fm}, otherwise broken at spaces into
	 * lines of at most {@code room} pixels, as an HTML string (only then: text that needs no break stays plain).
	 * Measured with the real font, because a CSS width in an HTML label is not in pixels.
	 *
	 * @param maxLines 0 for as many lines as it takes; otherwise at most this many, the last one ending in "..."
	 *     when the rest of the name does not fit (and a single word wider than the room is cut the same way)
	 */
	static String wrapIfLong(String plain, FontMetrics fm, int room, int maxLines)
	{
		if (plain == null || plain.isEmpty() || room <= 0)
		{
			return plain;
		}
		List<String> lines = new ArrayList<>();
		StringBuilder line = new StringBuilder();
		for (String word : plain.split(" "))
		{
			String longer = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && fm.stringWidth(longer) > room)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(longer);
			}
		}
		lines.add(line.toString());
		if (maxLines > 0)
		{
			while (lines.size() > maxLines)
			{
				// the rest of the name goes onto the last line, which is then cut short
				String last = lines.remove(lines.size() - 1);
				lines.set(lines.size() - 1, lines.get(lines.size() - 1) + " " + last);
			}
			for (int i = 0; i < lines.size(); i++)
			{
				boolean overflow = fm.stringWidth(lines.get(i)) > room;
				if (overflow)
				{
					lines.set(i, ellipsize(lines.get(i), fm, room));
				}
			}
		}
		if (lines.size() == 1)
		{
			return lines.get(0);
		}
		StringBuilder shown = new StringBuilder("<html>");
		for (int i = 0; i < lines.size(); i++)
		{
			shown.append(i > 0 ? "<br>" : "").append(Texts.html(lines.get(i).replace("&", "&amp;")));
		}
		return shown.append("</html>").toString();
	}

	/** {@code text} cut from the end, with "..." added, until it fits {@code room} pixels. */
	private static String ellipsize(String text, FontMetrics fm, int room)
	{
		String cut = text;
		while (cut.length() > 1 && fm.stringWidth(cut + "...") > room)
		{
			cut = cut.substring(0, cut.length() - 1);
		}
		return cut.trim() + "...";
	}

	void set(String verdict, Color color, String numbersText, String luckText, String tip)
	{
		word.setText(verdict);
		this.wordText = verdict;
		word.setForeground(color);
		this.accent = color;
		luck.setHue(color);
		this.numbersText = numbersText;
		this.luckText = luckText;
		numbers.setText(numbersText);
		luck.setText(luckText);
		setToolTipText(tip);
		for (Component c : getComponents())
		{
			((JLabel) c).setToolTipText(tip);
		}
		// the tile was taken out of its row while its text changed: drop the size it remembers
		invalidate();
		repaint();
	}
}

package com.expecteddrops.ui;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import java.awt.Color;

import java.awt.BasicStroke;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.*;
import javax.swing.border.LineBorder;
import net.runelite.client.ui.FontManager;

/**
 * A small outlined button that shows the current item view and opens a list of all five to pick from.
 * Quiet on purpose: muted outline, no fill, no accent colour (the orange is only the keyboard focus ring).
 * The same button sits on the boss pages and on the account overview; the view it changes is one setting.
 */
final class ViewChip extends JPanel
{
	private static final int HEIGHT = 22;
	private static final int PAD = 6;
	private static final int GAP = 4;
	private static final int ICON = 14;

	private final Consumer<ItemView> onPick;
	private ItemView view = ItemView.TARGET_BARS;
	private boolean compact;
	private boolean hover;

	ViewChip(Consumer<ItemView> onPick)
	{
		this.onPick = onPick;
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		setFont(FontManager.getRunescapeSmallFont());
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				repaint();
			}

			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					open();
				}
			}
		});
		update();
	}

	void setView(ItemView view)
	{
		ItemView next = view == null ? ItemView.TARGET_BARS : view;
		if (next != this.view)
		{
			this.view = next;
			update();
		}
	}

	/** Icon and arrow only, for a row that is short of width (the name stays in the tooltip). */
	void setCompact(boolean compact)
	{
		if (compact != this.compact)
		{
			this.compact = compact;
			update();
		}
	}

	private void update()
	{
		setToolTipText("View: " + view.shortName());
		if (getAccessibleContext() != null)
		{
			getAccessibleContext().setAccessibleName("View: " + view.shortName());
		}
		Dimension size = new Dimension(width(), HEIGHT);
		setPreferredSize(size);
		setMinimumSize(size);
		setMaximumSize(size);
		revalidate();
		repaint();
	}

	private int width()
	{
		FontMetrics fm = getFontMetrics(getFont());
		int w = PAD + ICON + GAP + ChevronIcon.WIDTH + PAD;
		if (!compact)
		{
			w += fm.stringWidth("View") + GAP + fm.stringWidth(view.shortName()) + GAP;
		}
		return w + 2;
	}

	private void open()
	{
		JPopupMenu menu = new JPopupMenu();
		menu.setBorder(new LineBorder(Theme.OUTLINE, 1));
		menu.setBackground(Theme.SURFACE);
		int width = Math.max(150, getWidth());
		for (ItemView v : ItemView.values())
		{
			menu.add(new Entry(v, v == view, width));
		}
		menu.show(this, getWidth() - width - 1, getHeight() + 2);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int w = getWidth();
		int h = getHeight();
		if (hover)
		{
			g.setColor(Theme.SURFACE_RAISED);
			g.fillRoundRect(0, 0, w - 1, h - 1, 4, 4);
		}
		g.setColor(Theme.OUTLINE);
		g.setStroke(new BasicStroke(1f));
		g.drawRoundRect(0, 0, w - 1, h - 1, 4, 4);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		int baseline = (h - fm.getHeight()) / 2 + fm.getAscent();
		int x = PAD + 1;
		if (!compact)
		{
			g.setColor(Theme.TEXT_MUTED);
			g.drawString("View", x, baseline);
			x += fm.stringWidth("View") + GAP;
		}
		new ViewIcon(view, Theme.TEXT_MUTED).paintIcon(this, g, x, (h - ICON) / 2);
		x += ICON + GAP;
		if (!compact)
		{
			g.setColor(Theme.TEXT);
			g.drawString(view.shortName(), x, baseline);
			x += fm.stringWidth(view.shortName()) + GAP;
		}
		new ChevronIcon().paintIcon(this, g, x, (h - ChevronIcon.HEIGHT) / 2);
		g.dispose();
	}

	/** One line of the list: icon, name, and a small tick on the current view. */
	private final class Entry extends JMenuItem
	{
		private final ItemView entryView;
		private final boolean current;

		Entry(ItemView view, boolean current, int width)
		{
			super(view.shortName());
			this.entryView = view;
			this.current = current;
			setFont(FontManager.getRunescapeSmallFont());
			setOpaque(false);
			setBorderPainted(false);
			setFocusPainted(false);
			setPreferredSize(new Dimension(width - 4, 22));
			getAccessibleContext().setAccessibleName(view.shortName() + (current ? ", current view" : ""));
			addActionListener(e ->
			{
				if (entryView != ViewChip.this.view)
				{
					onPick.accept(entryView);
				}
			});
		}

		@Override
		protected void paintComponent(Graphics graphics)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
			int w = getWidth();
			int h = getHeight();
			if (current)
			{
				g.setColor(Theme.SURFACE_SELECTED);
				g.fillRect(0, 0, w, h);
			}
			else if (isArmed())
			{
				g.setColor(Theme.SURFACE_RAISED);
				g.fillRect(0, 0, w, h);
			}
			new ViewIcon(entryView, Theme.TEXT_MUTED).paintIcon(this, g, 6, (h - ICON) / 2);
			g.setFont(getFont());
			FontMetrics fm = g.getFontMetrics();
			g.setColor(Theme.TEXT);
			g.drawString(getText(), 6 + ICON + 6, (h - fm.getHeight()) / 2 + fm.getAscent());
			if (current)
			{
				g.setColor(Theme.TEXT);
				g.setStroke(new BasicStroke(1.4f));
				int cx = w - 16;
				int cy = h / 2;
				g.drawLine(cx, cy, cx + 3, cy + 3);
				g.drawLine(cx + 3, cy + 3, cx + 8, cy - 3);
			}
			if (isArmed() && hasFocus())
			{
				g.setColor(Theme.ACCENT);
				g.setStroke(new BasicStroke(1f));
				g.drawRect(0, 0, w - 1, h - 1);
			}
			g.dispose();
		}
	}

	/** A small arrow pointing down: this opens a list. */
	private static final class ChevronIcon implements Icon
	{
		static final int WIDTH = 7;
		static final int HEIGHT = 4;

		@Override
		public void paintIcon(Component c, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setColor(Theme.TEXT_MUTED);
			g.setStroke(new BasicStroke(1.2f));
			g.drawLine(x, y, x + 3, y + 3);
			g.drawLine(x + 3, y + 3, x + 6, y);
			g.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return WIDTH;
		}

		@Override
		public int getIconHeight()
		{
			return HEIGHT;
		}
	}

	/** A 14 x 14 sketch of each view, drawn in one muted colour. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	static final class ViewIcon implements Icon
	{
		private final ItemView view;
		private final Color color;

		@Override
		public void paintIcon(Component c, Graphics graphics, int x, int y)
		{
			Graphics2D g = (Graphics2D) graphics.create();
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.translate(x, y);
			g.setColor(color);
			g.setStroke(new BasicStroke(1.2f));
			switch (view)
			{
				case DELVE_BARS:
					g.drawLine(1, 2, 6, 2);
					g.drawLine(8, 2, 13, 2);
					g.fillRect(1, 6, 9, 2);
					g.fillRect(1, 10, 6, 2);
					break;
				case COMPACT:
					g.drawRect(1, 2, 11, 10);
					g.drawLine(1, 6, 12, 6);
					g.drawLine(1, 9, 12, 9);
					g.drawLine(6, 2, 6, 12);
					break;
				case RINGS:
					g.drawOval(2, 2, 10, 10);
					g.setStroke(new BasicStroke(2.4f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
					g.drawArc(2, 2, 10, 10, 90, -200);
					break;
				case GAUGE:
					g.drawArc(1, 3, 12, 12, 0, 180);
					g.drawLine(7, 9, 10, 5);
					break;
				default:
					g.fillRect(1, 3, 10, 2);
					g.fillRect(1, 8, 6, 2);
					g.drawLine(8, 1, 8, 12);
			}
			g.dispose();
		}

		@Override
		public int getIconWidth()
		{
			return ICON;
		}

		@Override
		public int getIconHeight()
		{
			return ICON;
		}
	}
}

package com.expecteddrops.ui;

