package com.onrate.engine.data;

import com.google.gson.Gson;
import java.io.*;
import java.nio.charset.StandardCharsets;

/**
 * The data files bundled with the plugin. On Rate reads nothing else and makes no web requests:
 * drop rates, kill times and the Ladlor chart all ship inside the jar.
 */
public final class Bundled
{
	/** Where the bundled files live inside the jar. */
	public static final String BASE = "/com/onrate/";

	private Bundled()
	{
	}

	/** A bundled file as UTF-8 text. The caller closes it. */
	public static Reader reader(String file)
	{
		InputStream in = Bundled.class.getResourceAsStream(BASE + file);
		if (in == null)
		{
			throw new IllegalStateException("Missing bundled file " + file);
		}
		return new InputStreamReader(in, StandardCharsets.UTF_8);
	}

	/** The boss catalog from {@code bosses.json}. */
	public static BossCatalog catalog(Gson gson)
	{
		try (Reader reader = reader("bosses.json"))
		{
			return BossCatalog.load(gson, reader);
		}
		catch (IOException e)
		{
			throw new IllegalStateException("Could not read bosses.json", e);
		}
	}
}

package com.onrate.engine.data;


import lombok.Getter;
import lombok.Setter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * One row in a boss's unique list, as read from bosses.json.
 */
public class DropDefinition
{
	@Getter private String name;
	private String label;
	@Getter private String rate;
	@Getter @Setter private Double weight;
	@Getter @Setter private String perUnique;
	/** Tombs of Amascut: lowest raid level where this unique drops normally (below it, 1 in 50 is kept). */
	@Getter @Setter private Integer minRaidLevel;
	/** A drop that is guaranteed on this kill (Vorkath's head on the 50th): that kill's roll becomes a sure drop. */
	@Getter private Integer guaranteedAt;
	/** Tombs of Amascut: weight from a raid level on (e.g. {"400": 4}); below the lowest key the normal weight. */
	private Map<String, Double> levelWeights;
	/** Items that drop in stacks: average stack size. The collection log counts items, not drops. */
	private Double stack;
	/** Most copies the collection log can count (2 for the two Royal Titans prayer scrolls). */
	private Integer max;
	/** Rate per minion kill (God Wars bodyguards), added for each minion of the boss. */
	@Getter private String minionRate;
	@Setter private List<String> match;
	@Setter private Boolean any;
	@Setter private Boolean pet;
	private Boolean clogShared;
	/** True for items you can only get once (a prayer scroll you read). Pets count as once too. */
	private Boolean once;
	/** True when this drop does not scale with damage share at team bosses (e.g. Bran). */
	private Boolean noShare;
	/** Other monsters that drop this item, whose drops the collection log counts here too. */
	@Getter private String alsoFrom;
	/** What an untradeable item is worth, from tradeable ones ("Noxious halberd / 3"). See {@link ValueFormula}. */
	@Getter private String valueFrom;
	/** A line for the item's hover about how it drops (e.g. no repeats until you have all four). */
	@Getter private String note;
	/** Per-level rates for delve bosses, keyed "1".."9" (9 = level 8+). */
	@Setter private Map<String, String> levelRates;
	/** Per-part rates for combined pages, keyed by part name. */
	private Map<String, String> partRates;
	/** Raid modes whose unique table differs: weight per part name. */
	private Map<String, Double> partWeights;

	public DropDefinition()
	{
	}

	public DropDefinition(String name, String rate)
	{
		this.name = name;
		this.rate = rate;
	}

	/** Text shown in the panel: the label if set, otherwise the item name. */
	public String getDisplayName()
	{
		return label != null && !label.isEmpty() ? label : name;
	}

	/** Weight of this item in one raid mode (falls back to the normal weight). */
	public Double getWeight(String part)
	{
		if (partWeights != null && part != null && partWeights.containsKey(part))
		{
			return partWeights.get(part);
		}
		return weight;
	}

	/** This item's weight at a raid level: the entry for the highest level at or below it. */
	public Double getWeightAtLevel(int raidLevel)
	{
		Double w = weight;
		int best = Integer.MIN_VALUE;
		if (levelWeights != null)
		{
			for (Map.Entry<String, Double> e : levelWeights.entrySet())
			{
				int level = Integer.parseInt(e.getKey());
				if (level <= raidLevel && level > best)
				{
					best = level;
					w = e.getValue();
				}
			}
		}
		return w;
	}

	public boolean hasLevelWeights()
	{
		return levelWeights != null && !levelWeights.isEmpty();
	}

	/** Collection log quantity turned into a number of drops for stackable items. */
	public int dropsFromQuantity(int quantity)
	{
		if (stack == null || stack <= 1 || quantity <= 0)
		{
			return quantity;
		}
		return Math.max(1, (int) Math.round(quantity / stack));
	}

	/** The item name plus every extra name that counts for this row. */
	public List<String> getAllNames()
	{
		List<String> names = new ArrayList<>();
		names.add(name);
		if (match != null)
		{
			names.addAll(match);
		}
		return Collections.unmodifiableList(names);
	}

	public boolean hasLevelRates()
	{
		return levelRates != null && !levelRates.isEmpty();
	}

	/** Rate text for a delve level, or null if the item can't drop there. */
	public String getLevelRate(int level)
	{
		return levelRates == null ? null : levelRates.get(String.valueOf(level));
	}

	/** Rate text for one part of a combined page, or null if that part doesn't drop it. */
	public String getPartRate(String part)
	{
		return partRates == null ? null : partRates.get(part);
	}

	public boolean hasPartRates()
	{
		return partRates != null && !partRates.isEmpty();
	}

	public boolean countsTowardAny()
	{
		return any == null || any;
	}

	public boolean isPet()
	{
		return pet != null && pet;
	}

	/**
	 * Items the collection log counts at most once: pets (duplicates aren't logged) and
	 * items that stop dropping after the first, like Royal Titans prayer scrolls.
	 */
	public boolean isOnce()
	{
		return isPet() || (once != null && once);
	}

	/**
	 * Most copies that count: 1 for pets and once-only items, the "max" from the data for a
	 * row of several once-only items (the two Royal Titans scrolls), 0 for no limit.
	 */
	public int getMax()
	{
		if (isOnce())
		{
			return 1;
		}
		return max == null ? 0 : max;
	}

	public boolean isNoShare()
	{
		return noShare != null && noShare;
	}

	public boolean isClogSharedFlag()
	{
		return clogShared != null && clogShared;
	}
}

package com.onrate.engine.data;

import lombok.Getter;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Average time for a kill or raid, bundled with the plugin (killtimes.json): the stand-in for the
 * Time page until you have enough timed kills of your own. Read once; nothing is fetched while
 * the plugin runs.
 */
public final class KillTimes
{
	private static KillTimes bundled;

	/** The only place a guide link may point at: the OSRS Wiki's article address. */
	private static final String WIKI_BASE = "https://oldschool.runescape.wiki/w/";

	private final Map<String, Raw> bosses;
	private final Doom doom;
	private final String guideBase;

	/** A figure from the file: kills (raids, completions) per hour, and where it comes from. */
	public static final class Estimate
	{
		@Getter private final double killsPerHour;
		@Getter private final List<String> guides;
		@Getter private final String note;
		@Getter private final boolean lowConfidence;

		Estimate(Raw raw)
		{
			this.killsPerHour = raw.kph;
			this.guides = raw.guides == null ? Collections.emptyList() : raw.guides;
			this.note = raw.note;
			this.lowConfidence = "low".equals(raw.confidence);
		}

		public double getSecondsPerKill()
		{
			return 3600.0 / killsPerHour;
		}
	}

	/** Doom of Mokhaiotl: time per delve level, banking per run and the depth assumed with no history. */
	public static final class Doom
	{
		private double[] secondsPerLevel;
		@Getter private double bankingSecondsPerRun;
		@Getter private int assumedDepthWithoutHistory = 8;

		/** Seconds for one delve of this level (1 to 8, 9 for the deep delves). */
		public double secondsFor(int level)
		{
			if (secondsPerLevel == null || secondsPerLevel.length == 0)
			{
				return Double.NaN;
			}
			return secondsPerLevel[Math.max(0, Math.min(secondsPerLevel.length, level) - 1)];
		}

		public boolean isAvailable()
		{
			return secondsPerLevel != null && secondsPerLevel.length > 0;
		}
	}

	private static final class Raw
	{
		Double kph;
		List<String> guides;
		String note;
		String confidence;
		Map<String, Raw> parts;
	}

	private static final class FileFormat
	{
		String guideUrl;
		Map<String, Raw> bosses;
		Doom doom;
	}

	private KillTimes(FileFormat file)
	{
		this.bosses = file.bosses == null ? Collections.emptyMap() : file.bosses;
		this.doom = file.doom == null ? new Doom() : file.doom;
		this.guideBase = file.guideUrl;
	}

	public static KillTimes load(Gson gson, Reader reader)
	{
		FileFormat file = gson.fromJson(reader, FileFormat.class);
		return new KillTimes(file == null ? new FileFormat() : file);
	}

	/**
	 * The file that ships with the plugin, loaded with the given Gson the first time and cached; empty (no estimates)
	 * if it can't be read.
	 */
	public static synchronized KillTimes bundled(Gson gson)
	{
		if (bundled == null)
		{
			try (Reader reader = new InputStreamReader(KillTimes.class.getResourceAsStream("/com/onrate/killtimes.json"),
				StandardCharsets.UTF_8))
			{
				bundled = load(gson, reader);
			}
			catch (Exception e)
			{
				bundled = new KillTimes(new FileFormat());
			}
		}
		return bundled;
	}

	/** The file loaded by {@link #bundled(Gson)}; empty (no estimates) until the plugin has loaded it. */
	public static synchronized KillTimes bundled()
	{
		return bundled == null ? new KillTimes(new FileFormat()) : bundled;
	}

	/**
	 * The figure for a boss, or for one part of a combined page (a raid mode, one boss of a pair);
	 * null when there is none. {@code part} is ignored for a boss without parts.
	 */
	public Estimate forBoss(String boss, String part)
	{
		Raw raw = bosses.get(boss);
		if (raw == null)
		{
			return null;
		}
		if (raw.parts != null)
		{
			Raw p = part == null ? null : raw.parts.get(part);
			return p == null || p.kph == null || p.kph <= 0 ? null : new Estimate(p);
		}
		return raw.kph == null || raw.kph <= 0 ? null : new Estimate(raw);
	}

	/** The parts of a combined page that have a figure, in file order. */
	public List<String> partsWithEstimate(String boss)
	{
		Raw raw = bosses.get(boss);
		List<String> names = new ArrayList<>();
		if (raw != null && raw.parts != null)
		{
			for (Map.Entry<String, Raw> e : raw.parts.entrySet())
			{
				if (e.getValue().kph != null && e.getValue().kph > 0)
				{
					names.add(e.getKey());
				}
			}
		}
		return names;
	}

	public Doom doom()
	{
		return doom;
	}

	/**
	 * The address of the OSRS Wiki page with this title (a guide from {@link Estimate#getGuides()}): spaces become
	 * underscores and anything else a link can't hold is percent-encoded, while {@code ' ( ) /} and letters and digits
	 * stay as they are. Null for an empty title, or when the file's base address is not the OSRS Wiki's.
	 */
	public String guideUrl(String title)
	{
		if (title == null || title.trim().isEmpty() || !WIKI_BASE.equals(guideBase))
		{
			return null;
		}
		StringBuilder sb = new StringBuilder(WIKI_BASE);
		for (byte b : title.trim().replace(' ', '_').getBytes(StandardCharsets.UTF_8))
		{
			char c = (char) (b & 0xff);
			if (c >= 'A' && c <= 'Z' || c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || "_-.~'()/,:!".indexOf(c) >= 0)
			{
				sb.append(c);
			}
			else
			{
				sb.append('%').append(Character.toUpperCase(Character.forDigit((b >> 4) & 0xf, 16)))
					.append(Character.toUpperCase(Character.forDigit(b & 0xf, 16)));
			}
		}
		return sb.toString();
	}
}

package com.onrate.engine.data;

import lombok.Getter;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The boss drops on the Ladlor ironman progression chart, in the order of the chart
 * (ladlorchart.json, bundled with the plugin). Each chart item lists the drops it needs.
 */
public final class LadlorChart
{
	private static LadlorChart bundled;

	private final List<Item> items;

	/** A drop a chart item needs, or a number of kills of a boss (a reward that is sure at that kill count). */
	public static final class Need
	{
		@Getter private String boss;
		@Getter private String drop;
		@Getter private Integer kills;
		private Integer count;

		/** How many of the drop are needed (crystal armour seeds: 3 for the body), at least 1. */
		public int getCount()
		{
			return count == null || count < 1 ? 1 : count;
		}
	}

	/** One item of the chart. */
	public static final class Item
	{
		@Getter private int step;
		@Getter private String name;
		@Getter private String icon;
		private List<Need> needs;
		@Getter private String note;
		@Getter private String route;

		public List<Need> getNeeds()
		{
			return needs == null ? Collections.emptyList() : needs;
		}
	}

	private static final class FileFormat
	{
		List<Item> items;
	}

	private LadlorChart(FileFormat file)
	{
		this.items = file.items == null ? new ArrayList<>() : file.items;
	}

	public static LadlorChart load(Gson gson, Reader reader)
	{
		FileFormat file = gson.fromJson(reader, FileFormat.class);
		return new LadlorChart(file == null ? new FileFormat() : file);
	}

	/**
	 * The file that ships with the plugin, loaded with the given Gson the first time and cached; empty
	 * if it can't be read.
	 */
	public static synchronized LadlorChart bundled(Gson gson)
	{
		if (bundled == null)
		{
			try (Reader reader = new InputStreamReader(LadlorChart.class.getResourceAsStream("/com/onrate/ladlorchart.json"),
				StandardCharsets.UTF_8))
			{
				bundled = load(gson, reader);
			}
			catch (Exception e)
			{
				bundled = new LadlorChart(new FileFormat());
			}
		}
		return bundled;
	}

	/** The file loaded by {@link #bundled(Gson)}; empty until the plugin has loaded it. */
	public static synchronized LadlorChart bundled()
	{
		return bundled == null ? new LadlorChart(new FileFormat()) : bundled;
	}

	/** The chart's items in chart order. */
	public List<Item> getItems()
	{
		return Collections.unmodifiableList(items);
	}
}

package com.onrate.engine.data;

import lombok.Getter;
import java.util.regex.Matcher;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.function.ToLongFunction;
import java.util.regex.Pattern;

/**
 * What an untradeable unique is worth, written in terms of tradeable items:
 * {@code "Amulet of rancour - Amulet of torture"}, {@code "Noxious halberd / 3"}.
 * Operators ({@code + - * /}) have spaces around them; a term is an item name or a number,
 * and {@code *} and {@code /} bind tighter than {@code +} and {@code -}.
 */
public final class ValueFormula
{
	private static final Pattern SUM_SPLIT = Pattern.compile("\\s([+-])\\s");
	private static final Pattern PRODUCT_SPLIT = Pattern.compile("\\s([*/])\\s");

	private final List<Character> signs = new ArrayList<>();
	private final List<List<String>> terms = new ArrayList<>();
	private final List<List<Character>> productOps = new ArrayList<>();
	@Getter private final Set<String> itemNames = new LinkedHashSet<>();

	private ValueFormula()
	{
	}

	public static ValueFormula parse(String text)
	{
		ValueFormula f = new ValueFormula();
		Matcher sums = SUM_SPLIT.matcher(text);
		int start = 0;
		char sign = '+';
		while (true)
		{
			boolean found = sums.find();
			f.addTerm(sign, text.substring(start, found ? sums.start() : text.length()).trim());
			if (!found)
			{
				break;
			}
			sign = sums.group(1).charAt(0);
			start = sums.end();
		}
		return f;
	}

	private void addTerm(char sign, String term)
	{
		List<String> factors = new ArrayList<>();
		List<Character> ops = new ArrayList<>();
		Matcher m = PRODUCT_SPLIT.matcher(term);
		int start = 0;
		while (m.find())
		{
			factors.add(term.substring(start, m.start()).trim());
			ops.add(m.group(1).charAt(0));
			start = m.end();
		}
		factors.add(term.substring(start).trim());
		for (String factor : factors)
		{
			if (factor.isEmpty())
			{
				throw new IllegalArgumentException("Empty term in value formula: " + term);
			}
			if (!isNumber(factor))
			{
				itemNames.add(factor);
			}
		}
		signs.add(sign);
		terms.add(factors);
		productOps.add(ops);
	}

	private static boolean isNumber(String s)
	{
		return s.matches("\\d+(\\.\\d+)?");
	}

	/**
	 * The value in GP, never below 0. 0 as well when any item in it has no price, since the
	 * rest of the formula would then be a wrong number rather than a small one.
	 */
	public long evaluate(ToLongFunction<String> price)
	{
		double total = 0;
		for (int t = 0; t < terms.size(); t++)
		{
			List<String> factors = terms.get(t);
			double value = 0;
			for (int f = 0; f < factors.size(); f++)
			{
				double x;
				String factor = factors.get(f);
				if (isNumber(factor))
				{
					x = Double.parseDouble(factor);
				}
				else
				{
					long p = price.applyAsLong(factor);
					if (p <= 0)
					{
						return 0;
					}
					x = p;
				}
				if (f == 0)
				{
					value = x;
				}
				else if (productOps.get(t).get(f - 1) == '*')
				{
					value *= x;
				}
				else
				{
					value /= x;
				}
			}
			total += signs.get(t) == '+' ? value : -value;
		}
		return Math.max(0, (long) total);
	}
}

package com.onrate.engine.math;

/**
 * Luck as a percentile in 0..1 (0.5 = average). Built from the {@link Poisson} shares, and
 * deliberately tie-aware: the most common result is never called dry.
 */
public final class Luck
{
	private Luck()
	{
	}

	/**
	 * Of the range from "share with fewer" to "share with this many or fewer", the point closest to
	 * the middle. So you only count as dry when few players have this many or fewer, and as spooned
	 * when few have this many or more. With big counts ties are rare and this is the usual percentile.
	 */
	public static double tieAware(double fewer, double same)
	{
		return Math.max(0, Math.min(1, Math.min(Math.max(0.5, fewer), fewer + same)));
	}

	/** Tie-aware luck behind every verdict. NaN when nothing is expected. */
	public static double of(int received, double expected)
	{
		double[] s = Poisson.shares(received, expected);
		return s == null ? Double.NaN : tieAware(s[0], s[1]);
	}

	/** Tie-aware luck when at most {@code cap} copies count. NaN when nothing is expected. */
	public static double ofCapped(int received, double expected, int cap)
	{
		double[] s = Poisson.sharesCapped(received, expected, cap);
		return s == null ? Double.NaN : tieAware(s[0], s[1]);
	}

	/**
	 * The mid-p percentile: players with fewer than you, plus half of those with exactly as many.
	 * NaN when nothing is expected yet.
	 */
	public static double midP(int received, double expected)
	{
		if (expected <= 0 || Double.isNaN(expected))
		{
			return Double.NaN;
		}
		double[] raw = Poisson.rawShares(Math.max(received, 0), expected);
		double p = raw[0] + 0.5 * raw[1];
		return Math.max(0, Math.min(1, p));
	}
}

package com.onrate.engine.math;

import java.util.List;

/**
 * Probability of drop counts. Every kill is an independent roll, so the number of drops after
 * n kills is binomial; with the small rates bosses use a Poisson with the same mean is an
 * excellent approximation, and it lets several items be added into one "any unique" row.
 *
 * <p>A "shares" result is {share of players with fewer than you, share with exactly as many};
 * the rest have more.
 */
public final class Poisson
{
	private Poisson()
	{
	}

	/** Chance of at least one drop in {@code kc} kills at {@code rate} per kill (binomial). */
	public static double chanceAtLeastOne(double rate, long kc)
	{
		if (kc <= 0 || rate <= 0)
		{
			return 0;
		}
		if (rate >= 1)
		{
			return 1;
		}
		return -Math.expm1(kc * Math.log1p(-rate));
	}

	/** Chance of at least one event when {@code expected} events are expected (Poisson). */
	public static double chanceAtLeastOne(double expected)
	{
		if (expected <= 0)
		{
			return 0;
		}
		return -Math.expm1(-expected);
	}

	/** Kills needed to reach {@code probability} chance of at least one drop. -1 if never. */
	public static long killsForChance(double rate, double probability)
	{
		if (rate <= 0 || probability <= 0)
		{
			return -1;
		}
		if (rate >= 1)
		{
			return 1;
		}
		return (long) Math.ceil(Math.log1p(-probability) / Math.log1p(-rate));
	}

	/** Expected number of copies that count when at most {@code cap} can: E[min(X, cap)], X Poisson. */
	public static double expectedCapped(double expected, int cap)
	{
		if (expected <= 0 || cap <= 0)
		{
			return 0;
		}
		double sum = 0;
		double p = Math.exp(-expected);
		double cdf = 0;
		for (int k = 0; k < cap; k++)
		{
			cdf += p;
			sum += 1 - cdf;
			p *= expected / (k + 1);
		}
		return sum;
	}

	/** Expected copies that count: the plain expected, or E[min(X, cap)] when at most {@code cap} count. */
	public static double expectedCounted(double expected, int cap)
	{
		return cap > 0 ? expectedCapped(expected, cap) : expected;
	}

	/** Shares for a plain (uncapped) count; null when nothing is expected. */
	public static double[] shares(int received, double expected)
	{
		if (expected <= 0 || Double.isNaN(expected))
		{
			return null;
		}
		double[] raw = rawShares(Math.max(received, 0), expected);
		return new double[]{Math.min(1, raw[0]), Math.min(1, raw[1])};
	}

	/**
	 * Unclamped {fewer, same} for {@code received} drops when {@code expected} are expected.
	 * Shared by {@link #shares} and {@link Luck#midP} so both use the very same arithmetic.
	 */
	static double[] rawShares(int received, double expected)
	{
		double logLambda = Math.log(expected);
		double logFactorial = 0;
		double below = 0;
		for (int j = 0; j < received; j++)
		{
			if (j > 0)
			{
				logFactorial += Math.log(j);
			}
			below += Math.exp(-expected + j * logLambda - logFactorial);
		}
		if (received > 0)
		{
			logFactorial += Math.log(received);
		}
		double equal = Math.exp(-expected + received * logLambda - logFactorial);
		return new double[]{below, equal};
	}

	/**
	 * Shares when at most {@code cap} copies count: everyone with {@code cap} or more is level with
	 * you. Null when nothing is expected.
	 */
	public static double[] sharesCapped(int received, double expected, int cap)
	{
		if (expected <= 0 || Double.isNaN(expected))
		{
			return null;
		}
		int r = Math.min(Math.max(received, 0), cap);
		double p = Math.exp(-expected);
		double below = 0;
		for (int k = 0; k < r; k++)
		{
			below += p;
			p *= expected / (k + 1);
		}
		double same = r < cap ? p : 1 - below;
		return new double[]{below, Math.max(0, same)};
	}

	/** {@link #sharesSum(int, int, double, double[], int[], List)} without guaranteed items. */
	public static double[] sharesSum(int received, int sure, double plain, double[] cappedMeans, int[] caps)
	{
		return sharesSum(received, sure, plain, cappedMeans, caps, null);
	}

	/**
	 * Shares for a total made of several items: {@code sure} copies that drop for certain, a part
	 * with no limit ({@code plain} expected), items of which at most {@code caps[i]} count (each
	 * with its uncapped mean {@code cappedMeans[i]}), and items that are sure on one kill only for a
	 * player with none yet ({@code guaranteed}: {kills, rate per kill, kill with the guarantee}).
	 * A capped item's count isn't Poisson, so the total isn't either: this adds the exact
	 * distributions. Null when nothing is expected.
	 */
	public static double[] sharesSum(int received, int sure, double plain, double[] cappedMeans, int[] caps,
		List<double[]> guaranteed)
	{
		int n = cappedMeans == null ? 0 : cappedMeans.length;
		int g = guaranteed == null ? 0 : guaranteed.size();
		if (n == 0 && g == 0 && sure <= 0)
		{
			return shares(received, plain);
		}
		double total = Math.max(0, sure) + (Double.isNaN(plain) ? 0 : Math.max(0, plain));
		for (int i = 0; i < n; i++)
		{
			total += expectedCapped(cappedMeans[i], caps[i]);
		}
		for (int i = 0; i < g; i++)
		{
			double[] item = guaranteed.get(i);
			total += guaranteedExpected(item[0], item[1], (int) item[2]);
		}
		if (!(total > 0))
		{
			return null;
		}
		int r = Math.max(received, 0) - Math.max(0, sure);
		if (r < 0)
		{
			// fewer than the sure copies: nobody has as few
			return new double[]{0, 0};
		}
		// only counts up to r matter for "fewer" and "the same"
		double[] pmf = poissonPmf(Double.isNaN(plain) ? 0 : plain, r);
		for (int i = 0; i < n; i++)
		{
			if (!(cappedMeans[i] > 0) || caps[i] <= 0)
			{
				continue;
			}
			double[] item = poissonPmf(cappedMeans[i], caps[i]);
			double rest = 1;
			for (int k = 0; k < caps[i]; k++)
			{
				rest -= item[k];
			}
			item[caps[i]] = Math.max(0, rest);
			pmf = convolve(pmf, item, caps[i], r, true);
		}
		for (int i = 0; i < g; i++)
		{
			double[] item = guaranteed.get(i);
			double[] own = guaranteedPmf(item[0], item[1], (int) item[2], r);
			pmf = convolve(pmf, own, r, r, false);
		}
		double below = 0;
		for (int k = 0; k < r; k++)
		{
			below += pmf[k];
		}
		return new double[]{Math.min(1, below), Math.min(1, pmf[r])};
	}

	/** Adds two independent counts, keeping totals up to {@code r}. */
	private static double[] convolve(double[] left, double[] right, int rightMax, int r, boolean skipEmptyLeft)
	{
		double[] next = new double[r + 1];
		for (int a = 0; a <= r; a++)
		{
			if (skipEmptyLeft && left[a] == 0)
			{
				continue;
			}
			for (int b = 0; b <= rightMax && a + b <= r; b++)
			{
				next[a + b] += left[a] * right[b];
			}
		}
		return next;
	}

	/**
	 * Expected copies of an item rolled at {@code rate} per kill that is also sure on kill
	 * {@code at} for a player who has none yet (Vorkath's head on the 50th): kills * rate, plus the
	 * extra copy that kill gives, (1 - rate)^at, from then on.
	 */
	public static double guaranteedExpected(double kills, double rate, int at)
	{
		double expected = kills * rate;
		return kills >= at ? expected + Math.pow(1 - rate, at) : expected;
	}

	/**
	 * Exact probabilities of 0..{@code max} copies after {@code kills} kills at {@code rate}, when
	 * kill {@code at} is a sure drop for a player with none from kills 1 to at - 1 and a plain roll
	 * otherwise. Nobody who has been through kill {@code at} has none.
	 */
	public static double[] guaranteedPmf(double kills, double rate, int at, int max)
	{
		int total = (int) Math.round(kills);
		if (total < at)
		{
			return binomialPmf(total, rate, max);
		}
		double miss = 1 - rate;
		double[] before = binomialPmf(at - 1, rate, max);
		// kills 1 to at - 1, then kill at: sure with none so far, a plain roll with one or more
		double[] upTo = new double[max + 1];
		for (int k = 0; k <= max; k++)
		{
			if (k == 0)
			{
				if (max >= 1)
				{
					upTo[1] += before[0];
				}
				continue;
			}
			upTo[k] += before[k] * miss;
			if (k + 1 <= max)
			{
				upTo[k + 1] += before[k] * rate;
			}
		}
		double[] after = binomialPmf(total - at, rate, max);
		return convolve(upTo, after, max, max, false);
	}

	private static double[] binomialPmf(int n, double p, int max)
	{
		double[] pmf = new double[max + 1];
		if (p <= 0)
		{
			pmf[0] = 1;
			return pmf;
		}
		if (p >= 1)
		{
			if (n <= max)
			{
				pmf[n] = 1;
			}
			return pmf;
		}
		double logChoose = 0;
		for (int k = 0; k <= Math.min(n, max); k++)
		{
			if (k > 0)
			{
				logChoose += Math.log((double) (n - k + 1) / k);
			}
			pmf[k] = Math.exp(logChoose + k * Math.log(p) + (n - k) * Math.log1p(-p));
		}
		return pmf;
	}

	private static double[] poissonPmf(double mean, int max)
	{
		double[] pmf = new double[max + 1];
		if (!(mean > 0))
		{
			pmf[0] = 1;
			return pmf;
		}
		double logMean = Math.log(mean);
		double logFactorial = 0;
		for (int k = 0; k <= max; k++)
		{
			if (k > 0)
			{
				logFactorial += Math.log(k);
			}
			pmf[k] = Math.exp(-mean + k * logMean - logFactorial);
		}
		return pmf;
	}
}

package com.onrate.engine.math;

import java.util.Locale;

/** Reading and writing drop rates ("1/50", "3/512", "0.02") and GP amounts. */
public final class Rates
{
	private Rates()
	{
	}

	/** Parses "1/50", "3/512" or a plain decimal like "0.02". Returns 0 for null or blank. */
	public static double parse(String rate)
	{
		if (rate == null || rate.trim().isEmpty())
		{
			return 0;
		}
		String s = rate.replace(",", "").trim();
		int slash = s.indexOf('/');
		if (slash < 0)
		{
			return Double.parseDouble(s);
		}
		double num = Double.parseDouble(s.substring(0, slash).trim());
		double den = Double.parseDouble(s.substring(slash + 1).trim());
		if (den <= 0)
		{
			throw new IllegalArgumentException("Bad rate: " + rate);
		}
		return num / den;
	}

	/** "1/181" style text for a per-kill rate. */
	public static String format(double rate)
	{
		if (rate <= 0)
		{
			return "unknown";
		}
		double inverse = 1.0 / rate;
		if (inverse < 10)
		{
			return String.format(Locale.ROOT, "1/%.2f", inverse);
		}
		if (Math.abs(inverse - Math.rint(inverse)) < 0.05 || inverse >= 1000)
		{
			return String.format(Locale.ROOT, "1/%,d", Math.round(inverse));
		}
		return String.format(Locale.ROOT, "1/%,.1f", inverse);
	}

	/** "1.24b", "345.6m", "12.3k" or "950" coins. */
	public static String gp(double gp)
	{
		double abs = Math.abs(gp);
		if (abs >= 1_000_000_000)
		{
			return String.format(Locale.ROOT, "%.2fb", gp / 1_000_000_000);
		}
		if (abs >= 1_000_000)
		{
			return String.format(Locale.ROOT, "%.1fm", gp / 1_000_000);
		}
		if (abs >= 1_000)
		{
			return String.format(Locale.ROOT, "%.1fk", gp / 1_000);
		}
		return String.format(Locale.ROOT, "%.0f", gp);
	}
}

package com.onrate.engine.math;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Locale;
import java.util.Set;

/** Araxxor's halberd pieces: untradeable, and no duplicates drop until a full set is made. */
public final class Untradeables
{
	private static final Set<String> HALBERD_PIECES = Collections.unmodifiableSet(new HashSet<>(
		Arrays.asList("noxious point", "noxious blade", "noxious pommel")));

	private Untradeables()
	{
	}

	public static boolean isHalberdPiece(String itemName)
	{
		return itemName != null && HALBERD_PIECES.contains(itemName.toLowerCase(Locale.ROOT));
	}

	public static int halberdPieceCount()
	{
		return HALBERD_PIECES.size();
	}

	/**
	 * GP the halberd pieces you have are worth: only full sets, since a piece alone can't be sold
	 * and duplicates don't drop before the set is done. {@code piecePrice} is a third of a halberd.
	 */
	public static long setValue(int pieces, long piecePrice)
	{
		return (pieces / HALBERD_PIECES.size()) * HALBERD_PIECES.size() * piecePrice;
	}
}

package com.onrate.engine.math;

import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Random;

/**
 * Luck by GP value. Rare, expensive items dominate value, so there is no formula: the kills are
 * simulated many times with a fixed seed (the number doesn't jump around between refreshes) and
 * your value is placed among the simulated players, ties counted like the counts do.
 */
public final class ValueLuck
{
	/** Players simulated for the account and boss GP verdicts. */
	public static final int SAMPLES = 5000;
	/** The fixed seed the account GP verdict has always used. */
	public static final long SEED = 1234567L;

	private ValueLuck()
	{
	}

	/**
	 * @param expected expected number of drops per item
	 * @param prices   price per item (0 for untradeables, which are skipped)
	 * @param caps     at most {@code caps[i]} copies of an item count (0 for no limit); may be null
	 * @param received total value actually received
	 * @return luck between 0 and 1, or NaN when nothing of value is expected yet
	 */
	public static double of(double[] expected, long[] prices, int[] caps, long received, int samples, long seed)
	{
		// Only items with a price and a chance take part; keeping them in the same order means
		// the random numbers, and so the result, are the same as drawing for every item.
		int n = 0;
		double total = 0;
		for (int i = 0; i < expected.length; i++)
		{
			if (prices[i] > 0)
			{
				total += Poisson.expectedCounted(expected[i], caps == null ? 0 : caps[i]) * prices[i];
				if (expected[i] > 0)
				{
					n++;
				}
			}
		}
		if (total <= 0)
		{
			return Double.NaN;
		}
		double[] means = new double[n];
		double[] limits = new double[n];
		long[] values = new long[n];
		int[] itemCaps = new int[n];
		int j = 0;
		for (int i = 0; i < expected.length; i++)
		{
			if (prices[i] > 0 && expected[i] > 0)
			{
				means[j] = expected[i];
				limits[j] = Math.exp(-expected[i]);
				values[j] = prices[i];
				itemCaps[j] = caps == null ? 0 : Math.max(0, caps[i]);
				j++;
			}
		}
		Key key = new Key(means, values, itemCaps, received, samples, seed);
		synchronized (CACHE)
		{
			Double cached = CACHE.get(key);
			if (cached != null)
			{
				return cached;
			}
		}
		Random random = new Random(seed);
		double below = 0;
		double equal = 0;
		for (int s = 0; s < samples; s++)
		{
			long value = 0;
			for (int i = 0; i < n; i++)
			{
				long copies = poisson(random, means[i], limits[i]);
				if (itemCaps[i] > 0)
				{
					copies = Math.min(copies, itemCaps[i]);
				}
				value += copies * values[i];
			}
			if (value < received)
			{
				below += 1;
			}
			else if (value == received)
			{
				equal += 1;
			}
		}
		// ties (often: nothing tradeable yet, like most players) handled like the counts
		double luck = Luck.tieAware(below / samples, equal / samples);
		synchronized (CACHE)
		{
			CACHE.put(key, luck);
		}
		return luck;
	}

	/** Without caps. */
	public static double of(double[] expected, long[] prices, long received, int samples, long seed)
	{
		return of(expected, prices, null, received, samples, seed);
	}

	/** A random number of drops when {@code mean} are expected. */
	public static long poisson(Random random, double mean)
	{
		return poisson(random, mean, Math.exp(-mean));
	}

	/** The last few results: switching tabs or re-opening a boss asks for the same numbers. */
	private static final Map<Key, Double> CACHE = new LinkedHashMap<Key, Double>(16, 0.75f, true)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<Key, Double> eldest)
		{
			return size() > 32;
		}
	};

	private static long poisson(Random random, double mean, double limit)
	{
		if (mean > 30)
		{
			// normal approximation is accurate here and much faster
			return Math.max(0, Math.round(mean + Math.sqrt(mean) * random.nextGaussian()));
		}
		double product = random.nextDouble();
		long count = 0;
		while (product > limit)
		{
			product *= random.nextDouble();
			count++;
		}
		return count;
	}

	private static final class Key
	{
		private final double[] means;
		private final long[] values;
		private final int[] caps;
		private final long received;
		private final int samples;
		private final long seed;
		private final int hash;

		Key(double[] means, long[] values, int[] caps, long received, int samples, long seed)
		{
			this.means = means;
			this.values = values;
			this.caps = caps;
			this.received = received;
			this.samples = samples;
			this.seed = seed;
			this.hash = Objects.hash(Arrays.hashCode(means), Arrays.hashCode(values), Arrays.hashCode(caps),
				received, samples, seed);
		}

		@Override
		public boolean equals(Object o)
		{
			if (!(o instanceof Key))
			{
				return false;
			}
			Key k = (Key) o;
			return hash == k.hash && received == k.received && samples == k.samples && seed == k.seed
				&& Arrays.equals(means, k.means) && Arrays.equals(values, k.values) && Arrays.equals(caps, k.caps);
		}

		@Override
		public int hashCode()
		{
			return hash;
		}
	}
}

package com.onrate.engine.math;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The nine words a luck value can earn, driest first. One definition shared by every list,
 * tile, overlay, trip card and graph.
 *
 * <p>Luck is a percentile in 0..1 (0.5 = average). A value exactly on a line goes to the side
 * nearer the middle: 1% is Very dry, 35% is A bit dry, 45% and 55% are On rate, 65% is A bit
 * spooned, 99% is Very spooned.
 */
public enum Verdict
{
	EXTREMELY_DRY("Extremely dry"),
	VERY_DRY("Very dry"),
	DRY("Dry"),
	A_BIT_DRY("A bit dry"),
	ON_RATE("On rate"),
	A_BIT_SPOONED("A bit spooned"),
	SPOONED("Spooned"),
	VERY_SPOONED("Very spooned"),
	EXTREMELY_SPOONED("Extremely spooned");

	/** Below this luck it is dry; at or above it the middle band starts. */
	public static final double DRY_BELOW = 0.35;
	/** Above this luck it is spooned. */
	public static final double SPOONED_ABOVE = 0.65;
	/** Under this many expected uniques there is nothing to read yet ("Too early"). */
	public static final double TOO_EARLY_BELOW = 0.5;
	/**
	 * The smaller cut-off for one trip (the trip card and the overlay): under this many expected uniques a trip
	 * says "Too early" instead of a verdict. A trip is short by nature, so it keeps a lower bar than a boss page.
	 */
	public static final double TRIP_TOO_EARLY_BELOW = 0.05;

	/** Whether a trip with this many uniques expected is too small to judge ({@code NaN} is not: it has its own dash). */
	public static boolean tripTooEarly(double expected)
	{
		return expected < TRIP_TOO_EARLY_BELOW;
	}

	private final String label;

	Verdict(String label)
	{
		this.label = label;
	}

	public String label()
	{
		return label;
	}

	/** 0 (extremely dry) to 8 (extremely spooned). */
	public int band()
	{
		return ordinal();
	}

	public boolean isDry()
	{
		return ordinal() < ON_RATE.ordinal();
	}

	public boolean isSpooned()
	{
		return ordinal() > ON_RATE.ordinal();
	}

	/** Every word, driest first. */
	public static List<String> labels()
	{
		List<String> labels = new ArrayList<>();
		for (Verdict v : values())
		{
			labels.add(v.label);
		}
		return Collections.unmodifiableList(labels);
	}

	/** The verdict for a luck percentile, or null when there is nothing to judge (NaN). */
	public static Verdict of(double luck)
	{
		if (Double.isNaN(luck))
		{
			return null;
		}
		int band;
		if (luck < 0.01)
		{
			band = 0;
		}
		else if (luck < 0.10)
		{
			band = 1;
		}
		else if (luck < DRY_BELOW)
		{
			band = 2;
		}
		else if (luck < 0.45)
		{
			band = 3;
		}
		else if (luck <= 0.55)
		{
			band = 4;
		}
		else if (luck <= SPOONED_ABOVE)
		{
			band = 5;
		}
		else if (luck <= 0.90)
		{
			band = 6;
		}
		else if (luck <= 0.99)
		{
			band = 7;
		}
		else
		{
			band = 8;
		}
		return values()[band];
	}

	/** The word for a luck percentile, or "" when there is nothing to judge. */
	public static String labelOf(double luck)
	{
		Verdict v = of(luck);
		return v == null ? "" : v.label;
	}

	/** True when {@code luck} reads "On rate" (false for NaN). */
	public static boolean isOnRate(double luck)
	{
		return of(luck) == ON_RATE;
	}

	/**
	 * Where a luck value sits on the nine-step Rate Line, 0 (far left, driest) to 1 (far right).
	 * Every verdict gets an equal ninth, and the value moves along inside its own band, so the
	 * 1% and 99% bands stay readable. Null luck (NaN) gives NaN.
	 */
	public static double position(double luck)
	{
		Verdict v = of(luck);
		if (v == null)
		{
			return Double.NaN;
		}
		double lo = LOWER[v.ordinal()];
		double hi = LOWER[v.ordinal() + 1];
		double within = hi > lo ? Math.max(0, Math.min(1, (luck - lo) / (hi - lo))) : 0.5;
		return (v.ordinal() + within) / 9.0;
	}

	/** Lower edge of each band, plus 1 at the end. */
	private static final double[] LOWER = {0, 0.01, 0.10, 0.35, 0.45, 0.55, 0.65, 0.90, 0.99, 1};
}

package com.onrate.engine.raids;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;

/**
 * Estimates your contribution in The Fractured Archive from the damage you and your team deal.
 * Jagex's loot post: each room hands out 100 contribution (Ocellus 300) split by damage, minion
 * damage included. The game doesn't show the number, so this adds up the hitsplats On Rate sees:
 * yours, and the other players' (the game shows them on monsters too).
 *
 * <p>NPC IDs are from the OSRS Wiki's boss pages and its Strategies page (November 2026). Not
 * modelled, because Jagex hasn't said how they work: the soft cap on minion damage, and how
 * Ocellus's 300 is split between his phases (here it is one share of all his damage).
 */
public class FracturedContribution
{
	/** The five fights of a run: the Archive Guardian, one of each pair, then Ocellus. */
	enum Room
	{
		ARCHIVE_GUARDIAN(0, 100, 16659, 16660, 16664),
		EZEKIEL(1, 100, 16652, 16653),
		BORK(1, 100, 16640, 16641),
		MOIA(2, 100, 16667, 16670),
		DREADNOTH(2, 100, 16665, 16666),
		DAGONHAI_ELDER(3, 100, 16643, 16644, 16646, 16647, 16648, 16650),
		XARTH(3, 100, 16684, 16687, 16688),
		OCELLUS(4, 300, 16672, 16673, 16674, 16675, 16676, 16677, 16678, 16679, 16680, 16681);

		/** Which of the five fights this is (rooms of a pair share it). */
		final int slot;
		final double contribution;
		final int[] npcIds;

		Room(int slot, double contribution, int... npcIds)
		{
			this.slot = slot;
			this.contribution = contribution;
			this.npcIds = npcIds;
		}
	}

	static final int SLOTS = 5;

	private static final Map<Integer, Room> BY_NPC = new HashMap<>();

	static
	{
		for (Room room : Room.values())
		{
			for (int id : room.npcIds)
			{
				BY_NPC.put(id, room);
			}
		}
	}

	/** What On Rate saw of one raid. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class Result
	{
		/** Your contribution out of 700 before deaths, or -1 when a fight was missed. */
		public final double contribution;
		/** Your deaths in the raid. */
		public final int deaths;
	}

	private final Map<Room, long[]> damage = new EnumMap<>(Room.class);
	private int deaths;

	/** True when the NPC belongs to The Fractured Archive. */
	public static boolean isArchiveNpc(int npcId)
	{
		return BY_NPC.containsKey(npcId);
	}

	/**
	 * A hitsplat on a monster. Only player damage counts (yours or another player's), not poison,
	 * venom, burns or healing, which have no owner.
	 */
	public void onHitsplat(int npcId, int amount, boolean mine, boolean others)
	{
		Room room = BY_NPC.get(npcId);
		if (room == null || amount <= 0 || !mine && !others)
		{
			return;
		}
		if (room == Room.ARCHIVE_GUARDIAN && seenPastGuardian())
		{
			// the Archive Guardian is the first fight: this is a new raid (the last one was wiped or missed)
			reset();
		}
		long[] d = damage.computeIfAbsent(room, r -> new long[2]);
		d[0] += mine ? amount : 0;
		d[1] += amount;
	}

	/** You died: counted only during a raid On Rate is following. */
	public void onLocalDeath()
	{
		if (isActive())
		{
			deaths++;
		}
	}

	/** True once a fight of this raid was seen. */
	public boolean isActive()
	{
		return !damage.isEmpty();
	}

	/**
	 * The raid is complete: what it saw, then starts over. Null when it saw nothing of the raid.
	 * The contribution is -1 unless all five fights were seen (On Rate turned on mid-raid, say).
	 */
	public Result finish()
	{
		if (!isActive())
		{
			return null;
		}
		boolean[] seen = new boolean[SLOTS];
		double contribution = 0;
		for (Map.Entry<Room, long[]> e : damage.entrySet())
		{
			long[] d = e.getValue();
			if (d[1] > 0)
			{
				seen[e.getKey().slot] = true;
				contribution += e.getKey().contribution * d[0] / d[1];
			}
		}
		boolean all = true;
		for (boolean s : seen)
		{
			all &= s;
		}
		Result result = new Result(all ? contribution : -1, deaths);
		reset();
		return result;
	}

	public void reset()
	{
		damage.clear();
		deaths = 0;
	}

	private boolean seenPastGuardian()
	{
		for (Room room : damage.keySet())
		{
			if (room != Room.ARCHIVE_GUARDIAN)
			{
				return true;
			}
		}
		return false;
	}
}

package com.onrate.engine.raids;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import com.google.gson.*;
import java.io.BufferedReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import net.runelite.client.util.Filepath;

/**
 * Reads your raid times from the Raid Data Tracker plugin's log files, so raids start on your own
 * times instead of waiting for five timed raids. Read only: it never writes to that plugin's folder, and
 * it reads only the folder the player picked with RuneLite's file chooser.
 *
 * <p>The plugin keeps one file per raid, {@code raid_tracker_data.log}, with one JSON object per
 * line, in {@code .runelite/raid-data tracker/<name>/<raid>/} (the folder name has a space in it; older
 * versions kept the raid folders directly in {@code raid-data tracker/}). Only completed raids of this
 * account (matched by its account hash) with a plausible time are taken, so a second account's raids or
 * a raid you left don't count. Its times are in whole seconds.
 *
 * <p>Which time: the whole raid's time ({@code raidTime}), which the plugin reads from the game's
 * "Duration" (Chambers) or "total completion time" (Tombs) message. For Tombs that is the total, not the
 * challenge time ({@code toaCompTime}): On Rate counts only the total there. Chambers and Tombs only: the
 * plugin does not record whether a Theatre of Blood raid was Normal or Hard Mode, so those times can't be
 * told apart and are left out.
 */
public final class RaidDataImport
{
	/** A raid time shorter than this isn't a finished raid (a record from a failed or abandoned run). */
	static final long MIN_MILLIS = 2 * 60_000L;
	/** A raid time longer than this is a stuck timer, not a raid. */
	static final long MAX_MILLIS = 3 * 60 * 60_000L;
	static final int MILLIS_PER_SECOND = 1000;
	/** The other plugin's folder inside {@code .runelite}: the name has a space, not a hyphen, before "tracker". */
	public static final String FOLDER = "raid-data tracker";
	/** The log file each raid folder holds. */
	static final String LOG_NAME = "raid_tracker_data.log";
	/** Raid folders of the other plugin; "unknown" holds raids it could not place and is skipped. */
	private static final String[] RAIDS = {"cox", "toa"};

	/** The boss name On Rate uses for each folder. */
	private static String boss(String raid)
	{
		switch (raid)
		{
			case "cox":
				return "Chambers of Xeric";
			default:
				return "Tombs of Amascut";
		}
	}

	private RaidDataImport()
	{
	}

	/**
	 * One finished raid as the other plugin saved it: its mode and that mode's completion count, when
	 * it ended, how long it took (-1 when unknown), the team, the points, the raid level (Tombs only,
	 * else -1) and the unique it gave you (null for none, or a unique that went to a teammate).
	 */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class Raid
	{
		public final String part;
		public final int kc;
		public final long when;
		public final long millis;
		public final int teamSize;
		public final int personalPoints;
		public final int totalPoints;
		public final int raidLevel;
		public final String unique;
	}

	/** One raid time, by boss and raid mode. {@code when} is when the raid ended, in epoch millis. */
	public static final class Times
	{
		/** Boss, then mode, then {when, millis} pairs. */
		private final Map<String, Map<String, List<long[]>>> byBoss = new LinkedHashMap<>();
		/** Boss, then its whole raids in the order read. */
		private final Map<String, List<Raid>> raids = new LinkedHashMap<>();

		void addRaid(String boss, Raid raid)
		{
			raids.computeIfAbsent(boss, k -> new ArrayList<>()).add(raid);
		}

		/** The whole raids read, per boss. */
		public Map<String, List<Raid>> raids()
		{
			return raids;
		}

		void add(String boss, String part, long when, long millis)
		{
			byBoss.computeIfAbsent(boss, k -> new LinkedHashMap<>()).computeIfAbsent(part, k -> new ArrayList<>())
				.add(new long[]{when, millis});
		}

		public Map<String, Map<String, List<long[]>>> byBoss()
		{
			return byBoss;
		}

		public int count()
		{
			int n = 0;
			for (Map<String, List<long[]>> parts : byBoss.values())
			{
				for (List<long[]> list : parts.values())
				{
					n += list.size();
				}
			}
			return n;
		}
	}

	/**
	 * The times of {@code accountHash} found under the folder the player chose (Raid Data Tracker's
	 * folder, or the {@code .runelite} folder that holds it), or none when it has no raid logs.
	 * Unreadable files and lines are skipped.
	 */
	public static Times read(Filepath chosen, long accountHash)
	{
		Times times = new Times();
		if (chosen == null || !chosen.isDirectory() || accountHash == -1)
		{
			return times;
		}
		Filepath root = chosen;
		try
		{
			Filepath inside = chosen.joinSegment(FOLDER);
			if (inside.isDirectory())
			{
				root = inside;
			}
		}
		catch (RuntimeException e)
		{
			// read the folder as it was chosen
		}
		Filepath top = root;
		List<Filepath> folders = new ArrayList<>();
		folders.add(top);
		try (Stream<Filepath> children = top.walk(1))
		{
			folders.addAll(children.filter(f -> !f.equals(top) && f.isDirectory()).collect(Collectors.toList()));
		}
		catch (IOException | RuntimeException e)
		{
			// unreadable folder: the top level only
		}
		for (Filepath folder : folders)
		{
			for (String raid : RAIDS)
			{
				try
				{
					Filepath log = folder.joinSegment(raid).joinSegment(LOG_NAME);
					if (log.isFile())
					{
						readLog(log, raid, accountHash, times);
					}
				}
				catch (RuntimeException e)
				{
					// skip this folder
				}
			}
		}
		return times;
	}

	private static void readLog(Filepath log, String raid, long accountHash, Times times)
	{
		try (BufferedReader reader = log.openBufferedReader())
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				line = line.trim();
				if (!line.isEmpty())
				{
					readLine(line, raid, accountHash, times);
				}
			}
		}
		catch (IOException | RuntimeException e)
		{
			// a file being written or in another encoding: take what was read, skip the rest
		}
	}

	private static void readLine(String line, String raid, long accountHash, Times times)
	{
		JsonObject o;
		try
		{
			JsonElement e = new JsonParser().parse(line);
			if (!e.isJsonObject())
			{
				return;
			}
			o = e.getAsJsonObject();
		}
		catch (RuntimeException e)
		{
			return;
		}
		try
		{
			addRecord(o, raid, accountHash, times);
		}
		catch (RuntimeException e)
		{
			// a field with the wrong type: skip this line only
		}
	}

	private static void addRecord(JsonObject o, String raid, long accountHash, Times times)
	{
		if (!has(o, "accountHash") || o.get("accountHash").getAsLong() != accountHash || !bool(o, "raidComplete"))
		{
			return;
		}
		long when = has(o, "date") ? o.get("date").getAsLong() : 0;
		String part = part(o, raid);
		if (when <= 0 || part == null)
		{
			return;
		}
		int seconds = seconds(o);
		long millis = seconds <= 0 ? -1 : (long) seconds * MILLIS_PER_SECOND;
		boolean plausible = millis >= MIN_MILLIS && millis <= MAX_MILLIS;
		if (plausible)
		{
			times.add(boss(raid), part, when, millis);
		}
		int kc = num(o, "completionCount");
		int personal = num(o, "personalPoints");
		if (kc > 0 && personal > 0)
		{
			// the unique only counts when it was yours, not a teammate's
			String unique = bool(o, "specialLootInOwnName") && has(o, "specialLoot") ? o.get("specialLoot").getAsString().trim() : "";
			times.addRaid(boss(raid), new Raid(part, kc, when, plausible ? millis : -1, Math.max(0, num(o, "teamSize")), personal,
				Math.max(0, num(o, "totalPoints")), "toa".equals(raid) ? num(o, "raidLevel") : -1, unique.isEmpty() ? null : unique));
		}
	}

	/** The raid's whole time in seconds (see the class comment): -1 when there is none. */
	private static int seconds(JsonObject o)
	{
		return num(o, "raidTime");
	}

	/**
	 * The raid mode, as On Rate names its parts. Tombs of Amascut modes come from the raid level
	 * (Entry below 150, Normal 150 to 295, Expert from 300), because the other plugin's completion
	 * count mixes the modes.
	 */
	static String part(JsonObject o, String raid)
	{
		switch (raid)
		{
			case "cox":
				return bool(o, "challengeMode") ? "Challenge Mode" : "Normal";
			default:
				int level = num(o, "raidLevel");
				if (level < 0)
				{
					return null;
				}
				return level >= 300 ? "Expert Mode" : level >= 150 ? "Normal" : "Entry Mode";
		}
	}

	private static boolean has(JsonObject o, String key)
	{
		return o.has(key) && o.get(key).isJsonPrimitive();
	}

	private static boolean bool(JsonObject o, String key)
	{
		return has(o, key) && o.get(key).getAsBoolean();
	}

	private static int num(JsonObject o, String key)
	{
		return has(o, key) ? o.get(key).getAsInt() : -1;
	}
}

package com.onrate.engine.stats;

import lombok.Getter;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * The whole account at once: one row per boss with kills, plus a total.
 */
public class AccountStats
{
	@Getter private final RowStats total;
	@Getter private final List<RowStats> rows;
	private final Map<String, Integer> killCounts;
	@Getter private double expectedValue;
	@Getter private long receivedValue;
	@Getter private double valueLuck = Double.NaN;
	@Getter private List<ItemHighlight> items = Collections.emptyList();
	@Getter private List<String> unsynced = Collections.emptyList();

	public AccountStats(RowStats total, List<RowStats> rows, Map<String, Integer> killCounts)
	{
		this.total = total;
		this.rows = Collections.unmodifiableList(rows);
		this.killCounts = Collections.unmodifiableMap(killCounts);
	}

	public void setValue(double expectedValue, long receivedValue, double valueLuck)
	{
		this.expectedValue = expectedValue;
		this.receivedValue = receivedValue;
		this.valueLuck = valueLuck;
	}

	public void setItems(List<ItemHighlight> items)
	{
		this.items = Collections.unmodifiableList(items);
	}

	public int getKillCount(String boss)
	{
		Integer kc = killCounts.get(boss);
		return kc == null ? 0 : kc;
	}

	public void setUnsynced(List<String> unsynced)
	{
		this.unsynced = Collections.unmodifiableList(unsynced);
	}
}

package com.onrate.engine.stats;

import lombok.Getter;
import lombok.Setter;
import com.onrate.engine.data.DropDefinition;

import com.onrate.engine.data.BossDefinition;
import java.util.List;
import java.util.Map;

/**
 * Everything the panel needs to draw one boss.
 */
public class BossStats
{
	@Getter private final BossDefinition boss;
	@Getter private final int killCount;
	@Getter private final boolean killCountKnown;
	@Getter private final boolean clogSynced;
	@Getter private final RowStats anyRow;
	@Getter private final List<RowStats> rows;
	@Getter private final double raidUniqueChance;
	@Getter private final Map<Integer, Integer> levelCounts;
	@Getter @Setter private Map<String, Integer> partCounts;
	@Setter private List<DropDefinition> drops;

	public BossStats(BossDefinition boss, int killCount, boolean killCountKnown, boolean clogSynced,
		RowStats anyRow, List<RowStats> rows, double raidUniqueChance, Map<Integer, Integer> levelCounts)
	{
		this.levelCounts = levelCounts;
		this.boss = boss;
		this.killCount = killCount;
		this.killCountKnown = killCountKnown;
		this.clogSynced = clogSynced;
		this.anyRow = anyRow;
		this.rows = rows;
		this.raidUniqueChance = raidUniqueChance;
	}

	/**
	 * The drop of each row, in the same order: the boss's own uniques, then any shared items
	 * the player chose to judge on each boss separately.
	 */
	public List<DropDefinition> getDrops()
	{
		return drops != null ? drops : boss.getDrops();
	}
}

package com.onrate.engine.stats;

import lombok.Getter;
import java.util.Collections;
import java.util.List;

/**
 * One item of the Ladlor chart you don't have yet, and how long it takes to get all of what it
 * needs. See {@link ChartTimes}.
 */
public class ChartTime
{
	/** One drop (or set of kills) the chart item needs. */
	public static final class Part
	{
		@Getter private final String label;
		@Getter private final String boss;
		@Getter private final boolean have;
		@Getter private final double seconds;
		@Getter private final double chancePerKill;
		@Getter private final double secondsPerKill;
		@Getter private final String dropKey;
		@Getter private final int missing;

		Part(String label, String boss, boolean have, double seconds, double chancePerKill, double secondsPerKill)
		{
			this(label, boss, have, seconds, chancePerKill, secondsPerKill, null, 0);
		}

		Part(String label, String boss, boolean have, double seconds, double chancePerKill, double secondsPerKill, String dropKey, int missing)
		{
			this.dropKey = dropKey;
			this.missing = missing;
			this.label = label;
			this.boss = boss;
			this.have = have;
			this.seconds = seconds;
			this.chancePerKill = chancePerKill;
			this.secondsPerKill = secondsPerKill;
		}
	}

	@Getter private final int step;
	@Getter private final String name;
	@Getter private final String icon;
	@Getter private final String note;
	@Getter private final List<Part> parts;
	@Getter private final double seconds;
	@Getter private final boolean estimated;
	private final boolean usesOwn;
	@Getter private String route;

	ChartTime(int step, String name, String icon, String note, List<Part> parts, double seconds, boolean estimated, boolean usesOwn)
	{
		this.step = step;
		this.name = name;
		this.icon = icon;
		this.note = note;
		this.parts = Collections.unmodifiableList(parts);
		this.seconds = seconds;
		this.estimated = estimated;
		this.usesOwn = usesOwn;
	}

	ChartTime withRoute(String route)
	{
		this.route = route;
		return this;
	}

	public boolean hasTime()
	{
		return !Double.isNaN(seconds);
	}

	public boolean usesOwnTimes()
	{
		return usesOwn;
	}

	/** Where the time comes from, short: "your times", "wiki rate" or "wiki + yours". */
	public String getSourceTag()
	{
		return !estimated ? "your times" : usesOwn ? "wiki + yours" : "wiki rate";
	}
}

package com.onrate.engine.stats;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Getter;
import java.util.Arrays;
import com.onrate.engine.data.KillTimes;
import java.util.function.Predicate;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.LadlorChart;
import com.onrate.engine.tracking.Tracker;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * How long each item of the Ladlor chart that you don't have takes, in the order of the chart.
 *
 * <p>A chart item is counted as the drops that give it: one or more, some of them several times
 * (crystal armour seeds: 3 for the body). Drops at different bosses are separate grinds, so their
 * times add up. Several drops at one boss (the three Oathplate pieces) come on the same kills, so
 * that boss's time is the expected number of kills until every one has dropped, times the time of
 * a kill. Each drop's time per kill and chance come from the Time page's calculation
 * ({@link ItemTimes}).
 *
 * <p>The collection log counts a drop once, however many chart items it went into, so the copies
 * you have are shared out along the chart: the first chart item that needs the drop takes its
 * copies first (the body's three seeds, then the helm's one, then the legs' two).
 */
public final class ChartTimes
{
	private ChartTimes()
	{
	}

	/** Items of the chart you are still missing something of, in chart order. */
	public static List<ChartTime> compute(Tracker tracker, KillTimes web, RaidSettings raids, LadlorChart chart)
	{
		return compute(tracker, web, raids, chart, boss -> true);
	}

	/**
	 * The chart items you are missing something of, leaving out any that needs a drop of a boss
	 * {@code allowed} doesn't let through (a Slayer boss above your level).
	 */
	public static List<ChartTime> compute(Tracker tracker, KillTimes web, RaidSettings raids, LadlorChart chart,
		Predicate<String> allowed)
	{
		List<ItemTime> all = ItemTimes.compute(tracker, web, raids, allowed);
		Map<String, Map<String, ItemTime>> byBoss = new LinkedHashMap<>();
		for (ItemTime t : all)
		{
			byBoss.computeIfAbsent(t.getBoss(), k -> new LinkedHashMap<>())
				.put(BossCatalog.normalize(t.getIconItem()), t);
		}
		// copies of each drop already given to an earlier chart item
		Map<String, Integer> taken = new LinkedHashMap<>();
		List<ChartTime> result = new ArrayList<>();
		for (LadlorChart.Item item : chart.getItems())
		{
			if (item.getNeeds().stream().anyMatch(need -> !allowed.test(need.getBoss())))
			{
				continue;
			}
			ChartTime t = timeOf(tracker, raids, byBoss, taken, item);
			if (t != null)
			{
				result.add(t);
			}
		}
		return result;
	}

	/** Null when you have everything the item needs. */
	private static ChartTime timeOf(Tracker tracker, RaidSettings raids, Map<String, Map<String, ItemTime>> byBoss,
		Map<String, Integer> taken, LadlorChart.Item item)
	{
		List<ChartTime.Part> parts = new ArrayList<>();
		// the missing drops of each boss, which come on the same kills (with how many copies of each)
		Map<String, List<ItemTime>> missingAtBoss = new LinkedHashMap<>();
		Map<String, List<Integer>> missingCounts = new LinkedHashMap<>();
		double seconds = 0;
		boolean unknown = false;
		boolean estimated = false;
		boolean usesOwn = false;
		boolean anythingMissing = false;
		for (LadlorChart.Need need : item.getNeeds())
		{
			Map<String, ItemTime> rows = byBoss.get(need.getBoss());
			if (need.getDrop() != null)
			{
				ItemTime drop = rows == null ? null : rows.get(BossCatalog.normalize(need.getDrop()));
				if (drop == null)
				{
					// no time for this boss (or a drop that isn't on its page): the item can't be timed
					parts.add(new ChartTime.Part(need.getDrop(), need.getBoss(), false, Double.NaN, Double.NaN, Double.NaN));
					unknown = true;
					anythingMissing = true;
					continue;
				}
				String key = need.getBoss() + "|" + BossCatalog.normalize(need.getDrop());
				int copies = need.getCount();
				int before = taken.getOrDefault(key, 0);
				taken.put(key, before + copies);
				// the copies you have go to the chart items in order
				int missing = copies - Math.max(0, Math.min(copies, drop.getReceived() - before));
				String label = copies > 1 ? copies + " x " + drop.getLabel() : drop.getLabel();
				parts.add(new ChartTime.Part(label, need.getBoss(), missing == 0, missing * drop.getSecondsPerDrop(),
					drop.getChancePerKill(), drop.getSecondsPerKill(), key, missing));
				if (missing > 0)
				{
					anythingMissing = true;
					missingAtBoss.computeIfAbsent(need.getBoss(), k -> new ArrayList<>()).add(drop);
					missingCounts.computeIfAbsent(need.getBoss(), k -> new ArrayList<>()).add(missing);
					estimated |= drop.isEstimated();
					usesOwn |= drop.usesOwnTimes();
				}
			}
			else if (need.getKills() != null)
			{
				// a reward that is sure at a kill count: the kills still to do
				BossStats stats = tracker.stats(need.getBoss(), raids);
				int done = stats == null ? 0 : stats.getKillCount();
				int left = Math.max(0, need.getKills() - done);
				String label = need.getKills() + " " + need.getBoss() + " kills";
				ItemTime any = rows == null || rows.isEmpty() ? null : rows.values().iterator().next();
				if (left == 0)
				{
					parts.add(new ChartTime.Part(label, need.getBoss(), true, 0, Double.NaN, Double.NaN));
				}
				else if (any == null)
				{
					parts.add(new ChartTime.Part(label, need.getBoss(), false, Double.NaN, Double.NaN, Double.NaN));
					unknown = true;
					anythingMissing = true;
				}
				else
				{
					double s = left * any.getSecondsPerKill();
					parts.add(new ChartTime.Part(label + " (" + left + " to go)", need.getBoss(), false, s, Double.NaN, any.getSecondsPerKill()));
					seconds += s;
					anythingMissing = true;
					estimated |= any.isEstimated();
					usesOwn |= any.usesOwnTimes();
				}
			}
		}
		if (!anythingMissing)
		{
			return null;
		}
		for (Map.Entry<String, List<ItemTime>> e : missingAtBoss.entrySet())
		{
			List<ItemTime> group = e.getValue();
			double[] chances = new double[group.size()];
			int[] counts = new int[group.size()];
			for (int i = 0; i < chances.length; i++)
			{
				chances[i] = group.get(i).getChancePerKill();
				counts[i] = missingCounts.get(e.getKey()).get(i);
			}
			seconds += expectedKillsForAll(chances, counts) * group.get(0).getSecondsPerKill();
		}
		ChartTime result = new ChartTime(item.getStep(), item.getName(), item.getIcon(), item.getNote(), parts,
			unknown ? Double.NaN : seconds, estimated, usesOwn);
		if ("oathplate-shards".equals(item.getRoute()))
		{
			List<ItemTime> yama = missingAtBoss.get("Yama");
			if (yama != null && !yama.isEmpty())
			{
				long yamaNeeds = item.getNeeds().stream().filter(n -> "Yama".equals(n.getBoss()) && n.getDrop() != null).count();
				result.withRoute(OathplateShards.describe(yama.stream().mapToDouble(ItemTime::getChancePerKill).toArray(),
					yama.get(0).getSecondsPerKill(), (int) (yamaNeeds - yama.size())));
			}
		}
		return result;
	}

	/** The time for everything the listed chart items still need, and how many items had no time and are left out of it. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class Total
	{
		@Getter private final double seconds;
		@Getter private final int withoutTime;
	}

	/**
	 * How long everything on the list takes together. Drops at one boss, across all the chart's items
	 * (the five Chambers items, say), come on the same kills, and the same drop in two items (the
	 * crystal seeds of the body, helm and legs) is one grind of all its copies, so this is less than
	 * the items added up.
	 */
	public static Total total(List<ChartTime> items)
	{
		// per boss: each drop with its chance and how many copies are missing in all
		Map<String, Map<String, double[]>> dropsAtBoss = new LinkedHashMap<>();
		Map<String, Double> secondsAtBoss = new LinkedHashMap<>();
		double seconds = 0;
		int without = 0;
		for (ChartTime item : items)
		{
			if (!item.hasTime())
			{
				without++;
				continue;
			}
			for (ChartTime.Part part : item.getParts())
			{
				if (part.isHave())
				{
					continue;
				}
				if (part.getDropKey() == null)
				{
					// the kills to go for a reward that is sure at a kill count
					seconds += part.getSeconds();
				}
				else
				{
					double[] slot = dropsAtBoss.computeIfAbsent(part.getBoss(), k -> new LinkedHashMap<>())
						.computeIfAbsent(part.getDropKey(), k -> new double[]{part.getChancePerKill(), 0});
					slot[1] += part.getMissing();
					secondsAtBoss.putIfAbsent(part.getBoss(), part.getSecondsPerKill());
				}
			}
		}
		for (Map.Entry<String, Map<String, double[]>> e : dropsAtBoss.entrySet())
		{
			double[] chances = new double[e.getValue().size()];
			int[] counts = new int[chances.length];
			int i = 0;
			for (double[] slot : e.getValue().values())
			{
				chances[i] = slot[0];
				counts[i++] = (int) slot[1];
			}
			seconds += expectedKillsForAll(chances, counts) * secondsAtBoss.get(e.getKey());
		}
		return new Total(seconds, without);
	}

	/**
	 * Expected number of kills until every drop has dropped at least once, when each kill rolls
	 * each drop independently at its own chance (inclusion and exclusion over the sets of drops).
	 */
	public static double expectedKillsForAll(double[] chances)
	{
		int[] ones = new int[chances.length];
		Arrays.fill(ones, 1);
		return expectedKillsForAll(chances, ones);
	}

	/**
	 * Expected number of kills until drop {@code i} has dropped {@code counts[i]} times, for every
	 * drop, each rolled independently at its own chance on every kill. One copy of each is worked
	 * out exactly by inclusion and exclusion over the sets of drops; more than one by adding up,
	 * kill by kill, the chance that something is still missing (the expected value of a wait is the
	 * sum of the chances that it is not over yet).
	 */
	public static double expectedKillsForAll(double[] chances, int[] counts)
	{
		int n = chances.length;
		if (n == 0)
		{
			return 0;
		}
		boolean single = true;
		for (int c : counts)
		{
			single &= c == 1;
		}
		if (single)
		{
			if (n > 12)
			{
				throw new IllegalArgumentException("too many drops at one boss");
			}
			double expected = 0;
			for (int set = 1; set < (1 << n); set++)
			{
				double p = 0;
				int bits = 0;
				for (int i = 0; i < n; i++)
				{
					if ((set & (1 << i)) != 0)
					{
						p += chances[i];
						bits++;
					}
				}
				expected += (bits % 2 == 1 ? 1 : -1) / p;
			}
			return expected;
		}
		// dist[i][j]: the chance of exactly j copies of drop i so far, the last slot being "all of them"
		double[][] dist = new double[n][];
		for (int i = 0; i < n; i++)
		{
			dist[i] = new double[counts[i] + 1];
			dist[i][0] = 1;
		}
		double expected = 0;
		for (long kill = 0; kill < 50_000_000L; kill++)
		{
			double allDone = 1;
			for (int i = 0; i < n; i++)
			{
				allDone *= dist[i][counts[i]];
			}
			double stillMissing = 1 - allDone;
			expected += stillMissing;
			if (stillMissing < 1e-12)
			{
				break;
			}
			for (int i = 0; i < n; i++)
			{
				double p = chances[i];
				double[] d = dist[i];
				int need = counts[i];
				d[need] += d[need - 1] * p;
				for (int j = need - 1; j >= 1; j--)
				{
					d[j] = d[j] * (1 - p) + d[j - 1] * p;
				}
				d[0] *= 1 - p;
			}
		}
		return expected;
	}
}

package com.onrate.engine.stats;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Getter;
import com.onrate.engine.data.*;
import com.onrate.engine.tracking.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;

/**
 * How long each boss's collection log page takes to finish: the items you don't have, each its own
 * roll (see {@link LogForecast}), at the time of one kill the Time page uses (your own average once you
 * have enough timed kills, else the OSRS Wiki's rate).
 *
 * <p>An item the log counts once for several bosses (dragon pickaxe) is on every page that lists it:
 * it is missing on all of them until you have it from anywhere, and each page uses its own boss's chance.
 * A shared item whose log page hasn't been opened yet is left out, as On Rate can't tell if you have it.
 */
public final class GreenLog
{
	/** Half of players with these chances are done by then. */
	public static final double MEDIAN = 0.5;
	/** Nine in ten players with these chances are done by then. */
	public static final double LIKELY = 0.9;

	private GreenLog()
	{
	}

	/** One boss's page. */
	public static final class Page
	{
		@Getter private final String boss;
		@Getter private final List<String> missing;
		@Getter private final boolean petLeftOut;
		@Getter private final double secondsPerKill;
		@Getter private final boolean estimated;
		@Getter private final String unit;
		@Getter private final double averageSeconds;
		@Getter private final double medianSeconds;
		@Getter private final double likelySeconds;

		Page(String boss, List<String> missing, boolean petLeftOut, double secondsPerKill, boolean estimated, String unit,
			double averageSeconds, double medianSeconds, double likelySeconds)
		{
			this.averageSeconds = averageSeconds;
			this.boss = boss;
			this.missing = Collections.unmodifiableList(missing);
			this.petLeftOut = petLeftOut;
			this.secondsPerKill = secondsPerKill;
			this.estimated = estimated;
			this.unit = unit;
			this.medianSeconds = medianSeconds;
			this.likelySeconds = likelySeconds;
		}

		public boolean isDone()
		{
			return missing.isEmpty();
		}

		/**
		 * The average time to get everything missing, the figure the Time page and Ladlor's chart give (for one
		 * item, its time per kill over its chance). 0 when done, NaN when it can't be said.
		 */
	}

	/** One missing item: its label, its chance in a kill and whether it's a pet. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class Missing
	{
		final String label;
		final double chance;
		final boolean pet;
	}

	/**
	 * The page of every boss {@code allowed} lets through that has something to go on, by boss name.
	 * A boss with no items counted (nothing known about its drops) isn't in the map.
	 *
	 * @param withPets false: pets are left out, so a page missing only its pet is done
	 */
	public static Map<String, Page> compute(Tracker tracker, KillTimes web, RaidSettings raids, Predicate<String> allowed,
		boolean withPets)
	{
		Map<String, List<ItemTime>> timed = new LinkedHashMap<>();
		for (ItemTime t : ItemTimes.compute(tracker, web, raids, allowed))
		{
			timed.computeIfAbsent(t.getBoss(), k -> new ArrayList<>()).add(t);
		}
		BossCatalog catalog = tracker.getCatalog();
		List<SharedPool> pools = tracker.sharedPools(raids);
		Map<String, Page> result = new LinkedHashMap<>();
		for (BossDefinition boss : catalog.getBosses())
		{
			if (!allowed.test(boss.getName()) || boss.getWaves() > 0)
			{
				continue;
			}
			List<Missing> missing = new ArrayList<>();
			boolean petLeftOut = false;
			int known = 0;
			double seconds = Double.NaN;
			boolean estimated = true;
			String unit = Tracker.unit(boss);
			for (ItemTime t : timed.getOrDefault(boss.getName(), Collections.emptyList()))
			{
				known++;
				seconds = t.getSecondsPerKill();
				estimated = t.isEstimated();
				unit = t.getUnit();
				if (t.isHave())
				{
					continue;
				}
				if (t.isPet() && !withPets)
				{
					petLeftOut = true;
					continue;
				}
				missing.add(new Missing(t.getLabel(), t.getChancePerKill(), t.isPet()));
			}
			BossStats stats = null;
			for (SharedPool pool : pools)
			{
				if (!pool.isLogKnown() || !pool.getBosses().contains(boss.getName()))
				{
					continue;
				}
				for (BossCatalog.PoolSource src : catalog.getPools().getOrDefault(pool.getKey(), Collections.emptyList()))
				{
					if (!src.getBoss().getName().equals(boss.getName()))
					{
						continue;
					}
					known++;
					if (pool.getReceived() > 0)
					{
						continue;
					}
					DropDefinition drop = src.getDrop();
					if (drop.isPet() && !withPets)
					{
						petLeftOut = true;
						continue;
					}
					stats = stats != null ? stats : tracker.stats(boss.getName(), raids);
					missing.add(new Missing(pool.getLabel(), sharedChance(boss, drop, stats, raids), drop.isPet()));
				}
			}
			if (known == 0)
			{
				continue;
			}
			if (Double.isNaN(seconds))
			{
				// only shared items: the boss's time per kill is not on any item
				stats = stats != null ? stats : tracker.stats(boss.getName(), raids);
				seconds = ItemTimes.secondsPerKill(tracker, web, boss, stats);
				estimated = !ownTimes(tracker, boss, stats);
			}
			result.put(boss.getName(), page(boss.getName(), missing, petLeftOut, seconds, estimated, unit));
		}
		return result;
	}

	private static Page page(String boss, List<Missing> missing, boolean petLeftOut, double seconds, boolean estimated, String unit)
	{
		List<String> labels = new ArrayList<>();
		double[] chances = new double[missing.size()];
		for (int i = 0; i < chances.length; i++)
		{
			labels.add(missing.get(i).label);
			chances[i] = missing.get(i).chance;
		}
		return new Page(boss, labels, petLeftOut, seconds, estimated, unit,
			averageSeconds(chances, seconds), seconds(chances, MEDIAN, seconds), seconds(chances, LIKELY, seconds));
	}

	/** At most this many items are worked out exactly (see {@link ChartTimes#expectedKillsForAll}); more are summed kill by kill. */
	private static final int EXACT_ITEMS = 12;

	/**
	 * The average seconds to get every item: the same figure the Time page and Ladlor's chart give. It is higher
	 * than the median (half of players are done by then) because a few players wait very long.
	 */
	static double averageSeconds(double[] chances, double secondsPerKill)
	{
		if (chances.length == 0)
		{
			return 0;
		}
		for (double c : chances)
		{
			if (!(c > 0))
			{
				return Double.NaN;
			}
		}
		if (!(secondsPerKill > 0))
		{
			return Double.NaN;
		}
		if (chances.length <= EXACT_ITEMS)
		{
			return ChartTimes.expectedKillsForAll(chances) * secondsPerKill;
		}
		// a big page: the average wait is the sum over kills of the chance that something is still missing
		double kills = 0;
		double k = 0;
		while (k < 1e9)
		{
			double step = Math.max(1, Math.floor(k * 0.01));
			double still = 1 - LogForecast.chanceDone(chances, (long) k);
			if (still < 1e-12)
			{
				break;
			}
			kills += still * step;
			k += step;
		}
		return kills * secondsPerKill;
	}

	/** Seconds to finish with this chance, or NaN when an item can't drop or the time of a kill isn't known. */
	static double seconds(double[] chances, double chance, double secondsPerKill)
	{
		if (chances.length == 0)
		{
			return 0;
		}
		long kills = LogForecast.raidsFor(chances, chance);
		return kills == LogForecast.NEVER || !(secondsPerKill > 0) ? Double.NaN : kills * secondsPerKill;
	}

	/** The chance of a shared drop in one kill at this boss; for a combined page, the mode you did most. */
	private static double sharedChance(BossDefinition boss, DropDefinition drop, BossStats stats, RaidSettings raids)
	{
		if (!boss.hasParts())
		{
			return RateModel.effectiveRate(boss, drop, raids);
		}
		BossPart best = boss.getParts().get(0);
		Map<String, Integer> counts = stats == null ? null : stats.getPartCounts();
		int most = 0;
		for (BossPart part : boss.getParts())
		{
			int n = counts == null ? 0 : counts.getOrDefault(part.getName(), 0);
			if (n > most)
			{
				most = n;
				best = part;
			}
		}
		return RateModel.partRate(boss, best, drop, raids);
	}

	/** True when the boss's time per kill is from your own timed kills (enough of them), not the wiki. */
	private static boolean ownTimes(Tracker tracker, BossDefinition boss, BossStats stats)
	{
		int need = boss.getRaid() != null ? ItemTimes.MIN_TIMED_RAIDS : ItemTimes.MIN_TIMED_KILLS;
		if (boss.hasParts())
		{
			// parts: own times only when every part you did has enough
			Map<String, Integer> counts = stats == null ? null : stats.getPartCounts();
			boolean any = false;
			for (BossPart part : boss.getParts())
			{
				if (counts == null || counts.getOrDefault(part.getName(), 0) <= 0)
				{
					continue;
				}
				TimeStats own = tracker.killTimes(boss.getName(), part.getName());
				if (own == null || own.getCount() < need)
				{
					return false;
				}
				any = true;
			}
			return any;
		}
		TimeStats own = tracker.killTimes(boss.getName(), null);
		return own != null && own.getCount() >= need;
	}
}

