package com.onrate.engine.tracking;

import java.util.Set;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * What we know about one boss for one account. Saved as JSON in the RuneLite profile.
 */
public class BossProgress
{
	/** Latest kill count per chat counter name (e.g. normal and challenge mode). */
	Map<String, Integer> chatKc = new HashMap<>();
	/** Latest kill count per collection log counter label. */
	Map<String, Integer> clogKc = new HashMap<>();
	/** Kills seen through the loot tracker since the plugin was installed. */
	int lootKills;
	/** Loot-only bosses: lootKills when the log page was last read, to add kills since then. */
	Integer lootKillsAtSync;
	/** Group bosses: kills per team size (players around you at the kill) that On Rate saw. */
	Map<Integer, Integer> teamKills = new HashMap<>();
	/** Received count per normalized item name. */
	Map<String, Integer> received = new HashMap<>();
	/** True once the boss's collection log page has been opened. */
	boolean clogSynced;
	/** Delve bosses only: completions per delve level (9 = "8+"). */
	Map<Integer, Integer> levelKc = new HashMap<>();
	/** Delve bosses only: true once the scoreboard has been read. */
	boolean levelsSynced;
	/** Kill count at the last drop of each item that On Rate saw (normalized item name). */
	Map<String, Integer> lastDropKc = new HashMap<>();
	/** Kill count when On Rate first knew it; how long ago older drops came is unknown. */
	Integer trackingStartKc;
	/**
	 * Content with loot per reward roll (Tempoross): the rolls from before On Rate counted them,
	 * estimated once (subdues times the rolls per subdue, minus the permits not spent yet).
	 * Null until known. Rolls counted since are in {@link #lootKills}.
	 */
	Integer rollBase;
	/** Wave runs (Fortis Colosseum): runs claimed, per the wave they were claimed at. Null in older saves. */
	Map<Integer, Integer> waveClaims;
	/** Fewest kills between two drops of an item that On Rate saw (normalized item name). Null in older saves. */
	Map<String, Integer> fastestGap;
	/** Most kills between two drops of an item that On Rate saw. Null in older saves. */
	Map<String, Integer> longestGap;
	/** Wave runs: last-wave claims On Rate had counted when the log page was last read. */
	Integer lastWaveClaimsAtSync;
	/**
	 * Group bosses: the share of a kill used for the kills from before On Rate counted teams,
	 * fixed when it started counting. Null until then (they count as solo).
	 */
	Double olderShare;
	/**
	 * Items the player left out of the calculations (normalized item names), e.g. an Araxyte
	 * head that came from a slayer task, or jars they don't care about. Null in older saves.
	 */
	Set<String> leftOut;
	/**
	 * Copies of shared items (pool key) On Rate saw this boss drop, for judging them per boss
	 * (see {@link PoolSplit}). Null in older saves.
	 */
	Map<String, Integer> poolSeen;
	/** Highest milestone already announced per item in its current dry streak. */
	Map<String, Integer> milestone = new HashMap<>();
	/** Kill count at the last milestone check, so a big jump (first sync) stays quiet. */
	Integer lastCheckedKc;
	/**
	 * Raids only: times read from another plugin's log (Raid Data Tracker), per raid mode: {when it
	 * ended in epoch millis, how long it took in millis}. Null in older saves and until something is imported.
	 */
	Map<String, List<long[]>> importedTimes;
	/** Raids only: each raid finished with On Rate, with its points (see RaidRecord). */
	/**
	 * Saved raids with their points. Kept out of the main save (it's saved per raid under its own
	 * key, only when a raid is added), so a kill elsewhere doesn't rewrite all of them.
	 */
	transient List<RaidRecord> raids = new ArrayList<>();
	/** Raids as earlier versions saved them, inside the main data; moved out when loaded. */
	@com.google.gson.annotations.SerializedName("raids")
	List<RaidRecord> savedRaids;
	/**
	 * The last kills On Rate saw, newest last, for the History section. Saved under its own
	 * key per boss (see Tracker#changedKills), not with the rest of this.
	 */
	transient List<KillEntry> kills = new ArrayList<>();

	void ensureMaps()
	{
		if (chatKc == null)
		{
			chatKc = new HashMap<>();
		}
		if (clogKc == null)
		{
			clogKc = new HashMap<>();
		}
		if (levelKc == null)
		{
			levelKc = new HashMap<>();
		}
		if (lastDropKc == null)
		{
			lastDropKc = new HashMap<>();
		}
		if (milestone == null)
		{
			milestone = new HashMap<>();
		}
		if (raids == null)
		{
			raids = new ArrayList<>();
		}
		if (kills == null)
		{
			kills = new ArrayList<>();
		}
		if (received == null)
		{
			received = new HashMap<>();
		}
		if (teamKills == null)
		{
			teamKills = new HashMap<>();
		}
	}
}

package com.onrate.engine.tracking;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Getter;
import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads how long a kill or raid took from the game's chat messages ("Fight duration: 1:01.20",
 * "Team size: 3 players Duration: 26:10.20", "Subdued in 5:12.60"...). The wordings are the ones
 * RuneLite's chat commands plugin reads for personal bests. Times of single rooms and waves
 * ("Wave 'The Maiden of Sugadinti' complete! Duration: 1:41.40") are not the time of the whole
 * kill, so they are ignored.
 */
public final class ChatTimes
{
	/** A reading from a message that names the whole kill or raid time. */
	public static final int RANK_TOTAL = 3;
	/** A reading from a plain "duration:" style message. */
	public static final int RANK_KILL = 2;

	private static final String TIME = "(\\d+(?::\\d{2}){1,2}(?:\\.\\d+)?)";
	private static final long MAX_MILLIS = 24L * 60 * 60 * 1000;

	/** Chambers of Xeric: "Congratulations - your raid is complete! Team size: 3 players Duration: 26:10.20". */
	private static final Pattern RAID_COMPLETE = Pattern.compile("your raid is complete!?.*?duration:\\s*" + TIME, Pattern.CASE_INSENSITIVE);
	/** Tombs of Amascut: "Tombs of Amascut: Expert Mode challenge completion time: 31:35.40". Not used: only the total counts. */
	private static final Pattern CHALLENGE_TIME = Pattern.compile("challenge completion time:\\s*" + TIME, Pattern.CASE_INSENSITIVE);
	/**
	 * The whole run: "Theatre of Blood total completion time: 23:50.40", "Tombs of Amascut: Expert Mode total
	 * completion time: 36:00.00", "The Fractured Archive: Total completion time: 12:00.00".
	 */
	private static final Pattern TOTAL_TIME = Pattern.compile("total completion time:\\s*" + TIME, Pattern.CASE_INSENSITIVE);
	/** Bosses, the Gauntlet ("Challenge duration"), Tempoross ("Subdued in"), other timed content. */
	private static final Pattern KILL_TIME = Pattern.compile(
		"(?:(?:fight |lap |challenge |corrupted challenge )?duration:|subdued in|(?<!total )completion time:)\\s*" + TIME,
		Pattern.CASE_INSENSITIVE);
	/** Messages about a part of a run: their time is not the run's. */
	private static final Pattern PART_OF_A_RUN = Pattern.compile("\\bwave\\b|\\broom\\b|challenge complete|\\bphase\\b", Pattern.CASE_INSENSITIVE);

	private ChatTimes()
	{
	}

	/** A time read from a message and how sure we are it is the whole kill's. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class Reading
	{
		@Getter private final int millis;
		@Getter private final int rank;
	}

	/** The time of the whole kill or raid in this message, or null when it has none. */
	public static Reading read(String message)
	{
		if (message == null)
		{
			return null;
		}
		String plain = message.replace("<br>", " ").replaceAll("<[^>]*>", "").replaceAll("@[^@\\s]{1,12}@", "");
		if (PART_OF_A_RUN.matcher(plain).find())
		{
			return null;
		}
		if (CHALLENGE_TIME.matcher(plain).find())
		{
			// Tombs: the challenge time leaves out the rooms around the fight; the total that comes with it is used instead
			return null;
		}
		Reading r = first(RAID_COMPLETE, plain, RANK_TOTAL);
		if (r == null)
		{
			r = first(TOTAL_TIME, plain, RANK_TOTAL);
		}
		if (r == null)
		{
			r = first(KILL_TIME, plain, RANK_KILL);
		}
		return r;
	}

	private static Reading first(Pattern pattern, String plain, int rank)
	{
		Matcher m = pattern.matcher(plain);
		if (!m.find())
		{
			return null;
		}
		int millis = parseMillis(m.group(1));
		return millis > 0 ? new Reading(millis, rank) : null;
	}

	/** "26:10.20", "1:01.2", "1:02:03" to milliseconds; 0 when it isn't a sensible time. */
	public static int parseMillis(String time)
	{
		if (time == null)
		{
			return 0;
		}
		String[] parts = time.trim().split(":");
		if (parts.length < 2 || parts.length > 3)
		{
			return 0;
		}
		try
		{
			double seconds = Double.parseDouble(parts[parts.length - 1]);
			long minutes = Long.parseLong(parts[parts.length - 2]);
			long hours = parts.length == 3 ? Long.parseLong(parts[0]) : 0;
			long total = Math.round((hours * 3600 + minutes * 60 + seconds) * 1000);
			return total > 0 && total < MAX_MILLIS ? (int) total : 0;
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	/** "26:10", "1:01.2" (tenths under ten minutes), "1:02:03" for an hour or more. */
	public static String format(int millis)
	{
		if (millis <= 0)
		{
			return "";
		}
		long tenths = Math.round(millis / 100.0);
		long totalSeconds = tenths / 10;
		long hours = totalSeconds / 3600;
		long minutes = totalSeconds % 3600 / 60;
		long seconds = totalSeconds % 60;
		if (hours > 0)
		{
			return String.format(Locale.ROOT, "%d:%02d:%02d", hours, minutes, seconds);
		}
		if (millis < 10 * 60_000)
		{
			return String.format(Locale.ROOT, "%d:%02d.%d", minutes, seconds, tenths % 10);
		}
		return String.format(Locale.ROOT, "%d:%02d", minutes, seconds);
	}
}

package com.onrate.engine.tracking;

import lombok.AllArgsConstructor;
import lombok.Getter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Turns what a collection log page shows (plain values copied from the client's widgets) into
 * the page title, its counters and the quantity obtained of each item. No client needed, so it
 * can be tested; the plugin only copies the widgets into these values.
 */
public final class ClogPage
{
	/**
	 * Opacity of an item the player has: the log draws items they don't have faded (more than 0).
	 * RuneLite has no constant for it; it is how the log draws. To re-check after a game update:
	 * run the plugin with `./gradlew run`, open a log page, and compare the opacity of an owned
	 * and a missing item in RuneLite's widget inspector (children of InterfaceID.Collection.ITEMS_CONTENTS).
	 */
	public static final int OBTAINED_OPACITY = 0;

	/** A counter line such as "Vorkath kills: 1,234". */
	private static final Pattern COUNTER_LINE = Pattern.compile(".*:\\s*[\\d,]+\\s*");

	/** One item of a page, as the widget shows it. */
	@AllArgsConstructor
	public static final class Item
	{
		final String name;
		final int quantity;
		final int opacity;
	}

	/** Why a page could not be read. */
	public enum Problem
	{
		/** No title: the header widget has no lines or its first line is empty. */
		NO_TITLE,
		/** The first header line is a counter, so the header layout is not what we expect. */
		TITLE_IS_A_COUNTER,
		/** The title is there but no item could be read. */
		NO_ITEMS,
	}

	/** What was read. Use title, counters and items only when {@link #getProblem()} is null. */
	public static final class Result
	{
		@Getter private final Problem problem;
		@Getter private final String title;
		@Getter private final List<String> counters;
		@Getter private final Map<String, Integer> items;
		@Getter private final boolean allFaded;

		Result(Problem problem, String title, List<String> counters, Map<String, Integer> items, boolean allFaded)
		{
			this.problem = problem;
			this.title = title;
			this.counters = Collections.unmodifiableList(counters);
			this.items = Collections.unmodifiableMap(items);
			this.allFaded = allFaded;
		}
	}

	private ClogPage()
	{
	}

	/**
	 * @param rawTitle    first header line as drawn (may have tags), or null when the header has no lines
	 * @param rawCounters the other header lines, as drawn
	 * @param items       every item widget of the page that holds an item
	 */
	public static Result parse(String rawTitle, List<String> rawCounters, List<Item> items)
	{
		String title = rawTitle == null ? "" : stripTags(rawTitle).trim();

		List<String> counters = new ArrayList<>();
		if (rawCounters != null)
		{
			for (String line : rawCounters)
			{
				String text = line == null ? "" : stripTags(line).trim();
				if (!text.isEmpty())
				{
					counters.add(text);
				}
			}
		}

		Map<String, Integer> obtained = new LinkedHashMap<>();
		boolean anyObtained = false;
		if (items != null)
		{
			for (Item item : items)
			{
				if (item == null || item.name == null || item.name.isEmpty())
				{
					continue;
				}
				boolean has = item.opacity == OBTAINED_OPACITY;
				obtained.put(item.name, has ? Math.max(1, item.quantity) : 0);
				anyObtained |= has;
			}
		}
		boolean allFaded = !obtained.isEmpty() && !anyObtained;

		Problem problem = title.isEmpty() ? Problem.NO_TITLE
			: COUNTER_LINE.matcher(title).matches() ? Problem.TITLE_IS_A_COUNTER
			: obtained.isEmpty() ? Problem.NO_ITEMS
			: null;
		return new Result(problem, title, counters, obtained, allFaded);
	}

	private static String stripTags(String text)
	{
		return text.replaceAll("<[^>]*>", "");
	}
}

package com.onrate.engine.tracking;

import com.onrate.engine.data.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.TreeMap;

import static com.onrate.engine.tracking.Tracker.DELVE_SCOREBOARD;

/**
 * The collection log: which pages On Rate covers, reading a page (kill counts, received counts, the
 * kill count tracking starts from, shared item totals) without ever zeroing drops already saved,
 * pages that could not be read this session, the boss with the most kills, and the checklist of pages
 * still to open.
 * <p>
 * Package-private and unsynchronized: reached only through {@link Tracker}, under its lock.
 */
final class ClogSync
{
	private final TrackerContext ctx;
	private final BossCatalog catalog;
	private final Statistics statistics;

	/**
	 * Collection log pages we cover that were opened but could not be read this session (normalized
	 * title to the title shown). Never saved: it says nothing about the data, only about the last read.
	 */
	private final Map<String, String> unreadablePages = new LinkedHashMap<>();
	/** A log page was opened whose header could not be read, so we don't know which page it was. */
	private boolean headerUnreadable;

	ClogSync(TrackerContext ctx, Statistics statistics)
	{
		this.ctx = ctx;
		this.catalog = ctx.catalog;
		this.statistics = statistics;
	}

	/** Another account was loaded: what could not be read was about the last one's log. */
	void clear()
	{
		unreadablePages.clear();
		headerUnreadable = false;
	}

	/** This boss was reset: its pages count as not tried yet. */
	void forget(String bossName)
	{
		BossDefinition resetBoss = catalog.byName(bossName);
		if (resetBoss != null)
		{
			for (String page : resetBoss.getClogPages())
			{
				unreadablePages.remove(BossCatalog.normalize(page));
			}
		}
	}

	/** True when the collection log page with this title is one On Rate reads. */
	boolean coversPage(String pageTitle)
	{
		return !catalog.byClogPage(pageTitle).isEmpty();
	}

	/**
	 * A collection log page was opened but could not be read. Changes no saved data. Pass a null or
	 * empty title when not even the title could be read.
	 *
	 * @return true when this is worth telling the player: the page is one we cover, or the title is unknown
	 */
	boolean onClogPageUnreadable(String pageTitle)
	{
		if (pageTitle == null || pageTitle.isEmpty())
		{
			headerUnreadable = true;
			return true;
		}
		if (!coversPage(pageTitle))
		{
			return false;
		}
		unreadablePages.put(BossCatalog.normalize(pageTitle), pageTitle);
		return true;
	}

	/** True when a log page of this boss was opened this session but could not be read. */
	boolean logPageUnreadable(String bossName)
	{
		BossDefinition boss = catalog.byName(bossName);
		if (boss == null)
		{
			return false;
		}
		for (String page : boss.getClogPages())
		{
			if (unreadablePages.containsKey(BossCatalog.normalize(page)))
			{
				return true;
			}
		}
		return false;
	}

	/** Titles of the pages we cover that were opened but could not be read this session. */
	List<String> unreadablePages()
	{
		return new ArrayList<>(unreadablePages.values());
	}

	/** True when a log page was opened whose title could not be read. */
	boolean isHeaderUnreadable()
	{
		return headerUnreadable;
	}

	/**
	 * True when applying this page would set a count we already hold above zero back to zero: every
	 * item reads as not obtained, but a drop on the page is saved as received. The log never loses
	 * items, so this is a page that was misread, not a player who lost drops. A fresh account whose
	 * page is truly all faded has nothing saved and is not flagged.
	 */
	boolean wouldZeroSaved(String pageTitle, Map<String, Integer> items)
	{
		if (items.isEmpty())
		{
			return false;
		}
		for (int quantity : items.values())
		{
			if (quantity > 0)
			{
				return false;
			}
		}
		for (BossDefinition boss : catalog.byClogPage(pageTitle))
		{
			BossProgress progress = ctx.state().peek(boss.getName());
			for (DropDefinition drop : boss.getDrops())
			{
				for (String name : drop.getAllNames())
				{
					String key = BossCatalog.normalize(name);
					if (findQuantity(items, key) == null)
					{
						continue;
					}
					Integer saved = catalog.isClogShared(key) ? ctx.state().sharedClog().get(key)
						: progress == null ? null : progress.received.get(key);
					if (saved != null && saved > 0)
					{
						return true;
					}
				}
			}
		}
		return false;
	}

	/**
	 * Handles an opened collection log page.
	 *
	 * @param pageTitle page title, e.g. "Vorkath"
	 * @param counters  header lines like "Vorkath kills: 123", tags already removed
	 * @param items     every item on the page with its obtained quantity (0 if not obtained)
	 * @return bosses whose numbers changed
	 */
	Set<String> onClogPage(String pageTitle, List<String> counters, Map<String, Integer> items)
	{
		Set<String> changed = new LinkedHashSet<>();
		List<BossDefinition> bosses = catalog.byClogPage(pageTitle);
		for (BossDefinition boss : bosses)
		{
			BossProgress progress = ctx.state().get(boss.getName());

			// Kill counts: use the counters that name this boss; if none do and the page
			// belongs to this boss alone, use all of them.
			List<String[]> parsed = new ArrayList<>();
			for (String line : counters)
			{
				int colon = line.lastIndexOf(':');
				if (colon < 0)
				{
					continue;
				}
				String label = line.substring(0, colon).trim();
				String value = line.substring(colon + 1).trim().replace(",", "");
				if (!value.matches("\\d+"))
				{
					continue;
				}
				parsed.add(new String[]{label, value});
			}
			if (boss.hasParts())
			{
				// Combined page: one counter per boss, e.g. "Dagannoth Rex kills: 436".
				for (String[] p : parsed)
				{
					String part = Statistics.partForName(boss, p[0], true);
					if (part == null)
					{
						// the game can leave "The" off a boss's name ("Fractured Archive completions")
						part = Statistics.partForName(boss, "The " + p[0], true);
					}
					if (part != null)
					{
						progress.clogKc.put(BossCatalog.normalize(part), Integer.parseInt(p[1]));
					}
				}
				parsed.clear();
			}
			List<String[]> matching = new ArrayList<>();
			for (String[] p : parsed)
			{
				if (labelNamesBoss(p[0], boss))
				{
					matching.add(p);
				}
			}
			if (matching.isEmpty() && bosses.size() == 1)
			{
				matching = parsed;
			}
			if (boss.getRollsPerKill() > 0)
			{
				// "Rewards claimed" doesn't name the boss but is its exact roll count
				for (String[] p : parsed)
				{
					if (BossCatalog.normalize(p[0]).contains("reward") && !matching.contains(p))
					{
						matching.add(p);
					}
				}
			}
			if (!matching.isEmpty())
			{
				progress.clogKc.clear();
				for (String[] p : matching)
				{
					progress.clogKc.put(BossCatalog.normalize(p[0]), Integer.parseInt(p[1]));
				}
				progress.lootKillsAtSync = progress.lootKills;
				if (boss.getWaves() > 0)
				{
					progress.lastWaveClaimsAtSync = progress.waveClaims == null ? 0
						: progress.waveClaims.getOrDefault(boss.getWaves(), 0);
				}
			}

			// Items several bosses drop: the log total is the same on every page that shows it.
			for (Map.Entry<String, DropDefinition> e : catalog.poolsOf(boss).entrySet())
			{
				Integer total = null;
				for (String name : e.getValue().getAllNames())
				{
					Integer q = findQuantity(items, BossCatalog.normalize(name));
					if (q != null)
					{
						total = (total == null ? 0 : total) + q;
					}
				}
				if (total != null)
				{
					ctx.state().sharedClog().put(e.getKey(), e.getValue().dropsFromQuantity(total));
				}
			}

			// Received counts: the collection log is the full history, so it replaces
			// what we have, except for items several bosses share.
			for (DropDefinition drop : boss.getDrops())
			{
				for (String name : drop.getAllNames())
				{
					String key = BossCatalog.normalize(name);
					if (catalog.isClogShared(key))
					{
						// Can't tell which boss these came from, but the total is right for the account.
						Integer total = findQuantity(items, key);
						if (total != null && !drop.isClogSharedFlag())
						{
							ctx.state().sharedClog().put(key, total);
						}
						continue;
					}
					Integer qty = findQuantity(items, key);
					if (qty != null)
					{
						// stackable items: the log counts items, we count drops
						qty = drop.dropsFromQuantity(qty);
						Integer before = progress.received.get(key);
						if (before != null && qty > before && progress.trackingStartKc != null)
						{
							// a new copy since the last look. The log doesn't say when or where it
							// came from, so it gets no History entry or day count (they'd show a date
							// and kill that aren't known); only its dry streak restarts here
							progress.lastDropKc.put(key, statistics.currentKc(boss));
							progress.milestone.remove(key);
						}
						progress.received.put(key, qty);
					}
				}
			}
			progress.clogSynced = true;
			statistics.startTracking(boss);
			changed.add(boss.getName());
		}
		if (!bosses.isEmpty())
		{
			// a page we cover was read: it is no longer unreadable, and the header works
			unreadablePages.remove(BossCatalog.normalize(pageTitle));
			headerUnreadable = false;
		}
		return changed;
	}

	static Integer findQuantity(Map<String, Integer> items, String normalizedName)
	{
		for (Map.Entry<String, Integer> e : items.entrySet())
		{
			if (BossCatalog.normalize(e.getKey()).equals(normalizedName))
			{
				return e.getValue();
			}
		}
		return null;
	}

	static boolean labelNamesBoss(String label, BossDefinition boss)
	{
		String l = BossCatalog.normalize(label);
		if (l.contains(BossCatalog.normalize(boss.getName())))
		{
			return true;
		}
		for (String kc : boss.getKcNames())
		{
			if (l.contains(BossCatalog.normalize(kc)))
			{
				return true;
			}
		}
		return false;
	}

	/** The boss with the highest known kill count, used to pick what to show on login. */
	String bossWithMostKills()
	{
		String best = null;
		int bestKc = 0;
		if (ctx.state().bosses == null)
		{
			return null;
		}
		for (String name : ctx.state().bosses.keySet())
		{
			BossDefinition boss = catalog.byName(name);
			if (boss == null)
			{
				continue;
			}
			BossProgress p = ctx.state().peek(name);
			int kc = boss.isDelve() ? Statistics.sum(p.levelKc.values()) : boss.hasParts() ? Statistics.sum(Statistics.partKills(boss, p).values()) : Math.max(p.lootKills, Math.max(Statistics.combine(p.chatKc.values(), boss.combineKcWithMax()),
				Statistics.combine(p.clogKc.values(), boss.combineKcWithMax())));
			if (kc > bestKc)
			{
				bestKc = kc;
				best = boss.getName();
			}
		}
		return best;
	}

	/**
	 * The setup checklist: every collection log page the plugin can read, in alphabetical
	 * order, plus the Doom scoreboard. A page counts as synced once every boss on it is.
	 */
	List<SyncStatus> syncChecklist()
	{
		Map<String, List<String>> bossesByPage = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		Map<String, Boolean> syncedByPage = new LinkedHashMap<>();
		Set<String> killedPages = new HashSet<>();
		List<SyncStatus> result = new ArrayList<>();
		for (BossDefinition boss : catalog.getBosses())
		{
			BossProgress p = ctx.state().peek(boss.getName());
			for (String page : boss.getClogPages())
			{
				bossesByPage.computeIfAbsent(page, k -> new ArrayList<>()).add(boss.getName());
				boolean synced = p != null && p.clogSynced;
				syncedByPage.merge(page.toLowerCase(Locale.ROOT), synced, Boolean::logicalAnd);
				if (p != null && statistics.currentKc(boss) > 0)
				{
					killedPages.add(page.toLowerCase(Locale.ROOT));
				}
			}
			if (boss.isDelve())
			{
				result.add(new SyncStatus(DELVE_SCOREBOARD, Collections.singletonList(boss.getName()),
					p != null && p.levelsSynced, p != null && statistics.currentKc(boss) > 0));
			}
		}
		List<SyncStatus> pages = new ArrayList<>();
		for (Map.Entry<String, List<String>> e : bossesByPage.entrySet())
		{
			pages.add(new SyncStatus(e.getKey(), e.getValue(),
				syncedByPage.getOrDefault(e.getKey().toLowerCase(Locale.ROOT), false),
				killedPages.contains(e.getKey().toLowerCase(Locale.ROOT))));
		}
		pages.addAll(result);
		return pages;
	}
}

package com.onrate.engine.tracking;

import com.google.gson.annotations.SerializedName;

/**
 * One boss on one day: kills, uniques and the uniques you should have had from those kills.
 * Kept for the last two weeks, for "Today" and "Last 7 days" in the Recent tab.
 */
public class DayCount
{
	@SerializedName("k")
	int kills;
	@SerializedName("u")
	int uniques;
	@SerializedName("e")
	double expected;
	/**
	 * Time of the earliest kill in this count. Kills in History from before it (On Rate didn't
	 * count days yet) are added once, see Tracker#fillDaysFromHistory. Null for old counts.
	 */
	@SerializedName("f")
	Long first;

	public int getKills()
	{
		return kills;
	}

	public int getUniques()
	{
		return uniques;
	}

	public double getExpected()
	{
		return expected;
	}
}

package com.onrate.engine.tracking;

import java.util.HashSet;
import java.time.Instant;
import java.util.Set;
import java.time.ZoneId;

import com.onrate.engine.data.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * The day counts behind Today and Last 7 days: kills, uniques and expected per boss per local day,
 * the oldest days dropped, History's older kills added once per boss per session, and a raid's
 * expected moved along when its points come in after the kill was counted.
 * <p>
 * Package-private and unsynchronized: reached only through {@link Tracker}, under its lock.
 */
final class DayCounts
{
	private final TrackerContext ctx;
	private final BossCatalog catalog;
	private final Statistics statistics;

	/** Days kept for the Recent tab's day counts. */
	static final int DAYS_KEPT = 14;
	/** Bosses whose History was already added to the day counts this session. */
	private final Set<String> daysFilled = new HashSet<>();

	DayCounts(TrackerContext ctx, Statistics statistics)
	{
		this.ctx = ctx;
		this.catalog = ctx.catalog;
		this.statistics = statistics;
	}

	/** Another account was loaded: its History is added to the day counts again when asked. */
	void clear()
	{
		daysFilled.clear();
	}

	/** This boss's History was loaded or reset: it is added to the day counts again when asked. */
	void forget(String bossName)
	{
		daysFilled.remove(bossName);
	}

	/** The day counter of a boss on the day of this time (local time zone), created when missing. */
	DayCount dayCount(String bossName, long millis)
	{
		long day = Instant.ofEpochMilli(millis).atZone(ZoneId.systemDefault()).toLocalDate().toEpochDay();
		Map<String, Map<String, DayCount>> days = ctx.state().days();
		if (!days.containsKey(String.valueOf(day)))
		{
			// a new day: forget the ones that are too old
			days.keySet().removeIf(d ->
			{
				try
				{
					return Long.parseLong(d) <= day - DAYS_KEPT;
				}
				catch (NumberFormatException e)
				{
					return true;
				}
			});
		}
		return days.computeIfAbsent(String.valueOf(day), d -> new HashMap<>()).computeIfAbsent(bossName, b ->
		{
			DayCount count = new DayCount();
			count.first = millis;
			return count;
		});
	}

	/**
	 * Adds kills from History to the day counts when they're older than what the counts hold, so
	 * Today and Last 7 days include the kills from before On Rate counted days. Safe to repeat:
	 * a kill is only added when it's older than the earliest one already counted that day.
	 */
	void fillDaysFromHistory(BossDefinition boss, long nowMillis)
	{
		if (!daysFilled.add(boss.getName()))
		{
			return;
		}
		BossProgress p = ctx.state().peek(boss.getName());
		if (p == null || p.kills.isEmpty())
		{
			return;
		}
		ZoneId zone = ZoneId.systemDefault();
		long today = Instant.ofEpochMilli(nowMillis).atZone(zone).toLocalDate().toEpochDay();
		Map<Long, List<KillEntry>> toAdd = new HashMap<>();
		for (KillEntry k : p.kills)
		{
			if (k.time <= 0)
			{
				continue;
			}
			long day = Instant.ofEpochMilli(k.time).atZone(zone).toLocalDate().toEpochDay();
			if (day > today || day <= today - DAYS_KEPT)
			{
				continue;
			}
			Map<String, DayCount> forDay = ctx.state().days().get(String.valueOf(day));
			DayCount count = forDay == null ? null : forDay.get(boss.getName());
			// no count that day yet, or this kill came before the first one it holds
			if (count == null || count.first != null && k.time < count.first)
			{
				toAdd.computeIfAbsent(day, d -> new ArrayList<>()).add(k);
			}
		}
		for (List<KillEntry> kills : toAdd.values())
		{
			long earliest = Long.MAX_VALUE;
			DayCount count = null;
			for (KillEntry k : kills)
			{
				count = dayCount(boss.getName(), k.time);
				count.kills++;
				count.expected += statistics.expectedFromKill(boss, k);
				for (KillEntry.DropEntry d : k.getDrops())
				{
					DropDefinition drop = Statistics.dropNamed(boss, d.getName());
					if (drop != null && drop.countsTowardAny())
					{
						count.uniques++;
					}
				}
				earliest = Math.min(earliest, k.time);
			}
			count.first = count.first == null ? earliest : Math.min(count.first, earliest);
		}
	}

	/** Names of the uniques History has for this boss between these days (local epoch days). */
	List<String> uniqueNames(String bossName, long fromDay, long toDay)
	{
		List<String> names = new ArrayList<>();
		BossDefinition boss = catalog.byName(bossName);
		BossProgress p = ctx.state().peek(bossName);
		if (boss == null || p == null)
		{
			return names;
		}
		ZoneId zone = ZoneId.systemDefault();
		for (KillEntry k : p.kills)
		{
			if (!k.isDateKnown())
			{
				continue;
			}
			long day = Instant.ofEpochMilli(k.time).atZone(zone).toLocalDate().toEpochDay();
			if (day < fromDay || day > toDay)
			{
				continue;
			}
			for (KillEntry.DropEntry d : k.getDrops())
			{
				DropDefinition drop = Statistics.rowOfSaved(boss, d.getName());
				if (drop != null && drop.countsTowardAny())
				{
					names.add(d.getName());
				}
			}
		}
		return names;
	}

	/** Tests only: drops the day counts, as a version from before they existed would have. */
	void forgetDaysForTest()
	{
		ctx.state().days().clear();
		daysFilled.clear();
	}

	/**
	 * Kills, uniques and expected per boss over the last {@code days} days (1 = today), most
	 * kills first. The first entry is the total of all bosses (its boss is null).
	 */
	List<BossDays> recentDays(int days, long nowMillis)
	{
		for (BossDefinition boss : catalog.getBosses())
		{
			fillDaysFromHistory(boss, nowMillis);
		}
		long today = Instant.ofEpochMilli(nowMillis).atZone(ZoneId.systemDefault()).toLocalDate().toEpochDay();
		Map<String, DayCount> perBoss = new HashMap<>();
		DayCount total = new DayCount();
		for (Map.Entry<String, Map<String, DayCount>> d : ctx.state().days().entrySet())
		{
			long day;
			try
			{
				day = Long.parseLong(d.getKey());
			}
			catch (NumberFormatException e)
			{
				continue;
			}
			if (day > today || day <= today - days)
			{
				continue;
			}
			for (Map.Entry<String, DayCount> b : d.getValue().entrySet())
			{
				DayCount sum = perBoss.computeIfAbsent(b.getKey(), k -> new DayCount());
				sum.kills += b.getValue().kills;
				sum.uniques += b.getValue().uniques;
				sum.expected += b.getValue().expected;
				total.kills += b.getValue().kills;
				total.uniques += b.getValue().uniques;
				total.expected += b.getValue().expected;
			}
		}
		List<BossDays> result = new ArrayList<>();
		result.add(new BossDays(null, total, new ArrayList<>()));
		perBoss.entrySet().stream()
			.filter(e -> e.getValue().kills > 0 || e.getValue().uniques > 0)
			.sorted((a, b) -> a.getValue().kills != b.getValue().kills ? b.getValue().kills - a.getValue().kills
				: a.getKey().compareTo(b.getKey()))
			.forEach(e -> result.add(new BossDays(e.getKey(), e.getValue(),
				uniqueNames(e.getKey(), today - days + 1, today))));
		return result;
	}

	/**
	 * A raid is counted at the purple chance from the settings first; when its points come in a
	 * moment later, this moves the day's expected along, so Recent uses your points too.
	 */
	void shiftToday(String bossName, double change)
	{
		if (Double.isNaN(change) || Math.abs(change) < 1e-12)
		{
			return;
		}
		BossProgress progress = ctx.state().peek(bossName);
		// the latest kill with a date: drops added by hand have none
		KillEntry latest = null;
		for (int i = progress == null ? -1 : progress.kills.size() - 1; i >= 0 && latest == null; i--)
		{
			latest = progress.kills.get(i).isDateKnown() ? progress.kills.get(i) : null;
		}
		DayCount day = dayCount(bossName, latest == null ? System.currentTimeMillis() : latest.time);
		day.expected = Math.max(0, day.expected + change);
	}
}

package com.onrate.engine.tracking;

import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * How long kills and raids took: a time message is matched to the kill it belongs to (it can come a
 * moment before or after the kill count), raid times imported from Raid Data Tracker are kept and
 * matched to the raids On Rate saw, and the times are summed up for the Time pages.
 * <p>
 * Package-private and unsynchronized: reached only through {@link Tracker}, under its lock.
 */
final class FightTimes
{
	private final TrackerContext ctx;
	private final BossCatalog catalog;

	/**
	 * A kill's time message and its kill count message arrive within a moment of each other, in
	 * either order: the one that comes first waits here for the other.
	 */
	private static final long DURATION_MATCH_MILLIS = 20_000;
	private ChatTimes.Reading pendingDuration;
	private long pendingDurationAt;
	/** The kill whose time message may still come, and the rank of the time it has. */
	private KillEntry durationEntry;
	private String durationBoss;
	private long durationAt;
	private int durationRank;
	/** A raid time from another plugin counts as the same raid as one On Rate timed when they ended this close together. */
	private static final long IMPORT_MATCH_MILLIS = 5 * 60_000;

	FightTimes(TrackerContext ctx)
	{
		this.ctx = ctx;
		this.catalog = ctx.catalog;
	}

	/**
	 * A kill was just counted: it takes the time message that came a moment before it, and
	 * waits for one that comes a moment after.
	 */
	void offerDuration(String bossName, KillEntry entry, long nowMillis)
	{
		durationEntry = entry;
		durationBoss = bossName;
		durationAt = nowMillis;
		durationRank = 0;
		ChatTimes.Reading waiting = pendingDuration;
		pendingDuration = null;
		if (waiting != null && nowMillis - pendingDurationAt <= DURATION_MATCH_MILLIS)
		{
			setDuration(bossName, entry, waiting);
		}
	}

	/**
	 * A message with the time of a whole kill or raid. Goes to the kill counted a moment ago when
	 * that has no time yet (or a less certain one), else waits for the kill it belongs to.
	 * Returns the boss whose History changed, or null.
	 */
	String onDuration(ChatTimes.Reading time, long nowMillis)
	{
		if (durationEntry != null && nowMillis - durationAt <= DURATION_MATCH_MILLIS
			&& (durationEntry.durationMillis == null || time.getRank() > durationRank))
		{
			setDuration(durationBoss, durationEntry, time);
			return durationBoss;
		}
		// two time messages can wait for one kill (Tombs: the challenge time, then a total): keep the better one
		boolean waiting = pendingDuration != null && nowMillis - pendingDurationAt <= DURATION_MATCH_MILLIS;
		if (!waiting || time.getRank() >= pendingDuration.getRank())
		{
			pendingDuration = time;
			pendingDurationAt = nowMillis;
		}
		return null;
	}

	void setDuration(String bossName, KillEntry entry, ChatTimes.Reading time)
	{
		entry.durationMillis = time.getMillis();
		if (entry == durationEntry)
		{
			durationRank = time.getRank();
		}
		ctx.killsChanged.add(bossName);
		BossProgress progress = ctx.state().peek(bossName);
		if (progress == null || entry.partKc == null)
		{
			return;
		}
		// the raid's own record, when its points were already saved
		for (int i = progress.raids.size() - 1, looked = 0; i >= 0 && looked < 10; i--, looked++)
		{
			RaidRecord record = progress.raids.get(i);
			if (record.kc == entry.partKc && Objects.equals(record.part, entry.part))
			{
				if (record.durationMillis != time.getMillis())
				{
					record.durationMillis = time.getMillis();
					ctx.raidsChanged.add(bossName);
				}
				return;
			}
		}
	}

	/** The time of the latest kill of this raid mode, when its message came before the raid's points. */
	static int knownDuration(BossProgress progress, String part, int kc)
	{
		for (int i = progress.kills.size() - 1, looked = 0; i >= 0 && looked < 10; i--, looked++)
		{
			KillEntry kill = progress.kills.get(i);
			if (kill.partKc != null && kill.partKc == kc && Objects.equals(kill.part, part)
				&& kill.durationMillis != null)
			{
				return kill.durationMillis;
			}
		}
		return -1;
	}

	/**
	 * Adds raid times read from another plugin's log (Raid Data Tracker): for one raid mode, when
	 * each raid ended (epoch millis) and how long it took (millis). A raid already imported (same end
	 * time) is skipped, and one On Rate timed itself is not counted twice: its time is used, or
	 * filled in when On Rate saw the raid but not its time. Safe to call again with the same list.
	 *
	 * @return how many times were new
	 */
	int importRaidTimes(String bossName, String part, List<long[]> samples)
	{
		BossDefinition boss = catalog.byName(bossName);
		if (boss == null || boss.getRaid() == null || part == null || samples == null || samples.isEmpty())
		{
			return 0;
		}
		BossProgress progress = ctx.state().get(bossName);
		if (progress.importedTimes == null)
		{
			progress.importedTimes = new HashMap<>();
		}
		List<long[]> known = progress.importedTimes.computeIfAbsent(part, k -> new ArrayList<>());
		Set<Long> have = new HashSet<>();
		for (long[] k : known)
		{
			have.add(k[0]);
		}
		int added = 0;
		for (long[] sample : samples)
		{
			if (sample == null || sample.length < 2 || sample[0] <= 0 || sample[1] <= 0 || sample[1] > Integer.MAX_VALUE
				|| !have.add(sample[0]))
			{
				continue;
			}
			known.add(new long[]{sample[0], sample[1]});
			added++;
			fillLiveRaid(bossName, progress, part, sample[0], (int) sample[1]);
		}
		if (known.isEmpty())
		{
			progress.importedTimes.remove(part);
		}
		return added;
	}

	/** Gives the raid On Rate saw at this time (when it has no time yet) the imported time. */
	void fillLiveRaid(String bossName, BossProgress progress, String part, long when, int millis)
	{
		KillEntry nearest = null;
		for (KillEntry kill : progress.kills)
		{
			if (kill.isDateKnown() && part.equals(kill.part) && Math.abs(kill.time - when) <= IMPORT_MATCH_MILLIS
				&& (nearest == null || Math.abs(kill.time - when) < Math.abs(nearest.time - when)))
			{
				nearest = kill;
			}
		}
		if (nearest == null || nearest.durationMillis != null)
		{
			return;
		}
		nearest.durationMillis = millis;
		ctx.killsChanged.add(bossName);
		for (RaidRecord record : progress.raids)
		{
			if (nearest.partKc != null && record.kc == nearest.partKc && part.equals(record.part) && record.durationMillis < 0)
			{
				record.durationMillis = millis;
				ctx.raidsChanged.add(bossName);
			}
		}
	}

	/**
	 * How long this boss's kills took (a combined page: one part's), from the kills in History and,
	 * for raids, the times imported from Raid Data Tracker. Null when nothing has a time.
	 */
	TimeStats killTimes(String bossName, String partName)
	{
		BossProgress progress = ctx.state().peek(bossName);
		if (progress == null)
		{
			return null;
		}
		List<Integer> times = new ArrayList<>();
		int last = -1;
		long lastAt = Long.MIN_VALUE;
		List<long[]> live = new ArrayList<>();
		for (KillEntry kill : progress.kills)
		{
			if (kill.durationMillis == null || (partName != null && !partName.equals(kill.part)))
			{
				continue;
			}
			times.add(kill.durationMillis);
			last = kill.durationMillis;
			lastAt = kill.time;
			if (kill.isDateKnown())
			{
				live.add(new long[]{kill.time, kill.durationMillis});
			}
		}
		if (progress.importedTimes != null)
		{
			for (Map.Entry<String, List<long[]>> e : progress.importedTimes.entrySet())
			{
				if (partName != null && !partName.equals(e.getKey()))
				{
					continue;
				}
				for (long[] sample : e.getValue())
				{
					if (countedLive(live, sample[0]))
					{
						continue;
					}
					times.add((int) sample[1]);
					if (sample[0] >= lastAt)
					{
						last = (int) sample[1];
						lastAt = sample[0];
					}
				}
			}
		}
		return times.isEmpty() ? null : new TimeStats(times, last);
	}

	/** True when a raid On Rate timed itself ended within a few minutes of this imported one: the same raid. */
	static boolean countedLive(List<long[]> live, long when)
	{
		for (long[] l : live)
		{
			if (Math.abs(l[0] - when) <= IMPORT_MATCH_MILLIS)
			{
				return true;
			}
		}
		return false;
	}

	/** How many raid times of this boss were imported from another plugin (all modes, or one). */
	int importedRaidTimes(String bossName, String part)
	{
		BossProgress progress = ctx.state().peek(bossName);
		if (progress == null || progress.importedTimes == null)
		{
			return 0;
		}
		int n = 0;
		for (Map.Entry<String, List<long[]>> e : progress.importedTimes.entrySet())
		{
			if (part == null || part.equals(e.getKey()))
			{
				n += e.getValue().size();
			}
		}
		return n;
	}

	/** How long delves of one level took (Doom: 1 to 8, 9 for the deep delves), or null when none has a time. */
	TimeStats levelTimes(String bossName, int level)
	{
		BossProgress progress = ctx.state().peek(bossName);
		if (progress == null)
		{
			return null;
		}
		List<Integer> times = new ArrayList<>();
		int last = -1;
		for (KillEntry kill : progress.kills)
		{
			if (kill.durationMillis != null && kill.level != null && kill.level == level)
			{
				times.add(kill.durationMillis);
				last = kill.durationMillis;
			}
		}
		return times.isEmpty() ? null : new TimeStats(times, last);
	}
}

package com.onrate.engine.tracking;

import java.util.Iterator;

import com.onrate.engine.data.*;
import com.onrate.engine.stats.*;
import com.onrate.engine.tracking.Tracker.LastUnique;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;

import static com.onrate.engine.tracking.Tracker.MAX_KILLS;
import static com.onrate.engine.tracking.Tracker.UNKNOWN_PART_LIMIT;
import static com.onrate.engine.tracking.Tracker.roundMultiple;

/**
 * What happened over time: the kills kept per boss for History (the oldest go once there are too
 * many), the drops in them and the queries on them (recent drops, a drop's kills, the luckiest and
 * driest), removing a kill or drop, past drops the player adds by hand (with the rules on when one
 * can be placed and ranked), and the luck graph's one point per day.
 * <p>
 * Package-private and unsynchronized: reached only through {@link Tracker}, under its lock.
 */
final class HistoryBook
{
	private final TrackerContext ctx;
	private final BossCatalog catalog;
	private final Statistics statistics;
	private final RaidRecords raidData;

	/** Most points the luck graph keeps (about three years of daily play). */
	private static final int MAX_HISTORY = 1000;

	HistoryBook(TrackerContext ctx, Statistics statistics, RaidRecords raidData)
	{
		this.ctx = ctx;
		this.catalog = ctx.catalog;
		this.statistics = statistics;
		this.raidData = raidData;
	}

	/** Saves a kill for the History section (the oldest ones go once there are too many). */
	KillEntry addKill(BossDefinition boss, BossProgress progress, long nowMillis)
	{
		KillEntry entry = new KillEntry();
		entry.kc = statistics.currentKc(boss);
		entry.time = nowMillis;
		progress.kills.add(entry);
		ctx.killsChanged.add(boss.getName());
		while (progress.kills.size() > MAX_KILLS)
		{
			progress.kills.remove(0);
		}
		return entry;
	}

	/** This boss's saved kills, newest first, with each raid's points and purple chance. */
	List<HistoryRow> history(String bossName)
	{
		BossDefinition boss = catalog.byName(bossName);
		BossProgress p = ctx.state().peek(bossName);
		List<HistoryRow> rows = new ArrayList<>();
		if (boss == null || p == null)
		{
			return rows;
		}
		for (int i = p.kills.size() - 1; i >= 0; i--)
		{
			KillEntry k = p.kills.get(i);
			RaidRecord match = null;
			double chance = Double.NaN;
			if (boss.getRaid() != null && k.partKc != null)
			{
				for (RaidRecord r : p.raids)
				{
					if (r.kc == k.partKc && (k.part == null || k.part.equals(r.part)))
					{
						match = r;
					}
				}
				if (match != null)
				{
					for (BossPart part : boss.getParts())
					{
						if (part.getName().equals(match.part))
						{
							chance = RateModel.recordChance(match, part, ctx.settings());
						}
					}
				}
			}
			rows.add(new HistoryRow(k, match, chance));
		}
		return rows;
	}

	/** Kills saved for this boss (at most {@link #MAX_KILLS}). */
	int killsSeen(String bossName)
	{
		BossProgress p = ctx.state().peek(bossName);
		return p == null ? 0 : p.kills.size();
	}

	/** The latest uniques across every boss, newest first. */
	List<RecentDrop> recentDrops(int limit)
	{
		List<RecentDrop> all = new ArrayList<>();
		for (BossDefinition boss : catalog.getBosses())
		{
			BossProgress p = ctx.state().peek(boss.getName());
			if (p == null)
			{
				continue;
			}
			for (KillEntry k : p.kills)
			{
				if (!k.isDateKnown())
				{
					// added by hand from memory: it has a kill count but no date, so it isn't "recent"
					continue;
				}
				for (KillEntry.DropEntry d : k.getDrops())
				{
					// saved before the item was flagged clogShared (dragon thrownaxes and knives): kept,
					// not shown. Pooled items saved when they were a row (a Kings dragon axe) still show.
					if (!catalog.isUntracked(d.getName()))
					{
						all.add(new RecentDrop(boss.getName(), k, d));
					}
				}
			}
		}
		all.sort((a, b) -> Long.compare(b.getKill().getTime(), a.getKill().getTime()));
		return all.size() > limit ? new ArrayList<>(all.subList(0, limit)) : all;
	}

	/**
	 * Removes one unique from History: exactly this saved drop of this kill, as picked in Recent
	 * or History (by the entries themselves, so two copies of the same item stay apart). Only
	 * what is read from History changes: History, Recent and Last unique. The received count,
	 * kill count, expected and dry streak stay as they are, and the kill itself stays in History.
	 * Today and Last 7 days keep their counts: the day a unique was counted on isn't saved (it
	 * can differ from its kill's day), so a removed unique stays in them until that day expires.
	 * Returns false when the entry isn't there any more (trimmed, or another account loaded since
	 * it was shown).
	 */
	boolean removeFromHistory(String bossName, KillEntry kill, KillEntry.DropEntry drop)
	{
		BossDefinition boss = catalog.byName(bossName);
		BossProgress p = ctx.state().peek(bossName);
		if (boss == null || p == null || kill == null || drop == null || kill.drops == null)
		{
			return false;
		}
		boolean listed = false;
		for (KillEntry k : p.kills)
		{
			if (k == kill)
			{
				listed = true;
				break;
			}
		}
		boolean removed = false;
		for (Iterator<KillEntry.DropEntry> it = kill.drops.iterator(); listed && it.hasNext(); )
		{
			if (it.next() == drop)
			{
				it.remove();
				removed = true;
				break;
			}
		}
		if (!removed)
		{
			return false;
		}
		if (kill.drops.isEmpty())
		{
			// saved like a kill that never had a unique
			kill.drops = null;
		}
		if (drop.isEntered() && kill.part == null)
		{
			// a drop added by hand also moved the item's dry streak: put it back to the latest one left
			DropDefinition def = Statistics.rowOfSaved(boss, drop.getName());
			String key = def == null ? null : BossCatalog.normalize(def.getName());
			if (key != null && Integer.valueOf(kill.kc).equals(p.lastDropKc.get(key)))
			{
				Integer latest = null;
				for (KillEntry k : p.kills)
				{
					for (KillEntry.DropEntry d : k.getDrops())
					{
						if (d.getName().equals(drop.getName()) && !(d.isEntered() && k.part != null)
							&& k.kc < kill.kc && (latest == null || k.kc > latest))
						{
							latest = k.kc;
						}
					}
				}
				if (latest == null)
				{
					p.lastDropKc.remove(key);
				}
				else
				{
					p.lastDropKc.put(key, latest);
				}
			}
		}
		ctx.killsChanged.add(bossName);
		return true;
	}

	/**
	 * Why a drop added by hand can't be ranked in Luckiest drops / Longest waits, or null when it can
	 * (or isn't in History): its wait isn't known, or the boss's drop rate isn't.
	 */
	String pastDropNotRankedReason(String bossName, String itemName, int kc)
	{
		return pastDropNotRankedReason(bossName, itemName, kc, null);
	}

	/** As above for a drop entered at a part of a combined page. */
	String pastDropNotRankedReason(String bossName, String itemName, int kc, String partName)
	{
		BossDefinition boss = catalog.byName(bossName);
		BossProgress p = ctx.state().peek(bossName);
		if (boss == null || p == null)
		{
			return null;
		}
		for (KillEntry k : p.kills)
		{
			if (!inCounting(k, partName) || countOf(k, partName) != kc)
			{
				continue;
			}
			for (KillEntry.DropEntry d : k.getDrops())
			{
				DropDefinition drop = Statistics.rowOfSaved(boss, d.getName());
				if (d.isEntered() && drop != null && drop.getName().equals(itemName))
				{
					if (d.getSince() == null)
					{
						return "On Rate can't tell how long it took: it doesn't know this was your first one. "
							+ "Open this boss's collection log page, or remove it and add it again with \"This was my first one\" ticked.";
					}
					return d.getMultiple() == null ? "On Rate doesn't know this item's drop rate yet." : null;
				}
			}
		}
		return null;
	}

	/**
	 * The drops of one item at one boss in History (seen or added by hand) whose wait is known
	 * exactly, luckiest first, for the item's hover.
	 */
	List<RecentDrop> dropsOf(String bossName, String itemName)
	{
		List<RecentDrop> list = new ArrayList<>();
		BossDefinition boss = catalog.byName(bossName);
		BossProgress p = ctx.state().peek(bossName);
		if (boss == null || p == null)
		{
			return list;
		}
		for (KillEntry k : p.kills)
		{
			for (KillEntry.DropEntry d : k.getDrops())
			{
				DropDefinition drop = Statistics.rowOfSaved(boss, d.getName());
				if (drop != null && drop.getName().equals(itemName) && d.getMultiple() != null && !d.isAtLeast())
				{
					list.add(new RecentDrop(bossName, k, d));
				}
			}
		}
		list.sort((a, b) -> Double.compare(a.getDrop().getMultiple(), b.getDrop().getMultiple()));
		return list;
	}

	/**
	 * Drops across every boss whose wait is known exactly and was lucky (shorter than the drop rate
	 * gives on average) or dry (longer), best first: luckiest are ranked by the smallest multiple of
	 * the drop rate, dry ones by the largest. Drops added by hand count; undated ones are fine.
	 */
	List<RecentDrop> dropsByLuck(boolean lucky, int limit)
	{
		List<RecentDrop> all = new ArrayList<>();
		for (BossDefinition boss : catalog.getBosses())
		{
			BossProgress p = ctx.state().peek(boss.getName());
			if (p == null)
			{
				continue;
			}
			for (KillEntry k : p.kills)
			{
				for (KillEntry.DropEntry d : k.getDrops())
				{
					Double m = d.getMultiple();
					if (m == null || d.isAtLeast() || catalog.isUntracked(d.getName()) || (lucky ? m >= 1 : m <= 1))
					{
						continue;
					}
					DropDefinition drop = Statistics.rowOfSaved(boss, d.getName());
					if (drop != null && statistics.counts(boss, drop, p))
					{
						all.add(new RecentDrop(boss.getName(), k, d));
					}
				}
			}
		}
		all.sort((a, b) ->
		{
			int byLuck = lucky ? Double.compare(a.getDrop().getMultiple(), b.getDrop().getMultiple())
				: Double.compare(b.getDrop().getMultiple(), a.getDrop().getMultiple());
			return byLuck != 0 ? byLuck : Long.compare(b.getKill().getTime(), a.getKill().getTime());
		});
		return all.size() > limit ? new ArrayList<>(all.subList(0, limit)) : all;
	}

	/**
	 * Adds a unique the player remembers getting at a known kill count (before On Rate, or one it
	 * missed) to History, e.g. "Twisted bow at raid 115". The entry has no date. Only History,
	 * the item's dry streak and its "after N kills" text change: the received count already comes
	 * from the collection log, so nothing is counted twice. Returns false when the boss or item is
	 * unknown, the kill count is not between 1 and the current one, the item is already listed at
	 * that kill count, or History is full of newer kills.
	 */
	boolean addPastDrop(String bossName, String itemName, int kc)
	{
		return addPastDrop(bossName, itemName, kc, false);
	}

	/**
	 * As {@link #addPastDrop(String, String, int)}, with {@code first} true when the player says
	 * this was their first copy: its wait is then its kill count, even when the collection log
	 * shows more copies. Ignored when an earlier copy is already listed (the gap since it is used).
	 */
	boolean addPastDrop(String bossName, String itemName, int kc, boolean first)
	{
		return addPastDrop(bossName, itemName, kc, first, null);
	}

	/** Kills in the counting a past drop is entered in: the part's own count, or the page's when it has no parts. */
	static boolean inCounting(KillEntry k, String part)
	{
		return part == null || part.equals(k.part) && k.partKc != null;
	}

	static int countOf(KillEntry k, String part)
	{
		return part == null ? k.kc : k.partKc;
	}

	/** Most kills a past drop can be entered at: the page's kill count, or the part's own. 0 for a page whose kills are unknown. */
	int pastDropLimit(String bossName, String partName)
	{
		BossDefinition boss = catalog.byName(bossName);
		if (boss == null)
		{
			return 0;
		}
		if (partName == null)
		{
			return boss.hasParts() ? 0 : statistics.currentKc(boss);
		}
		BossStats s = statistics.stats(bossName, ctx.settings());
		Integer n = s == null || s.getPartCounts() == null ? null : s.getPartCounts().get(partName);
		// the part's count isn't known (not in the log yet, no kills seen): the player knows better, so don't block them
		return n == null || n < 1 ? UNKNOWN_PART_LIMIT : n;
	}

	/**
	 * The parts of a combined page a drop can be entered at: the ones the item drops from (all of
	 * them when none has a known rate). Empty for a page without parts.
	 */
	List<String> pastDropParts(String bossName, String itemName)
	{
		List<String> names = new ArrayList<>();
		BossDefinition boss = catalog.byName(bossName);
		if (boss == null || !boss.hasParts())
		{
			return names;
		}
		DropDefinition drop = null;
		for (DropDefinition d : boss.getDrops())
		{
			if (d.getName().equals(itemName))
			{
				drop = d;
			}
		}
		List<String> fallback = new ArrayList<>();
		for (BossPart part : boss.getParts())
		{
			fallback.add(part.getName());
			if (drop != null && RateModel.partRate(boss, part, drop, ctx.settings()) > 0)
			{
				names.add(part.getName());
			}
		}
		return names.isEmpty() ? fallback : names;
	}

	/**
	 * As above for a page with parts: {@code partName} is the mode or boss ("Challenge Mode",
	 * "Artio") and {@code kc} that part's own kill count, as the game's chat shows it. The wait and
	 * its luck use that part's kills and drop rate. The item's dry streak counts the page's kills,
	 * which aren't known for that moment, so it stays as it is. Null for a page without parts.
	 */
	boolean addPastDrop(String bossName, String itemName, int kc, boolean first, String partName)
	{
		return tryAddPastDrop(bossName, itemName, kc, first, partName) == PastDropResult.ADDED;
	}

	/** As {@link #addPastDrop(String, String, int, boolean, String)}, saying why a refused drop was refused. */
	PastDropResult tryAddPastDrop(String bossName, String itemName, int kc, boolean first, String partName)
	{
		BossDefinition boss = catalog.byName(bossName);
		if (boss == null)
		{
			return PastDropResult.UNKNOWN;
		}
		if (kc < 1)
		{
			return PastDropResult.COUNT_TOO_LOW;
		}
		BossPart part = null;
		for (BossPart candidate : boss.getParts())
		{
			if (candidate.getName().equals(partName))
			{
				part = candidate;
			}
		}
		if (boss.hasParts() != (part != null) || (partName != null && part == null))
		{
			return PastDropResult.UNKNOWN;
		}
		if (kc > pastDropLimit(bossName, partName))
		{
			return PastDropResult.COUNT_TOO_HIGH;
		}
		DropDefinition drop = null;
		for (DropDefinition d : boss.getDrops())
		{
			if (d.getName().equals(itemName))
			{
				drop = d;
			}
		}
		if (drop == null)
		{
			return PastDropResult.UNKNOWN;
		}
		BossProgress progress = ctx.state().get(boss.getName());
		String shown = drop.getDisplayName();
		// check everything before changing anything: a drop On Rate saw at that count can't be replaced, and
		// History can't list more copies than the collection log shows
		int listed = 0;
		int replaceable = 0;
		List<Object[]> enteredElsewhere = new ArrayList<>();
		for (KillEntry k : progress.kills)
		{
			boolean sameSpot = inCounting(k, partName) && countOf(k, partName) == kc;
			for (KillEntry.DropEntry d : k.getDrops())
			{
				if (!d.getName().equals(shown))
				{
					continue;
				}
				listed++;
				if (sameSpot && d.isEntered())
				{
					replaceable++;
				}
				else if (sameSpot)
				{
					return PastDropResult.SAW_AT_COUNT;
				}
				else if (d.isEntered())
				{
					enteredElsewhere.add(new Object[]{k, d});
				}
			}
		}
		Object[] swap = null;
		Integer copies = progress.received.get(BossCatalog.normalize(itemName));
		if (progress.clogSynced && copies != null && copies >= 1 && listed - replaceable >= copies)
		{
			// History already lists every copy: when exactly one was added by hand, the new one corrects it
			if (enteredElsewhere.size() != 1)
			{
				return PastDropResult.ALL_COPIES_LISTED;
			}
			swap = enteredElsewhere.get(0);
		}
		if (swap != null)
		{
			KillEntry swapKill = (KillEntry) swap[0];
			removeFromHistory(boss.getName(), swapKill, (KillEntry.DropEntry) swap[1]);
			if (swapKill.drops == null && !swapKill.isDateKnown())
			{
				progress.kills.remove(swapKill);
			}
		}
		// adding it again at the same kill count replaces what the player entered before (never a drop On Rate saw)
		for (Iterator<KillEntry> kills = progress.kills.iterator(); kills.hasNext(); )
		{
			KillEntry k = kills.next();
			if (inCounting(k, partName) && countOf(k, partName) == kc && k.drops != null
				&& k.drops.removeIf(d -> d.isEntered() && d.getName().equals(shown)))
			{
				if (k.drops.isEmpty())
				{
					k.drops = null;
					if (!k.isDateKnown())
					{
						kills.remove();
					}
				}
				ctx.killsChanged.add(boss.getName());
			}
		}
		KillEntry at = null;
		int index = progress.kills.size();
		boolean placed = false;
		int firstDated = progress.kills.size();
		int previousKc = 0;
		for (int i = 0; i < progress.kills.size(); i++)
		{
			KillEntry k = progress.kills.get(i);
			if (k.isDateKnown() && firstDated == progress.kills.size())
			{
				firstDated = i;
			}
			if (!inCounting(k, partName))
			{
				continue;
			}
			int at0 = countOf(k, partName);
			if (at0 == kc && at == null)
			{
				at = k;
			}
			if (at0 > kc && !placed)
			{
				index = i;
				placed = true;
			}
			if (at0 < kc)
			{
				for (KillEntry.DropEntry d : k.getDrops())
				{
					if (d.getName().equals(shown))
					{
						previousKc = Math.max(previousKc, at0);
					}
				}
			}
		}
		if (!placed && part != null)
		{
			// no later kill of this part is saved: after the older entries without a date, before the dated ones
			index = firstDated;
		}
		if (at != null)
		{
			for (KillEntry.DropEntry d : at.getDrops())
			{
				if (d.getName().equals(shown))
				{
					return PastDropResult.SAW_AT_COUNT;
				}
			}
		}
		else if (index == 0 && progress.kills.size() >= MAX_KILLS)
		{
			return PastDropResult.HISTORY_FULL;
		}
		KillEntry.DropEntry entry = new KillEntry.DropEntry();
		entry.name = shown;
		entry.pet = drop.isPet() ? Boolean.TRUE : null;
		entry.entered = Boolean.TRUE;
		String key = BossCatalog.normalize(itemName);
		Integer have = progress.received.get(key);
		if (previousKc > 0)
		{
			entry.since = kc - previousKc;
		}
		else if (first || progress.clogSynced && !catalog.isClogShared(key) && have != null && have == 1)
		{
			// the player says it was the first, or the only copy the log shows is this one
			entry.since = kc;
			entry.first = Boolean.TRUE;
		}
		if (entry.since != null)
		{
			double expected;
			if (part != null && part.getRaid() != null && !drop.hasPartRates())
			{
				// a raid: each raid in the wait counts at its own purple chance (from its points when On Rate
				// counted them), and at the settings' chance for the ones from before
				expected = raidData.raidWaitExpected(boss, part, drop, progress, kc - entry.since, kc);
			}
			else
			{
				expected = entry.since * (part == null ? statistics.rateOf(boss, drop) : RateModel.partRate(boss, part, drop, ctx.settings()));
			}
			if (expected > 0)
			{
				entry.multiple = roundMultiple(expected);
			}
			// the same records a drop On Rate saw feeds
			if (progress.fastestGap == null)
			{
				progress.fastestGap = new HashMap<>();
				progress.longestGap = new HashMap<>();
			}
			progress.fastestGap.merge(key, entry.since, Math::min);
			progress.longestGap.merge(key, entry.since, Math::max);
		}
		if (at == null)
		{
			at = new KillEntry();
			at.kc = kc;
			at.time = 0;
			if (part != null)
			{
				at.part = partName;
				at.partKc = kc;
			}
			progress.kills.add(index, at);
			while (progress.kills.size() > MAX_KILLS)
			{
				progress.kills.remove(0);
			}
		}
		if (at.drops == null)
		{
			at.drops = new ArrayList<>();
		}
		at.drops.add(entry);
		ctx.killsChanged.add(boss.getName());
		// the dry streak counts from the latest drop of any copy (page kills: not known for a part)
		Integer last = progress.lastDropKc.get(key);
		if (part == null && (last == null || kc > last))
		{
			progress.lastDropKc.put(key, kc);
			progress.milestone.remove(key);
		}
		return PastDropResult.ADDED;
	}

	/**
	 * Saves today's account luck for the graph. One point per day: a later call on the same
	 * day replaces it. Returns true when something was stored.
	 */
	boolean recordHistory(long day, RaidSettings raids)
	{
		AccountStats account = statistics.accountStats(raids);
		RowStats total = account.getTotal();
		if (total.getExpected() <= 0 || Double.isNaN(total.getLuck()))
		{
			return false;
		}
		List<HistoryPoint> history = ctx.state().history();
		HistoryPoint point = new HistoryPoint(day, total.getExpected(), total.getReceived(), total.getLuck());
		if (!history.isEmpty() && history.get(history.size() - 1).day >= day)
		{
			history.set(history.size() - 1, point);
		}
		else
		{
			history.add(point);
		}
		while (history.size() > MAX_HISTORY)
		{
			history.remove(0);
		}
		return true;
	}

	/** The luck graph's points, oldest first. */
	List<HistoryPoint> history()
	{
		return new ArrayList<>(ctx.state().history());
	}

	/** The last unique On Rate saw in History (any boss), or null; with when History starts. */
	LastUnique lastUnique()
	{
		LastUnique result = null;
		long earliest = Long.MAX_VALUE;
		if (ctx.state().bosses == null)
		{
			return null;
		}
		for (String name : ctx.state().bosses.keySet())
		{
			BossDefinition boss = catalog.byName(name);
			BossProgress p = ctx.state().peek(name);
			if (boss == null || p == null)
			{
				continue;
			}
			for (KillEntry k : p.kills)
			{
				if (!k.isDateKnown())
				{
					continue;
				}
				earliest = Math.min(earliest, k.time);
				for (KillEntry.DropEntry d : k.getDrops())
				{
					DropDefinition drop = Statistics.rowOfSaved(boss, d.getName());
					if (drop != null && statistics.counts(boss, drop, p) && (result == null || k.time > result.time))
					{
						result = new LastUnique(d.getName(), boss.getName(), k.time, 0);
					}
				}
			}
		}
		if (earliest == Long.MAX_VALUE)
		{
			return null;
		}
		return result == null ? new LastUnique(null, null, 0, earliest) : new LastUnique(result.item, result.boss, result.time, earliest);
	}
}

