/**
 * One kill On Rate saw, for the History section: when, at what kill count, the uniques it
 * gave and what else is known about it (raid mode, team size, delve level, titan looted).
 * Saved in the RuneLite profile; kept short so the history stays small.
 */
public class KillEntry
{
	/** Kill count of the whole page after this kill (raids: all modes together). */
	@SerializedName("k")
	int kc;
	/** Kill count in the chat message (one mode or one boss of a combined page). */
	@SerializedName("p")
	Integer partKc;
	/** When, in milliseconds. */
	@SerializedName("t")
	long time;
	/** Raid mode or boss of a combined page ("Challenge Mode", "Dagannoth Rex"), or null. */
	@SerializedName("m")
	String part;
	/** Players around you at a group boss, or null. */
	@SerializedName("n")
	Integer team;
	/** Delve level (Doom), or null. */
	@SerializedName("l")
	Integer level;
	/** Royal Titans: the titan you looted ("Branda", "Eldric"), or null. */
	@SerializedName("ti")
	String titan;
	/** How long the kill or raid took, in milliseconds, as the game's chat said; null when it didn't say. */
	@SerializedName("du")
	Integer durationMillis;
	/** Uniques from this kill. */
	@SerializedName("d")
	List<DropEntry> drops;

	public int getKc()
	{
		return kc;
	}

	/** How long this kill or raid took in milliseconds, or null when unknown (older kills, bosses with no time message). */
	public Integer getDurationMillis()
	{
		return durationMillis;
	}

	/** False for a kill the player added by hand from memory: its kill count is known, its date isn't. */
	public boolean isDateKnown()
	{
		return time > 0;
	}

	public Integer getPartKc()
	{
		return partKc;
	}

	public long getTime()
	{
		return time;
	}

	public String getPart()
	{
		return part;
	}

	public Integer getTeam()
	{
		return team;
	}

	public Integer getLevel()
	{
		return level;
	}

	public String getTitan()
	{
		return titan;
	}

	public List<DropEntry> getDrops()
	{
		return drops == null ? Collections.emptyList() : drops;
	}

	/** One unique from a kill. */
	public static class DropEntry
	{
		/** Name as shown in the panel. */
		@SerializedName("i")
		String name;
		/** Kills since the previous one of this item, or null when unknown. */
		@SerializedName("s")
		Integer since;
		/** That gap in multiples of the drop rate, or null. */
		@SerializedName("x")
		Double multiple;
		/** True when it's the first one (the collection log said so). */
		@SerializedName("f")
		Boolean first;
		/** True when {@link #since} is only a minimum (an earlier one came before On Rate). */
		@SerializedName("a")
		Boolean atLeast;
		@SerializedName("pt")
		Boolean pet;
		/** True when the player added this drop by hand ("I got this at kill 115"). */
		@SerializedName("u")
		Boolean entered;

		public String getName()
		{
			return name;
		}

		public Integer getSince()
		{
			return since;
		}

		public Double getMultiple()
		{
			return multiple;
		}

		public boolean isFirst()
		{
			return first != null && first;
		}

		public boolean isAtLeast()
		{
			return atLeast != null && atLeast;
		}

		public boolean isPet()
		{
			return pet != null && pet;
		}

		/**
		 * How lucky this wait was: the share of players who would have had one by then at the
		 * drop rate (1 - e^-multiple). Small is lucky, large is dry. NaN when the wait isn't known
		 * exactly. Drops saved by older versions with a multiple rounded to 0.00 count as 0.005.
		 */
		public double getLuck()
		{
			return multiple == null || isAtLeast() ? Double.NaN : 1 - Math.exp(-(multiple == 0 ? 0.005 : multiple));
		}

		public boolean isEntered()
		{
			return entered != null && entered;
		}
	}
}

package com.onrate.engine.tracking;

import lombok.Getter;

/** The outcome of adding a past drop by hand: added, or why it was refused. */
public enum PastDropResult
{
	ADDED(false),
	/** The boss or item isn't known, or the item can't be entered at that page or part. */
	UNKNOWN(false),
	/** The kill count is below 1. */
	COUNT_TOO_LOW(true),
	/** The kill count is above the page's (or part's) own kill count. */
	COUNT_TOO_HIGH(true),
	/** On Rate saw this item at that kill count itself, so it can't be replaced. */
	SAW_AT_COUNT(true),
	/** History already lists every copy the collection log shows, and none can be replaced. */
	ALL_COPIES_LISTED(false),
	/** History is full of newer kills. */
	HISTORY_FULL(false);

	@Getter private final boolean retryable;

	PastDropResult(boolean retryable)
	{
		this.retryable = retryable;
	}

	public boolean isAdded()
	{
		return this == ADDED;
	}
}

package com.onrate.engine.tracking;

import java.util.Collections;

import java.util.Map;
import java.util.TreeMap;

/**
 * The player's choice to judge a shared item (dragon axe, draconic visage...) on each boss
 * separately: the copies On Rate saw drop go to the boss they dropped from, and the older ones
 * it didn't see go where the player said ({@link #older}). Saved with how many older copies
 * there were, so a copy the log gains later without On Rate seeing it (played elsewhere) makes
 * the item shared again until the player answers once more.
 */
class PoolSplit
{
	/**
	 * Older copies per boss name, or under {@link Tracker#NOT_FROM_A_BOSS} for the ones from
	 * other monsters (a visage from a regular dragon).
	 */
	Map<String, Integer> older = new TreeMap<>();

	PoolSplit(Map<String, Integer> older)
	{
		this.older.putAll(older);
	}

	int olderCopies()
	{
		int n = 0;
		for (Integer v : older == null ? Collections.<Integer>emptyList() : older.values())
		{
			n += v == null ? 0 : v;
		}
		return n;
	}

	int olderAt(String where)
	{
		Integer n = older == null ? null : older.get(where);
		return n == null ? 0 : n;
	}
}

package com.onrate.engine.tracking;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.BossPart;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

/**
 * How you usually raid, from the raids On Rate saw: your average purple chance per raid mode
 * (Chambers of Xeric and Tombs of Amascut, from your points) and your usual team size (Theatre of
 * Blood and The Fractured Archive, which have no points). Raids On Rate didn't see (older
 * completions) can use these instead of the settings' typical values. Worked out from the saved
 * raid records only; nothing here is saved.
 */
@AllArgsConstructor(access = AccessLevel.PRIVATE)
public final class RaidHabits
{
	/** A raid mode needs this many recorded raids before its average is used. */
	public static final int MIN_RAIDS = 10;
	/** Only the latest this many raids of a mode count: how you raid now. */
	public static final int RECENT = 50;

	private static final RaidHabits NONE = new RaidHabits(Collections.emptyMap(), Collections.emptyMap(), Collections.emptyMap());

	private final Map<String, Double> chances;
	private final Map<String, Integer> teams;
	private final Map<String, Integer> raids;

	/** No recorded raids: every mode keeps its setting. */
	public static RaidHabits none()
	{
		return NONE;
	}

	/**
	 * Your average purple chance per raid (0 to 1) for a raid mode key ("cox", "toaExpert"...), or NaN
	 * when there are fewer than {@link #MIN_RAIDS} raids with points.
	 */
	public double chance(String raid)
	{
		Double c = chances.get(raid);
		return c == null ? Double.NaN : c;
	}

	/** Your usual team size for a raid mode key ("tob", "fractured"...), or 0 when not enough raids. */
	public int teamSize(String raid)
	{
		Integer t = teams.get(raid);
		return t == null ? 0 : t;
	}

	/** How many recorded raids {@link #chance} or {@link #teamSize} came from, 0 when it isn't used. */
	public int raids(String raid)
	{
		Integer n = raids.get(raid);
		return n == null ? 0 : n;
	}

	/**
	 * Works it out for every raid in the catalogue. {@code progress} gives a boss's saved progress
	 * (null when there is none).
	 */
	public static RaidHabits of(Iterable<BossDefinition> bosses, Function<String, BossProgress> progress)
	{
		Map<String, Double> chances = new HashMap<>();
		Map<String, Integer> teams = new HashMap<>();
		Map<String, Integer> raids = new HashMap<>();
		for (BossDefinition boss : bosses)
		{
			if (boss.getRaid() == null)
			{
				continue;
			}
			BossProgress p = progress.apply(boss.getName());
			if (p == null || p.raids.isEmpty())
			{
				continue;
			}
			for (BossPart part : boss.getParts())
			{
				String key = part.getRaid();
				if (key == null || "none".equals(key))
				{
					continue;
				}
				List<RaidRecord> mine = new ArrayList<>();
				for (RaidRecord r : p.raids)
				{
					if (part.getName().equals(r.part))
					{
						mine.add(r);
					}
				}
				if (usesTeamSize(boss.getRaid()))
				{
					addTeam(key, mine, teams, raids);
				}
				else
				{
					addChance(key, mine, chances, raids);
				}
			}
		}
		return chances.isEmpty() && teams.isEmpty() ? NONE : new RaidHabits(chances, teams, raids);
	}

	/** Theatre of Blood and The Fractured Archive have no points: what they learn is your team size. */
	public static boolean usesTeamSize(String family)
	{
		return "tob".equals(family) || "fractured".equals(family);
	}

	/** The average purple chance of the latest raids with points (an average, as expected counts add up). */
	private static void addChance(String key, List<RaidRecord> mine, Map<String, Double> chances, Map<String, Integer> raids)
	{
		double sum = 0;
		int n = 0;
		for (int i = mine.size() - 1; i >= 0 && n < RECENT; i--)
		{
			double c = RateModel.purpleChance(mine.get(i));
			if (!Double.isNaN(c))
			{
				sum += c;
				n++;
			}
		}
		if (n >= MIN_RAIDS)
		{
			chances.put(key, sum / n);
			raids.put(key, n);
		}
	}

	/** The middle team size of the latest raids whose team was counted. */
	private static void addTeam(String key, List<RaidRecord> mine, Map<String, Integer> teams, Map<String, Integer> raids)
	{
		List<Integer> sizes = new ArrayList<>();
		for (int i = mine.size() - 1; i >= 0 && sizes.size() < RECENT; i--)
		{
			int t = mine.get(i).teamSize;
			if (t > 0)
			{
				sizes.add(t);
			}
		}
		if (sizes.size() >= MIN_RAIDS)
		{
			Collections.sort(sizes);
			teams.put(key, sizes.get(sizes.size() / 2));
			raids.put(key, sizes.size());
		}
	}
}

package com.onrate.engine.tracking;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import lombok.Getter;
import com.onrate.engine.data.*;
import com.onrate.engine.stats.RaidSettings;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.function.BiPredicate;
import java.util.function.ToLongFunction;

/**
 * What a raid page shows about the raids On Rate saw: your purple chance (and GP value) an hour per
 * setup you chose, your personal bests, and your points raid by raid. Worked out from the saved raid
 * records and History only; nothing here is saved.
 */
public final class RaidInsights
{
	/** A setup row needs this many raids with a time before it shows an hour figure. */
	public static final int MIN_TIMED = 5;
	/** Raid levels are grouped in steps of this many. */
	public static final int LEVEL_STEP = 50;
	/** Team sizes from this one up share one row ("6+"). */
	public static final int TEAM_CAP = 6;

	/** One setup: a raid mode with a team size, and at Tombs of Amascut a raid level step. */
	public static final class Setup
	{
		private final String part;
		private final int team;
		@Getter private final int levelFrom;
		private int raids;
		private double chanceSum;
		@Getter private int timed;
		private double timedChance;
		private double timedGp;
		private long timedMillis;
		private double gpSum;
		private final int players;
		/** Per item: its expected count over these raids, and over the timed ones. */
		private final Map<String, double[]> items = new HashMap<>();

		Setup(String part, int team, int levelFrom)
		{
			this(part, team, levelFrom, team);
		}

		Setup(String part, int team, int levelFrom, int players)
		{
			this.part = part;
			this.team = team;
			this.levelFrom = levelFrom;
			this.players = players;
		}

		/** The raid mode, e.g. "Normal" or "Challenge Mode". */
		public String getPart()
		{
			return part;
		}

		/**
		 * Team size, at Chambers of Xeric the size the raid scaled to; 0 = unknown; {@link #TEAM_CAP}
		 * means that many or more.
		 */
		public int getTeam()
		{
			return team;
		}

		/**
		 * Players still in the raid at the end: the team size for a raid that wasn't scaled, fewer for a
		 * scaled one (1 for "1+2"), -1 when not known whether it was scaled (older Chambers raids).
		 */
		public int getPlayers()
		{
			return players;
		}

		/** Raids of this setup with a known purple chance. */
		public int getRaids()
		{
			return raids;
		}

		/** True once there are enough timed raids for an hour figure. */
		public boolean isEnough()
		{
			return timed >= MIN_TIMED;
		}

		/** Average purple chance a raid (0 to 1). */
		public double getChancePerRaid()
		{
			return raids == 0 ? Double.NaN : chanceSum / raids;
		}

		/** Average GP value of the uniques a raid should give, at RuneLite's prices. */
		public double getGpPerRaid()
		{
			return raids == 0 ? Double.NaN : gpSum / raids;
		}

		/** Average time of the timed raids, or -1. */
		public long getAverageMillis()
		{
			return timed == 0 ? -1 : timedMillis / timed;
		}

		/** Purple chance an hour over the timed raids (0.088 = 8.8% an hour), NaN without times. */
		public double getChancePerHour()
		{
			return timedMillis <= 0 ? Double.NaN : timedChance / (timedMillis / 3_600_000.0);
		}

		/**
		 * One item's chance a raid at this setup (its expected count a raid: the purple chance times its
		 * share at these raid levels), NaN when the item isn't from the purple or there are no raids.
		 */
		public double getItemPerRaid(String item)
		{
			double[] s = items.get(item);
			return s == null || raids == 0 ? Double.NaN : s[0] / raids;
		}

		/** The same item an hour over the timed raids, NaN without times. */
		public double getItemPerHour(String item)
		{
			double[] s = items.get(item);
			return s == null || timedMillis <= 0 ? Double.NaN : s[1] / (timedMillis / 3_600_000.0);
		}

		void addItems(Setup other)
		{
			for (Map.Entry<String, double[]> e : other.items.entrySet())
			{
				double[] s = items.computeIfAbsent(e.getKey(), k -> new double[2]);
				s[0] += e.getValue()[0];
				s[1] += e.getValue()[1];
			}
		}

		/** GP value an hour over the timed raids, NaN without times. */
		public double getGpPerHour()
		{
			return timedMillis <= 0 ? Double.NaN : timedGp / (timedMillis / 3_600_000.0);
		}
	}

	/** A personal best: its value and the raid that set it. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	public static final class Best
	{
		@Getter private final double value;
		private final RaidRecord raid;

		public RaidRecord getRaid()
		{
			return raid;
		}

		/** When the raid that set it was saved (epoch millis), 0 when unknown. */
		public long getSavedMillis()
		{
			return raid.savedMillis;
		}
	}

	/** Personal bests of one mode and team size. Any of them can be null. */
	public static final class Bests
	{
		private final String part;
		private final int team;
		@Getter private Best fastest;
		@Getter private Best mostPoints;
		@Getter private Best highestLevel;
		@Getter private Best biggestShare;
		private int raids;
		@Getter private int withoutDeath;
		private int withDeaths;
		private final int players;

		Bests(String part, int team, int players)
		{
			this.part = part;
			this.team = team;
			this.players = players;
		}

		public String getPart()
		{
			return part;
		}

		public int getTeam()
		{
			return team;
		}

		/** Players at the end, as {@link Setup#getPlayers()}. */
		public int getPlayers()
		{
			return players;
		}

		/** Raids of this mode and team size. */
		public int getRaids()
		{
			return raids;
		}

		/** Raids whose deaths are known. */
		public int getDeathsKnown()
		{
			return withoutDeath + withDeaths;
		}
	}

	/** One raid on the points graph. */
	public static final class Point
	{
		private final RaidRecord raid;
		@Getter private final double chance;
		@Getter private final List<String> uniques;

		Point(RaidRecord raid, double chance, List<String> uniques)
		{
			this.raid = raid;
			this.chance = chance;
			this.uniques = uniques == null ? Collections.emptyList() : uniques;
		}

		public RaidRecord getRaid()
		{
			return raid;
		}

		/** When the raid was saved (epoch millis), 0 when unknown. */
		public long getSavedMillis()
		{
			return raid.savedMillis;
		}

		/** Your points, or 0 when unknown (Theatre of Blood has none). */
		public int getPoints()
		{
			return raid.personalPoints;
		}

		/** True when this raid gave you a unique (History, or Raid Data Tracker for raids it read). */
		public boolean isPurple()
		{
			return !uniques.isEmpty();
		}
	}

	/** Group by the whole setup: mode and team size (Tombs of Amascut: team size and raid level). */
	public static final int BY_SETUP = 0;
	/** Group by team size only. */
	public static final int BY_TEAM = 1;
	/** Group by the other choice only: the mode, or at Tombs of Amascut the raid level. */
	public static final int BY_CHOICE = 2;

	@Getter private final List<Setup> setups;
	@Getter private final List<Bests> bests;
	private final Map<String, List<Point>> points;
	private final List<String> order;
	/** Your latest raids with a known chance, all modes together, or null when there are none. */
	@Getter private Setup recent;

	private RaidInsights(List<Setup> setups, List<Bests> bests, Map<String, List<Point>> points, List<String> order)
	{
		this.setups = setups;
		this.bests = bests;
		this.points = points;
		this.order = order;
	}

	/**
	 * The setups grouped one of three ways ({@link #BY_SETUP}, {@link #BY_TEAM}, {@link #BY_CHOICE}),
	 * sorted the same way. A merged row has no mode (null), no team (-1) or no raid level (-1).
	 */
	public List<Setup> getSetups(int by)
	{
		if (by == BY_SETUP)
		{
			return setups;
		}
		Map<String, Setup> merged = new LinkedHashMap<>();
		for (Setup s : setups)
		{
			boolean level = s.levelFrom >= 0 || isLevelled();
			String part = by == BY_CHOICE && !level ? s.part : null;
			int team = by == BY_TEAM ? s.team : -1;
			int from = by == BY_CHOICE && level ? s.levelFrom : -1;
			int players = by == BY_TEAM ? s.players : -1;
			Setup m = merged.computeIfAbsent(part + "#" + team + "#" + players + "#" + from, k -> new Setup(part, team, from, players));
			m.raids += s.raids;
			m.chanceSum += s.chanceSum;
			m.gpSum += s.gpSum;
			m.timed += s.timed;
			m.timedChance += s.timedChance;
			m.timedGp += s.timedGp;
			m.timedMillis += s.timedMillis;
			m.addItems(s);
		}
		List<Setup> list = new ArrayList<>(merged.values());
		sort(list, order);
		return list;
	}

	/** True when the setups are told apart by raid level (Tombs of Amascut). */
	private boolean isLevelled()
	{
		for (Setup s : setups)
		{
			if (s.levelFrom >= 0)
			{
				return true;
			}
		}
		return false;
	}

	private static void sort(List<Setup> setups, List<String> order)
	{
		setups.sort(Comparator.comparing((Setup s) -> !s.isEnough())
			.thenComparing(s -> s.isEnough() ? -s.getChancePerHour() : 0.0)
			.thenComparing(s -> s.part == null ? -1 : order.indexOf(s.part))
			.thenComparingInt(s -> s.team)
			.thenComparingInt(s -> -s.players)
			.thenComparingInt(s -> s.levelFrom));
	}

	/**
	 * Your latest {@link RaidHabits#RECENT} raids with a known chance, all modes together, as one row:
	 * how you raid now, for the collection log forecast. Null when On Rate saw none.
	 */

	private static Setup recentOf(BossDefinition boss, Map<String, BossPart> parts, List<RaidRecord> all, RaidSettings settings)
	{
		Setup recent = new Setup(null, -1, -1);
		for (int i = all.size() - 1; i >= 0 && recent.raids < RaidHabits.RECENT; i--)
		{
			RaidRecord r = all.get(i);
			BossPart part = r.part == null ? null : parts.get(r.part);
			double chance = part == null ? Double.NaN : RateModel.recordChance(r, part, settings);
			if (Double.isNaN(chance))
			{
				continue;
			}
			recent.raids++;
			recent.chanceSum += chance;
			if (r.durationMillis > 0)
			{
				recent.timed++;
				recent.timedChance += chance;
				recent.timedMillis += r.durationMillis;
			}
			addItems(boss, part, r, chance, recent);
		}
		return recent.raids == 0 ? null : recent;
	}

	/** Raids per mode, oldest first, for the graph. */
	public List<Point> getPoints(String part)
	{
		List<Point> p = points.get(part);
		return p == null ? Collections.emptyList() : p;
	}

	/** True when no raid of this boss was saved. */
	public boolean isEmpty()
	{
		return setups.isEmpty() && bests.isEmpty();
	}

	/** The row a team size goes in: 0 unknown, then 1 to {@link #TEAM_CAP}, the cap meaning that many or more. */
	static int teamRow(int teamSize)
	{
		return teamSize <= 0 ? 0 : Math.min(teamSize, TEAM_CAP);
	}

	/** The first raid level of the step a raid level goes in, or -1 when unknown. */
	static int levelStep(int raidLevel)
	{
		return raidLevel < 0 ? -1 : raidLevel / LEVEL_STEP * LEVEL_STEP;
	}

	/**
	 * Works it all out for one raid. {@code prices} may be null (no GP value); {@code counts} says
	 * whether a drop counts (not left out), like the GP value tile.
	 */
	static RaidInsights of(BossDefinition boss, BossProgress progress, RaidSettings settings,
		ToLongFunction<String> prices, BiPredicate<BossDefinition, DropDefinition> counts)
	{
		return of(boss, progress, settings, prices, counts, Collections.emptyMap(), Collections.emptyList(), Collections.emptyMap());
	}

	/** The same, with your uniques from raids read from Raid Data Tracker, by "mode#completion count". */
	static RaidInsights of(BossDefinition boss, BossProgress progress, RaidSettings settings,
		ToLongFunction<String> prices, BiPredicate<BossDefinition, DropDefinition> counts, Map<String, String> imported,
		List<RaidRecord> extra, Map<RaidRecord, String> extraUniques)
	{
		if (boss == null || boss.getRaid() == null || progress == null)
		{
			return new RaidInsights(new ArrayList<>(), new ArrayList<>(), new LinkedHashMap<>(), new ArrayList<>());
		}
		Map<String, BossPart> parts = new LinkedHashMap<>();
		for (BossPart p : boss.getParts())
		{
			parts.put(p.getName(), p);
		}
		Map<String, List<String>> purples = purpleRaids(progress, imported);
		Map<String, Setup> setupMap = new LinkedHashMap<>();
		Map<String, Bests> bestMap = new LinkedHashMap<>();
		Map<String, List<Point>> points = new LinkedHashMap<>();
		boolean toa = "toa".equals(boss.getRaid());
		// the saved raids, and the raids that only show here (Tombs of Amascut from Raid Data Tracker), by date
		List<RaidRecord> all = new ArrayList<>(progress.raids);
		if (extra != null && !extra.isEmpty())
		{
			all.addAll(extra);
			all.sort(Comparator.comparingLong(x -> x.savedMillis));
		}
		for (RaidRecord r : all)
		{
			BossPart part = r.part == null ? null : parts.get(r.part);
			if (part == null)
			{
				continue;
			}
			double chance = RateModel.recordChance(r, part, settings);
			int team = teamRow(r.teamSize);
			// Chambers of Xeric can be scaled: fewer players than the scale; -1 when that isn't known
			int players = !"cox".equals(boss.getRaid()) || team <= 1 ? team
				: r.players == null ? -1 : Math.min(teamRow(r.players), team);
			points.computeIfAbsent(part.getName(), k -> new ArrayList<>())
				.add(new Point(r, chance, extraUniques != null && extraUniques.containsKey(r)
					? Collections.singletonList(extraUniques.get(r)) : purples.get(part.getName() + "#" + r.kc)));
			addBest(bestMap.computeIfAbsent(part.getName() + "#" + team + "#" + players, k -> new Bests(part.getName(), team, players)), r);
			if (Double.isNaN(chance))
			{
				continue;
			}
			int level = toa ? levelStep(r.raidLevel) : -1;
			Setup s = setupMap.computeIfAbsent(part.getName() + "#" + team + "#" + players + "#" + level,
				k -> new Setup(part.getName(), team, level, players));
			double gp = prices == null ? 0 : gpOf(boss, part, r, chance, prices, counts);
			s.raids++;
			s.chanceSum += chance;
			s.gpSum += gp;
			addItems(boss, part, r, chance, s);
			if (r.durationMillis > 0)
			{
				s.timed++;
				s.timedChance += chance;
				s.timedGp += gp;
				s.timedMillis += r.durationMillis;
			}
		}
		Setup recent = recentOf(boss, parts, all, settings);
		List<Setup> setups = new ArrayList<>(setupMap.values());
		List<String> order = new ArrayList<>(parts.keySet());
		sort(setups, order);
		List<Bests> bests = new ArrayList<>(bestMap.values());
		bests.sort(Comparator.comparingInt((Bests b) -> order.indexOf(b.part)).thenComparingInt(b -> b.team).thenComparingInt(b -> -b.players));
		RaidInsights insights = new RaidInsights(setups, bests, points, order);
		insights.recent = recent;
		return insights;
	}

	/**
	 * The uniques of each raid that brought one, by "mode#kc": from History, and for raids History
	 * doesn't have, from Raid Data Tracker.
	 */
	private static Map<String, List<String>> purpleRaids(BossProgress progress, Map<String, String> imported)
	{
		Map<String, List<String>> purples = new HashMap<>();
		for (KillEntry k : progress.kills)
		{
			if (k.partKc != null && k.drops != null && !k.drops.isEmpty())
			{
				List<String> names = purples.computeIfAbsent((k.part == null ? "" : k.part) + "#" + k.partKc, x -> new ArrayList<>());
				for (KillEntry.DropEntry d : k.drops)
				{
					names.add(d.getName());
				}
			}
		}
		if (imported != null)
		{
			for (Map.Entry<String, String> e : imported.entrySet())
			{
				purples.computeIfAbsent(e.getKey(), x -> new ArrayList<>(Collections.singletonList(e.getValue())));
			}
		}
		return purples;
	}

	private static void addBest(Bests b, RaidRecord r)
	{
		b.raids++;
		if (r.durationMillis > 0 && (b.fastest == null || r.durationMillis < b.fastest.value))
		{
			b.fastest = new Best(r.durationMillis, r);
		}
		if (r.personalPoints > 0 && (b.mostPoints == null || r.personalPoints > b.mostPoints.value))
		{
			b.mostPoints = new Best(r.personalPoints, r);
		}
		if (r.raidLevel >= 0 && (b.highestLevel == null || r.raidLevel > b.highestLevel.value))
		{
			b.highestLevel = new Best(r.raidLevel, r);
		}
		if (r.contribution >= 0 && (b.biggestShare == null || r.contribution > b.biggestShare.value))
		{
			b.biggestShare = new Best(r.contribution, r);
		}
		if (r.deaths == 0)
		{
			b.withoutDeath++;
		}
		else if (r.deaths > 0)
		{
			b.withDeaths++;
		}
	}

	/** Adds what one raid should give of each item from the purple (the pet too) to its setup. */
	private static void addItems(BossDefinition boss, BossPart part, RaidRecord r, double chance, Setup s)
	{
		for (DropDefinition drop : boss.getDrops())
		{
			if (!RateModel.fromPurple(part, drop))
			{
				continue;
			}
			double expected = RateModel.recordDropExpected(boss, part, drop, r, chance);
			double[] sums = s.items.computeIfAbsent(drop.getName(), k -> new double[2]);
			sums[0] += expected;
			if (r.durationMillis > 0)
			{
				sums[1] += expected;
			}
		}
	}

	/** GP value the uniques of one raid should give: each drop's expected count times its price. */
	private static double gpOf(BossDefinition boss, BossPart part, RaidRecord r, double chance,
		ToLongFunction<String> prices, BiPredicate<BossDefinition, DropDefinition> counts)
	{
		double sum = 0;
		for (DropDefinition drop : boss.getDrops())
		{
			if (!RateModel.fromPurple(part, drop) || (counts != null && !counts.test(boss, drop)))
			{
				continue;
			}
			long price = Math.max(0, prices.applyAsLong(drop.getName()));
			if (price > 0)
			{
				sum += RateModel.recordDropExpected(boss, part, drop, r, chance) * price;
			}
		}
		return sum;
	}
}

package com.onrate.engine.tracking;

/**
 * One finished raid with what On Rate could read about it. Saved with the completion, so
 * the purple chance can be worked out from the points instead of the settings.
 * Fields the game didn't give stay at 0 / -1.
 */
public class RaidRecord
{
	/** "cox", "toa", "tob" or "fractured": the start of the raid setting keys. */
	String family;
	/** Mode, matched from the completion count message, e.g. "Challenge Mode". */
	String part;
	/** Completion count of that mode at the end of this raid. */
	int kc;
	/** Your points (ToA: without the 5,000 everyone starts with; see {@link #estimated}). 0 = unknown. */
	int personalPoints;
	/** Team points. 0 = unknown (a ToA team without the Tombs of Amascut plugin's total). */
	int teamPoints;
	/** ToA: points the whole party earns once (puzzle rooms). */
	int partyPoints;
	int teamSize;
	/** ToA raid level, -1 when not a ToA raid. */
	int raidLevel = -1;
	/** True when the points are On Rate's own estimate (ToA). */
	boolean estimated;
	/** ToB board: your deaths, the team's deaths and whether you were MVP (-1 / null = unknown). */
	int deaths = -1;
	int teamDeaths = -1;
	Boolean mvp;
	/**
	 * The Fractured Archive: your contribution out of the raid's 700 before deaths, or -1 when
	 * unknown (then an even share of the team size is assumed).
	 */
	double contribution = -1;
	/** When it was saved (epoch millis), to match the board or a party message to it. */
	long savedMillis;
	/** How long the raid took in milliseconds, as the game's chat said; -1 when unknown. */
	int durationMillis = -1;
	/**
	 * Chambers of Xeric: the players still in the raid at the end, next to {@link #teamSize}, the size
	 * the raid scaled to. Fewer players than the scale is a scaled raid ("1+2": one player, scaled for
	 * three). Null when unknown (raids saved before this was read, and imported raids); then it isn't
	 * written either, so those saves stay exactly as they were.
	 */
	Integer players;

	public RaidRecord()
	{
	}

	/**
	 * A Chambers of Xeric raid with the size it scaled to and the players still in it at the end.
	 */
	public static RaidRecord cox(int personalPoints, int teamPoints, int scale, int players)
	{
		RaidRecord r = cox(personalPoints, teamPoints, scale);
		r.players = players > 0 ? players : null;
		return r;
	}

	public static RaidRecord cox(int personalPoints, int teamPoints, int teamSize)
	{
		RaidRecord r = new RaidRecord();
		r.family = "cox";
		r.personalPoints = personalPoints;
		r.teamPoints = teamPoints;
		r.teamSize = teamSize;
		return r;
	}

	/** {@code teamPoints} 0 when unknown. */
	public static RaidRecord toa(int personalPoints, int partyPoints, int teamPoints, int teamSize, int raidLevel)
	{
		RaidRecord r = new RaidRecord();
		r.family = "toa";
		r.personalPoints = personalPoints;
		r.partyPoints = partyPoints;
		r.teamPoints = teamPoints;
		r.teamSize = teamSize;
		r.raidLevel = raidLevel;
		r.estimated = true;
		return r;
	}

	/** A Tombs of Amascut raid with the exact points the game sent (not On Rate's estimate). */
	public static RaidRecord toaExact(int personalPoints, int teamSize, int raidLevel)
	{
		RaidRecord r = toa(personalPoints, 0, 0, teamSize, raidLevel);
		r.estimated = false;
		return r;
	}

	public static RaidRecord tob(int teamSize, int deaths, int teamDeaths, Boolean mvp)
	{
		RaidRecord r = new RaidRecord();
		r.family = "tob";
		r.teamSize = teamSize;
		r.deaths = deaths;
		r.teamDeaths = teamDeaths;
		r.mvp = mvp;
		return r;
	}

	/**
	 * A Fractured Archive raid. {@code deaths} -1 and {@code contribution} -1 when unknown: the
	 * chance then assumes an even share of the damage and no deaths.
	 */
	public static RaidRecord fractured(int teamSize, int deaths, double contribution)
	{
		RaidRecord r = new RaidRecord();
		r.family = "fractured";
		r.teamSize = teamSize;
		r.deaths = deaths;
		r.contribution = contribution;
		return r;
	}

	public double getContribution()
	{
		return contribution;
	}

	/** How long the raid took in milliseconds, or -1 when unknown. */
	public int getDurationMillis()
	{
		return durationMillis;
	}

	public String getFamily()
	{
		return family;
	}

	public String getPart()
	{
		return part;
	}

	public int getKc()
	{
		return kc;
	}

	public int getPersonalPoints()
	{
		return personalPoints;
	}

	public int getTeamPoints()
	{
		return teamPoints;
	}

	public int getPartyPoints()
	{
		return partyPoints;
	}

	public int getTeamSize()
	{
		return teamSize;
	}

	public int getRaidLevel()
	{
		return raidLevel;
	}

	public boolean isEstimated()
	{
		return estimated;
	}

	public int getDeaths()
	{
		return deaths;
	}

	public int getTeamDeaths()
	{
		return teamDeaths;
	}

	public Boolean getMvp()
	{
		return mvp;
	}
}

package com.onrate.engine.tracking;

import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.Set;

import com.onrate.engine.data.*;
import com.onrate.engine.stats.RaidChance;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Raid data that arrives in pieces: the points (from the raid's own interface or another plugin) and
 * the completion count message come seconds apart in either order, the Tombs of Amascut team total
 * and party points can follow later, and the Fractured Archive damage share may come just after. They
 * are matched within each raid's window and saved as one record per completion. Also the raid
 * records themselves: how many were measured, the average purple chance, and what a raid wait expects.
 * <p>
 * Package-private and unsynchronized: reached only through {@link Tracker}, under its lock.
 */
final class RaidRecords
{
	private final TrackerContext ctx;
	private final BossCatalog catalog;
	private final Statistics statistics;
	private final DayCounts dayCounts;

	/** A finished raid's data that arrived before its completion count message. */
	private RaidRecord pendingRecord;
	private long pendingRecordMillis;
	/** The raid mode whose completion message came last, for data that arrives after it. */
	private String lastRaidBoss;
	private String lastRaidPart;
	private int lastRaidKc;
	private long lastRaidMillis;
	/** The latest Tombs of Amascut record, for the team total the ToA plugin sends after it. */
	private RaidRecord latestToa;
	private long latestToaMillis;
	/** The latest Fractured Archive raid, for the damage share that may come just after it. */
	private RaidRecord latestFractured;
	private String latestFracturedBoss;
	private long latestFracturedMillis;
	private int[] pendingParty;
	private long pendingPartyMillis;
	/** Points and the completion count message arrive within seconds of each other. */
	private static final long RAID_MATCH_MILLIS = 60_000;
	/** The Theatre of Blood board can be read a while after the completion message. */
	private static final long TOB_MATCH_MILLIS = 5 * 60_000;
	private static final long PARTY_MATCH_MILLIS = 2 * 60_000;
	/** Most raid records kept per raid. */
	static final int MAX_RAID_RECORDS = 5000;
	/**
	 * Your uniques from raids read from Raid Data Tracker, per boss and "mode#completion count". Only
	 * kept while the account is loaded (they are read again at every login), never saved: History
	 * stays what On Rate saw itself.
	 */
	private final Map<String, Map<String, String>> importedUniques = new HashMap<>();
	/** Tombs of Amascut raids from Raid Data Tracker, for the raid sections only; never saved. */
	private final Map<String, List<RaidRecord>> sectionOnly = new HashMap<>();
	private final Map<RaidRecord, String> sectionUniques = new IdentityHashMap<>();

	RaidRecords(TrackerContext ctx, Statistics statistics, DayCounts dayCounts)
	{
		this.ctx = ctx;
		this.catalog = ctx.catalog;
		this.statistics = statistics;
		this.dayCounts = dayCounts;
	}

	/**
	 * Another account was loaded: raid data waiting for its match is dropped. Exactly the fields
	 * Tracker reset before it was split up; the pending record's time, the last raid's mode and
	 * count and the latest Fractured Archive raid were never reset there and are still left as is.
	 */
	void clear()
	{
		importedUniques.clear();
		sectionOnly.clear();
		sectionUniques.clear();
		lastRaidMillis = 0;
		latestToaMillis = 0;
		pendingPartyMillis = 0;
		pendingRecord = null;
		lastRaidBoss = null;
		latestToa = null;
		pendingParty = null;
	}

	/**
	 * Average purple chance of the raids in this mode where On Rate had your points, or NaN.
	 * A good value for the setting that raids without points use.
	 */
	double averagePurpleChance(String bossName, String part)
	{
		double sum = 0;
		int n = 0;
		BossDefinition boss = catalog.byName(bossName);
		for (RaidRecord r : raidRecords(bossName))
		{
			double chance = RateModel.purpleChance(r);
			if (!Double.isNaN(chance) && "fractured".equals(r.family) && boss != null && boss.hasParts())
			{
				// the Fractured Archive's base chance follows the setting
				chance = RateModel.recordChance(r, boss.getParts().get(0), ctx.settings());
			}
			if ((part == null ? bossName : part).equals(r.part) && !Double.isNaN(chance))
			{
				sum += chance;
				n++;
			}
		}
		return n == 0 ? Double.NaN : sum / n;
	}

	/**
	 * Data read at the end of a raid: points (CoX, estimated for ToA) or the ToB board.
	 * The completion count message tells which mode it was; it may come just before or
	 * just after. Returns the boss whose numbers changed, or null.
	 */
	String onRaidRecord(RaidRecord record, long nowMillis)
	{
		if (record == null || record.family == null)
		{
			return null;
		}
		record.savedMillis = nowMillis;
		if ("fractured".equals(record.family) && latestFractured != null
			&& nowMillis - latestFracturedMillis <= RAID_MATCH_MILLIS)
		{
			// the completion message came first and saved the raid: add the damage share to it
			String boss = latestFracturedBoss;
			double before = statistics.anyExpected(boss);
			latestFractured.contribution = record.contribution;
			latestFractured.deaths = record.deaths;
			latestFractured = null;
			ctx.raidsChanged.add(boss);
			dayCounts.shiftToday(boss, statistics.anyExpected(boss) - before);
			return boss;
		}
		if ("toa".equals(record.family))
		{
			latestToa = record;
			latestToaMillis = nowMillis;
			applyPendingParty(record, nowMillis);
		}
		if (lastRaidBoss != null && nowMillis - lastRaidMillis <= matchWindow(record.family)
			&& raidFamily(lastRaidBoss, lastRaidPart).startsWith(record.family))
		{
			String boss = lastRaidBoss;
			saveRecord(boss, lastRaidPart, lastRaidKc, record);
			lastRaidBoss = null;
			return boss;
		}
		pendingRecord = record;
		pendingRecordMillis = nowMillis;
		return null;
	}

	/**
	 * Your exact points for the latest Tombs of Amascut raid, sent by the game a moment after
	 * the raid was saved: they replace On Rate's estimate in it. Returns the boss, or null.
	 */
	String onToaPoints(int personalPoints, long nowMillis)
	{
		if (personalPoints <= 0 || latestToa == null || nowMillis - latestToaMillis > PARTY_MATCH_MILLIS)
		{
			return null;
		}
		String toaBoss = toaBossName();
		double before = toaBoss == null ? Double.NaN : statistics.anyExpected(toaBoss);
		latestToa.personalPoints = personalPoints;
		// the estimate's extra points (counted outside a RuneLite party) are part of the exact number
		latestToa.partyPoints = 0;
		latestToa.estimated = false;
		if (toaBoss != null)
		{
			ctx.raidsChanged.add(toaBoss);
			dayCounts.shiftToday(toaBoss, statistics.anyExpected(toaBoss) - before);
		}
		return toaBoss;
	}

	String toaBossName()
	{
		for (BossDefinition boss : catalog.getBosses())
		{
			if ("toa".equals(boss.getRaid()))
			{
				return boss.getName();
			}
		}
		return null;
	}

	/**
	 * Team and personal points the Tombs of Amascut plugin sends at the end of a raid.
	 * They replace On Rate's own estimate for the latest ToA raid.
	 */
	String onPartyPoints(int personalPoints, int teamPoints, long nowMillis)
	{
		if (personalPoints <= 0 || teamPoints <= 0)
		{
			return null;
		}
		if (latestToa != null && nowMillis - latestToaMillis <= PARTY_MATCH_MILLIS)
		{
			String toaBoss = null;
			for (BossDefinition boss : catalog.getBosses())
			{
				if ("toa".equals(boss.getRaid()))
				{
					toaBoss = boss.getName();
				}
			}
			double before = toaBoss == null ? Double.NaN : statistics.anyExpected(toaBoss);
			latestToa.personalPoints = personalPoints;
			latestToa.teamPoints = teamPoints;
			latestToa = null;
			if (toaBoss != null)
			{
				ctx.raidsChanged.add(toaBoss);
				dayCounts.shiftToday(toaBoss, statistics.anyExpected(toaBoss) - before);
			}
			return toaBoss;
		}
		pendingParty = new int[]{personalPoints, teamPoints};
		pendingPartyMillis = nowMillis;
		return null;
	}

	void applyPendingParty(RaidRecord record, long nowMillis)
	{
		if (pendingParty != null && nowMillis - pendingPartyMillis <= PARTY_MATCH_MILLIS)
		{
			record.personalPoints = pendingParty[0];
			record.teamPoints = pendingParty[1];
			latestToa = null;
		}
		pendingParty = null;
	}

	static long matchWindow(String family)
	{
		return "tob".equals(family) ? TOB_MATCH_MILLIS : RAID_MATCH_MILLIS;
	}

	void onRaidCompletion(BossDefinition boss, String part, int kc, long nowMillis)
	{
		String family = raidFamily(boss.getName(), part);
		if (family.isEmpty())
		{
			return;
		}
		if ("fractured".equals(family))
		{
			// the damage share may have come just before (or comes just after: see onRaidRecord);
			// the team is counted around you now, for its bonus and your expected contribution
			boolean pending = pendingRecord != null && "fractured".equals(pendingRecord.family)
				&& nowMillis - pendingRecordMillis <= RAID_MATCH_MILLIS;
			RaidRecord record = pending ? pendingRecord : RaidRecord.fractured(0, -1, -1);
			pendingRecord = null;
			lastRaidBoss = null;
			int size = ctx.teamSize().applyAsInt(boss.getName());
			if (size > 0)
			{
				record.teamSize = Math.min(size, RaidChance.TFA_MAX_TEAM);
			}
			if (record.teamSize > 0 || record.contribution >= 0)
			{
				record.savedMillis = nowMillis;
				saveRecord(boss.getName(), part, kc, record);
				latestFractured = pending ? null : record;
				latestFracturedBoss = boss.getName();
				latestFracturedMillis = nowMillis;
			}
			return;
		}
		if (pendingRecord != null && nowMillis - pendingRecordMillis <= matchWindow(pendingRecord.family)
			&& family.startsWith(pendingRecord.family))
		{
			saveRecord(boss.getName(), part, kc, pendingRecord);
			pendingRecord = null;
			lastRaidBoss = null;
			return;
		}
		pendingRecord = null;
		lastRaidBoss = boss.getName();
		lastRaidPart = part;
		lastRaidKc = kc;
		lastRaidMillis = nowMillis;
	}

	/** The raid setting key of a boss part ("coxCm"), or "" when it isn't a raid. */
	String raidFamily(String bossName, String partName)
	{
		BossDefinition boss = catalog.byName(bossName);
		if (boss == null || boss.getRaid() == null)
		{
			return "";
		}
		if (partName != null && boss.hasParts())
		{
			for (BossPart part : boss.getParts())
			{
				if (part.getName().equals(partName))
				{
					return part.getRaid() == null || "none".equals(part.getRaid()) ? "" : part.getRaid();
				}
			}
		}
		return boss.hasParts() ? "" : boss.getRaid();
	}

	void saveRecord(String bossName, String part, int kc, RaidRecord record)
	{
		double before = statistics.anyExpected(bossName);
		record.part = part == null ? bossName : part;
		record.kc = kc;
		if (record.durationMillis < 0)
		{
			// the raid's time message may have come before its points
			record.durationMillis = FightTimes.knownDuration(ctx.state().get(bossName), record.part, kc);
		}
		List<RaidRecord> raids = ctx.state().get(bossName).raids;
		raids.add(record);
		ctx.raidsChanged.add(bossName);
		while (raids.size() > MAX_RAID_RECORDS)
		{
			raids.remove(0);
		}
		dayCounts.shiftToday(bossName, statistics.anyExpected(bossName) - before);
	}

	/**
	 * Adds raids read from Raid Data Tracker as raid records, so they count with their own points like
	 * the raids On Rate saw. A raid On Rate already has (same mode and completion count) is left as it
	 * is: On Rate's own record wins. Per mode, a raid whose completion count doesn't go up with its date
	 * is skipped, as a count that runs backwards can't be placed. Raids are kept oldest first. Safe to
	 * call again with the same list.
	 *
	 * @return how many raids were added
	 */
	int importRaids(String bossName, List<ImportedRaid> imported)
	{
		BossDefinition boss = catalog.byName(bossName);
		if (boss == null || boss.getRaid() == null || imported == null || imported.isEmpty())
		{
			return 0;
		}
		Map<String, BossPart> parts = new HashMap<>();
		for (BossPart p : boss.getParts())
		{
			parts.put(p.getName(), p);
		}
		BossProgress progress = ctx.state().get(bossName);
		Set<String> have = new HashSet<>();
		for (RaidRecord r : progress.raids)
		{
			have.add(r.part + "#" + r.kc);
		}
		List<ImportedRaid> sorted = new ArrayList<>(imported);
		sorted.sort(Comparator.comparingLong(r -> r.when));
		Map<String, Integer> lastKc = new HashMap<>();
		Map<String, String> uniques = importedUniques.computeIfAbsent(bossName, k -> new HashMap<>());
		boolean toa = "toa".equals(boss.getRaid());
		List<RaidRecord> extra = new ArrayList<>();
		int added = 0;
		for (ImportedRaid i : sorted)
		{
			if (i.part == null || !parts.containsKey(i.part) || i.personalPoints <= 0)
			{
				continue;
			}
			if (toa)
			{
				// Raid Data Tracker's Tombs counts don't reliably follow the mode (a raid's level and
				// count can disagree), so these raids can't be placed among your raids for the luck
				// numbers. They only show in the raid sections, matched to your own raids by date.
				if (!nearOwnRaid(progress, i.when))
				{
					RaidRecord r = RaidRecord.toa(i.personalPoints, 0, i.totalPoints, Math.max(1, i.teamSize), i.raidLevel);
					r.part = i.part;
					r.savedMillis = i.when;
					r.durationMillis = i.millis > 0 && i.millis <= Integer.MAX_VALUE ? (int) i.millis : -1;
					extra.add(r);
					if (i.unique != null)
					{
						sectionUniques.put(r, i.unique);
					}
				}
				continue;
			}
			if (i.kc <= 0)
			{
				continue;
			}
			Integer last = lastKc.get(i.part);
			if (last != null && i.kc <= last)
			{
				continue;
			}
			lastKc.put(i.part, i.kc);
			String key = i.part + "#" + i.kc;
			if (i.unique != null)
			{
				uniques.put(key, i.unique);
			}
			if (!have.add(key))
			{
				continue;
			}
			RaidRecord r = "toa".equals(boss.getRaid())
				? RaidRecord.toa(i.personalPoints, 0, i.totalPoints, Math.max(1, i.teamSize), i.raidLevel)
				: RaidRecord.cox(i.personalPoints, Math.max(i.totalPoints, i.personalPoints), Math.max(1, i.teamSize));
			r.part = i.part;
			r.kc = i.kc;
			r.savedMillis = i.when;
			r.durationMillis = i.millis > 0 && i.millis <= Integer.MAX_VALUE ? (int) i.millis : -1;
			// before the newer raids at the end, without moving any raid already saved
			int at = progress.raids.size();
			while (at > 0 && progress.raids.get(at - 1).savedMillis > r.savedMillis)
			{
				at--;
			}
			progress.raids.add(at, r);
			added++;
		}
		if (toa)
		{
			// read again at every login: the new list replaces the last one
			List<RaidRecord> old = sectionOnly.put(bossName, extra);
			if (old != null)
			{
				old.forEach(sectionUniques::remove);
			}
		}
		if (added > 0)
		{
			while (progress.raids.size() > MAX_RAID_RECORDS)
			{
				progress.raids.remove(0);
			}
			ctx.raidsChanged.add(bossName);
		}
		return added;
	}

	/** A raid read from Raid Data Tracker within this long of one On Rate saved is that same raid. */
	static final long SAME_RAID_MILLIS = 10 * 60_000;

	private static boolean nearOwnRaid(BossProgress progress, long when)
	{
		for (RaidRecord r : progress.raids)
		{
			if (r.savedMillis > 0 && Math.abs(r.savedMillis - when) <= SAME_RAID_MILLIS)
			{
				return true;
			}
		}
		return false;
	}

	/** Raids read from Raid Data Tracker that only show in the raid sections (Tombs of Amascut), oldest first. */
	List<RaidRecord> sectionOnly(String bossName)
	{
		List<RaidRecord> r = sectionOnly.get(bossName);
		return r == null ? Collections.emptyList() : r;
	}

	/** Your unique from each of those raids. */
	Map<RaidRecord, String> sectionUniques()
	{
		return sectionUniques;
	}

	/** Your uniques from raids read from Raid Data Tracker, by "mode#completion count". */
	Map<String, String> importedUniques(String bossName)
	{
		Map<String, String> u = importedUniques.get(bossName);
		return u == null ? Collections.emptyMap() : u;
	}

	/** Completions of this raid mode whose purple chance came from your points. */
	int measuredRaids(String bossName, String part)
	{
		int n = 0;
		for (RaidRecord r : raidRecords(bossName))
		{
			if ((part == null ? bossName : part).equals(r.part) && !Double.isNaN(RateModel.purpleChance(r)))
			{
				n++;
			}
		}
		return n;
	}

	/** Every raid saved for this boss, oldest first. */
	List<RaidRecord> raidRecords(String bossName)
	{
		BossProgress progress = ctx.state().peek(bossName);
		return progress == null ? new ArrayList<>() : new ArrayList<>(progress.raids);
	}

	/**
	 * Uniques of this item you would expect from the raids of a mode after {@code fromKc} up to
	 * and including {@code toKc} (that mode's own counts): raids On Rate counted use their own
	 * purple chance (from the points), the others the chance from the settings.
	 */
	double raidWaitExpected(BossDefinition boss, BossPart part, DropDefinition drop, BossProgress progress,
		int fromKc, int toKc)
	{
		double perRaid = RateModel.partRate(boss, part, drop, ctx.settings());
		Map<Integer, RaidRecord> counted = new HashMap<>();
		for (RaidRecord r : progress.raids)
		{
			if (part.getName().equals(r.part) && r.kc > fromKc && r.kc <= toKc)
			{
				counted.put(r.kc, r);
			}
		}
		double sum = 0;
		for (int raid = fromKc + 1; raid <= toKc; raid++)
		{
			RaidRecord r = counted.get(raid);
			double chance = r == null ? Double.NaN : RateModel.recordChance(r, part, ctx.settings());
			sum += Double.isNaN(chance) ? perRaid : RateModel.recordDropExpected(boss, part, drop, r, chance);
		}
		return sum;
	}
}

package com.onrate.engine.tracking;

import com.onrate.engine.math.*;
import com.onrate.engine.data.*;
import com.onrate.engine.stats.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * What a drop should give, from its rate, the raid points saved with each raid, the raid level,
 * the part of a combined page, the delve level or the wave. Pure functions: no state, no
 * RuneLite. Moved out of {@link Tracker} unchanged (the replay tests compare it with the original).
 */
public final class RateModel
{
	private RateModel()
	{
	}

	/** Your expected uniques for this raid from its points, or NaN when they are unknown. */
	public static double purpleChance(RaidRecord record)
	{
		if (record == null || record.family == null)
		{
			return Double.NaN;
		}
		switch (record.family)
		{
			case "cox":
				return RaidChance.cox(record.personalPoints, record.teamPoints);
			case "toa":
				return RaidChance.toa(record.personalPoints, record.partyPoints, record.teamPoints,
					record.teamSize, record.raidLevel);
			case "fractured":
				// only a measured contribution counts as "from your points"; a team size alone doesn't
				return record.contribution < 0 ? Double.NaN
					: fracturedChance(record, RaidChance.TFA_BASE_CHANCE, record.teamSize > 0 ? record.teamSize : 2);
			default:
				return Double.NaN;
		}
	}

	/**
	 * Share of a purple that is this item at a raid level (ToA's weights shift towards the
	 * rarer items at high raid levels). Falls back to {@code normal} without level weights.
	 */
	static double levelShare(BossDefinition boss, DropDefinition drop, int raidLevel, double normal)
	{
		boolean any = false;
		double total = 0;
		for (DropDefinition d : boss.getDrops())
		{
			any |= d.hasLevelWeights();
			Double w = d.getWeightAtLevel(raidLevel);
			if (w != null)
			{
				total += w;
			}
		}
		Double w = drop.getWeightAtLevel(raidLevel);
		if (!any || w == null || total <= 0)
		{
			return normal;
		}
		return w / total;
	}

	/**
	 * Your purple chance for one saved raid: from its points (CoX, ToA), or for ToB the
	 * team chance from the settings split over that raid's real team size. NaN when
	 * neither is known, so the setting is used.
	 */
	static double recordChance(RaidRecord record, BossPart part, RaidSettings raids)
	{
		if ("fractured".equals(record.family) && (record.teamSize > 0 || record.contribution >= 0))
		{
			// the base chance follows the setting for raids since the update of 11 November 2026 (older
			// ones keep the chance of their time); without a counted team, the team size setting
			int team = record.teamSize > 0 ? record.teamSize : raids.teamSize(part.getRaid());
			return fracturedChance(record, raids.tfaBaseChance(), team);
		}
		double chance = purpleChance(record);
		if (!Double.isNaN(chance))
		{
			return chance;
		}
		String key = part.getRaid();
		if ("tob".equals(record.family) && record.teamSize > 0 && key != null && !"none".equals(key))
		{
			return raids.uniqueChance(key) * Math.max(1, raids.teamSize(key)) / record.teamSize;
		}
		return Double.NaN;
	}

	/**
	 * The Fractured Archive: your chance from your contribution (or an even share of the team when
	 * it is unknown) after your deaths. A raid saved before the game update of 11 November 2026 keeps
	 * the chance it had then (1 in 14, +4% per player beyond two, whatever {@code baseChance} is now);
	 * raids since use the game's fixed chance for their team size, scaled from {@code baseChance}.
	 */
	static double fracturedChance(RaidRecord record, double baseChance, int teamSize)
	{
		int team = Math.max(1, teamSize);
		boolean before = RaidChance.tfaBeforeChange(record.savedMillis);
		if (record.contribution < 0)
		{
			return before ? RaidChance.tfaEvenBefore(team, record.deaths) : RaidChance.tfaEven(team, record.deaths, baseChance);
		}
		double kept = RaidChance.tfaContributionAfterDeaths(record.contribution, team, record.deaths);
		return before ? RaidChance.tfaBefore(kept, team) : RaidChance.tfa(kept, team, baseChance);
	}

	/**
	 * True when a raid drop comes out of the purple (a weight or a share per unique). Other raid
	 * drops, like The Fractured Archive's pet, folio and fragments, roll on their own at a flat rate
	 * per completion, whatever the points or contribution.
	 */
	static boolean fromPurple(BossPart part, DropDefinition drop)
	{
		return drop.getWeight(part.getName()) != null || drop.getPerUnique() != null;
	}

	/** {@link #fromPurple}, for the panel. */
	public static boolean fromPurplePublic(BossPart part, DropDefinition drop)
	{
		return fromPurple(part, drop);
	}

	/**
	 * What one saved raid adds to the expected count of a drop: its purple chance times the
	 * item's share at that raid level. The Tombs of Amascut pet has its own formula, and drops
	 * that don't come from the purple keep their flat rate.
	 */
	static double recordDropExpected(BossDefinition boss, BossPart part, DropDefinition drop, RaidRecord r,
		double chance)
	{
		if (!fromPurple(part, drop))
		{
			return partRate(boss, part, drop, key -> 1.0);
		}
		if (drop.isPet() && "toa".equals(r.family))
		{
			double pet = RaidChance.toaPet(r.personalPoints, r.partyPoints, r.teamPoints, r.teamSize, r.raidLevel);
			if (!Double.isNaN(pet))
			{
				return pet;
			}
		}
		double share = partRate(boss, part, drop, key -> 1.0);
		double itemShare = r.raidLevel >= 0 ? levelShare(boss, drop, r.raidLevel, share) : share;
		return chance * itemShare * RaidChance.toaLevelFactor(r.raidLevel, drop.getMinRaidLevel());
	}

	/**
	 * A drop's chance over a whole run claimed at {@code wave}: its chance on each wave up to
	 * that one, added up (at most one unique per wave, so this is its expected count).
	 */
	public static double waveRate(DropDefinition drop, int wave)
	{
		double sum = 0;
		for (int w = 1; w <= wave; w++)
		{
			sum += Rates.parse(drop.getLevelRate(w));
		}
		return sum;
	}

	/**
	 * Rate of a drop for one part of a combined page (one boss, or one raid mode).
	 * Explicit part rates win; raid modes use their own purple chance and weights.
	 */
	public static double partRate(BossDefinition boss, BossPart part, DropDefinition drop, RaidSettings raids)
	{
		if (drop.hasPartRates())
		{
			return Rates.parse(drop.getPartRate(part.getName()));
		}
		if (part.getRaid() != null)
		{
			double unique = raids.uniqueChance(part.getRaid());
			Double weight = drop.getWeight(part.getName());
			if (weight != null)
			{
				double total = boss.getTotalWeight(part.getName());
				return total > 0 ? unique * weight / total : 0;
			}
			if (drop.getPerUnique() != null)
			{
				return unique * Rates.parse(drop.getPerUnique());
			}
		}
		return Rates.parse(drop.getRate());
	}

	/**
	 * Expected count of a drop from one part. For raid modes, completions whose points
	 * were read use their own purple chance; older ones use the setting.
	 */
	static double partExpected(BossDefinition boss, BossPart part, DropDefinition drop, RaidSettings raids,
		int completions, PartRaids known)
	{
		double perRaid = partRate(boss, part, drop, raids);
		if (known == null || known.count == 0 || part.getRaid() == null || drop.hasPartRates() || !fromPurple(part, drop))
		{
			return completions * perRaid;
		}
		double expected = (completions - known.count) * perRaid;
		if (drop.isPet() && known.toa)
		{
			// the Tombs of Amascut pet has its own formula from the points
			return expected + known.petSum;
		}
		double share = partRate(boss, part, drop, key -> 1.0);
		for (Map.Entry<Integer, Double> e : known.chanceByLevel.entrySet())
		{
			int level = e.getKey();
			double itemShare = level >= 0 ? levelShare(boss, drop, level, share) : share;
			expected += e.getValue() * itemShare * RaidChance.toaLevelFactor(level, drop.getMinRaidLevel());
		}
		return expected;
	}

	/**
	 * A raid mode's saved raids whose chance is known, added up once per calculation: the purple
	 * chances per raid level (the item shares depend on the level) and the pet chances. Only the
	 * latest {@code completions} raids count.
	 */
	static final class PartRaids
	{
		int count;
		boolean toa;
		double petSum;
		final Map<Integer, Double> chanceByLevel = new HashMap<>();
	}

	static PartRaids partRaids(BossPart part, RaidSettings raids, int completions, BossProgress progress)
	{
		if (progress == null || part.getRaid() == null || progress.raids.isEmpty() || completions <= 0)
		{
			return null;
		}
		List<RaidRecord> known = new ArrayList<>();
		List<Double> chances = new ArrayList<>();
		for (RaidRecord r : progress.raids)
		{
			if (!part.getName().equals(r.part))
			{
				continue;
			}
			double chance = recordChance(r, part, raids);
			if (!Double.isNaN(chance))
			{
				known.add(r);
				chances.add(chance);
			}
		}
		PartRaids result = new PartRaids();
		int from = Math.max(0, known.size() - completions);
		for (int i = from; i < known.size(); i++)
		{
			RaidRecord r = known.get(i);
			result.count++;
			result.chanceByLevel.merge(r.raidLevel, chances.get(i), Double::sum);
			if ("toa".equals(r.family))
			{
				result.toa = true;
				double pet = RaidChance.toaPet(r.personalPoints, r.partyPoints, r.teamPoints, r.teamSize, r.raidLevel);
				result.petSum += Double.isNaN(pet) ? 0 : pet;
			}
		}
		return result;
	}

	/** Per-kill rate for a drop, taking raid settings into account. */
	public static double effectiveRate(BossDefinition boss, DropDefinition drop, RaidSettings raids)
	{
		if (boss.getWaves() > 0)
		{
			// a whole run, claimed at the last wave
			return waveRate(drop, boss.getWaves());
		}
		double rate = Rates.parse(drop.getRate());
		if (boss.getRaid() != null)
		{
			double unique = raids.uniqueChance(boss.getRaid());
			if (drop.getWeight() != null)
			{
				double total = boss.getTotalWeight();
				rate = total > 0 ? unique * drop.getWeight() / total : 0;
			}
			else if (drop.getPerUnique() != null)
			{
				rate = unique * Rates.parse(drop.getPerUnique());
			}
		}
		if (drop.getMinionRate() != null && boss.getMinions() > 0)
		{
			// God Wars bodyguards roll some of the general's uniques too
			rate += boss.getMinions() * Rates.parse(drop.getMinionRate());
		}
		return rate;
	}

	/** Expected drops of a pooled item from one boss, from its kill counts. */
	static double poolExpected(BossDefinition boss, DropDefinition drop, BossStats s, RaidSettings raids)
	{
		if (s.getPartCounts() != null && boss.hasParts())
		{
			double expected = 0;
			for (BossPart part : boss.getParts())
			{
				Integer kc = s.getPartCounts().get(part.getName());
				if (kc != null)
				{
					expected += kc * partRate(boss, part, drop, raids);
				}
			}
			return expected;
		}
		double rate = effectiveRate(boss, drop, raids);
		if (boss.getTeam() != null && !drop.isNoShare())
		{
			rate *= raids.contribution(boss.getTeam(), s.getKillCount());
		}
		return rate * s.getKillCount();
	}
}

