/*
 * Adapted for On Rate from RaidTrackerPlugin.java and PointsTracker.java in Raid Data
 * Tracker by Raitab (https://github.com/Raitab/raid-data-tracker, branch raid-data-tracker,
 * commit 963f3c4f). Only the parts that read raid points are used here: the Chambers of
 * Xeric points at the end of a raid, the Tombs of Amascut points estimate (from the Tombs
 * of Amascut plugin by LlemonDuck and TheStonedTurtle), the Tombs of Amascut plugin's party
 * points message and the Theatre of Blood end-of-raid board. The Fractured Archive's damage
 * share (FracturedContribution) is On Rate's own.
 */
package com.onrate.game;

import net.runelite.api.WorldView;

import com.onrate.game.toa.*;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.raids.FracturedContribution;
import com.onrate.engine.tracking.Tracker;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Consumer;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.Hitsplat;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.events.*;
import net.runelite.api.gameval.*;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.util.Text;

/**
 * Reads your points at the end of each raid and hands them to the {@link Tracker}, so that
 * raid's purple chance comes from the points instead of the settings. Registered on the
 * event bus by the plugin while "Use raid points" is on.
 */
public class RaidPointsReader
{
	private static final org.slf4j.Logger log = org.slf4j.LoggerFactory.getLogger(RaidPointsReader.class);
	private static final String RAID_COMPLETE_MESSAGE_COX = "Congratulations - your raid is complete!";
	private static final String RAID_COMPLETE_MESSAGE_TOA = "Challenge complete: The Wardens.";
	/** The Fractured Archive's completion count message. */
	static final String RAID_COMPLETE_MESSAGE_TFA = "Your The Fractured Archive completion count is";
	private static final String TOA_EVENT_NAMESPACE = "tombs-of-amascut";
	private static final String TOA_EVENT_NAME_POINTS = "raidCompletedPoints";

	/** Theatre of Blood board: the MVP's name, then each player's name and deaths. */
	private static final int[] TOB_NAMES = {
		InterfaceID.TobInfoboard.PLAYERNAME0, InterfaceID.TobInfoboard.PLAYERNAME1, InterfaceID.TobInfoboard.PLAYERNAME2,
		InterfaceID.TobInfoboard.PLAYERNAME3, InterfaceID.TobInfoboard.PLAYERNAME4,
	};
	private static final int[] TOB_DEATHS = {
		InterfaceID.TobInfoboard.DEATHS0, InterfaceID.TobInfoboard.DEATHS1, InterfaceID.TobInfoboard.DEATHS2,
		InterfaceID.TobInfoboard.DEATHS3, InterfaceID.TobInfoboard.DEATHS4,
	};

	private final Client client;
	private final ClientThread clientThread;
	private final Tracker tracker;
	private final Consumer<String> changed;
	private final BooleanSupplier enabled;

	private final RaidStateTracker raidStateTracker;
	private final ToaPointsEstimator toaPoints = new ToaPointsEstimator();
	/** Your damage share in The Fractured Archive, room by room. */
	private final FracturedContribution fractured = new FracturedContribution();
	/** True once the start of this Tombs raid was seen, so a half-tracked raid isn't saved. */
	private boolean toaStartSeen;
	private int toaRaidLevel = -1;
	/**
	 * Your exact Tombs of Amascut points, which the game sends at the end of each raid (since
	 * client revision 232), or 0 before they came. They replace On Rate's own estimate.
	 */
	private int toaExactPoints;

	public RaidPointsReader(Client client, ClientThread clientThread, Tracker tracker, Consumer<String> changed,
		BooleanSupplier enabled)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.tracker = tracker;
		this.changed = changed;
		this.enabled = enabled;
		this.raidStateTracker = new RaidStateTracker(client);
	}

	@Subscribe
	public void onGameTick(GameTick e)
	{
		RaidState previous = raidStateTracker.onGameTick();
		RaidState current = raidStateTracker.getCurrentState();
		if (current.isInRaid())
		{
			int level = client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL);
			if (level > 0)
			{
				toaRaidLevel = level;
			}
		}
		if (previous == null)
		{
			return;
		}
		toaPoints.setTeamSize(current.getPlayerCount());
		if (previous.getCurrentRoom() != null && previous.getCurrentRoom() != current.getCurrentRoom())
		{
			toaPoints.onRoomLeft(previous.getCurrentRoom());
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged e)
	{
		switch (e.getGameState())
		{
			case LOGGING_IN:
			case HOPPING:
				raidStateTracker.reset();
				break;
			default:
				break;
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.FRIENDSCHATNOTIFICATION && event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String message = Text.removeTags(event.getMessage()).replace(' ', ' ');

		if (message.startsWith(RAID_COMPLETE_MESSAGE_COX))
		{
			readCoxPoints();
			return;
		}

		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		if (message.startsWith(RAID_COMPLETE_MESSAGE_TFA))
		{
			saveFracturedRaid();
			return;
		}
		if (message.startsWith(ToaPointsEstimator.START_MESSAGE))
		{
			toaPoints.reset();
			toaPoints.setTeamSize(raidStateTracker.getPlayerCount());
			toaStartSeen = true;
			toaRaidLevel = -1;
			toaExactPoints = 0;
			return;
		}
		if (!raidStateTracker.getCurrentState().isInRaid())
		{
			return;
		}
		if (message.startsWith(RAID_COMPLETE_MESSAGE_TOA))
		{
			saveToaRaid();
		}
		toaPoints.onGameMessage(message);
	}

	/** Same values Raid Data Tracker and RuneLite's raids plugin read. */
	private void readCoxPoints()
	{
		if (!enabled.getAsBoolean() || client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) != 1)
		{
			return;
		}
		int total = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSCORE);
		int personal = client.getVarpValue(VarPlayerID.RAIDS_PLAYERSCORE);
		int partySize = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE);
		int scaledSize = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PARTYSIZE_SCALED);
		if (total <= 0 || personal <= 0)
		{
			return;
		}
		// the size the raid scaled to: it never goes down when players leave, so the higher of the two
		int scale = Math.max(partySize, scaledSize);
		// the players still in the raid, counted, as the scale doesn't say who stayed ("1+2")
		int players = playersInRaid();
		log.debug("Chambers of Xeric done: party size {}, scaled size {}, scaling {}, players counted {}",
			partySize, scaledSize, client.getVarbitValue(VarbitID.RAIDS_SCALING), players);
		report(tracker.onRaidRecord(RaidRecord.cox(personal, total, scale, scale > 0 ? Math.min(players, scale) : players),
			System.currentTimeMillis()));
	}

	/** Players in the raid's instance right now, you included; 0 when it can't be told. */
	private int playersInRaid()
	{
		WorldView view = client.getTopLevelWorldView();
		if (view == null)
		{
			return 0;
		}
		int n = 0;
		for (Player p : view.players())
		{
			if (p != null && p.getName() != null)
			{
				n++;
			}
		}
		return n;
	}

	private void saveToaRaid()
	{
		boolean started = toaStartSeen;
		toaStartSeen = false;
		int exact = toaExactPoints;
		toaExactPoints = 0;
		if (!enabled.getAsBoolean() || !started && exact <= 0)
		{
			// On Rate missed the start of this raid and the game hasn't sent the points yet,
			// so an estimate would be too low; if the points come in a moment, they're used then
			return;
		}
		int level = toaRaidLevel > 0 ? toaRaidLevel : client.getVarbitValue(VarbitID.TOA_CLIENT_RAID_LEVEL);
		// the game's own number when it already came, else the estimate (replaced if it comes later)
		RaidRecord record = exact > 0
			? RaidRecord.toaExact(exact, Math.max(1, raidStateTracker.getPlayerCount()), level)
			: RaidRecord.toa(toaPoints.getPersonalTotalPoints(), toaPoints.getNonPartyPoints(), 0,
				Math.max(1, raidStateTracker.getPlayerCount()), level);
		report(tracker.onRaidRecord(record, System.currentTimeMillis()));
	}

	/** Your damage share and deaths for the Fractured Archive raid that just ended. */
	private void saveFracturedRaid()
	{
		FracturedContribution.Result result = fractured.finish();
		if (result == null || !enabled.getAsBoolean())
		{
			return;
		}
		// the team size is counted by the tracker when the completion message comes
		report(tracker.onRaidRecord(RaidRecord.fractured(0, result.deaths, result.contribution), System.currentTimeMillis()));
	}

	@Subscribe
	public void onActorDeath(ActorDeath e)
	{
		if (e.getActor() != null && e.getActor() == client.getLocalPlayer())
		{
			fractured.onLocalDeath();
		}
	}

	/**
	 * The game sends your exact Tombs of Amascut points at the end of the raid (the same value the
	 * Tombs of Amascut plugin reads). Before the raid is saved they're kept for it; after, they
	 * replace the estimate in the saved raid.
	 */
	@Subscribe
	public void onVarbitChanged(VarbitChanged e)
	{
		if (e.getVarpId() != VarPlayerID.TOA_PERSONAL_CONTRIBUTION || e.getValue() <= 0 || !enabled.getAsBoolean())
		{
			return;
		}
		if (toaStartSeen)
		{
			// the raid isn't saved yet: "Challenge complete" comes after this
			toaExactPoints = e.getValue();
			return;
		}
		report(tracker.onToaPoints(e.getValue(), System.currentTimeMillis()));
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied e)
	{
		if (e.getActor() instanceof NPC && FracturedContribution.isArchiveNpc(((NPC) e.getActor()).getId()))
		{
			Hitsplat hit = e.getHitsplat();
			fractured.onHitsplat(((NPC) e.getActor()).getId(), hit.getAmount(), hit.isMine(), hit.isOthers());
			return;
		}
		if (!raidStateTracker.getCurrentState().isInRaid() || !(e.getActor() instanceof NPC))
		{
			return;
		}
		NPC target = (NPC) e.getActor();
		toaPoints.onHitsplat(target.getId(), e.getHitsplat().getAmount(), e.getHitsplat().isMine(),
			raidStateTracker.getCurrentState().getCurrentRoom());
	}

	@Subscribe
	public void onItemSpawned(ItemSpawned e)
	{
		if (raidStateTracker.getCurrentState().isInRaid())
		{
			toaPoints.onItemSpawned(e.getItem().getId());
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged e)
	{
		Actor actor = e.getActor();
		if (!raidStateTracker.getCurrentState().isInRaid() || !(actor instanceof NPC))
		{
			return;
		}
		if (actor.getAnimation() == AnimationID.NPC_WARDENS_KNEEL01)
		{
			toaPoints.onWardenDowned(((NPC) actor).getId());
		}
	}

	/**
	 * The Tombs of Amascut plugin shares the party's points at the end of a raid
	 * (thanks to Adam, LlemonDuck and jocopa3 for the PluginMessage event in RuneLite).
	 */
	@Subscribe
	public void onPluginMessage(PluginMessage message)
	{
		if (!enabled.getAsBoolean() || !TOA_EVENT_NAMESPACE.equals(message.getNamespace())
			|| !TOA_EVENT_NAME_POINTS.equals(message.getName()))
		{
			return;
		}
		Map<String, Object> data = message.getData();
		if (data == null || toInt(data.get("version")) != 1)
		{
			return;
		}
		int personal = toInt(data.get("personalPoints"));
		int total = toInt(data.get("totalPoints"));
		report(tracker.onPartyPoints(personal, total, System.currentTimeMillis()));
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() != InterfaceID.TOB_INFOBOARD || !enabled.getAsBoolean())
		{
			return;
		}
		clientThread.invokeLater(this::readTobBoard);
	}

	/** MVP and deaths from the board at the end of a Theatre of Blood raid. */
	private void readTobBoard()
	{
		Player me = client.getLocalPlayer();
		String myName = me == null || me.getName() == null ? null : clean(me.getName());
		int teamSize = 0;
		int teamDeaths = 0;
		int myDeaths = -1;
		for (int i = 0; i < TOB_NAMES.length; i++)
		{
			String name = widgetText(client.getWidget(TOB_NAMES[i]));
			if (name.isEmpty())
			{
				continue;
			}
			teamSize++;
			int deaths = widgetNumber(client.getWidget(TOB_DEATHS[i]));
			teamDeaths += deaths;
			if (myName != null && myName.equalsIgnoreCase(clean(name)))
			{
				myDeaths = deaths;
			}
		}
		if (teamSize == 0)
		{
			return;
		}
		String mvp = widgetText(client.getWidget(InterfaceID.TobInfoboard.MVP_PLAYER));
		Boolean isMvp = myName == null || mvp.isEmpty() ? null : myName.equalsIgnoreCase(clean(mvp));
		report(tracker.onRaidRecord(RaidRecord.tob(teamSize, myDeaths, teamDeaths, isMvp), System.currentTimeMillis()));
	}

	private void report(String boss)
	{
		if (boss != null)
		{
			changed.accept(boss);
		}
	}

	private static String clean(String name)
	{
		return Text.removeTags(name).replace(' ', ' ').trim();
	}

	private static String widgetText(Widget widget)
	{
		if (widget == null || widget.getText() == null || widget.getText().equals("-"))
		{
			return "";
		}
		return widget.getText();
	}

	private static int widgetNumber(Widget widget)
	{
		String text = widgetText(widget).trim();
		if (text.isEmpty())
		{
			return 0;
		}
		try
		{
			return Integer.parseInt(text);
		}
		catch (NumberFormatException e)
		{
			return 0;
		}
	}

	private static int toInt(Object value)
	{
		return value instanceof Number ? ((Number) value).intValue() : -1;
	}
}

package com.onrate.game;

import java.util.ArrayList;
import com.onrate.engine.tracking.ImportedRaid;
import java.util.LinkedHashSet;
import java.util.Set;

import com.onrate.engine.raids.RaidDataImport;
import com.onrate.engine.tracking.Tracker;
import java.util.List;
import java.util.Map;
import java.util.concurrent.Executor;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.config.RuneScapeProfileType;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Raid times from the Raid Data Tracker plugin's files, read on a worker thread and added on the
 * client thread, only to the RuneLite profile they were read for.
 *
 * <p>Reading takes a moment. If another profile is loaded meanwhile (another account, or a Leagues
 * world of the same account), what was read is dropped: it is never added to whichever account
 * happens to be loaded when the read finishes. Nothing is added after {@link #stop()}.
 */
public final class RaidTimesImport
{
	private static final Logger log = LoggerFactory.getLogger(RaidTimesImport.class);

	private final Executor worker;
	private final Consumer<Runnable> clientThread;
	private final Supplier<String> loadedProfile;
	private volatile boolean stopped;

	/**
	 * @param worker reads the files (the plugin's executor)
	 * @param clientThread runs a task on the client thread, where the profile is loaded and events arrive
	 * @param loadedProfile the RuneLite profile key whose data the tracker holds now (ProfileStore)
	 */
	public RaidTimesImport(Executor worker, Consumer<Runnable> clientThread, Supplier<String> loadedProfile)
	{
		this.worker = worker;
		this.clientThread = clientThread;
		this.loadedProfile = loadedProfile;
	}

	/**
	 * True when raid times may be imported into this profile: a standard RuneScape profile. Raid Data
	 * Tracker's records carry the account but not the world type, so in a Leagues, Deadman or other
	 * seasonal profile of the same account they would bring in the main game's raids. False too when
	 * the profile isn't known.
	 */
	public static boolean importsInto(String profileKey, List<RuneScapeProfile> profiles)
	{
		if (profileKey == null || profiles == null)
		{
			return false;
		}
		for (RuneScapeProfile p : profiles)
		{
			if (profileKey.equals(p.getKey()))
			{
				return p.getType() == RuneScapeProfileType.STANDARD;
			}
		}
		return false;
	}

	/**
	 * Reads on the worker, then adds the times on the client thread if {@code profile} is still the
	 * loaded one; {@code changed} is told each boss that gained times. Adding a time twice is harmless.
	 */
	public void start(String profile, Supplier<RaidDataImport.Times> read, Tracker tracker, Consumer<String> changed)
	{
		if (stopped || profile == null || tracker == null)
		{
			return;
		}
		worker.execute(() ->
		{
			RaidDataImport.Times times;
			try
			{
				times = read.get();
			}
			catch (RuntimeException e)
			{
				log.debug("Could not import raid times from Raid Data Tracker", e);
				return;
			}
			if (times == null || stopped)
			{
				return;
			}
			clientThread.accept(() -> apply(profile, times, tracker, changed));
		});
	}

	private void apply(String profile, RaidDataImport.Times times, Tracker tracker, Consumer<String> changed)
	{
		if (stopped)
		{
			return;
		}
		if (!profile.equals(loadedProfile.get()))
		{
			log.debug("Raid Data Tracker times read for another profile were not imported");
			return;
		}
		Set<String> bosses = new LinkedHashSet<>();
		for (Map.Entry<String, Map<String, List<long[]>>> boss : times.byBoss().entrySet())
		{
			int added = 0;
			for (Map.Entry<String, List<long[]>> part : boss.getValue().entrySet())
			{
				added += tracker.importRaidTimes(boss.getKey(), part.getKey(), part.getValue());
			}
			if (added > 0)
			{
				bosses.add(boss.getKey());
			}
		}
		// the whole raids: their points, team and raid level, saved like the raids On Rate saw
		for (Map.Entry<String, List<RaidDataImport.Raid>> boss : times.raids().entrySet())
		{
			List<ImportedRaid> raids = new ArrayList<>();
			for (RaidDataImport.Raid r : boss.getValue())
			{
				raids.add(new ImportedRaid(r.part, r.kc, r.when, r.millis, r.teamSize,
					r.personalPoints, r.totalPoints, r.raidLevel, r.unique));
			}
			// the uniques are kept in memory even when no raid is new, so the graph can name them
			if (tracker.importRaids(boss.getKey(), raids) > 0 || !raids.isEmpty())
			{
				bosses.add(boss.getKey());
			}
		}
		bosses.forEach(changed);
	}

	/** The plugin stopped: nothing read from now on is added. */
	public void stop()
	{
		stopped = true;
	}
}

package com.onrate.game;

import lombok.AllArgsConstructor;
import com.onrate.engine.tracking.Tracker;
import java.util.HashMap;
import java.util.Map;
import java.util.function.BiConsumer;
import net.runelite.api.Client;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/**
 * Content with loot per reward roll (Tempoross, Wintertodt): the game keeps a counter of rewards
 * not yet collected. When it drops, each reward collected is one roll; the counter and the total
 * subdues also give the number of rolls from before On Rate was running.
 */
@AllArgsConstructor
public final class RollCounters
{
	/** Boss name, the game's counter of uncollected rewards, and the total subdues. */
	private static final Object[][] COUNTERS = {
		{"Tempoross", VarbitID.TEMPOROSS_REWARDPERMITS, VarPlayerID.TOTAL_TEMPOROSS_KILLS},
		{"Wintertodt", VarbitID.WINT_REWARD_POOL, VarPlayerID.TOTAL_WINTERTODT_KILLS},
	};

	private final Client client;
	private final Tracker tracker;
	/** Each counter's value last seen this login; a drop means rewards were collected. */
	private final Map<String, Integer> last = new HashMap<>();

	/** @param changed told the boss whose numbers changed, and whether a roll was just counted */
	public void onVarbit(VarbitChanged event, BiConsumer<String, Boolean> changed)
	{
		for (Object[] c : COUNTERS)
		{
			String boss = (String) c[0];
			int rewardsVarbit = (Integer) c[1];
			int subduesVarp = (Integer) c[2];
			if (event.getVarbitId() != rewardsVarbit && event.getVarpId() != subduesVarp)
			{
				continue;
			}
			int held = client.getVarbitValue(rewardsVarbit);
			int subdues = client.getVarpValue(subduesVarp);
			String baseline = tracker.onRollBaseline(boss, subdues, held);
			if (baseline != null)
			{
				changed.accept(baseline, false);
			}
			Integer before = last.get(boss);
			if (before != null && held < before)
			{
				// each reward collected is one reward roll
				String rolled = tracker.onRewardRolls(boss, before - held, System.currentTimeMillis());
				if (rolled != null)
				{
					changed.accept(rolled, true);
				}
			}
			last.put(boss, held);
		}
	}

	/** A new login sends the counters again: that's not collecting rewards. */
	public void forget()
	{
		last.clear();
	}
}

package com.onrate.game;

import lombok.AllArgsConstructor;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * Counts your team at a group-boss kill: you plus the players seen hitting the boss with you
 * (Nex, Yama, the Hueycoatl, Corp). Zalcano and the Fractured Archive can't be told that way
 * (mining and smithing count there, and the raid is an instance), so they use the players around you.
 */
@AllArgsConstructor
public final class TeamDetector
{
	/** Players within this many tiles of you count as your team where hits can't tell. */
	private static final int RADIUS_TILES = 15;
	private static final int LOCAL_UNITS_PER_TILE = 128;

	private final Client client;
	private final TeamSpotter spotter = new TeamSpotter();

	/** Notes who is hitting a group boss. Call every game tick. */
	public void onTick(long now)
	{
		Player me = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (me == null || view == null)
		{
			return;
		}
		for (Player p : view.players())
		{
			if (p == null || p == me || p.getName() == null)
			{
				continue;
			}
			Actor target = p.getInteracting();
			String fight = target instanceof NPC ? TeamSpotter.fightOf(target.getName()) : null;
			if (fight != null)
			{
				spotter.onHitting(fight, p.getName(), now);
			}
		}
	}

	/** Your team at a kill (you included); called on the client thread, from the kill message. */
	public int sizeFor(String bossName)
	{
		String fight = TeamSpotter.fightOf(bossName);
		return fight == null ? playersAround() : 1 + spotter.others(fight, System.currentTimeMillis());
	}

	/** This kill is counted: the next one starts with nobody seen. */
	public void killCounted(String bossName)
	{
		String fight = TeamSpotter.fightOf(bossName);
		if (fight != null)
		{
			spotter.clear(fight);
		}
	}

	public void clear()
	{
		spotter.clearAll();
	}

	private int playersAround()
	{
		Player me = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		LocalPoint here = me == null ? null : me.getLocalLocation();
		if (here == null || view == null)
		{
			return 0;
		}
		int count = 0;
		for (Player p : view.players())
		{
			LocalPoint there = p == null ? null : p.getLocalLocation();
			if (there == null)
			{
				continue;
			}
			int dx = Math.abs(there.getX() - here.getX()) / LOCAL_UNITS_PER_TILE;
			int dy = Math.abs(there.getY() - here.getY()) / LOCAL_UNITS_PER_TILE;
			if (Math.max(dx, dy) <= RADIUS_TILES)
			{
				count++;
			}
		}
		return Math.max(1, count);
	}
}

package com.onrate.game;

import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * Who fights a group boss with you: the other players seen hitting it. Only they share the kill,
 * not the players who happen to stand nearby. Seen players expire after a few minutes, and a
 * boss's list is cleared once its kill is counted.
 */
final class TeamSpotter
{
	/** A player seen hitting the boss this long ago (or less) still counts as part of the fight. */
	static final long WINDOW_MILLIS = 5 * 60_000;

	/** The bosses counted this way, by the name their NPC and their kill count both use. */
	private static final String[] FIGHTS = {"nex", "yama", "hueycoatl", "corporeal beast"};

	/** Fight key to the players seen hitting it and when. */
	private final Map<String, Map<String, Long>> seen = new HashMap<>();

	/**
	 * The fight an NPC or boss name belongs to ("Nex", "The Hueycoatl", "Hueycoatl tail"), or null
	 * when it isn't one counted by who hits it.
	 */
	static String fightOf(String name)
	{
		if (name == null)
		{
			return null;
		}
		// asked for every player in view on every game tick: no pattern is compiled and no text is
		// built here (tags are rare in NPC names, and the names are compared in place)
		String n = (name.indexOf('<') >= 0 ? TAGS.matcher(name).replaceAll("") : name).trim();
		int from = n.regionMatches(true, 0, "the ", 0, 4) ? 4 : 0;
		for (String fight : FIGHTS)
		{
			int end = from + fight.length();
			if (n.regionMatches(true, from, fight, 0, fight.length()) && (n.length() == end || n.charAt(end) == ' '))
			{
				return fight;
			}
		}
		return null;
	}

	private static final Pattern TAGS = Pattern.compile("<[^>]*>");

	synchronized void onHitting(String fight, String player, long nowMillis)
	{
		seen.computeIfAbsent(fight, f -> new HashMap<>()).put(player, nowMillis);
	}

	/** The other players seen hitting this boss lately (you are not counted). */
	synchronized int others(String fight, long nowMillis)
	{
		Map<String, Long> players = seen.get(fight);
		if (players == null)
		{
			return 0;
		}
		players.values().removeIf(at -> nowMillis - at > WINDOW_MILLIS);
		return players.size();
	}

	/** The kill is counted: the next one starts with nobody seen. */
	synchronized void clear(String fight)
	{
		seen.remove(fight);
	}

	synchronized void clearAll()
	{
		seen.clear();
	}
}

