		// Phase 3
		m.put(NpcID.TOA_WARDEN_ELIDINIS_PHASE3_INACTIVE, 0.0);
		m.put(NpcID.TOA_WARDEN_TUMEKEN_PHASE3_INACTIVE, 0.0);
		m.put(NpcID.TOA_WARDEN_ELIDINIS_PHASE3, 2.5);
		m.put(NpcID.TOA_WARDEN_TUMEKEN_PHASE3, 2.5);
		m.put(NpcID.TOA_WARDEN_ELIDINIS_PHASE3_CHARGING, 2.5);
		m.put(NpcID.TOA_WARDEN_TUMEKEN_PHASE3_CHARGING, 2.5);
		DAMAGE_POINTS_FACTORS = Collections.unmodifiableMap(m);
	}

	// these have a cap at 3 "downs"
	static final Set<Integer> P2_WARDENS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		NpcID.TOA_WARDEN_ELIDINIS_PHASE2_MAGE,
		NpcID.TOA_WARDEN_ELIDINIS_PHASE2_RANGE,
		NpcID.TOA_WARDEN_ELIDINIS_PHASE2_EXPOSED,
		NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE,
		NpcID.TOA_WARDEN_TUMEKEN_PHASE2_RANGE,
		NpcID.TOA_WARDEN_TUMEKEN_PHASE2_EXPOSED
	)));

	static final Set<Integer> MVP_ITEMS = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		ItemID.TOA_ZEBAK_FANG,
		ItemID.TOA_KEPHRI_POO,
		ItemID.TOA_BABA_BANANA,
		ItemID.TOA_AKKHA_ASHES
	)));

	private int personalRoomPoints;
	private int personalTotalPoints;
	private int nonPartyPoints; // points that are earned once by the entire party
	private final List<Integer> seenMvpItems = new ArrayList<>(4);

	@Getter @Setter private int teamSize;
	private int wardenDowns;

	public ToaPointsEstimator()
	{
		reset();
	}

	/** You left a room: puzzle rooms give fixed points. */
	public void onRoomLeft(RaidRoom previousRoom)
	{
		if (previousRoom == null)
		{
			return;
		}

		switch (previousRoom)
		{
			// puzzle estimates
			case SCABARAS:
				personalTotalPoints += 300;
				nonPartyPoints += 300;
				break;

			case APMEKEN:
				personalTotalPoints += 450;
				nonPartyPoints += 300;
				break;

			case CRONDIS:
				personalTotalPoints += 400;
				nonPartyPoints += 300;
				break;

			case HET:
			case WARDENS:
				nonPartyPoints += 300;
				break;

			default:
				break;
		}
	}

	/** A game message while in the raid (tags already removed). */
	public void onGameMessage(String message)
	{
		if (message.startsWith(START_MESSAGE))
		{
			reset();
		}
		else if (message.startsWith(DEATH_MESSAGE))
		{
			personalTotalPoints -= (int) Math.max(0.2 * personalTotalPoints, 1000);
			if (personalTotalPoints < 0)
			{
				personalTotalPoints = 0;
			}

		}
		else if (message.startsWith(ROOM_FAIL_MESSAGE))
		{
			wardenDowns = 0;
		}
		else if (message.startsWith(ROOM_FINISH_MESSAGE))
		{
			personalRoomPoints = 0;
		}
	}

	/** A hitsplat on an NPC. Only your own hits ({@code mine}) earn you points. */
	public void onHitsplat(int npcId, int amount, boolean mine, RaidRoom currentRoom)
	{
		if (amount < 1)
		{
			return;
		}

		if (P2_WARDENS.contains(npcId) && wardenDowns > 3)
		{
			return;
		}

		Double known = DAMAGE_POINTS_FACTORS.get(npcId);
		double factor = known == null ? 1.0 : known;
		if (mine)
		{
			int pointsEarned = (int) (amount * factor);
			int roomMax = currentRoom == RaidRoom.CRONDIS ? CRONDIS_MAX_ROOM_POINTS : MAX_ROOM_POINTS;
			if (personalRoomPoints + pointsEarned > roomMax)
			{
				pointsEarned = roomMax - personalRoomPoints;
			}

			this.personalRoomPoints = Math.min(roomMax, personalRoomPoints + pointsEarned);
			this.personalTotalPoints = Math.min(MAX_TOTAL_POINTS, personalTotalPoints + pointsEarned);
		}
	}

	/** An item appeared on the floor; the MVP items give 300 points per player. */
	public void onItemSpawned(int itemId)
	{
		if (MVP_ITEMS.contains(itemId) && !seenMvpItems.contains(itemId))
		{
			personalTotalPoints += 300 * teamSize;
			seenMvpItems.add(itemId);
		}
	}

	/** A P2 Warden knelt down (was downed). */
	public void onWardenDowned(int npcId)
	{
		if (P2_WARDENS.contains(npcId))
		{
			wardenDowns++;
		}
	}

	/** Your points so far, without the 5,000 everyone starts with. */
	public int getPersonalTotalPoints()
	{
		return this.personalTotalPoints - BASE_POINTS;
	}

	/** Points the whole party earns once (puzzle completions). */
	public int getNonPartyPoints()
	{
		return nonPartyPoints;
	}

	public double getPersonalPercent()
	{
		if (teamSize <= 1)
		{
			return 1.0;
		}

		return (double) getPersonalTotalPoints() / getTotalPoints();
	}

	public int getTotalPoints()
	{
		return getPersonalTotalPoints() + nonPartyPoints;
	}

	public void reset()
	{
		this.personalTotalPoints = BASE_POINTS;
		this.personalRoomPoints = 0;
		this.nonPartyPoints = 0;
		this.teamSize = 0;
		this.wardenDowns = 0;
		this.seenMvpItems.clear();
	}

}

package com.onrate.service;

import lombok.AccessLevel;
import lombok.AllArgsConstructor;
import java.util.concurrent.atomic.AtomicLong;

import com.onrate.engine.data.KillTimes;
import com.onrate.engine.stats.*;
import com.onrate.engine.tracking.Tracker;
import java.util.List;
import java.util.concurrent.Executor;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Works out the whole account (and every item's time) on a worker thread after a kill, so the
 * panel's next draw doesn't have to do it on the Swing thread. A burst of events (a raid ends with
 * several) runs one calculation.
 *
 * <p>The result is lent to the panel for exactly one draw: the one this class starts. Any other
 * draw (a click, a setting, the panel opening) finds nothing here and calculates as it always did.
 * So the numbers on screen are the same as before; only the thread that works them out changes.
 *
 * <p>A request can also move the panel to a boss (auto-follow after a kill). The newest such move is
 * kept until a draw runs, even when a later request that doesn't move is the one that draws, so the
 * panel ends on the newest boss as it did when every draw ran.
 *
 * <p>Nothing is worked out for a panel that isn't on screen: its draw is handed to the Swing thread
 * straight away, as the original did, and the panel itself decides there is nothing to draw.
 */
public final class AccountPrecompute
{
	private static final Logger log = LoggerFactory.getLogger(AccountPrecompute.class);

	/** One calculation and the draw to run when it is ready. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class Job
	{
		final RaidSettings raids;
		final ToLongFunction<String> prices;
		final Runnable draw;
		final long seq;
	}

	/** A request's move to a boss, and the number of that request. */
	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class Nav
	{
		final Runnable show;
		final long seq;
	}

	@AllArgsConstructor(access = AccessLevel.PACKAGE)
	private static final class Result
	{
		final boolean withPrices;
		final AccountStats account;
		final List<ItemTime> times;
	}

	private final Tracker tracker;
	private final Executor worker;
	private final Consumer<Runnable> onSwing;
	private final BooleanSupplier onScreen;
	private final AtomicReference<Job> next = new AtomicReference<>();
	/** The newest move to a boss that no draw has made yet. */
	private final AtomicReference<Nav> nav = new AtomicReference<>();
	private final AtomicBoolean running = new AtomicBoolean();
	private volatile boolean stopped;
	/** Number of the latest request: only its draw runs. */
	private final AtomicLong latest = new AtomicLong();
	/** Only set on the Swing thread, during the draw this class started. */
	private Result lent;

	/**
	 * @param onSwing runs a task on the Swing thread (SwingUtilities::invokeLater)
	 */
	public AccountPrecompute(Tracker tracker, Executor worker, Consumer<Runnable> onSwing)
	{
		this(tracker, worker, onSwing, () -> true);
	}

	/**
	 * @param onSwing runs a task on the Swing thread (SwingUtilities::invokeLater)
	 * @param onScreen whether the panel is on screen now; asked on the calling thread at each request
	 */
	public AccountPrecompute(Tracker tracker, Executor worker, Consumer<Runnable> onSwing, BooleanSupplier onScreen)
	{
		this.tracker = tracker;
		this.worker = worker;
		this.onSwing = onSwing;
		this.onScreen = onScreen;
	}

	/**
	 * Asks for the account to be worked out, then {@code draw} to run on the Swing thread with the
	 * result lent to it. Only the latest request's draw runs when requests pile up.
	 *
	 * @param prices GE prices, or null when the GP value setting is off (as the panel asks)
	 */
	public void request(RaidSettings raids, ToLongFunction<String> prices, Runnable draw)
	{
		request(raids, prices, null, draw);
	}

	/**
	 * As {@link #request(RaidSettings, ToLongFunction, Runnable)}; {@code show}, when not null, moves
	 * the panel to a boss instead of {@code draw}. The newest move survives later requests that don't
	 * move, so a merged burst still ends on the newest boss.
	 */
	public void request(RaidSettings raids, ToLongFunction<String> prices, Runnable show, Runnable draw)
	{
		if (stopped)
		{
			return;
		}
		long seq = latest.incrementAndGet();
		if (show != null)
		{
			nav.set(new Nav(show, seq));
		}
		if (!onScreen.getAsBoolean())
		{
			// a closed panel: nothing is worked out here. The draw goes to the Swing thread as it always
			// did (every one runs, in order), and anything still being worked out is never used.
			Runnable run = pick(draw);
			dropUpTo(seq);
			onSwing.accept(run);
			return;
		}
		next.set(new Job(raids, prices, draw, seq));
		if (running.compareAndSet(false, true))
		{
			worker.execute(this::loop);
		}
	}

	private void loop()
	{
		try
		{
			Job job;
			while (!stopped && (job = next.getAndSet(null)) != null)
			{
				Result result = null;
				try
				{
					AccountStats account = tracker.accountStats(job.raids, job.prices);
					List<ItemTime> times = ItemTimes.compute(tracker, KillTimes.bundled(), job.raids);
					result = new Result(job.prices != null, account, times);
				}
				catch (RuntimeException e)
				{
					// the panel works it out itself, as it always did
					log.debug("On Rate could not work out the account in the background", e);
				}
				Result ready = result;
				Job done = job;
				onSwing.accept(() -> deliver(ready, done));
			}
		}
		finally
		{
			running.set(false);
			if (next.get() != null && !stopped)
			{
				if (running.compareAndSet(false, true))
				{
					worker.execute(this::loop);
				}
			}
		}
	}

	private void deliver(Result result, Job job)
	{
		if (stopped || job.seq != latest.get())
		{
			// newer numbers are on their way (draw once, with those), or the data changed since
			// (see supersede): either way these are out of date
			return;
		}
		Runnable run = pick(job.draw);
		lent = result;
		try
		{
			run.run();
		}
		finally
		{
			lent = null;
		}
	}

	/** The newest waiting move to a boss (taken, so it runs once), or else {@code draw}. */
	private Runnable pick(Runnable draw)
	{
		Nav n = nav.getAndSet(null);
		return n == null ? draw : n.show;
	}

	/**
	 * The account for the draw in progress, or null when this draw wasn't started here (the panel then
	 * calculates it) or the GP value setting doesn't match what was worked out. Swing thread only.
	 */
	public AccountStats account(boolean withPrices)
	{
		Result r = lent;
		return r == null || r.withPrices != withPrices ? null : r.account;
	}

	/** Every item's time for the draw in progress, or null (the panel then calculates them). Swing thread only. */
	public List<ItemTime> itemTimes()
	{
		Result r = lent;
		return r == null ? null : r.times;
	}

	/**
	 * The data changed without a request (a click in the panel, another account loaded, a setting): any
	 * result worked out before now is never drawn, and its draw never runs, and a waiting move to a
	 * boss is dropped too (use this one when another account is loaded). The caller redraws itself.
	 * Safe from any thread.
	 */
	public void supersede()
	{
		dropUpTo(latest.incrementAndGet());
	}

	/**
	 * As {@link #supersede()}, for a change on the same account (a setting, a click that changes the
	 * data): the numbers worked out before it are still never drawn, but a waiting move to a boss is
	 * still made, once, on the Swing thread. The original moved to the boss at the kill itself, so a
	 * later setting or click left the panel on that boss. Safe from any thread.
	 */
	public void supersedeKeepingMove()
	{
		long seq = latest.incrementAndGet();
		Nav move = nav.get();
		if (move != null && move.seq < seq && nav.compareAndSet(move, null))
		{
			onSwing.accept(move.show);
		}
		dropUpTo(seq);
	}

	/**
	 * Takes the waiting job off the queue if it is older than {@code seq}. Never one that came in since:
	 * a request racing with this one from another thread keeps its place, and its draw still runs.
	 */
	private void dropUpTo(long seq)
	{
		Nav move = nav.get();
		if (move != null && move.seq < seq)
		{
			nav.compareAndSet(move, null);
		}
		Job waiting = next.get();
		if (waiting != null && waiting.seq < seq)
		{
			next.compareAndSet(waiting, null);
		}
	}

	public void stop()
	{
		stopped = true;
		next.set(null);
		nav.set(null);
	}
}

package com.onrate.store;

/**
 * Where On Rate keeps things in RuneLite's settings. These names are the saved-data format: they
 * must not change, or players lose their history. (The group is still "expecteddrops" from the
 * first release for exactly that reason.)
 */
public final class Keys
{
	/** RuneLite config group. */
	public static final String GROUP = "expecteddrops";
	/** The main saved data of an account (one JSON document). */
	public static final String DATA = "progress";
	/** Each boss's History is saved under its own key: this plus the boss name. */
	public static final String KILLS = "kills.";
	/** Each raid's saved raids (with points) likewise. */
	public static final String RAIDS = "raids.";
	/** Unreadable data is kept under its key plus this, so the next save can't destroy it. */
	public static final String CORRUPT_SUFFIX = ".corrupt";

	/** Per account: the last real Slayer level seen. */
	public static final String SLAYER_LEVEL = "slayerLevel";
	/** The tab and page the panel was left on. */
	public static final String LAST_PAGE = "accountPage";

	private Keys()
	{
	}

	public static String killsKey(String bossName)
	{
		return KILLS + bossName.replaceAll("[^A-Za-z0-9]", "");
	}

	public static String raidsKey(String bossName)
	{
		return RAIDS + bossName.replaceAll("[^A-Za-z0-9]", "");
	}
}

package com.onrate.store;

import com.google.gson.*;
import com.google.gson.reflect.TypeToken;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Reads saved data that may be damaged: finds what can't be read and takes out only that (a null boss
 * or History entry, a count that isn't a number, a list where a map belongs), keeping everything else
 * exactly as it was. Data On Rate wrote itself comes out unchanged, so Gson reads it to the same
 * objects as before.
 *
 * <p>It never looks at the saved classes themselves. Each part of the saved text is tried by itself:
 * Gson reads a copy of the whole text that holds just that part (and what leads to it), so a part
 * that doesn't read is found, and what it holds is tried in turn. Parts of a saved object, entries of
 * a map and elements of a list are read independently of each other, so the rest is unaffected.
 *
 * <p>What was taken out is listed in {@link #dropped}, so the caller can keep the original text and
 * say what happened. A null in an object, a map or a list is taken out and counted (Gson never
 * writes one).
 */
final class LenientJson
{
	/** A way through the saved text: a member name, or null for "an element of a list". */
	private static final String ELEMENT = null;

	private final TypeAdapter<?> adapter;
	/** Where something was taken out, and why. */
	final List<String> dropped = new ArrayList<>();

	/** {@code type} is what the whole saved text is read as. */
	LenientJson(Gson gson, TypeToken<?> type)
	{
		this.adapter = gson.getAdapter(type);
	}

	/** A copy of {@code root} with what can't be read taken out, or null when none of it can. */
	JsonElement clean(JsonElement root, String path)
	{
		return prune(root, new ArrayList<>(), path);
	}

	private JsonElement prune(JsonElement e, List<String> steps, String path)
	{
		if (e == null || e.isJsonNull())
		{
			return null;
		}
		String broken = rule(steps, e);
		if (broken != null)
		{
			return reject(path, broken);
		}
		// Gson reads a null in a list or map and a drop without a name, so look inside before trusting it
		if (!hasProblem(steps, e) && reads(steps, e))
		{
			return e;
		}
		if (e.isJsonObject())
		{
			JsonObject out = new JsonObject();
			for (Map.Entry<String, JsonElement> member : e.getAsJsonObject().entrySet())
			{
				if (member.getValue().isJsonNull())
				{
					reject(path + "." + member.getKey(), "empty");
					continue;
				}
				JsonElement kept = prune(member.getValue(), with(steps, member.getKey()), path + "." + member.getKey());
				if (kept != null)
				{
					out.add(member.getKey(), kept);
				}
			}
			return checked(steps, out, path);
		}
		if (e.isJsonArray())
		{
			JsonArray in = e.getAsJsonArray();
			if (onlyValues(in))
			{
				// a list of plain values that doesn't read stays whole or goes whole (a raid time is a pair)
				return reject(path, "unreadable");
			}
			JsonArray out = new JsonArray();
			int i = 0;
			for (JsonElement element : in)
			{
				String at = path + "[" + i++ + "]";
				if (element.isJsonNull())
				{
					reject(at, "empty");
					continue;
				}
				JsonElement kept = prune(element, with(steps, ELEMENT), at);
				if (kept != null)
				{
					out.add(kept);
				}
			}
			return checked(steps, out, path);
		}
		return reject(path, "unreadable");
	}

	/** Whether anything inside {@code e} breaks a rule or is null, whatever Gson makes of it. */
	private static boolean hasProblem(List<String> steps, JsonElement e)
	{
		if (e.isJsonObject())
		{
			for (Map.Entry<String, JsonElement> member : e.getAsJsonObject().entrySet())
			{
				JsonElement value = member.getValue();
				if (value.isJsonNull() || rule(with(steps, member.getKey()), value) != null || hasProblem(with(steps, member.getKey()), value))
				{
					return true;
				}
			}
		}
		else if (e.isJsonArray())
		{
			for (JsonElement element : e.getAsJsonArray())
			{
				if (element.isJsonNull() || rule(with(steps, ELEMENT), element) != null || hasProblem(with(steps, ELEMENT), element))
				{
					return true;
				}
			}
		}
		return false;
	}

	/** What is left of a part once what can't be read is out: kept when it reads and breaks no rule. */
	private JsonElement checked(List<String> steps, JsonElement out, String path)
	{
		String broken = rule(steps, out);
		if (broken != null)
		{
			return reject(path, broken);
		}
		return reads(steps, out) ? out : reject(path, "unreadable");
	}

	/**
	 * Two things Gson reads without complaint but On Rate can't use: a drop with no item name (saved
	 * under {@code i}, in a kill's {@code d} list), and a raid time that isn't a pair (its end and its length).
	 */
	private static String rule(List<String> steps, JsonElement e)
	{
		int n = steps.size();
		if (n >= 2 && steps.get(n - 1) == ELEMENT && "d".equals(steps.get(n - 2)) && e.isJsonObject())
		{
			JsonElement name = e.getAsJsonObject().get("i");
			if (name == null || !name.isJsonPrimitive())
			{
				return "no item name";
			}
		}
		if (n >= 3 && steps.get(n - 1) == ELEMENT && "importedTimes".equals(steps.get(n - 3)))
		{
			if (!e.isJsonArray() || e.getAsJsonArray().size() < 2)
			{
				return "not a raid time";
			}
		}
		return null;
	}

	private static boolean onlyValues(JsonArray array)
	{
		for (JsonElement element : array)
		{
			if (!element.isJsonPrimitive())
			{
				return false;
			}
		}
		return true;
	}

	private static List<String> with(List<String> steps, String next)
	{
		List<String> longer = new ArrayList<>(steps);
		longer.add(next);
		return longer;
	}

	/** Whether Gson reads the saved text when it holds only {@code part}, at the place {@code steps} lead to. */
	private boolean reads(List<String> steps, JsonElement part)
	{
		JsonElement tree = part;
		for (int i = steps.size() - 1; i >= 0; i--)
		{
			String step = steps.get(i);
			if (step == ELEMENT)
			{
				JsonArray list = new JsonArray();
				list.add(tree);
				tree = list;
			}
			else
			{
				JsonObject holder = new JsonObject();
				holder.add(step, tree);
				tree = holder;
			}
		}
		try
		{
			adapter.fromJsonTree(tree);
			return true;
		}
		catch (RuntimeException ex)
		{
			return false;
		}
	}

	private JsonElement reject(String path, String why)
	{
		dropped.add(path + " (" + why + ")");
		return null;
	}
}

package com.onrate.store;

import java.util.HashSet;
import java.util.Set;

import com.google.gson.*;
import com.google.gson.reflect.TypeToken;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.tracking.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Loads and saves one account's data (the main data, plus the History and raids of each boss under
 * their own keys) in the settings of a RuneScape profile.
 *
 * <p>Every read and write names the profile that was loaded. RuneLite's "current" profile changes on
 * its own (it is none at the login screen, and switches as soon as another account logs in), so a save
 * that followed it could be dropped while logged out, or land in the next account. Saves always go to
 * the account whose data the tracker holds.
 */
public final class ProfileStore
{
	private static final Logger log = LoggerFactory.getLogger(ProfileStore.class);
	private static final TypeToken<List<RaidRecord>> RAIDS_TYPE = new TypeToken<List<RaidRecord>>()
	{
	};
	private static final TypeToken<List<KillEntry>> KILLS_TYPE = new TypeToken<List<KillEntry>>()
	{
	};

	/** RuneLite's per-profile settings, always addressed with the RuneScape profile key. */
	public interface Backend
	{
		String get(String profile, String key);

		void set(String profile, String key, String value);

		void unset(String profile, String key);
	}

	private final Backend backend;
	private final Gson gson;
	private String loadedProfile;
	/** True when the last load of a profile failed half way (see {@link #load}); false after one works. */
	private boolean loadFailed;
	/** Saved keys that couldn't be read or backed up when loaded: never written over until the next load. */
	private final Set<String> keep = new HashSet<>();

	public ProfileStore(Backend backend, Gson gson)
	{
		this.backend = backend;
		this.gson = gson;
	}

	/**
	 * Replaces the tracker's data with the one saved for this profile.
	 *
	 * <p>Damaged saved data never stops the load, and never loses what is still readable: each value
	 * is read along the saved classes and only the parts that can't be read are left out (see
	 * {@link LenientJson}). Whenever something is left out, the saved text is first kept under the
	 * same key plus {@code .corrupt}, and a warning says what was left out; a value whose backup
	 * can't be written is never written over this session. If loading still fails half way, no
	 * profile counts as loaded, so nothing is saved over the data that wasn't loaded.
	 *
	 * @return false when nothing was done: no profile yet, it is already the one loaded, or it failed
	 */
	public synchronized boolean load(String profile, Tracker tracker)
	{
		if (profile == null || profile.equals(loadedProfile))
		{
			return false;
		}
		loadedProfile = profile;
		loadFailed = false;
		keep.clear();
		try
		{
			String json = backend.get(profile, Keys.DATA);
			TrackerState state = json == null || json.isEmpty() ? null : read(profile, Keys.DATA, json, TypeToken.get(TrackerState.class));
			tracker.setState(state);
			for (BossDefinition boss : tracker.getCatalog().getBosses())
			{
				String key = Keys.killsKey(boss.getName());
				String kills = backend.get(profile, key);
				if (kills != null && !kills.isEmpty())
				{
					tracker.setKills(boss.getName(), read(profile, key, kills, KILLS_TYPE));
				}
			}
			for (BossDefinition boss : tracker.getCatalog().getBosses())
			{
				if (boss.getRaid() == null)
				{
					continue;
				}
				String key = Keys.raidsKey(boss.getName());
				String raids = backend.get(profile, key);
				if (raids != null && !raids.isEmpty())
				{
					tracker.setRaids(boss.getName(), read(profile, key, raids, RAIDS_TYPE));
				}
			}
			return true;
		}
		catch (RuntimeException e)
		{
			// the tracker may hold only part of this profile now: saving it would write over the rest
			log.error("Could not load the saved On Rate data of this profile; nothing will be saved until it loads", e);
			loadedProfile = null;
			loadFailed = true;
			return false;
		}
	}

	/**
	 * One saved value, with what can't be read left out (null when none of it can). When anything was
	 * left out the saved text is kept as a backup first.
	 */
	private <T> T read(String profile, String key, String json, TypeToken<T> type)
	{
		LenientJson lenient = new LenientJson(gson, type);
		JsonElement tree;
		try
		{
			tree = new JsonParser().parse(json);
		}
		catch (RuntimeException e)
		{
			log.warn("Could not read the saved On Rate {}; it is kept as {}", key, key + Keys.CORRUPT_SUFFIX, e);
			backup(profile, key, json);
			return null;
		}
		JsonElement clean = lenient.clean(tree, key);
		T value = null;
		if (clean != null)
		{
			try
			{
				value = gson.getAdapter(type).fromJsonTree(clean);
			}
			catch (RuntimeException e)
			{
				lenient.dropped.add(key + " (" + e.getMessage() + ")");
			}
		}
		if (!lenient.dropped.isEmpty() || (value == null && !tree.isJsonNull()))
		{
			List<String> what = lenient.dropped;
			log.warn("Parts of the saved On Rate {} could not be read and were left out ({}): {}; the saved text is kept as {}",
				key, what.size(), what.subList(0, Math.min(10, what.size())), key + Keys.CORRUPT_SUFFIX);
			backup(profile, key, json);
		}
		return value;
	}

	/** Writes what changed since the last save. Does nothing before a profile is loaded. */
	public synchronized void save(Tracker tracker)
	{
		if (tracker == null || loadedProfile == null)
		{
			return;
		}
		String profile = loadedProfile;
		// put together under the tracker's lock: safe from any thread (shutDown runs on Swing's)
		SaveData data = tracker.saveData(gson::toJson);
		// only the History and raids of bosses that changed are written again; they go first,
		// so raids moved out of the main data by an update are stored before it drops them
		List<String> killsLeft = new ArrayList<>();
		List<String> raidsLeft = new ArrayList<>();
		for (Map.Entry<String, String> e : data.kills.entrySet())
		{
			if (!write(profile, Keys.killsKey(e.getKey()), e.getValue()))
			{
				killsLeft.add(e.getKey());
			}
		}
		for (Map.Entry<String, String> e : data.raids.entrySet())
		{
			if (!write(profile, Keys.raidsKey(e.getKey()), e.getValue()))
			{
				raidsLeft.add(e.getKey());
			}
		}
		if (!killsLeft.isEmpty() || !raidsLeft.isEmpty())
		{
			// not written: the next save tries them again
			tracker.markUnsaved(killsLeft, raidsLeft);
		}
		if (!raidsLeft.isEmpty())
		{
			// the main data may no longer hold raids that just moved out of it: keep the saved one
			// until they are stored under their own key
			return;
		}
		if (keep.contains(Keys.DATA))
		{
			return;
		}
		try
		{
			backend.set(profile, Keys.DATA, data.progress);
		}
		catch (RuntimeException e)
		{
			// the main data is written whole on every save: the next one tries again
			log.warn("Could not save On Rate data", e);
		}
	}

	/** True when the last load failed half way, so no profile counts as loaded. False after a load works. */
	public synchronized boolean loadFailed()
	{
		return loadFailed;
	}

	/** The RuneLite profile key whose data the tracker holds now, or null before one is loaded. */
	public synchronized String loadedProfile()
	{
		return loadedProfile;
	}

	/** Forgets which profile is loaded (the plugin stopped). */
	public synchronized void forget()
	{
		loadedProfile = null;
	}

	/**
	 * Keeps a saved text that couldn't be fully read under its key plus ".corrupt". If even that
	 * fails, the key itself is not written this session, so the original stays where it was.
	 */
	private void backup(String profile, String key, String raw)
	{
		try
		{
			backend.set(profile, key + Keys.CORRUPT_SUFFIX, raw);
		}
		catch (RuntimeException e)
		{
			log.error("Could not keep a copy of the unreadable On Rate {}; it won't be written over", key, e);
			keep.add(key);
		}
	}

	/** Writes one key; false when the settings refused it. */
	private boolean write(String profile, String key, String json)
	{
		if (keep.contains(key))
		{
			// unreadable, and no copy of it could be made: leave the original alone
			return true;
		}
		try
		{
			if (json == null)
			{
				backend.unset(profile, key);
			}
			else
			{
				backend.set(profile, key, json);
			}
			return true;
		}
		catch (RuntimeException e)
		{
			log.warn("Could not save On Rate's {}", key, e);
			return false;
		}
	}
}

package com.expecteddrops;

import net.runelite.client.RuneLite;
