package com.expecteddrops;

import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.tracking.Tracker;
import java.lang.reflect.Field;
import java.util.Collection;
import java.util.Collections;
import net.runelite.api.events.VarbitChanged;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;
import org.junit.Test;

/** Events that arrive while On Rate is being stopped on another thread must not fail. */
public class ShutdownGuardTest
{
	private static void set(Object target, String name, Object value) throws Exception
	{
		Field f = ExpectedDropsPlugin.class.getDeclaredField(name);
		f.setAccessible(true);
		f.set(target, value);
	}

	@Test
	public void aVarbitDuringShutdownIsIgnored() throws Exception
	{
		ExpectedDropsPlugin plugin = new ExpectedDropsPlugin();
		// shutDown has cleared the roll counters but not yet the tracker check
		set(plugin, "tracker", new Tracker(Bundled.catalog(new Gson())));
		set(plugin, "rolls", null);
		plugin.onVarbitChanged(new VarbitChanged());
	}

	@Test
	public void lootDuringShutdownUsesTheTrackerItStartedWith() throws Exception
	{
		ExpectedDropsPlugin plugin = new ExpectedDropsPlugin();
		boolean[] askedOther = new boolean[1];
		Tracker stopping = new Tracker(Bundled.catalog(new Gson()))
		{
			@Override
			public synchronized String onLoot(String source, int amount, Collection<LootItem> items, long nowMillis)
			{
				try
				{
					// shutDown runs on another thread while this loot is handled
					set(plugin, "tracker", null);
				}
				catch (Exception e)
				{
					throw new AssertionError(e);
				}
				return null;
			}

			@Override
			public synchronized boolean onOtherLoot(String source, Collection<LootItem> items)
			{
				askedOther[0] = true;
				return false;
			}
		};
		set(plugin, "tracker", stopping);
		plugin.onLootReceived(new LootReceived("Goblin", 2, LootRecordType.NPC, Collections.emptyList(), 1, null));
		assertTrue("the rest of the event uses the same tracker", askedOther[0]);
	}
}

package com.expecteddrops;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.onrate.engine.stats.RaidChance;
import com.onrate.game.ConfigRaidSettings;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.client.config.ConfigItem;
import org.junit.Test;

/**
 * The Fractured Archive's team chance setting after the game update of 11 November 2026: its new key and
 * default, and the old value (which RuneLite had saved for everyone, changed or not) cleared exactly once.
 */
public class TfaSettingTest
{
	private static ExpectedDropsConfig withTeamChance(double percent)
	{
		return new ExpectedDropsConfig()
		{
			@Override
			public double tfaTeamChance()
			{
				return percent;
			}
		};
	}

	@Test
	public void theSettingHasANewKeyAndTheNewDefault() throws Exception
	{
		Method m = ExpectedDropsConfig.class.getMethod("tfaTeamChance");
		ConfigItem item = m.getAnnotation(ConfigItem.class);
		assertEquals("tfaSoloDuoChance", item.keyName());
		assertEquals("Fractured Archive team purple chance (%)", item.name());
		assertEquals(6.25, new ExpectedDropsConfig()
		{
		}.tfaTeamChance(), 0);
		// what it says matches the rules it stands for
		assertTrue(item.description().contains("1 in 16 (6.25%)"));
		assertTrue(item.description().contains("1 in 12.5 for three"));
		assertTrue(item.description().contains("1 in 7.5 for eight"));
		assertTrue(item.description().contains("11 November 2026"));
		assertFalse(item.description().contains("7.14"));
		assertFalse(item.description().contains("adds 4%"));
	}

	@Test
	public void theOldKeyIsClearedAndNoSettingInUseEverIs() throws Exception
	{
		List<String> old = Arrays.asList(ExpectedDropsPlugin.OLD_SETTINGS);
		assertTrue(old.contains("tfaTeamChance"));
		// a key in use on that list would be wiped at every start
		for (Method m : ExpectedDropsConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				assertFalse(item.keyName() + " is still a setting", old.contains(item.keyName()));
			}
		}
	}

	@Test
	public void theOldValueIsClearedOnceAndTheNewSettingKeepsWhatThePlayerSet()
	{
		// as RuneLite holds them: the old chance (7.14, saved for everyone), another old setting, and
		// the new setting already changed by hand
		Map<String, String> saved = new HashMap<>();
		saved.put("tfaTeamChance", "7.142857142857143");
		saved.put("showTrip", "true");
		saved.put("tfaSoloDuoChance", "9.0");
		saved.put("tfaTeamSize", "4");
		List<String> unset = new ArrayList<>();
		ExpectedDropsPlugin.clearOldSettings(saved::get, key ->
		{
			unset.add(key);
			saved.remove(key);
		});
		assertEquals(2, unset.size());
		assertTrue(unset.contains("tfaTeamChance"));
		assertFalse(saved.containsKey("tfaTeamChance"));
		assertEquals("9.0", saved.get("tfaSoloDuoChance"));
		assertEquals("4", saved.get("tfaTeamSize"));

		// the next start, and the one after: nothing left to clear, nothing reset again
		unset.clear();
		ExpectedDropsPlugin.clearOldSettings(saved::get, unset::add);
		ExpectedDropsPlugin.clearOldSettings(saved::get, unset::add);
		assertTrue(unset.isEmpty());
		assertEquals("9.0", saved.get("tfaSoloDuoChance"));
	}

	@Test
	public void aPlayerWhoNeverHadTheOldValueLosesNothing()
	{
		Map<String, String> saved = new HashMap<>();
		saved.put("tfaSoloDuoChance", "6.25");
		List<String> unset = new ArrayList<>();
		ExpectedDropsPlugin.clearOldSettings(saved::get, unset::add);
		assertTrue(unset.isEmpty());
		assertEquals(1, saved.size());
	}

	@Test
	public void theSettingIsThePercentForASoloOrDuoAndIsKeptBetween0And100()
	{
		assertEquals(RaidChance.TFA_BASE_CHANCE, new ConfigRaidSettings(new ExpectedDropsConfig()
		{
		}).tfaBaseChance(), 1e-15);
		ConfigRaidSettings ten = new ConfigRaidSettings(withTeamChance(10));
		assertEquals(0.10, ten.tfaBaseChance(), 1e-12);
		// the default team size is a duo: half the team's chance each
		assertEquals(0.05, ten.uniqueChance("fractured"), 1e-12);
		assertEquals(1.0, new ConfigRaidSettings(withTeamChance(150)).tfaBaseChance(), 0);
		assertEquals(0.0, new ConfigRaidSettings(withTeamChance(-5)).tfaBaseChance(), 0);
		assertEquals(0.0, new ConfigRaidSettings(withTeamChance(-5)).uniqueChance("fractured"), 0);
	}

	@Test
	public void raidsOnRateDidntCountUseTheFixedChanceOfTheSettingsTeamSize()
	{
		double[] oneIn = {16, 16, 12.5, 10.5, 9.5, 8.5, 8, 7.5};
		for (int team = 1; team <= 8; team++)
		{
			int size = team;
			ConfigRaidSettings s = new ConfigRaidSettings(new ExpectedDropsConfig()
			{
				@Override
				public int tfaTeamSize()
				{
					return size;
				}
			});
			// (a team size other than the default is the player's own choice: nothing learned replaces it)
			assertEquals(team + " players", 1 / oneIn[team - 1] / team, s.uniqueChance("fractured"), 1e-12);
		}
		// outside 1 to 8 the setting is read as the nearest size
		assertEquals(1 / 7.5 / 8, new ConfigRaidSettings(new ExpectedDropsConfig()
		{
			@Override
			public int tfaTeamSize()
			{
				return 20;
			}
		}).uniqueChance("fractured"), 1e-12);
		assertEquals(1 / 16.0, new ConfigRaidSettings(new ExpectedDropsConfig()
		{
			@Override
			public int tfaTeamSize()
			{
				return 0;
			}
		}).uniqueChance("fractured"), 1e-12);
	}
}

package com.expecteddrops.ui;

import com.expecteddrops.ExpectedDropsPlugin;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.stats.BossStats;
import com.onrate.engine.stats.RowStats;
import com.onrate.engine.stats.SharedPool;
import com.onrate.engine.tracking.Tracker;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.lang.reflect.Method;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The "also drops from" note in the hover of an item and of a shared item. */
public class AlsoFromNoteTest
{
	private static Tracker tracker() throws Exception
	{
		try (Reader reader = com.onrate.engine.data.Bundled.reader("bosses.json"))
		{
			Tracker tracker = new Tracker(BossCatalog.load(new Gson(), reader));
			tracker.setSettings(raid -> 0.03);
			return tracker;
		}
	}

	private static String itemTip(RowStats row, BossStats stats) throws Exception
	{
		Method m = ExpectedDropsPanel.class.getDeclaredMethod("tooltip", RowStats.class, BossStats.class, String.class);
		m.setAccessible(true);
		return (String) m.invoke(null, row, stats, "kill");
	}

	private static String poolTip(SharedPool pool) throws Exception
	{
		Method m = ExpectedDropsPanel.class.getDeclaredMethod("poolTooltip", SharedPool.class, RowStats.class);
		m.setAccessible(true);
		return (String) m.invoke(null, pool, pool.toRow());
	}

	@Test
	public void anItemOtherMonstersDropOffersToLeaveItOut() throws Exception
	{
		Tracker tracker = tracker();
		Map<String, Integer> page = new LinkedHashMap<>();
		page.put("Kraken tentacle", 3);
		tracker.onClogPage("Kraken", Collections.singletonList("Kraken kills: 800"), page);
		BossStats stats = tracker.stats("Kraken", raid -> 0.03);
		String tentacle = null;
		String jar = null;
		for (RowStats row : stats.getRows())
		{
			if (row.getLabel().equals("Kraken tentacle"))
			{
				tentacle = itemTip(row, stats);
			}
			else if (row.getLabel().equals("Jar of dirt"))
			{
				jar = itemTip(row, stats);
			}
		}
		assertTrue(tentacle, tentacle.contains("Also drops from cave krakens, and the collection log counts those too."));
		assertTrue(tentacle.contains("Right-click to leave it out."));
		assertFalse(jar, jar.contains("Also drops from"));
	}

	@Test
	public void aSharedItemOtherMonstersDropSaysItCanLookLuckier() throws Exception
	{
		Tracker tracker = tracker();
		boolean seen = false;
		for (SharedPool pool : tracker.sharedPools(raid -> 0.03))
		{
			String tip = poolTip(pool);
			if (pool.getItemName().equals("Dragon chainbody"))
			{
				assertTrue(tip, tip.contains("Also drops from dust devils and smoke devils, and the collection log counts "
					+ "those too, so this can look luckier than it is."));
				// shared items have no right-click to leave them out
				assertFalse(tip.contains("Right-click"));
				seen = true;
			}
			else if (pool.getItemName().equals("Dragon pickaxe"))
			{
				assertFalse(tip, tip.contains("Also drops from"));
			}
		}
		assertTrue(seen);
	}

	@Test
	public void aSharedItemHoverOnlyMentionsRightClickWhenTheMenuIsThere() throws Exception
	{
		Tracker tracker = tracker();
		Method m = ExpectedDropsPanel.class.getDeclaredMethod("poolTooltip", SharedPool.class, RowStats.class, boolean.class);
		m.setAccessible(true);
		for (SharedPool pool : tracker.sharedPools(raid -> 0.03))
		{
			String without = (String) m.invoke(null, pool, pool.toRow(), false);
			assertFalse(pool.getItemName(), without.contains("Right-click"));
			String with = (String) m.invoke(null, pool, pool.toRow(), ExpectedDropsPanel.hasSplitMenu(pool, true));
			assertEquals(pool.getItemName(), ExpectedDropsPanel.hasSplitMenu(pool, true), with.contains("Right-click"));
			if (pool.getOlderCopies() > 0 && pool.isSplittable() && pool.getKey() != null)
			{
				// older copies need somewhere to go
				assertFalse(ExpectedDropsPanel.hasSplitMenu(pool, false));
			}
		}
	}

	@Test
	public void theAnyUniqueRowHasNoLeaveOutMenu() throws Exception
	{
		Tracker tracker = tracker();
		BossStats stats = tracker.stats("Kraken", raid -> 0.03);
		assertFalse(ExpectedDropsPanel.hasLeaveOutMenu(stats.getAnyRow()));
		for (RowStats row : stats.getRows())
		{
			assertEquals(row.getLabel(), row.getIconItem() != null, ExpectedDropsPanel.hasLeaveOutMenu(row));
		}
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.BossDefinition;
import com.onrate.engine.data.Bundled;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/** The boss search box: name matches as before, item names from 3 letters, at word starts. */
public class BossSearchTest
{
	private BossCatalog catalog;
	private BossSearch search;

	@Before
	public void setUp() throws Exception
	{
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			catalog = BossCatalog.load(new Gson(), reader);
		}
		search = new BossSearch(catalog);
	}

	private List<String> names(String query)
	{
		List<String> out = new ArrayList<>();
		for (BossSearch.Hit hit : search.search(query))
		{
			out.add(hit.boss().getName());
		}
		return out;
	}

	private BossSearch.Hit hit(String query, String boss)
	{
		for (BossSearch.Hit hit : search.search(query))
		{
			if (hit.boss().getName().equals(boss))
			{
				return hit;
			}
		}
		return null;
	}

	@Test
	public void emptyQueryListsEveryBossWithoutReasons()
	{
		List<BossSearch.Hit> hits = search.search("");
		assertEquals(catalog.getBosses().size(), hits.size());
		for (BossSearch.Hit hit : hits)
		{
			assertNull(hit.reason());
		}
	}

	@Test
	public void fangFindsTheSixBossesThatDropOne()
	{
		assertEquals(Arrays.asList("Alchemical Hydra", "Araxxor", "Maggot King", "Tombs of Amascut",
			"Venenatis and Spindel", "Zulrah"), names("fang"));
		assertNotNull(hit("fang", "Zulrah").reason());
	}

	@Test
	public void ringMatchesWordStartsOnly()
	{
		List<String> found = names("ring");
		assertEquals(6, found.size());
		assertTrue(found.contains("Dagannoth Kings"));
		assertFalse(found.contains("Cerberus"));
		assertFalse(found.contains("Scorpia"));
		assertFalse(found.contains("Fractured Archive"));
	}

	@Test
	public void visageFindsThreeBosses()
	{
		assertEquals(Arrays.asList("King Black Dragon", "Vorkath", "Zulrah"), names("visage"));
	}

	@Test
	public void tassetsFindsGraardorThenMoonsOfPeril()
	{
		assertEquals(Arrays.asList("General Graardor", "Moons of Peril"), names("tassets"));
	}

	@Test
	public void bossNameMatchesComeFirstAndHaveNoReason()
	{
		List<BossSearch.Hit> hits = search.search("dragon");
		assertEquals("King Black Dragon", hits.get(0).boss().getName());
		assertNull(hits.get(0).reason());
		assertTrue(hits.size() > 1);
		assertNotNull(hits.get(1).reason());
	}

	@Test
	public void shortWordsFindNothingFromItemsEvenIfTheyStartAnItemWord()
	{
		// under 3 letters only the name rules apply: "fa" is no boss name, kill count name or short name
		for (BossSearch.Hit hit : search.search("fa"))
		{
			assertNull(hit.reason());
		}
	}

	@Test
	public void coxStillOpensChambersOfXericFirst()
	{
		List<BossSearch.Hit> hits = search.search("cox");
		assertEquals("Chambers of Xeric", hits.get(0).boss().getName());
		assertNull(hits.get(0).reason());
	}

	@Test
	public void everyTypedWordMustMatchAWordOfTheSameItem()
	{
		List<String> pick = names("dragon pick");
		assertTrue(pick.contains("Kalphite Queen"));
		assertTrue(pick.contains("Chaos Elemental"));
		// a name that is not an item, in any order
		assertTrue(names("pick dragon").containsAll(pick));
		assertTrue(names("dragon zzz").isEmpty());
	}

	@Test
	public void sharedItemsAreFoundOnEveryBossThatDropsThem()
	{
		List<String> onyx = names("uncut onyx");
		assertTrue(onyx.contains("Skotizo"));
		assertTrue(onyx.contains("Zulrah"));
		// godsword shards are several pools; each boss is listed once
		List<String> shard = names("godsword shard");
		assertEquals(shard.size(), new java.util.HashSet<>(shard).size());
		assertFalse(shard.isEmpty());
	}

	@Test
	public void clogSharedItemsMatchNothing()
	{
		assertTrue(names("dragon thrownaxe").isEmpty());
		assertTrue(names("dragon knife").isEmpty());
	}

	@Test
	public void extraNamesAndLabelsFindTheBoss()
	{
		assertEquals(Arrays.asList("Fortis Colosseum"), names("cuirass"));
		assertEquals("Sunfire fanatic cuirass", hit("cuirass", "Fortis Colosseum").reason().split(" \\+")[0]);
	}

	@Test
	public void curlyApostrophesAndDashesDoNotGetInTheWay()
	{
		assertEquals(Arrays.asList("jal", "nib", "rek"), BossSearch.words("Jal-Nib-Rek"));
		assertEquals(Arrays.asList("dragons", "pick"), BossSearch.words("Dragon\u2019s pick"));
	}

	@Test
	public void exactItemNameComesBeforeWordStartMatches()
	{
		// "Tanzanite fang" is an exact item name at Zulrah; every other fang hit is a word-start match
		List<BossSearch.Hit> hits = search.search("tanzanite fang");
		assertEquals("Zulrah", hits.get(0).boss().getName());
	}

	@Test
	public void everyBossStillFindsItselfByNameFirst()
	{
		for (BossDefinition boss : catalog.getBosses())
		{
			BossSearch.Hit first = search.search(boss.getName()).get(0);
			// an earlier boss may also contain the whole name, but only as a name match
			assertNull(boss.getName(), first.reason());
			assertTrue(boss.getName(), names(boss.getName()).contains(boss.getName()));
		}
	}

	@Test
	public void reasonsMapHoldsOnlyItemMatches()
	{
		java.util.Map<String, String> reasons = BossSearch.reasons(search.search("cox"));
		assertFalse(reasons.containsKey("Chambers of Xeric"));
		assertTrue(BossSearch.reasons(search.search("fang")).containsKey("Zulrah"));
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import org.junit.Test;

/** A boss page says the boss's own unit (chests, delves...), not always "kills" (audit M2). */
public class BossUnitWordsTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static final RaidSettings RAIDS = raid -> 0.03;

	private static void texts(Component c, List<String> out)
	{
		if (c instanceof JLabel && ((JLabel) c).getText() != null)
		{
			out.add(((JLabel) c).getText());
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				texts(child, out);
			}
		}
	}

	private static List<String> page(Tracker tracker, String boss) throws Exception
	{
		List<String> out = new ArrayList<>();
		SwingUtilities.invokeAndWait(() ->
		{
			ExpectedDropsPanel p = new ExpectedDropsPanel(tracker, null, () -> RAIDS, s -> -1, () -> { },
				name -> 0L, () -> new ViewOptions(ItemView.TARGET_BARS, false, false, false, false, true));
			p.onActivate();
			p.showBoss(boss);
			texts(p, out);
		});
		return out;
	}

	private static Tracker tracker()
	{
		Tracker t = new Tracker(Bundled.catalog(new Gson()));
		t.setSettings(RAIDS);
		return t;
	}

	@Test
	public void noKillsYetSaysTheBossesOwnUnit() throws Exception
	{
		assertTrue(page(tracker(), "Barrows").toString(), page(tracker(), "Barrows").contains("No chests yet"));
		assertTrue(page(tracker(), "Doom of Mokhaiotl").contains("No delves yet"));
		assertTrue(page(tracker(), "Vorkath").contains("No kills yet"));
	}

	@Test
	public void tooEarlySaysTheBossesOwnUnit() throws Exception
	{
		Tracker t = tracker();
		t.onClogPage("Barrows Chests", Collections.singletonList("Barrows Chests opened: 2"), new java.util.LinkedHashMap<>());
		List<String> texts = page(t, "Barrows");
		String joined = String.join("\n", texts);
		assertTrue(joined, joined.contains("Too few chests"));
		assertFalse(joined, joined.contains("Too few kills"));
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.onrate.engine.stats.AccountStats;
import com.onrate.engine.stats.ItemHighlight;
import com.onrate.engine.stats.RowStats;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import org.junit.Test;

/** The Pets groups and Recent stop at a few entries; "show all" needs the whole lists, in the same order. */
public class CappedListNotesTest
{
	private static ItemHighlight pet(String name, double expected, boolean have)
	{
		RowStats row = new RowStats(name, name, 0.001, expected, have ? 1 : 0, false);
		return new ItemHighlight("Boss", have ? row.once(1) : row, true);
	}

	private static AccountStats account(List<ItemHighlight> items)
	{
		AccountStats account = new AccountStats(new RowStats("Total", "Total", 1, 0, 0, false), new ArrayList<>(), new LinkedHashMap<>());
		account.setItems(items);
		return account;
	}

	private static List<String> labels(List<ItemHighlight> list)
	{
		List<String> names = new ArrayList<>();
		for (ItemHighlight h : list)
		{
			names.add(h.getRow().getLabel());
		}
		return names;
	}

	private static AccountStats sevenAndSix()
	{
		List<ItemHighlight> items = new ArrayList<>();
		for (int i = 1; i <= 7; i++)
		{
			items.add(pet(String.format("Have%d", i), i, true));
		}
		for (int i = 1; i <= 6; i++)
		{
			items.add(pet(String.format("Dry%d", i), i, false));
		}
		// not a pet, and a pet with nothing expected: neither is listed
		items.add(new ItemHighlight("Boss", new RowStats("Item", "Item", 0.001, 2, 0, false), false));
		items.add(pet("NoneExpected", 0, false));
		return account(items);
	}

	@Test
	public void petListHoldsEveryPetOfItsGroup()
	{
		AccountStats account = sevenAndSix();
		List<String> have = labels(ExpectedDropsPanel.petList(account, true));
		assertEquals(7, have.size());
		// the pets you have, the one got with the fewest kills expected first
		assertEquals("Have1", have.get(0));
		assertEquals("Have7", have.get(6));
		assertEquals(6, ExpectedDropsPanel.petList(account, false).size());
	}

	@Test
	public void topPetsStillShowFiveOfEachGroupAsTheStartOfTheFullLists()
	{
		AccountStats account = sevenAndSix();
		List<String> top = labels(ExpectedDropsPanel.topItems(account, ExpectedDropsPanel.TOP_PETS));
		assertEquals(2 * ExpectedDropsPanel.TOP_PETS_SHOWN, top.size());
		List<String> have = labels(ExpectedDropsPanel.petList(account, true));
		List<String> dry = labels(ExpectedDropsPanel.petList(account, false));
		assertEquals(have.subList(0, 5), top.subList(0, 5));
		assertEquals(dry.subList(0, 5), top.subList(5, 10));
		assertTrue(have.size() > 5 && dry.size() > 5);
	}

	@Test
	public void recentKeepsTenBeforeShowAll()
	{
		assertEquals(10, ExpectedDropsPanel.RECENT_SHOWN);
	}
}

package com.expecteddrops.ui;

import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.border.CompoundBorder;
import javax.swing.border.EmptyBorder;
import javax.swing.border.MatteBorder;
import net.runelite.client.ui.ColorScheme;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The card look: runs of list rows go into one outlined card, everything else stays where it was. */
public class CardLookTest
{
	private static JPanel row()
	{
		JPanel row = new JPanel();
		row.setBorder(new EmptyBorder(Theme.HAIR, Theme.S, Theme.HAIR, Theme.S));
		return Card.row(row);
	}

	private static JPanel gap(int height)
	{
		JPanel p = new JPanel();
		p.setOpaque(false);
		p.setPreferredSize(new Dimension(1, height));
		return p;
	}

	private static JPanel host(Component... parts)
	{
		JPanel host = new JPanel();
		host.setLayout(new BoxLayout(host, BoxLayout.Y_AXIS));
		for (Component c : parts)
		{
			host.add(c);
		}
		return host;
	}

	@Test
	public void rowsWithSmallGapsBecomeOneCardWithLinesBetween()
	{
		JLabel header = new JLabel("ITEMS");
		JPanel a = row();
		JPanel b = row();
		JPanel c = row();
		JPanel host = host(header, gap(Theme.HAIR), a, gap(Theme.HAIR), b, gap(Theme.HAIR), c);
		Card.box(host);
		// the header, the gap before the first row, then the card
		assertEquals(3, host.getComponentCount());
		assertSame(header, host.getComponent(0));
		assertTrue(host.getComponent(2) instanceof Card);
		Card card = (Card) host.getComponent(2);
		// three rows and a line between each two: the gaps between the rows are gone
		assertEquals(5, card.getComponentCount());
		assertSame(a, card.getComponent(0));
		assertSame(b, card.getComponent(2));
		assertSame(c, card.getComponent(4));
		assertEquals(1, card.getComponent(1).getPreferredSize().height);
	}

	@Test
	public void aLabelOrBiggerGapBetweenRowsStartsANewCard()
	{
		JPanel host = host(row(), row(), new JLabel("LUCKIEST"), row(), gap(Theme.S), row());
		Card.box(host);
		// card, label, card, gap, card
		assertEquals(5, host.getComponentCount());
		assertTrue(host.getComponent(0) instanceof Card);
		assertTrue(host.getComponent(1) instanceof JLabel);
		assertTrue(host.getComponent(2) instanceof Card);
		assertFalse(host.getComponent(3) instanceof Card);
		assertTrue(host.getComponent(4) instanceof Card);
	}

	@Test
	public void aSummaryHeadingRowOpensTheCardOfItsPartRows()
	{
		JLabel heading = new JLabel("Average purple chance from points");
		heading.setBorder(new EmptyBorder(Theme.HAIR, 0, Theme.HAIR, 0));
		JPanel host = host(row(), row(), gap(Theme.S), Card.row(heading), gap(Theme.HAIR), row(), gap(Theme.HAIR), row());
		Card.box(host);
		// the rows above, a gap, then one card: the heading and its part rows
		assertEquals(3, host.getComponentCount());
		assertTrue(host.getComponent(0) instanceof Card);
		assertFalse(host.getComponent(1) instanceof Card);
		assertEquals(Theme.S, host.getComponent(1).getPreferredSize().height);
		Card summary = (Card) host.getComponent(2);
		// heading, line, row, line, row
		assertEquals(5, summary.getComponentCount());
		assertSame(heading, summary.getComponent(0));
		assertEquals(Theme.S, heading.getInsets().left);
	}

	@Test
	public void unmarkedPanelsAreLeftAlone()
	{
		JPanel trip = new JPanel();
		JPanel host = host(trip, gap(Theme.M));
		Card.box(host);
		assertEquals(2, host.getComponentCount());
		assertSame(trip, host.getComponent(0));
	}

	@Test
	public void aRowsOwnSeparatorLineGoesInsideTheCard()
	{
		JPanel line = new JPanel();
		EmptyBorder inner = new EmptyBorder(Theme.HAIR, Theme.S, Theme.HAIR, Theme.S);
		line.setBorder(BorderFactory.createCompoundBorder(new MatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR), inner));
		JPanel host = host(Card.row(line));
		Card.box(host);
		assertSame(inner, line.getBorder());
	}

	@Test
	public void rowsWithoutSidePaddingGetSomeInsideTheCard()
	{
		JPanel bare = new JPanel();
		bare.setBorder(new EmptyBorder(Theme.HAIR, 0, Theme.HAIR, 0));
		Card.box(host(Card.row(bare)));
		assertTrue(bare.getBorder() instanceof CompoundBorder);
		assertEquals(Theme.S, bare.getInsets().left);
	}

	@Test
	public void aGridIsPaddedOnEverySide()
	{
		JPanel grid = Card.gridRow(new JPanel());
		Card.box(host(grid));
		assertEquals(Theme.M, grid.getInsets().top);
		assertEquals(Theme.S, grid.getInsets().left);
	}

	@Test
	public void turnedOffACardIsAPlainOpaquePanel()
	{
		Card card = new Card();
		assertFalse(card.isOpaque());
		card.setBoxed(false);
		assertTrue(card.isOpaque());
		assertFalse(card.isBoxed());
	}

	@Test
	public void aPillCanHaveAFixedWidthForAColumn()
	{
		LuckPill pill = new LuckPill("50%", Palette.luck(0.5), 46);
		assertEquals(46, pill.getPreferredSize().width);
		assertEquals(46, pill.getMaximumSize().width);
		assertTrue(new LuckPill("about average", Palette.luck(0.5), 0).getPreferredSize().width > 46);
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

/** The thin bar under a Time row: longer grinds fill more of it, on a scale of tens. */
public class EffortBarTest
{
	private static double hours(double h)
	{
		return EffortBar.fraction(h * 3600);
	}

	@Test
	public void noTimeIsAnEmptyBar()
	{
		assertEquals(0, EffortBar.fraction(Double.NaN), 0);
		assertEquals(0, EffortBar.fraction(0), 0);
		assertEquals(0, EffortBar.fraction(-5), 0);
	}

	@Test
	public void longerGrindsFillMore()
	{
		assertTrue(hours(0.25) < hours(3));
		assertTrue(hours(3) < hours(30));
		assertTrue(hours(30) < hours(300));
		assertTrue(hours(300) < hours(900));
	}

	@Test
	public void eachTenTimesLongerAddsAboutTheSame()
	{
		// 9 h, 99 h and 999 h are 1, 2 and 3 steps of ten on the scale of 1 + hours
		assertEquals(hours(99) - hours(9), hours(999) - hours(99), 1e-9);
		assertEquals(1.0, hours(999), 1e-3);
	}

	@Test
	public void theBarIsFullAtAThousandHoursAndStaysThere()
	{
		assertEquals(1.0, hours(EffortBar.FULL_HOURS), 1e-12);
		assertEquals(1.0, hours(5000), 0);
		assertTrue(hours(0.5) > 0 && hours(0.5) < 0.2);
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import java.awt.Component;
import java.awt.Container;
import java.io.Reader;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

/** The folds on a raid page: History, Personal bests and Points over time are remembered; the others start folded. */
public class FoldMemoryTest
{
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new Gson());
		com.onrate.engine.data.LadlorChart.bundled(new Gson());
	}

	private static final String COX = "Chambers of Xeric";

	private static ExpectedDropsPanel panel() throws Exception
	{
		RaidSettings raids = raid -> 0.035;
		try (Reader reader = com.onrate.engine.data.Bundled.reader("bosses.json"))
		{
			Tracker tracker = new Tracker(BossCatalog.load(new Gson(), reader));
			tracker.setSettings(raid -> 0.035);
			ExpectedDropsPanel panel = new ExpectedDropsPanel(tracker, null, () -> raids, s -> -1, () -> { },
				s -> 0L, () -> new ViewOptions(ItemView.TARGET_BARS, false, false, false, false, true));
			panel.setSize(225, 6000);
			return panel;
		}
	}

	private static boolean field(Object target, String name) throws Exception
	{
		java.lang.reflect.Field f = target.getClass().getDeclaredField(name);
		f.setAccessible(true);
		return f.getBoolean(target);
	}

	private static List<String> labels(Component c)
	{
		List<String> out = new ArrayList<>();
		collect(c, out);
		return out;
	}

	private static void collect(Component c, List<String> out)
	{
		if (c instanceof javax.swing.JLabel && ((javax.swing.JLabel) c).getText() != null)
		{
			out.add(((javax.swing.JLabel) c).getText());
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				collect(child, out);
			}
		}
	}

	private static boolean any(List<String> labels, String part)
	{
		for (String l : labels)
		{
			if (l.contains(part))
			{
				return true;
			}
		}
		return false;
	}

	@Test
	public void nothingSavedMeansEverythingFolded() throws Exception
	{
		ExpectedDropsPanel panel = panel();
		panel.setFoldStateStore("", state -> { });
		assertFalse(field(panel, "historyOpen"));
		assertFalse(field(panel, "bestsOpen"));
		assertFalse(field(panel, "pointsOpen"));
	}

	@Test
	public void savedIdsOpenTheirSectionsOnly() throws Exception
	{
		ExpectedDropsPanel panel = panel();
		panel.setFoldStateStore("history,points", state -> { });
		assertTrue(field(panel, "historyOpen"));
		assertFalse(field(panel, "bestsOpen"));
		assertTrue(field(panel, "pointsOpen"));
		// the setups and log folds are never remembered
		assertFalse(field(panel, "setupsOpen"));
		assertFalse(field(panel, "logOpen"));
	}

	@Test
	public void unknownAndBrokenValuesAreIgnored() throws Exception
	{
		ExpectedDropsPanel panel = panel();
		panel.setFoldStateStore(" bests ,setups,,log,nonsense", state -> { });
		assertFalse(field(panel, "historyOpen"));
		assertTrue(field(panel, "bestsOpen"));
		assertFalse(field(panel, "pointsOpen"));
		assertFalse(field(panel, "setupsOpen"));
		assertFalse(field(panel, "logOpen"));
		panel.setFoldStateStore(null, null);
		assertFalse(field(panel, "bestsOpen"));
	}

	@Test
	public void restoringDoesNotWriteBack() throws Exception
	{
		ExpectedDropsPanel panel = panel();
		List<String> saved = new ArrayList<>();
		panel.setFoldStateStore("history", saved::add);
		assertEquals(0, saved.size());
	}

	@Test
	public void aRememberedHistoryIsOpenWhenThePageIsShown() throws Exception
	{
		ExpectedDropsPanel panel = panel();
		panel.setFoldStateStore("history", state -> { });
		panel.showBoss(COX);
		panel.refresh();
		assertTrue(any(labels(panel), "\u25be HISTORY"));
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.data.KillTimes;
import com.onrate.engine.stats.GreenLog;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.stats.RowStats;
import com.onrate.engine.tracking.Tracker;
import java.awt.Component;
import java.awt.Container;
import java.io.Reader;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import org.junit.Test;

/** "Closest to green log": a sort of the Bosses list, with a Pets slider and the time on each row. */
public class GreenLogSortTest
{
	static
	{
		KillTimes.bundled(new Gson());
		com.onrate.engine.data.LadlorChart.bundled(new Gson());
	}

	private static final RaidSettings RAIDS = raid -> 0.03;

	private static Tracker tracker() throws Exception
	{
		BossCatalog catalog;
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			catalog = BossCatalog.load(new Gson(), reader);
		}
		Tracker tracker = new Tracker(catalog);
		tracker.setSettings(RAIDS);
		// a collection log page opened at a few bosses (kills, no uniques), so the account overview has rows
		int kills = 200;
		for (com.onrate.engine.data.BossDefinition boss : catalog.getBosses())
		{
			if (boss.getKcNames().isEmpty() || boss.getClogPages().isEmpty())
			{
				continue;
			}
			List<String> counters = new ArrayList<>();
			for (String name : boss.getKcNames())
			{
				counters.add(name + " kills: " + kills);
			}
			java.util.Map<String, Integer> items = new java.util.LinkedHashMap<>();
			for (com.onrate.engine.data.DropDefinition drop : boss.getDrops())
			{
				for (String name : drop.getAllNames())
				{
					items.put(name, 0);
				}
			}
			tracker.onClogPage(boss.getClogPages().get(0), counters, items);
		}
		return tracker;
	}

	private static ExpectedDropsPanel panel(Tracker tracker) throws Exception
	{
		ExpectedDropsPanel panel = new ExpectedDropsPanel(tracker, null, () -> RAIDS, s -> -1, () -> { },
			name -> 1L, () -> new ViewOptions(ItemView.TARGET_BARS, false, false, false, false, true));
		panel.showBoss(ExpectedDropsPanel.ACCOUNT);
		panel.refresh();
		return panel;
	}

	@SuppressWarnings("unchecked")
	private static JComboBox<Object> sortBox(ExpectedDropsPanel panel) throws Exception
	{
		Field f = ExpectedDropsPanel.class.getDeclaredField("sortSelect");
		f.setAccessible(true);
		return (JComboBox<Object>) f.get(panel);
	}

	private static PetsSwitch petsSwitch(ExpectedDropsPanel panel) throws Exception
	{
		Field f = ExpectedDropsPanel.class.getDeclaredField("petsSwitch");
		f.setAccessible(true);
		return (PetsSwitch) f.get(panel);
	}

	private static void texts(Component c, List<String> out)
	{
		if (c instanceof JLabel && ((JLabel) c).getText() != null)
		{
			out.add(((JLabel) c).getText());
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				texts(child, out);
			}
		}
	}

	@Test
	public void theSortIsTheLastOne() throws Exception
	{
		JComboBox<Object> box = sortBox(panel(tracker()));
		assertEquals("Closest to green log", box.getItemAt(box.getItemCount() - 1).toString());
	}

	@Test
	public void theSliderShowsOnlyForThatSort() throws Exception
	{
		ExpectedDropsPanel panel = panel(tracker());
		JComboBox<Object> box = sortBox(panel);
		assertFalse(petsSwitch(panel).isVisible());
		box.setSelectedItem(box.getItemAt(box.getItemCount() - 1));
		panel.refresh();
		assertTrue(petsSwitch(panel).isVisible());
		box.setSelectedIndex(0);
		panel.refresh();
		assertFalse(petsSwitch(panel).isVisible());
	}

	@Test
	public void theRowsShowATimeInsteadOfAVerdict() throws Exception
	{
		ExpectedDropsPanel panel = panel(tracker());
		JComboBox<Object> box = sortBox(panel);
		box.setSelectedItem(box.getItemAt(box.getItemCount() - 1));
		panel.refresh();
		List<String> shown = new ArrayList<>();
		texts(panel, shown);
		boolean timed = false;
		for (String text : shown)
		{
			timed |= text.matches("~?[0-9,.]+ (h|min)");
		}
		assertTrue("a row shows a time: " + shown, timed);
	}

	@Test
	public void turningPetsOnMakesEveryTimeLonger() throws Exception
	{
		Tracker tracker = tracker();
		Map<String, GreenLog.Page> without = GreenLog.compute(tracker, KillTimes.bundled(), RAIDS, b -> true, false);
		Map<String, GreenLog.Page> with = GreenLog.compute(tracker, KillTimes.bundled(), RAIDS, b -> true, true);
		for (String boss : new String[]{"Zulrah", "Vorkath"})
		{
			assertNotNull(boss, without.get(boss));
			assertTrue(boss, with.get(boss).getAverageSeconds() >= without.get(boss).getAverageSeconds());
		}
	}

	@Test
	public void theSliderChangesTheList() throws Exception
	{
		ExpectedDropsPanel panel = panel(tracker());
		JComboBox<Object> box = sortBox(panel);
		box.setSelectedItem(box.getItemAt(box.getItemCount() - 1));
		panel.refresh();
		List<String> before = new ArrayList<>();
		texts(panel, before);
		Method toggle = PetsSwitch.class.getDeclaredMethod("toggle");
		toggle.setAccessible(true);
		toggle.invoke(petsSwitch(panel));
		assertTrue(petsSwitch(panel).isOn());
		List<String> after = new ArrayList<>();
		texts(panel, after);
		assertFalse("the times change with pets on", before.equals(after));
	}

	@Test
	public void quickestFirstThenNoAnswerThenDone() throws Exception
	{
		Tracker tracker = tracker();
		Map<String, GreenLog.Page> pages = GreenLog.compute(tracker, KillTimes.bundled(), RAIDS, b -> true, false);
		List<RowStats> rows = new ArrayList<>();
		for (String name : new String[]{"Vorkath", "Zulrah", "Corporeal Beast", "No such boss"})
		{
			rows.add(new RowStats(name, null, 0.01, 1, 0, false));
		}
		rows.sort(ExpectedDropsPanel.greenLogOrder(pages));
		// the one with no page is after every timed one
		assertEquals("No such boss", rows.get(rows.size() - 1).getLabel());
		double last = 0;
		for (RowStats row : rows.subList(0, rows.size() - 1))
		{
			GreenLog.Page page = pages.get(row.getLabel());
			if (page != null && !page.isDone() && !Double.isNaN(page.getAverageSeconds()))
			{
				assertTrue(row.getLabel(), page.getAverageSeconds() >= last);
				last = page.getAverageSeconds();
			}
		}
	}

	@Test
	public void theTimeIsMarkedWhenItRestsOnTheWiki()
	{
		assertEquals("-", ExpectedDropsPanel.greenLogText(null));
		GreenLog.Page zulrah = null;
		try
		{
			zulrah = GreenLog.compute(new Tracker(BossCatalog.load(new Gson(), Bundled.reader("bosses.json"))), KillTimes.bundled(),
				RAIDS, b -> true, false).get("Zulrah");
		}
		catch (Exception e)
		{
			throw new AssertionError(e);
		}
		assertTrue(zulrah.isEstimated());
		assertTrue(ExpectedDropsPanel.greenLogText(zulrah).startsWith("~"));
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

