	{
		assertEquals(0, LuckWindow.span(Collections.emptyList()));
		assertEquals(1, LuckWindow.span(Arrays.asList(point(5, 0.5))));
		assertEquals(31, LuckWindow.span(Arrays.asList(point(5, 0.5), point(35, 0.4))));
