		HistoryPoint d = point(100, 0.5);
		List<HistoryPoint> out = LuckWindow.select(Arrays.asList(a, b, c, d), 71, 100);
		assertEquals(Arrays.asList(b, c, d), out);
		assertEquals(2, LuckWindow.inside(out, 71));
