/** The "Share of a purple" row in a raid item's hover. */
public class PurpleShareTest
{
	private static String share(String bossName, String item) throws Exception
	{
		try (Reader reader = com.onrate.engine.data.Bundled.reader("bosses.json"))
		{
			BossCatalog catalog = BossCatalog.load(new Gson(), reader);
			BossDefinition boss = catalog.byName(bossName);
			for (DropDefinition drop : boss.getDrops())
			{
				if (drop.getDisplayName().equals(item))
				{
					return ExpectedDropsPanel.purpleShare(boss, drop);
				}
			}
			throw new AssertionError("no " + item);
		}
	}

	@Test
	public void raidUniquesShowTheirShare() throws Exception
	{
		assertEquals("5 of 15", share("The Fractured Archive", "Rondache"));
		assertEquals("1 of 15", share("The Fractured Archive", "Obligator (uncharged)"));
		// Entry Mode has no purples, so ToB's share is the same in every mode that has them
		assertEquals("8 of 19", share("Theatre of Blood", "Avernic defender hilt"));
	}

	@Test
	public void noShareWhenItChangesOrIsntAPurple() throws Exception
	{
		// out of 60 in normal mode, 56 in Challenge Mode
		assertNull(share("Chambers of Xeric", "Twisted bow"));
		// ToA's weights move with the raid level
		assertNull(share("Tombs of Amascut", "Osmumten's fang"));
		// rolled on its own
		assertNull(share("The Fractured Archive", "Orion"));
		assertNull(share("The Fractured Archive", "Elemental fragments"));
	}
}

package com.expecteddrops.ui;

import com.onrate.engine.math.Verdict;

import com.onrate.engine.stats.RowStats;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotEquals;
import static org.junit.Assert.assertTrue;
import java.awt.Dimension;
import java.awt.image.BufferedImage;
import org.junit.Test;

/** Lists keep every row, but draw the ones with nothing to read quietly, and say "have it" the same way everywhere. */
public class QuietRowsTest
{
	private static RowStats row(double expected, int received)
	{
		return new RowStats("Twisted buckler", "Twisted buckler", expected / 100, expected, received, false);
	}

	@Test
	public void aRowIsQuietOnlyWhenNoneAreGotAndLessThanHalfIsExpected()
	{
		assertTrue(Texts.isQuiet(row(0.37, 0)));
		assertTrue(Texts.isQuiet(row(0.0, 0)));
		assertTrue(Texts.isQuiet(row(Texts.TOO_EARLY_BELOW - 0.001, 0)));
		// the same line as the boss page's "Too early": half a unique is the first row with something to read
		assertFalse(Texts.isQuiet(row(Texts.TOO_EARLY_BELOW, 0)));
		assertFalse(Texts.isQuiet(row(1.52, 0)));
		// a drop is always worth reading, however little was expected
		assertFalse(Texts.isQuiet(row(0.19, 1)));
		assertFalse(Texts.isQuiet(row(Double.NaN, 0)));
	}

	@Test
	public void anyUniqueIsNeverQuiet()
	{
		assertFalse(Texts.isQuiet(new RowStats("Any", null, 0, 0.1, 0, true)));
	}

	@Test
	public void petsAndCappedItemsFollowTheSameRule()
	{
		assertTrue(Texts.isQuiet(row(0.11, 0).once(0)));
		assertFalse(Texts.isQuiet(row(0.11, 1).once(1)));
		// Wintertodt's warm gloves: up to 3 copies
		assertTrue(Texts.isQuiet(row(0.2, 0).capped(3, 0)));
		assertFalse(Texts.isQuiet(row(0.2, 2).capped(3, 2)));
	}

	@Test
	public void aQuietRowIsNeverDryOrLucky()
	{
		// this is why muting hides nothing: with none got and under half expected, every verdict is "On rate"
		for (double expected = 0.01; expected < Texts.TOO_EARLY_BELOW; expected += 0.01)
		{
			RowStats r = row(expected, 0);
			assertTrue(Texts.isQuiet(r));
			// ordinary items, pets (have it or not) and capped items (warm gloves, titan scrolls) alike
			for (RowStats each : new RowStats[]{r, r.once(0), r.capped(3, 0)})
			{
				assertEquals("expected " + expected, Verdict.ON_RATE.label(), Verdict.labelOf(each.getLuck()));
			}
		}
	}

	@Test
	public void haveItMatchesTheCopiesThatCount()
	{
		assertEquals("have it", Texts.haveText(row(0.5, 1).once(1)));
		assertEquals("have both", Texts.haveText(row(2, 2).capped(2, 2)));
		// warm gloves and bruma torches stop at 3: "have both" would be wrong
		assertEquals("have all 3", Texts.haveText(row(2, 3).capped(3, 3)));
		assertTrue(row(2, 3).capped(3, 3).isComplete());
	}

	@Test
	public void theMiddleOfTheScaleIsWhiteAndTheRestKeepAColour()
	{
		assertEquals(Theme.TEXT, ExpectedDropsPanel.verdictWordColor(0.5));
		assertEquals(Theme.TEXT, ExpectedDropsPanel.verdictWordColor(0.46));
		for (double luck : new double[]{0.02, 0.2, 0.4, 0.6, 0.8, 0.97})
		{
			assertNotEquals("luck " + luck, Theme.TEXT, ExpectedDropsPanel.verdictWordColor(luck));
		}
		// no luck known: no colour claim either way
		assertNotEquals(null, ExpectedDropsPanel.verdictWordColor(Double.NaN));
	}

	@Test
	public void verdictColoursStayApartInColourBlindMode()
	{
		try
		{
			Palette.setColourBlind(true);
			// orange, grey and blue: the dry and spooned ends differ in hue as well as lightness
			java.awt.Color dry = ExpectedDropsPanel.verdictWordColor(0.02);
			java.awt.Color spooned = ExpectedDropsPanel.verdictWordColor(0.97);
			assertTrue(dry.getRed() > dry.getBlue());
			assertTrue(spooned.getBlue() > spooned.getRed());
		}
		finally
		{
			Palette.setColourBlind(false);
		}
	}

	@Test
	public void aLongVerdictWordShrinksToFitTheTileAndGrowsBack()
	{
		VerdictTile tile = new VerdictTile("UNIQUES");
		tile.set("Very spooned", java.awt.Color.GREEN, "9 / 1.2", "1 in 3 as lucky", null);
		// the tile is 104px wide at the panel's 225px (scrollbar showing), 111px at 239px
		java.awt.Font normal = Theme.verdictFont();
		tile.setSize(new Dimension(104, 80));
		tile.doLayout();
		java.awt.Font narrow = tile.getComponent(1).getFont();
		assertTrue("shrunk " + narrow.getSize2D(), narrow.getSize2D() < normal.getSize2D());
		int room = 104 - tile.getInsets().left - tile.getInsets().right;
		assertTrue(tile.getComponent(1).getFontMetrics(narrow).stringWidth("Very spooned") <= room);
		// the card's padding takes 11px: "Very spooned" is back at full size from about 114px
		tile.setSize(new Dimension(118, 80));
		tile.doLayout();
		assertEquals(normal.getSize2D(), tile.getComponent(1).getFont().getSize2D(), 0.001);
		// the longest words fit too, scrollbar showing
		for (String word : new String[]{"Extremely dry", "Extremely spooned"})
		{
			tile.set(word, java.awt.Color.GREEN, "9 / 1.2", "1 in 300 as lucky", null);
			tile.setSize(new Dimension(104, 80));
			tile.doLayout();
			javax.swing.JLabel shown = (javax.swing.JLabel) tile.getComponent(1);
			java.awt.FontMetrics fm = shown.getFontMetrics(shown.getFont());
			// every line of it fits: one line shrunk, or two at full size, never cut off
			for (String line : shown.getText().replaceAll("</?html>", "").split("<br>"))
			{
				assertTrue(word + ": " + line, fm.stringWidth(line) <= room);
			}
			assertEquals(word, shown.getText().replaceAll("</?html>", "").replace("<br>", " "));
			assertTrue(word, shown.getPreferredSize().width <= room);
		}
		// "Extremely spooned" takes two lines at full size; back to one line for a shorter word
		tile.set("Extremely spooned", java.awt.Color.GREEN, "9 / 1.2", "1 in 300 as lucky", null);
		tile.doLayout();
		assertEquals(normal.getSize2D(), tile.getComponent(1).getFont().getSize2D(), 0.001);
		tile.set("Spooned", java.awt.Color.GREEN, "9 / 1.2", "1 in 3 as lucky", null);
		tile.doLayout();
		assertEquals("Spooned", ((javax.swing.JLabel) tile.getComponent(1)).getText());
		// a short word never changes
		tile.set("Dry", java.awt.Color.ORANGE, "1 / 3", "1 in 3 as dry", null);
		tile.setSize(new Dimension(104, 80));
		tile.doLayout();
		assertEquals(normal.getSize2D(), tile.getComponent(1).getFont().getSize2D(), 0.001);
	}

	@Test
	public void aLongSmallLineWrapsInsteadOfBeingCutOff()
	{
		VerdictTile tile = new VerdictTile("UNIQUES");
		tile.set("Very dry", java.awt.Color.RED, "0 / 3.4", "only 1 in 10,000 has none", null);
		tile.setSize(new Dimension(104, 80));
		tile.doLayout();
		javax.swing.JLabel luck = (javax.swing.JLabel) tile.getComponent(3);
		assertTrue(luck.getText(), luck.getText().startsWith("<html>") && luck.getText().contains("<br>"));
		// every line fits the room the pill has (the tile's text width less the pill's own padding), and the words are all still there
		java.awt.FontMetrics fm = luck.getFontMetrics(luck.getFont());
		String[] lines = luck.getText().replace("<html>", "").replace("</html>", "").split("<br>");
		int room = 104 - tile.getInsets().left - tile.getInsets().right - 17;
		for (String line : lines)
		{
			assertTrue(line, fm.stringWidth(line) <= room);
		}
		assertEquals("only 1 in 10,000 has none", String.join(" ", lines));
		// a "<1 in ..." line keeps its less-than sign as text
		tile.set("Very dry", java.awt.Color.RED, "0 / 3.4", "<1 in 10,000 as lucky", null);
		tile.doLayout();
		assertTrue(luck.getText(), luck.getText().contains("&lt;1 in 10,000") && luck.getText().contains("lucky")
			&& !luck.getText().contains("<1"));
		// with room it is plain text again, and a short line never changes
		tile.setSize(new Dimension(300, 80));
		tile.doLayout();
		assertEquals("<1 in 10,000 as lucky", luck.getText());
		tile.set("Dry", java.awt.Color.ORANGE, "1 / 3", "1 in 3 as dry", null);
		tile.setSize(new Dimension(104, 80));
		tile.doLayout();
		assertEquals("1 in 3 as dry", luck.getText());
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.RaidInsights;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.Tracker;
import java.util.Collections;
import java.util.function.ToLongFunction;
import org.junit.Test;

/**
 * One draw of a raid page goes through the saved raids once (twice with the GP value on), however many
 * parts of the page ask: the sections, the line of facts, History's PB tags and every item's hover.
 */
public class RaidInsightsPerDrawTest
{
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new Gson());
		com.onrate.engine.data.LadlorChart.bundled(new Gson());
	}

	private static final String COX = "Chambers of Xeric";
	private long now = System.currentTimeMillis() - 100L * 3_600_000;
	private int kc;
	private final int[] calls = new int[1];

	private Tracker tracker()
	{
		Tracker tracker = new Tracker(Bundled.catalog(new Gson()))
		{
			@Override
			public synchronized RaidInsights raidInsights(String bossName, ToLongFunction<String> prices)
			{
				calls[0]++;
				return super.raidInsights(bossName, prices);
			}
		};
		tracker.setSettings(raid -> 0.035);
		tracker.onClogPage(COX, Collections.singletonList("Chambers of Xeric completions: 0"), Collections.singletonMap("Twisted bow", 0));
		for (int i = 0; i < 6; i++)
		{
			raid(tracker);
		}
		return tracker;
	}

	private void raid(Tracker tracker)
	{
		now += 3_600_000;
		tracker.onRaidRecord(RaidRecord.cox(30_000, 60_000, 2, 2), now);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>" + (++kc) + "</col>.", now + 1000);
	}

	private static ExpectedDropsPanel panel(Tracker tracker, boolean gp)
	{
		RaidSettings raids = raid -> 0.035;
		ExpectedDropsPanel panel = new ExpectedDropsPanel(tracker, null, () -> raids, s -> -1, () -> { },
			s -> 1_000_000L, () -> new ViewOptions(ItemView.TARGET_BARS, gp, false, false, false, true));
		panel.setSize(225, 6000);
		return panel;
	}

	@Test
	public void aRaidPageWorksItsInsightsOutOncePerDraw()
	{
		ExpectedDropsPanel panel = panel(tracker(), false);
		panel.showBoss(COX);
		calls[0] = 0;
		panel.refresh();
		assertTrue("the page asked for the raid's insights", calls[0] >= 1);
		assertTrue("worked out " + calls[0] + " times in one draw", calls[0] <= 1);
	}

	@Test
	public void withTheGpValueOnItIsOnceWithPricesAndOnceWithout()
	{
		ExpectedDropsPanel panel = panel(tracker(), true);
		panel.showBoss(COX);
		calls[0] = 0;
		panel.refresh();
		assertTrue("the page asked for the raid's insights", calls[0] >= 1);
		assertTrue("worked out " + calls[0] + " times in one draw", calls[0] <= 2);
	}

	@Test
	public void theNextDrawSeesANewRaid()
	{
		Tracker tracker = tracker();
		ExpectedDropsPanel panel = panel(tracker, false);
		panel.showBoss(COX);
		panel.refresh();
		raid(tracker);
		calls[0] = 0;
		panel.refresh();
		assertTrue("nothing is kept from the last draw", calls[0] >= 1);
	}
}

package com.expecteddrops.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.RaidInsights;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.Tracker;
import java.awt.Component;
import java.awt.Container;
import java.io.Reader;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

/**
 * The raid sections under History (purple chance by setup, personal bests, points over time) and
 * the PB tags in History. The pixel parity test leaves them out, so they are checked here.
 */
public class RaidSectionsTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static final String COX = "Chambers of Xeric";
	private long now = System.currentTimeMillis() - 100L * 3_600_000;
	private int kc;

	private static Tracker tracker() throws Exception
	{
		try (Reader reader = com.onrate.engine.data.Bundled.reader("bosses.json"))
		{
			Tracker tracker = new Tracker(BossCatalog.load(new Gson(), reader));
			tracker.setSettings(raid -> 0.035);
			return tracker;
		}
	}

	private static ExpectedDropsPanel panel(Tracker tracker, boolean gp) throws Exception
	{
		RaidSettings raids = raid -> 0.035;
		ExpectedDropsPanel panel = new ExpectedDropsPanel(tracker, null, () -> raids, s -> -1, () -> { },
			s -> "Twisted bow".equals(s) ? 1_000_000_000L : 0L, () -> new ViewOptions(ItemView.TARGET_BARS, gp, false, false, false, true));
		panel.setSize(225, 6000);
		return panel;
	}

	private static void set(Object target, String field, Object value) throws Exception
	{
		java.lang.reflect.Field f = target.getClass().getDeclaredField(field);
		f.setAccessible(true);
		f.set(target, value);
	}

	/** One Chambers raid with its points, team and time, then its completion message. */
	private void raid(Tracker tracker, int points, int teamPoints, int team, int minutes) throws Exception
	{
		RaidRecord r = RaidRecord.cox(points, teamPoints, team);
		set(r, "durationMillis", minutes * 60_000);
		now += 3_600_000;
		tracker.onRaidRecord(r, now);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>" + (++kc) + "</col>.", now + 1000);
	}

	private Tracker raided() throws Exception
	{
		Tracker tracker = tracker();
		java.util.Map<String, Integer> page = new java.util.LinkedHashMap<>();
		page.put("Twisted bow", 0);
		tracker.onClogPage(COX, Collections.singletonList("Chambers of Xeric completions: 0"), page);
		for (int i = 0; i < 5; i++)
		{
			raid(tracker, 43_380, 43_380, 1, 30);
			raid(tracker, 21_690, 43_380, 2, 12);
		}
		raid(tracker, 52_100, 52_100, 1, 29);
		return tracker;
	}

	private static List<String> labels(Component c)
	{
		List<String> out = new ArrayList<>();
		labels(c, out);
		return out;
	}

	private static void labels(Component c, List<String> out)
	{
		// what a player can see: the hidden one-time notice card also mentions Raid Data Tracker
		if (!c.isVisible())
		{
			return;
		}
		if (c instanceof javax.swing.JLabel && ((javax.swing.JLabel) c).getText() != null)
		{
			out.add(((javax.swing.JLabel) c).getText());
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				labels(child, out);
			}
		}
	}

	private static boolean any(List<String> labels, String part)
	{
		for (String l : labels)
		{
			if (l.contains(part))
			{
				return true;
			}
		}
		return false;
	}

	@Test
	public void theThreeSectionsAreFoldedUnderHistoryOnARaidPage() throws Exception
	{
		ExpectedDropsPanel panel = panel(raided(), true);
		panel.showBoss(COX);
		panel.refresh();
		List<String> labels = labels(panel);
		assertTrue(any(labels, "▸ PURPLE CHANCE BY SETUP"));
		assertTrue(any(labels, "▸ PERSONAL BESTS"));
		assertTrue(any(labels, "▸ POINTS OVER TIME"));
		// folded: nothing of their content yet
		assertFalse(any(labels, "FASTEST PURPLES"));
	}

	@Test
	public void setupsAreSortedByChanceAnHourWithTheTopOneTagged() throws Exception
	{
		ExpectedDropsPanel panel = panel(raided(), true);
		set(panel, "setupsOpen", true);
		panel.showBoss(COX);
		panel.refresh();
		List<String> labels = labels(panel);
		// the duo gets 12.5% an hour (2.5% a raid in 12 minutes), solo less
		assertTrue(any(labels, "Duo") && any(labels, "FASTEST PURPLES"));
		assertTrue(labels.contains("12.5%/h"));
		assertTrue(any(labels, "GP value"));

		set(panel, "setupsGp", true);
		panel.refresh();
		assertTrue(any(labels(panel), "MOST GP"));
	}

	@Test
	public void withoutGpValueThereIsNoGpTab() throws Exception
	{
		ExpectedDropsPanel panel = panel(raided(), false);
		set(panel, "setupsOpen", true);
		panel.showBoss(COX);
		panel.refresh();
		assertFalse(labels(panel).contains("GP value"));
	}

	@Test
	public void personalBestsAndThePbTagInHistory() throws Exception
	{
		ExpectedDropsPanel panel = panel(raided(), true);
		set(panel, "bestsOpen", true);
		set(panel, "historyOpen", true);
		panel.showBoss(COX);
		panel.refresh();
		List<String> labels = labels(panel);
		assertTrue(labels.contains("Fastest") && labels.contains("Most points"));
		assertTrue(labels.contains("52.1k"));
		assertTrue(labels.contains("12:00"));
		// the last raid holds the solo points record, and History says so
		assertTrue(any(labels, ">PB</font>"));
	}

	@Test
	public void pointsOverTimeDrawsTheGraph() throws Exception
	{
		ExpectedDropsPanel panel = panel(raided(), true);
		set(panel, "pointsOpen", true);
		panel.showBoss(COX);
		panel.refresh();
		assertEquals(1, count(panel, RaidPointsGraph.class));
		assertTrue(labels(panel).contains("Points"));
	}

	@Test
	public void raidsLeftForTheLogUseYourRecentRaids() throws Exception
	{
		ExpectedDropsPanel panel = panel(raided(), true);
		set(panel, "logOpen", true);
		panel.showBoss(COX);
		panel.refresh();
		List<String> labels = labels(panel);
		assertTrue(any(labels, "RAIDS LEFT FOR THE LOG"));
		assertTrue(labels.contains("Missing") && labels.contains("12 uniques + pet"));
		// the table: 50% and 90% columns, raids then hours
		assertTrue(labels.contains("50% chance") && labels.contains("90% chance"));
		assertTrue(labels.contains("All uniques") && labels.contains("With the pet"));
		assertTrue(labels.contains("  in hours"));
	}

	@Test
	public void raidsLeftForTheLogNeedTheLogPage() throws Exception
