import com.google.gson.Gson;
import java.awt.Component;
import java.awt.Container;
import java.awt.event.MouseListener;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.swing.JMenu;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import org.junit.Test;

/** The right-click menu that judges a shared item on each boss separately, and back. */
public class SplitSharedMenuTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static Tracker tracker() throws Exception
	{
		try (Reader reader = com.onrate.engine.data.Bundled.reader("bosses.json"))
		{
			Tracker tracker = new Tracker(BossCatalog.load(new Gson(), reader));
			tracker.setSettings(raid -> 0.03);
			return tracker;
		}
	}

	private static ExpectedDropsPanel panel(Tracker tracker)
	{
		RaidSettings raids = raid -> 0.03;
		ExpectedDropsPanel panel = new ExpectedDropsPanel(tracker, null, () -> raids, s -> -1, () -> { },
			s -> 1_000_000L, () -> new ViewOptions(ItemView.TARGET_BARS, true, false, false, false, true));
		panel.setSize(225, 4000);
		return panel;
	}

	private static JPopupMenu menuOf(Component c) throws Exception
	{
		for (MouseListener l : c.getMouseListeners())
		{
			if (!l.getClass().getName().startsWith("com.expecteddrops"))
			{
				continue;
			}
			for (java.lang.reflect.Field f : l.getClass().getDeclaredFields())
			{
				if (JPopupMenu.class.isAssignableFrom(f.getType()))
				{
					f.setAccessible(true);
					return (JPopupMenu) f.get(l);
				}
			}
		}
		return null;
	}

	/** The first menu entry (an item or a submenu) anywhere on the page with this text. */
	private static JMenuItem entry(Component c, String text) throws Exception
	{
		JPopupMenu menu = menuOf(c);
		if (menu != null)
		{
			for (Component e : menu.getComponents())
			{
				if (e instanceof JMenuItem && text.equals(((JMenuItem) e).getText()))
				{
					return (JMenuItem) e;
				}
			}
		}
		if (c instanceof Container)
		{
			for (Component child : ((Container) c).getComponents())
			{
				JMenuItem found = entry(child, text);
				if (found != null)
				{
					return found;
				}
			}
		}
		return null;
	}

	@Test
	public void olderCopiesGoToTheBossPickedAndCanComeBack() throws Exception
	{
		Tracker tracker = tracker();
		Map<String, Integer> items = new LinkedHashMap<>();
		items.put("Berserker ring", 2);
		items.put("Dragon axe", 3);
		tracker.onClogPage("Dagannoth Kings", Arrays.asList(
			"Dagannoth Rex kills: 436", "Dagannoth Prime kills: 10", "Dagannoth Supreme kills: 9"), items);
		tracker.onRollBaseline("Wintertodt", 200, 0);
		ExpectedDropsPanel panel = panel(tracker);
		panel.showBoss("Dagannoth Kings");
		panel.refresh();

		JMenu from = (JMenu) entry(panel, "Move all 3 older ones to");
		assertNotNull(from);
		List<String> bosses = new ArrayList<>();
		for (int i = 0; i < from.getItemCount(); i++)
		{
			bosses.add(from.getItem(i).getText());
		}
		assertEquals(Arrays.asList("Dagannoth Kings", "Wintertodt"), bosses);
		assertNotNull(entry(panel, "Split my 3 older ones between bosses..."));
		from.getItem(0).doClick();
		assertEquals("dragon axe", tracker.splitPoolOf("Dagannoth Kings", "Dragon axe"));

		// now a row of the Kings' own, with the way back on it
		panel.refresh();
		assertNull(entry(panel, "Move all 3 older ones to"));
		JMenuItem back = entry(panel, "Move it back to Shared with other bosses");
		assertNotNull(back);
		back.doClick();
		assertNull(tracker.splitPoolOf("Dagannoth Kings", "Dragon axe"));
	}

	@Test
	public void aVisageCanBeNotFromABoss() throws Exception
	{
		Tracker tracker = tracker();
		tracker.onClogPage("Vorkath", java.util.Collections.singletonList("Vorkath kills: 500"),
			java.util.Collections.singletonMap("Draconic visage", 1));
		ExpectedDropsPanel panel = panel(tracker);
		panel.showBoss("Vorkath");
		panel.refresh();
		JMenu from = (JMenu) entry(panel, "Move my older one to");
		assertNotNull(from);
		// King Black Dragon has no kills here, so only Vorkath and "not from a boss"
		assertEquals(2, from.getItemCount());
		assertEquals("Vorkath", from.getItem(0).getText());
		assertEquals("Not from a boss (other dragons and skeletal wyverns)", from.getItem(1).getText());
		from.getItem(1).doClick();
		assertEquals("draconic visage", tracker.splitPoolOf("Vorkath", "Draconic visage"));
		// split, but the one copy is no boss's: Vorkath has the row with none
		panel.refresh();
		assertNotNull(entry(panel, "Move it back to Shared with other bosses"));
	}
}

package com.expecteddrops.ui;

import com.onrate.engine.math.Poisson;

import java.util.Arrays;
import java.util.Collections;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** The words under and behind each verdict. */
public class TextsTest
{
	@Test
	public void tripCardNamesTheBossesUnit()
	{
		assertEquals("Last kill just now", Texts.tripIdle(0, 30, "kill"));
		assertEquals("Last raid just now", Texts.tripIdle(1, 120, "raid"));
		assertEquals("Last chest just now", Texts.tripIdle(1, 30, "chest"));
		assertEquals("Last delve just now", Texts.tripIdle(1, 30, "delve"));
		assertEquals("Last run just now", Texts.tripIdle(1, 30, "run"));
		assertEquals("Last roll just now", Texts.tripIdle(1, 30, "roll"));
		assertEquals("Idle 10 min \u00b7 ends in 20 min", Texts.tripIdle(10, 30, "raid"));
		assertEquals("Idle 40 min", Texts.tripIdle(40, 30, "raid"));
		assertEquals("The next kill starts a new trip. A trip also ends after 30 minutes without a kill "
			+ "(2 hours for raids, the Inferno and the Fight Caves).", Texts.tripResetTip("kill"));
		assertTrue(Texts.tripResetTip("chest").startsWith("The next chest starts a new trip."));
		assertTrue(Texts.tripResetTip("chest").contains("without a chest "));
	}

	@Test
	public void collectionLogLineSaysWhatIsLeft()
	{
		assertEquals("1 boss you killed not loaded yet", Texts.setupHeader(1, 10, 50));
		assertEquals("3 bosses you killed not loaded yet", Texts.setupHeader(3, 0, 50));
		assertEquals("Collection log: 0 of 50 pages opened", Texts.setupHeader(0, 0, 50));
		assertEquals("Collection log: 0 of 1 page opened", Texts.setupHeader(0, 0, 1));
		assertEquals("Collection log: 1 page not opened yet", Texts.setupHeader(0, 49, 50));
		assertEquals("Collection log: 18 pages not opened yet", Texts.setupHeader(0, 32, 50));
		// nothing left (or nothing to load): no line
		assertNull(Texts.setupHeader(0, 50, 50));
		assertNull(Texts.setupHeader(0, 0, 0));
	}

	@Test
	public void noneSaysHowManyHaveNone()
	{
		assertEquals("74% have none", Texts.luckShort(Poisson.shares(0, 0.30), 0));
		assertEquals("only 1 in 5 has none", Texts.luckShort(Poisson.shares(0, 1.65), 0));
		assertEquals(">99% have none", Texts.luckShort(Poisson.shares(0, 0.001), 0));
		assertEquals("74% of players have none by now, 26% have one or more", Texts.sharesLine(Poisson.shares(0, 0.30), 0));
	}

	@Test
	public void countsSayHowCommon()
	{
		// 4 of 5.67: 33% have this many or fewer
		assertEquals("1 in 3 as dry", Texts.luckShort(Poisson.shares(4, 5.67), 4));
		// 1 of 0.16: 15% have one or more
		assertEquals("1 in 7 as lucky", Texts.luckShort(Poisson.shares(1, 0.16), 1));
		// 2 of 1.65: the middle of the range
		assertEquals("about average", Texts.luckShort(Poisson.shares(2, 1.65), 2));
		assertEquals("18% of players have fewer, 15% as many, 67% more", Texts.sharesLine(Poisson.shares(4, 5.67), 4));
	}

	@Test
	public void tripRowsSayTooEarlyUnderHalfAnExpectedUnique()
	{
		assertEquals("Too early", Texts.tripVerdict(com.onrate.engine.math.Luck.of(1, 0.03), 0.03));
		assertEquals("Too early", Texts.tripVerdict(com.onrate.engine.math.Luck.of(0, 0.49), 0.49));
		assertNull(Texts.tripVerdict(Double.NaN, 0));
		assertEquals(com.onrate.engine.math.Verdict.labelOf(0.02), Texts.tripVerdict(0.02, 2.09));
		assertEquals(com.onrate.engine.math.Verdict.labelOf(0.97), Texts.tripVerdict(0.97, 0.84));
	}

	@Test
	public void tripRowTexts()
	{
		assertEquals("3 min", Texts.tripLength(3 * 60_000L));
		assertEquals("1h 22m", Texts.tripLength(82 * 60_000L));
		assertEquals("under 1 min", Texts.tripLength(20_000L));
		assertEquals("96 kills \u00b7 3 uniques", Texts.tripCounts(96, "kills", 3));
		assertEquals("240 kills \u00b7 no uniques", Texts.tripCounts(240, "kills", 0));
		assertEquals("4 raids \u00b7 1 unique", Texts.tripCounts(4, "raids", 1));
	}

	@Test
	public void valueLuckInWords()
	{
		assertEquals("1 in 6 as lucky", Texts.luckShort(0.83));
		assertEquals("1 in 3 as dry", Texts.luckShort(0.30));
		assertEquals("about average", Texts.luckShort(0.5));
		assertEquals("<1 in 10,000 as dry", Texts.luckShort(0.00001));
	}

	@Test
	public void shortLineFollowsTheVerdictBands()
	{
		// "On rate" (45% to 55%) is about average
