	public void anItemWithNoTimeStaysInTheChartWithoutOne() throws Exception
	{
		String json = "{\"items\":[{\"step\":1,\"name\":\"Beef\",\"icon\":\"Beef\",\"needs\":[{\"boss\":\"Brutus\",\"drop\":\"Beef\"}]},"
