		ItemTime seed = drop("The Gauntlet", "Crystal armour seed");
		assertEquals(3 * seed.getSecondsPerDrop(), find("Crystal body").getSeconds(), 1e-6);
		assertEquals(2 * seed.getSecondsPerDrop(), find("Crystal legs").getSeconds(), 1e-6);
		assertEquals(seed.getSecondsPerDrop(), find("Crystal helm").getSeconds(), 1e-6);
		assertEquals("3 x Crystal armour seed", find("Crystal body").getParts().get(0).getLabel());
		assertEquals("wiki rate", find("Crystal body").getSourceTag());
	}

	@Test
	public void theSeedsYouHaveGoToTheChartItemsInOrder()
	{
		// 4 seeds obtained: the body (3) and the helm (1) are covered, the legs (2) are not
		sync("The Gauntlet", 214, new String[]{}, 4);
		assertNull(find("Crystal body"));
		assertNull(find("Crystal helm"));
		assertNotNull(find("Crystal legs"));
		assertEquals(2, find("Crystal legs").getParts().get(0).getMissing());
		// 5 seeds: one seed short on the legs
		sync("The Gauntlet", 214, new String[]{}, 5);
		assertEquals(1, find("Crystal legs").getParts().get(0).getMissing());
		ItemTime seed = drop("The Gauntlet", "Crystal armour seed");
		assertEquals(seed.getSecondsPerDrop(), find("Crystal legs").getSeconds(), 1e-6);
		// 2 seeds: not even the body
		sync("The Gauntlet", 214, new String[]{}, 2);
		assertEquals(1, find("Crystal body").getParts().get(0).getMissing());
		assertEquals(1, find("Crystal helm").getParts().get(0).getMissing());
		assertEquals(2, find("Crystal legs").getParts().get(0).getMissing());
		// 6: all of it
		sync("The Gauntlet", 214, new String[]{}, 6);
		assertNull(find("Crystal body"));
		assertNull(find("Crystal helm"));
		assertNull(find("Crystal legs"));
	}

	@Test
	public void theSameDropInSeveralChartItemsIsOneGrindInTheTotal()
	{
		List<ChartTime> items = new ArrayList<>();
		for (ChartTime t : chart())
		{
			if (t.getName().startsWith("Crystal"))
			{
				items.add(t);
			}
		}
		assertEquals(3, items.size());
		ItemTime seed = drop("The Gauntlet", "Crystal armour seed");
		ChartTimes.Total total = ChartTimes.total(items);
		// six copies of one drop: 6 / p kills, not three separate waits that happen to add to the same
		assertEquals(6 * seed.getSecondsPerDrop(), total.getSeconds(), 1.0);
	}

	@Test
	public void expectedKillsForSeveralCopies()
	{
		double p = 1 / 120.0;
		assertEquals(3 / p, ChartTimes.expectedKillsForAll(new double[]{p}, new int[]{3}), 1e-3);
		assertEquals(1 / p, ChartTimes.expectedKillsForAll(new double[]{p}, new int[]{1}), 1e-9);
		// two drops, one needed twice: checked against a simulation
		double p1 = 1 / 100.0;
		double p2 = 1 / 250.0;
		double exact = ChartTimes.expectedKillsForAll(new double[]{p1, p2}, new int[]{2, 1});
		java.util.Random random = new java.util.Random(99);
		double sum = 0;
		int runs = 200_000;
		for (int r = 0; r < runs; r++)
		{
			int a = 0;
			boolean b = false;
			int kills = 0;
			while (a < 2 || !b)
			{
				kills++;
				if (random.nextDouble() < p1)
				{
					a++;
				}
				if (random.nextDouble() < p2)
				{
					b = true;
				}
			}
			sum += kills;
		}
		assertEquals(sum / runs, exact, exact * 0.01);
		// more copies of anything takes longer
		assertTrue(exact > ChartTimes.expectedKillsForAll(new double[]{p1, p2}, new int[]{1, 1}));
	}
}

package com.onrate.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

import com.onrate.engine.tracking.ChatTimes;
import org.junit.Test;

public class ChatTimesTest
{
	private static int millis(String message)
	{
		ChatTimes.Reading r = ChatTimes.read(message);
		assertNotNull(message, r);
		return r.getMillis();
	}

	@Test
	public void parsesTimes()
	{
		assertEquals(26 * 60_000 + 10_200, ChatTimes.parseMillis("26:10.20"));
		assertEquals(61_200, ChatTimes.parseMillis("1:01.2"));
		assertEquals(52_000, ChatTimes.parseMillis("0:52"));
		assertEquals(3_723_000, ChatTimes.parseMillis("1:02:03"));
		assertEquals(0, ChatTimes.parseMillis("abc"));
		assertEquals(0, ChatTimes.parseMillis("0:00"));
		assertEquals(0, ChatTimes.parseMillis(null));
	}

	@Test
	public void formatsTimes()
	{
		assertEquals("1:01.2", ChatTimes.format(61_200));
		assertEquals("26:10", ChatTimes.format(26 * 60_000 + 10_200));
		assertEquals("1:02:03", ChatTimes.format(3_723_000));
		assertEquals("0:52.0", ChatTimes.format(52_000));
		assertEquals("", ChatTimes.format(0));
	}

	@Test
	public void bossFightDuration()
	{
		assertEquals(61_200, millis("Fight duration: <col=ff0000>1:01.20</col>. Personal best: 0:55.80"));
		assertEquals(61_200, millis("Fight duration: <col=ff0000>1:01.20</col> (new personal best)"));
		assertEquals(ChatTimes.RANK_KILL, ChatTimes.read("Fight duration: 1:01.20").getRank());
	}

	@Test
	public void gauntletAndTempoross()
	{
		assertEquals(5 * 60_000 + 3_400, millis("Challenge duration: <col=ff0000>5:03.40</col>. Personal best: 4:50.00"));
		assertEquals(7 * 60_000 + 2_000, millis("Corrupted challenge duration: <col=ff0000>7:02.00</col> (new personal best)"));
		assertEquals(5 * 60_000 + 12_600, millis("Subdued in <col=ff0000>5:12.60</col>. Personal best: 4:40.20"));
	}

	@Test
	public void chambersRaid()
	{
		String message = "<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>3 players</col> Duration:</col> <col=ff0000>26:10.20</col> Personal best: </col><col=ff0000>25:00.00</col>";
		assertEquals(26 * 60_000 + 10_200, millis(message));
		assertEquals(ChatTimes.RANK_TOTAL, ChatTimes.read(message).getRank());
		assertEquals(18 * 60_000 + 59_000, millis("<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>Solo</col> Duration:</col> <col=ff0000>18:59.00</col> (new personal best)</col>"));
	}

	@Test
	public void tombsCountsOnlyTheTotalTime()
	{
		// the challenge time leaves out the rooms around the fight: not a time we keep
		assertNull(ChatTimes.read("Tombs of Amascut: Expert Mode challenge completion time: <col=ff0000>31:35.40</col>. Personal best: 24:19.80"));
		ChatTimes.Reading total = ChatTimes.read("Tombs of Amascut: Expert Mode total completion time: <col=ff0000>36:00.00</col>");
		assertEquals(36 * 60_000, total.getMillis());
		assertEquals(ChatTimes.RANK_TOTAL, total.getRank());
	}

	@Test
	public void theatreAndArchiveTotals()
	{
		ChatTimes.Reading tob = ChatTimes.read("Theatre of Blood total completion time: <col=ff0000>23:50.40</col>. Personal best: 22:12.00");
		assertEquals(23 * 60_000 + 50_400, tob.getMillis());
		assertEquals(ChatTimes.RANK_TOTAL, tob.getRank());
		ChatTimes.Reading archive = ChatTimes.read("The Fractured Archive: Total completion time: <col=ff0000>12:00.00</col>. Personal best: 11:00.00");
		assertEquals(12 * 60_000, archive.getMillis());
		assertEquals(ChatTimes.RANK_TOTAL, archive.getRank());
	}

	@Test
	public void timesOfRoomsAndWavesAreNotTheKill()
	{
		assertNull(ChatTimes.read("Wave 'The Maiden of Sugadinti' (Normal Mode) complete!<br>Duration: <col=ff0000>1:41.40</col>"));
		assertNull(ChatTimes.read("Challenge complete: Apmeken. Duration: <col=ff0000>3:04.20</col>"));
		assertNull(ChatTimes.read("Your Zulrah kill count is: <col=ff0000>309</col>."));
		assertNull(ChatTimes.read("Nothing to see here"));
		assertNull(ChatTimes.read(null));
	}
}

package com.onrate.engine;

import com.onrate.engine.tracking.ClogPage;
import com.onrate.engine.tracking.ClogPage.Item;
import com.onrate.engine.tracking.ClogPage.Problem;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Reading a collection log page from plain values, no client needed. */
public class ClogPageTest
{
	private static final int OWNED = ClogPage.OBTAINED_OPACITY;
	private static final int FADED = 175;

	private static List<Item> vorkath()
	{
		return Arrays.asList(new Item("Vorkath's head", 7, OWNED), new Item("Draconic visage", 1, OWNED),
			new Item("Skeletal visage", 0, FADED), new Item("Vorki", 1, OWNED));
	}

	@Test
	public void normalPageStripsTagsAndReadsOwnedItems()
	{
		ClogPage.Result r = ClogPage.parse("<col=ff9040>Vorkath</col>",
			Arrays.asList("<col=ffffff>Vorkath kills: <col=ff9040>350</col>"), vorkath());
		assertNull(r.getProblem());
		assertEquals("Vorkath", r.getTitle());
		assertEquals(Collections.singletonList("Vorkath kills: 350"), r.getCounters());
		assertEquals(7, (int) r.getItems().get("Vorkath's head"));
		assertEquals(1, (int) r.getItems().get("Vorki"));
		assertFalse(r.isAllFaded());
	}

	@Test
	public void fadedItemsAreNotObtained()
	{
		ClogPage.Result r = ClogPage.parse("Vorkath", Collections.emptyList(), vorkath());
		assertEquals(0, (int) r.getItems().get("Skeletal visage"));
		// the quantity of a faded item is not trusted
		ClogPage.Result faded = ClogPage.parse("Vorkath", Collections.emptyList(),
			Collections.singletonList(new Item("Vorki", 5, FADED)));
		assertEquals(0, (int) faded.getItems().get("Vorki"));
	}

	@Test
	public void stacksKeepTheirQuantityAndOwnedItemsCountAtLeastOne()
	{
		ClogPage.Result r = ClogPage.parse("Zulrah", Collections.emptyList(), Arrays.asList(
			new Item("Zulrah's scales", 250, OWNED), new Item("Tanzanite fang", 0, OWNED)));
		assertEquals(250, (int) r.getItems().get("Zulrah's scales"));
		assertEquals(1, (int) r.getItems().get("Tanzanite fang"));
	}

	@Test
	public void emptyPageHasNoItems()
	{
		assertEquals(Problem.NO_ITEMS, ClogPage.parse("Vorkath", Collections.emptyList(), new ArrayList<>()).getProblem());
		assertEquals(Problem.NO_ITEMS, ClogPage.parse("Vorkath", Collections.emptyList(), null).getProblem());
		// items without a name can't be matched either
		assertEquals(Problem.NO_ITEMS, ClogPage.parse("Vorkath", Collections.emptyList(),
			Collections.singletonList(new Item("", 1, OWNED))).getProblem());
	}

	@Test
	public void missingOrEmptyHeaderHasNoTitle()
	{
		assertEquals(Problem.NO_TITLE, ClogPage.parse(null, Collections.emptyList(), vorkath()).getProblem());
		assertEquals(Problem.NO_TITLE, ClogPage.parse("", Collections.emptyList(), vorkath()).getProblem());
		assertEquals(Problem.NO_TITLE, ClogPage.parse("<col=ff9040></col>", Collections.emptyList(), vorkath()).getProblem());
	}

	@Test
	public void aTitleThatIsACounterMeansTheHeaderChanged()
	{
		assertEquals(Problem.TITLE_IS_A_COUNTER,
			ClogPage.parse("Vorkath kills: 1,234", Collections.emptyList(), vorkath()).getProblem());
		assertEquals(Problem.TITLE_IS_A_COUNTER,
			ClogPage.parse("<col=ffffff>Vorkath kills: <col=ff9040>350</col>", Collections.emptyList(), vorkath()).getProblem());
		// a real title with no number after a colon is fine
		assertNull(ClogPage.parse("Tombs of Amascut", Collections.emptyList(), vorkath()).getProblem());
	}

	@Test
	public void combinedPageKeepsEveryCounterInOrder()
	{
		ClogPage.Result r = ClogPage.parse("Dagannoth Kings", Arrays.asList(
			"Dagannoth Rex kills: 436", "", null, "Dagannoth Prime kills: 10", "Dagannoth Supreme kills: 9"),
			Arrays.asList(new Item("Berserker ring", 2, OWNED), new Item("Seers ring", 1, FADED)));
		assertNull(r.getProblem());
		assertEquals(Arrays.asList("Dagannoth Rex kills: 436", "Dagannoth Prime kills: 10", "Dagannoth Supreme kills: 9"),
			r.getCounters());
		assertEquals(Arrays.asList("Berserker ring", "Seers ring"), new ArrayList<>(r.getItems().keySet()));
	}

	@Test
	public void allFadedOnlyWhenEveryItemIsMissing()
	{
		assertTrue(ClogPage.parse("Vorkath", Collections.emptyList(), Arrays.asList(
			new Item("Vorkath's head", 0, FADED), new Item("Vorki", 0, FADED))).isAllFaded());
		assertFalse(ClogPage.parse("Vorkath", Collections.emptyList(), vorkath()).isAllFaded());
		assertFalse(ClogPage.parse("Vorkath", Collections.emptyList(), new ArrayList<>()).isAllFaded());
	}
}

package com.onrate.engine;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.BossStats;
import com.onrate.engine.stats.RaidChance;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.HistoryRow;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.SaveData;
import com.onrate.engine.tracking.Tracker;
import com.onrate.engine.tracking.TrackerState;
import java.util.List;
import java.util.TimeZone;
import org.junit.Before;
import org.junit.Test;

/**
 * The Fractured Archive around the game update of 11 November 2026, 11:30 UTC: which raids keep the
 * chance of before it, which get the fixed chance of their team size, at the very moment of the
 * change, for every team size, in any time zone and after saving and loading.
 */
public class FracturedArchiveUpdateTest
{
	private static final String TFA = "The Fractured Archive";
	private static final long CHANGE = RaidChance.TFA_CHANGE_MILLIS;
	private static final double[] ONE_IN = {16, 16, 12.5, 10.5, 9.5, 8.5, 8, 7.5};
	/** Raids On Rate didn't count: none in these tests, so the setting's own chance never matters. */
	private static final RaidSettings RAIDS = raid -> 0;

	private Tracker tracker;
	private int around;
	private int kc;

	@Before
	public void setUp()
	{
		tracker = new Tracker(Bundled.catalog(new Gson()));
		tracker.setSettings(RAIDS);
		tracker.setTeamSizeDetector(() -> around);
	}

	private void raid(int team, long when)
	{
		around = team;
		tracker.onChatMessage("Your The Fractured Archive completion count is: <col=ff0000>" + (++kc) + "</col>.", when);
	}

	private static double before(int team)
	{
		return (1 + 0.04 * Math.max(0, team - 2)) / 14 / team;
	}

	private static double since(int team)
	{
		return 1 / ONE_IN[team - 1] / team;
	}

	/** Each raid's chance as History shows it, oldest first. */
	private double[] chances()
	{
		List<HistoryRow> history = tracker.history(TFA);
		double[] out = new double[history.size()];
		for (int i = 0; i < out.length; i++)
		{
			out[i] = history.get(out.length - 1 - i).getPurpleChance();
		}
		return out;
	}

	private double rondache()
	{
		BossStats stats = tracker.stats(TFA, RAIDS);
		return stats.getRows().stream().filter(r -> r.getLabel().equals("Rondache")).findFirst().get().getExpected();
	}

	@Test
	public void theLastMillisecondBeforeTheUpdateIsOldAndTheUpdateItselfIsNew()
	{
		raid(4, CHANGE - 1);
		raid(4, CHANGE);
		raid(4, CHANGE + 1);
		assertEquals(before(4), chances()[0], 1e-15);
		assertEquals(since(4), chances()[1], 1e-15);
		assertEquals(since(4), chances()[2], 1e-15);
		assertEquals((before(4) + 2 * since(4)) * 5 / 15, rondache(), 1e-12);
	}

	@Test
	public void everyTeamSizeHasItsOwnChanceOnEachSideOfTheUpdate()
	{
		for (int team = 1; team <= 8; team++)
		{
			raid(team, CHANGE - 3_600_000L * (9 - team));
		}
		for (int team = 1; team <= 8; team++)
		{
			raid(team, CHANGE + 3_600_000L * team);
		}
		double[] chances = chances();
		assertEquals(16, chances.length);
		for (int team = 1; team <= 8; team++)
		{
			assertEquals(team + " players before", before(team), chances[team - 1], 1e-15);
			assertEquals(team + " players since", since(team), chances[8 + team - 1], 1e-15);
		}
		// solo and duo dropped from 1 in 14 to 1 in 16; from three players up the team's chance went up
		assertTrue(since(1) < before(1));
		assertTrue(since(2) < before(2));
		for (int team = 3; team <= 8; team++)
		{
			assertTrue(team + " players", since(team) > before(team));
		}
	}

	@Test
	public void moreThanEightPlayersAroundYouCountAsEight()
	{
		raid(12, CHANGE - 60_000);
		raid(12, CHANGE + 60_000);
		List<RaidRecord> raids = tracker.raidRecords(TFA);
		assertEquals(8, raids.get(0).getTeamSize());
		assertEquals(8, raids.get(1).getTeamSize());
		assertEquals(before(8), chances()[0], 1e-15);
		assertEquals(since(8), chances()[1], 1e-15);
	}

	@Test
	public void aRaidCountsFromItsCompletionMessageWhicheverSideItsDamageShareComesOn()
	{
		around = 2;
		// completed just before the update; its damage share is read just after: still a raid from before
		tracker.onChatMessage("Your The Fractured Archive completion count is: <col=ff0000>1</col>.", CHANGE - 500);
		tracker.onRaidRecord(RaidRecord.fractured(0, 0, 420), CHANGE + 500);
		// the damage share read just before the update, the completion message just after: a raid since
		tracker.onRaidRecord(RaidRecord.fractured(0, 0, 420), CHANGE + 600_000 - 500);
		tracker.onChatMessage("Your The Fractured Archive completion count is: <col=ff0000>2</col>.", CHANGE + 600_000 + 500);
		List<RaidRecord> raids = tracker.raidRecords(TFA);
		assertEquals(2, raids.size());
		assertEquals(420, raids.get(0).getContribution(), 0);
		assertEquals(420, raids.get(1).getContribution(), 0);
		assertEquals(420 / 700.0 / 14, chances()[0], 1e-15);
		assertEquals(420 / 700.0 / 16, chances()[1], 1e-15);
	}

	@Test
	public void theTimeZoneOfTheComputerChangesNothing()
	{
		TimeZone usual = TimeZone.getDefault();
		try
		{
			// where 11:30 UTC is already the 12th, and where it is still the night of the 10th to the 11th
			for (String zone : new String[]{"Pacific/Kiritimati", "Pacific/Auckland", "Pacific/Honolulu", "UTC"})
			{
				TimeZone.setDefault(TimeZone.getTimeZone(zone));
				setUp();
				kc = 0;
				raid(3, CHANGE - 1);
				raid(3, CHANGE);
				assertEquals(zone, before(3), chances()[0], 1e-15);
				assertEquals(zone, since(3), chances()[1], 1e-15);
			}
		}
		finally
		{
			TimeZone.setDefault(usual);
		}
	}

	@Test
	public void savingAndLoadingKeepsEachRaidOnItsSideOfTheUpdate()
	{
		raid(5, CHANGE - 1);
		raid(5, CHANGE);
		Gson gson = new Gson();
		SaveData data = tracker.saveData(gson::toJson);
		Tracker loaded = new Tracker(Bundled.catalog(new Gson()));
		loaded.setSettings(RAIDS);
		loaded.setState(gson.fromJson(data.progress, TrackerState.class));
		loaded.setKills(TFA, gson.fromJson(data.kills.get(TFA), new com.google.gson.reflect.TypeToken<List<com.onrate.engine.tracking.KillEntry>>()
		{
		}.getType()));
		loaded.setRaids(TFA, gson.fromJson(data.raids.get(TFA), new com.google.gson.reflect.TypeToken<List<RaidRecord>>()
		{
		}.getType()));
		tracker = loaded;
		assertEquals(before(5), chances()[0], 1e-15);
		assertEquals(since(5), chances()[1], 1e-15);
	}

	@Test
	public void aRaidSavedWithoutADateIsFromBeforeTheUpdate()
	{
		// only a version from before raids carried their date could have saved one: long before this update
		Gson gson = new Gson();
		tracker.setState(gson.fromJson("{\"bosses\":{\"The Fractured Archive\":{\"chatKc\":{\"the fractured archive\":1}}}}", TrackerState.class));
		tracker.setKills(TFA, gson.fromJson("[{\"k\":1,\"p\":1,\"t\":1000,\"m\":\"Normal\"}]",
			new com.google.gson.reflect.TypeToken<List<com.onrate.engine.tracking.KillEntry>>()
			{
			}.getType()));
		tracker.setRaids(TFA, gson.fromJson("[{\"family\":\"fractured\",\"part\":\"Normal\",\"kc\":1,\"teamSize\":4}]",
			new com.google.gson.reflect.TypeToken<List<RaidRecord>>()
			{
			}.getType()));
		assertEquals(before(4), chances()[0], 1e-15);
	}

	@Test
	public void theSettingsChanceMovesOnlyTheRaidsSinceTheUpdateWhateverTheirTeam()
	{
		raid(1, CHANGE - 1);
		raid(6, CHANGE - 1);
		raid(1, CHANGE);
		raid(6, CHANGE);
		RaidSettings tripled = new RaidSettings()
		{
			@Override
			public double uniqueChance(String raid)
			{
				return 0;
			}

			@Override
			public double tfaBaseChance()
			{
				return 3 * RaidChance.TFA_BASE_CHANCE;
			}
		};
		BossStats stats = tracker.stats(TFA, tripled);
		double rondache = stats.getRows().stream().filter(r -> r.getLabel().equals("Rondache")).findFirst().get().getExpected();
		assertEquals((before(1) + before(6) + 3 * since(1) + 3 * since(6)) * 5 / 15, rondache, 1e-12);
	}
}

package com.onrate.engine;

import com.onrate.engine.data.Bundled;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.KillTimes;
import com.onrate.engine.stats.ItemTime;
import com.onrate.engine.stats.ItemTimes;
import com.onrate.engine.stats.RaidChance;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.Tracker;
import com.google.gson.Gson;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.junit.Before;
import org.junit.Test;

/** Average time to get each item: your own timed kills once there are enough, the estimate until then. */
public class ItemTimesTest
{
	private static final RaidSettings RAIDS = raid -> 0.03;
	private BossCatalog catalog;
	private Tracker tracker;
	private KillTimes web;
	private long now = 1_000_000;

	@Before
	public void setUp() throws Exception
	{
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			catalog = BossCatalog.load(new Gson(), reader);
		}
		web = KillTimes.bundled(new com.google.gson.Gson());
		tracker = new Tracker(catalog);
	}

	private ItemTime find(String boss, String label)
	{
		for (ItemTime t : ItemTimes.compute(tracker, web, RAIDS))
		{
			if (t.getBoss().equals(boss) && t.getLabel().equals(label))
			{
				return t;
			}
		}
		return null;
	}

	/** {@code n} Zulrah kills, each 100 seconds, an hour apart. */
	private void zulrahKills(int n, int from)
	{
		for (int i = 0; i < n; i++)
