import java.util.List;
import org.junit.Before;
import org.junit.Test;

/** Yama's oathplate shards: another way to the pieces, shown in the hovers. */
public class OathplateShardsTest
{
	private static final RaidSettings RAIDS = raid -> 0.03;
	private BossCatalog catalog;
	private Tracker tracker;

	@Before
	public void setUp() throws Exception
	{
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			catalog = BossCatalog.load(new Gson(), reader);
		}
		tracker = new Tracker(catalog);
		tracker.setSettings(RAIDS);
	}

	@Test
	public void onePieceWithShardsAgreesWithTheMathsDoneByHand()
	{
		// 450 shards are in hand after ceil(450 / 0.8075) = 558 kills: until then only the drop can give the piece,
		// so the expected kills are (1 - (1 - p)^558) / p
		double p = 1 / 600.0;
		double byHand = (1 - Math.pow(1 - p, 558)) / p;
		assertEquals(byHand, OathplateShards.expectedKills(new double[]{p}), 8);
		assertTrue(byHand > 350 && byHand < 380);
	}

	@Test
	public void shardsSaveKillsAndTheAnswerDoesNotChange()
	{
		double[] three = {1 / 600.0, 1 / 600.0, 1 / 600.0};
		double with = OathplateShards.expectedKills(three);
		double without = ChartTimes.expectedKillsForAll(three);
		assertTrue(with < without);
		assertTrue(with > 200);
		assertEquals(with, OathplateShards.expectedKills(three), 0);
		assertEquals(0, OathplateShards.expectedKills(new double[0]), 0);
		// a piece alone saves more than a piece in a set of three, in kills per piece
		assertTrue(OathplateShards.expectedKills(new double[]{1 / 600.0}) < 600);
	}

	@Test
	public void theAnswerIsRememberedPerSetOfChancesAndNeverMixedUp()
	{
		double[] one = {1 / 613.0};
		double first = OathplateShards.expectedKills(one);
		// the same chances in another array get the same answer; asking a thousand more times costs nothing
		long start = System.nanoTime();
		for (int i = 0; i < 1_000; i++)
		{
			assertEquals(first, OathplateShards.expectedKills(new double[]{1 / 613.0}), 0);
		}
		long thousand = System.nanoTime() - start;
		assertTrue("a thousand repeats took " + thousand / 1_000_000 + " ms: the simulation ran again", thousand < 2_000_000_000L);
		// other chances are another answer, in either order of asking
		double other = OathplateShards.expectedKills(new double[]{1 / 300.0});
		assertTrue(other < first);
		assertEquals(first, OathplateShards.expectedKills(one), 0);
		// changing the caller's array afterwards changes nothing that was remembered
		double[] mine = {1 / 613.0};
		OathplateShards.expectedKills(mine);
		mine[0] = 1 / 100.0;
		assertEquals(first, OathplateShards.expectedKills(new double[]{1 / 613.0}), 0);
		assertTrue(OathplateShards.expectedKills(mine) < other);
		// more sets of chances than are remembered: the oldest is worked out again, to the same answer
		for (int i = 0; i < 80; i++)
		{
			OathplateShards.expectedKills(new double[]{1 / (20.0 + i)});
		}
		assertEquals(first, OathplateShards.expectedKills(new double[]{1 / 613.0}), 0);
	}

	@Test
	public void theHoverSaysWhatShardsAre()
	{
		String text = OathplateShards.describe(new double[]{1 / 600.0, 1 / 600.0}, 360);
		assertTrue(text, text.contains("Oathplate shards"));
		assertTrue(text, text.contains("450"));
		assertTrue(text, text.contains("2,520 crushed infernal shale"));
		assertTrue(text, text.contains("83 Smithing"));
		assertTrue(text, text.contains("all 2 missing pieces"));
		assertTrue(text, text.contains(" h)") || text.contains(" min)"));
		assertTrue(OathplateShards.describe(new double[]{1 / 600.0}, 360).contains("this piece"));
		// without a time per kill only kills are given
		assertFalse(OathplateShards.describe(new double[]{1 / 600.0}, Double.NaN).contains(" h)"));
	}

	@Test
	public void theChartItemShowsTheShardRoute()
	{
		ChartTime oathplate = null;
		for (ChartTime t : ChartTimes.compute(tracker, KillTimes.bundled(new com.google.gson.Gson()), RAIDS, LadlorChart.bundled(new com.google.gson.Gson())))
		{
			if (t.getName().equals("Oathplate armour"))
			{
				oathplate = t;
			}
			else
			{
				assertNull(t.getName() + " has no second route", t.getRoute());
			}
		}
		assertNotNull(oathplate);
		assertNotNull(oathplate.getRoute());
		assertTrue(oathplate.getRoute().contains("all 3 missing pieces"));
		// the headline time is still from drops alone
		assertEquals(600 * (1 + 1 / 2.0 + 1 / 3.0) * 360, oathplate.getSeconds(), 1.0);
	}

	@Test
	public void withTwoPiecesHadItTalksOfThePieceLeft()
	{
		BossDefinition yama = catalog.byName("Yama");
		List<String> counters = new ArrayList<>();
		for (String name : yama.getKcNames())
		{
			counters.add(name + " kills: 40");
		}
		java.util.Map<String, Integer> have = new java.util.HashMap<>();
		have.put("Oathplate helm", 1);
		have.put("Oathplate chest", 1);
		tracker.onClogPage(yama.getClogPages().get(0), counters, have);
		for (ChartTime t : ChartTimes.compute(tracker, KillTimes.bundled(new com.google.gson.Gson()), RAIDS, LadlorChart.bundled(new com.google.gson.Gson())))
		{
			if (t.getName().equals("Oathplate armour"))
			{
				// it recounts for the piece left and says how many you have
				assertTrue(t.getRoute(), t.getRoute().startsWith("You have 2 of 3 pieces."));
				assertTrue(t.getRoute(), t.getRoute().contains("the piece you are missing"));
				return;
			}
		}
		throw new AssertionError("Oathplate armour should still be on the chart");
	}

	@Test
	public void yamasPiecesCarryTheHintAndNothingElseDoes()
	{
		for (ItemTime t : ItemTimes.compute(tracker, KillTimes.bundled(new com.google.gson.Gson()), RAIDS))
		{
			boolean oathplate = t.getBoss().equals("Yama") && t.getIconItem().startsWith("Oathplate ");
			if (oathplate)
			{
				assertNotNull(t.getIconItem(), t.getHint());
				assertTrue(t.getHint().contains("Oathplate shards"));
			}
			else
			{
				assertNull(t.getBoss() + " / " + t.getIconItem(), t.getHint());
			}
		}
	}

	@Test
	public void theRouteIsRecountedAsYouGetPieces()
	{
		BossDefinition yama = catalog.byName("Yama");
		List<String> counters = new ArrayList<>();
		for (String name : yama.getKcNames())
		{
			counters.add(name + " kills: 40");
		}
		double[] kills = new double[3];
		String[][] had = {{}, {"Oathplate helm"}, {"Oathplate helm", "Oathplate chest"}};
		for (int i = 0; i < had.length; i++)
		{
			Tracker t = new Tracker(catalog);
			t.setSettings(RAIDS);
			java.util.Map<String, Integer> have = new java.util.HashMap<>();
			for (String piece : had[i])
			{
				have.put(piece, 1);
			}
			t.onClogPage(yama.getClogPages().get(0), counters, have);
			for (ChartTime c : ChartTimes.compute(t, KillTimes.bundled(new com.google.gson.Gson()), RAIDS, LadlorChart.bundled(new com.google.gson.Gson())))
			{
				if (c.getName().equals("Oathplate armour"))
				{
					String route = c.getRoute();
					assertTrue(route, i == 0 ? !route.startsWith("You have") : route.startsWith("You have " + i + " of 3 pieces."));
					java.util.regex.Matcher m = java.util.regex.Pattern.compile("takes about ([\\d,]+) kills").matcher(route);
					assertTrue(route, m.find());
					kills[i] = Double.parseDouble(m.group(1).replace(",", ""));
				}
			}
		}
		// fewer pieces missing: fewer kills
		assertTrue(kills[0] > kills[1] && kills[1] > kills[2]);
	}
}

package com.onrate.engine;

import com.onrate.engine.stats.RaidChance;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

/** Raid formulas from the OSRS Wiki (Ancient chest; Chest (Tombs of Amascut)). */
public class RaidChanceTest
{
	@Test
	public void toaPetHasItsOwnLevelScaling()
	{
		// wiki: 1% per (350,000 - 700 x level); full up to 400, a third above, at most 550
		assertEquals(140_000, RaidChance.toaPetPointsPerPercent(300), 1e-9);
		assertEquals(70_000, RaidChance.toaPetPointsPerPercent(400), 1e-9);
		assertEquals(350_000 - 700 * (400 + 100 / 3.0), RaidChance.toaPetPointsPerPercent(500), 1e-6);
		assertEquals(RaidChance.toaPetPointsPerPercent(550), RaidChance.toaPetPointsPerPercent(600), 1e-9);
		// at level 400 the pet is about 1/19 of the purple chance, not 1/30
		double ratio = RaidChance.toaPet(30_000, 0, 0, 1, 400) / RaidChance.toa(30_000, 0, 0, 1, 400);
		assertEquals(3_700 / 70_000.0, ratio, 1e-9);
	}

	@Test
	public void coxIsOnePercentPer8676Points()
	{
		assertEquals(0.01, RaidChance.cox(8_676, 8_676), 1e-12);
		assertEquals(30_000 / 867_600.0, RaidChance.cox(30_000, 30_000), 1e-12);
	}

	@Test
	public void coxRollIsCappedAt570kAndRollsAgain()
	{
		assertEquals(0.657, RaidChance.coxTeamUniques(570_000), 0.0005);
		// 130,000 more points roll for a second unique
		assertEquals((570_000 + 130_000) / 867_600.0, RaidChance.coxTeamUniques(700_000), 1e-12);
		// at most six rolls
		assertEquals(RaidChance.coxTeamUniques(6 * 570_000), RaidChance.coxTeamUniques(9_000_000), 1e-12);
	}

	@Test
	public void coxShareIsYourShareOfThePoints()
	{
		assertEquals(RaidChance.coxTeamUniques(100_000) / 4, RaidChance.cox(25_000, 100_000), 1e-12);
		assertTrue(Double.isNaN(RaidChance.cox(0, 100_000)));
	}

	@Test
	public void toaScaledRaidLevel()
	{
		assertEquals(300, RaidChance.toaScaledLevel(300), 1e-12);
		assertEquals(340, RaidChance.toaScaledLevel(400), 1e-12);
		assertEquals(350, RaidChance.toaScaledLevel(430), 1e-12);
		assertEquals(360, RaidChance.toaScaledLevel(490), 1e-12);
	}

	@Test
	public void toaWikiExampleLevel400()
	{
		// "at raid level 400, the chance is 1% per 3,700 points"
		assertEquals(3_700, RaidChance.toaPointsPerPercent(400), 1e-9);
		assertEquals(0.05, RaidChance.toa(18_500, 0, 0, 1, 400), 1e-12);
	}

	@Test
	public void toaIsCappedAt55Percent()
	{
		// a solo raid can't reach the cap (64,000 points at most), a big team can
		assertTrue(RaidChance.toa(59_000, 1_500, 0, 1, 600) < 0.55);
		assertEquals(0.55, RaidChance.toaTeamChance(200_000, 600), 1e-12);
		assertEquals(0.55 / 5, RaidChance.toa(40_000, 0, 200_000, 5, 600), 1e-12);
		assertEquals(0.55, RaidChance.toa(170_000, 0, 0, 8, 600), 1e-12);
	}

	@Test
	public void toaSoloIncludesPuzzlePoints()
	{
		assertEquals(10_500 / (10_500 - 20 * 150.0) / 100, RaidChance.toa(9_000, 1_500, 0, 1, 150), 1e-12);
	}

	@Test
	public void toaTeamWithoutTotalUsesYourOwnPoints()
	{
		// below the cap, your share of the team chance is your points over the points per percent
		assertEquals(20_000 / 3_700.0 / 100, RaidChance.toa(20_000, 1_500, 0, 4, 400), 1e-12);
		assertEquals(RaidChance.toa(20_000, 0, 60_000, 4, 400), RaidChance.toa(20_000, 1_500, 0, 4, 400), 1e-12);
	}

	@Test
	public void toaUnknownPointsFallBack()
	{
		assertTrue(Double.isNaN(RaidChance.toa(0, 0, 0, 1, 300)));
		assertTrue(Double.isNaN(RaidChance.toa(10_000, 0, 0, 1, -1)));
	}

	@Test
	public void toaLowLevelItems()
	{
		assertEquals(1.0, RaidChance.toaLevelFactor(149, 50), 0);
		assertEquals(1 / 50.0, RaidChance.toaLevelFactor(149, 150), 1e-12);
		assertEquals(1.0, RaidChance.toaLevelFactor(150, 150), 0);
		assertEquals(1.0, RaidChance.toaLevelFactor(0, null), 0);
	}

	@Test
	public void fracturedArchiveTeamChanceIsFixedPerRaidSize()
	{
		// Jagex's loot scaling post of 11 November 2026: the team's chance with a full contribution
		double base = RaidChance.TFA_BASE_CHANCE;
		assertEquals(1 / 16.0, base, 0);
		double[] oneIn = {16, 16, 12.5, 10.5, 9.5, 8.5, 8, 7.5};
		for (int team = 1; team <= 8; team++)
		{
			assertEquals(team + " players", 1 / oneIn[team - 1], RaidChance.tfa(700, team, base), 1e-12);
		}
		assertEquals(1.0, RaidChance.tfaTeamMultiplier(1), 0);
		assertEquals(1.0, RaidChance.tfaTeamMultiplier(2), 0);
		assertEquals(1.28, RaidChance.tfaTeamMultiplier(3), 1e-12);
		assertEquals(2.0, RaidChance.tfaTeamMultiplier(7), 1e-12);
		// no team is bigger than eight, or smaller than one
		assertEquals(RaidChance.tfaTeamMultiplier(8), RaidChance.tfaTeamMultiplier(12), 0);
		assertEquals(1.0, RaidChance.tfaTeamMultiplier(0), 0);
		// a base chance the player changed moves every size with it
		assertEquals(2 / 12.5, RaidChance.tfa(700, 3, 2 * base), 1e-12);
	}

	@Test
	public void fracturedArchiveBeforeTheUpdateAddedFourPercentPerPlayerBeyondTwo()
	{
		// Jagex's first loot post: 3-man x1.04, 5-man x1.12, 8-man x1.24 (added, not compounded)
		assertEquals(1.0, RaidChance.tfaTeamMultiplierBefore(1), 1e-12);
		assertEquals(1.0, RaidChance.tfaTeamMultiplierBefore(2), 1e-12);
		assertEquals(1.04, RaidChance.tfaTeamMultiplierBefore(3), 1e-12);
		assertEquals(1.12, RaidChance.tfaTeamMultiplierBefore(5), 1e-12);
		assertEquals(1.24, RaidChance.tfaTeamMultiplierBefore(8), 1e-12);
		assertEquals(1.24, RaidChance.tfaTeamMultiplierBefore(12), 1e-12);
		// the wiki's 8-man team chance of that time: 8.86%
		assertEquals(0.0886, RaidChance.tfaBefore(700, 8), 0.00005);
		assertEquals(1 / 28.0, RaidChance.tfaEvenBefore(2, 0), 1e-12);
		assertEquals(1 / 14.0, RaidChance.tfaEvenBefore(1, 0), 1e-12);
		assertEquals(0.3 / 14, RaidChance.tfaBefore(0.3 * 700, 2), 1e-12);
		assertEquals(1.08 / 14 / 4, RaidChance.tfaEvenBefore(4, 0), 1e-12);
		assertEquals(315 / 700.0 / 14, RaidChance.tfaEvenBefore(2, 1), 1e-12);
		assertTrue(Double.isNaN(RaidChance.tfaBefore(-1, 2)));
	}

	@Test
	public void fracturedArchiveUpdateWentLiveOnTheEleventhOfNovember2026()
	{
		assertEquals(java.time.Instant.parse("2026-11-11T11:30:00Z").toEpochMilli(), RaidChance.TFA_CHANGE_MILLIS);
		assertTrue(RaidChance.tfaBeforeChange(RaidChance.TFA_CHANGE_MILLIS - 1));
		assertFalse(RaidChance.tfaBeforeChange(RaidChance.TFA_CHANGE_MILLIS));
		// a raid saved without a date can only be from an older version
		assertTrue(RaidChance.tfaBeforeChange(0));
	}

	@Test
	public void fracturedArchiveSplitsTheUniqueByContribution()
	{
		double base = RaidChance.TFA_BASE_CHANCE;
		// a duo with even damage: 1 in 16 for the team, half each
		assertEquals(1 / 32.0, RaidChance.tfaEven(2, 0, base), 1e-12);
		assertEquals(1 / 16.0, RaidChance.tfaEven(1, 0, base), 1e-12);
		// 30% of the contribution is 30% of the team's purples
		assertEquals(0.3 / 16, RaidChance.tfa(0.3 * 700, 2, base), 1e-12);
		// a four with even damage: 1 in 10.5 for the team, a quarter each
		assertEquals(1 / 10.5 / 4, RaidChance.tfaEven(4, 0, base), 1e-12);
		assertTrue(Double.isNaN(RaidChance.tfa(-1, 2, base)));
		assertEquals(base, RaidChance.tfa(900, 2, base), 1e-12);
	}

	@Test
	public void fracturedArchiveDeathTakesTenPercentOfExpectedContribution()
	{
		// "In a duo, your expected contribution is 350 out of 700, so a death would subtract 35"
		assertEquals(350, RaidChance.tfaExpectedContribution(2), 1e-12);
		assertEquals(315, RaidChance.tfaContributionAfterDeaths(350, 2, 1), 1e-12);
		// the same 35 whoever carried more damage
		assertEquals(565, RaidChance.tfaContributionAfterDeaths(600, 2, 1), 1e-12);
		assertEquals(0, RaidChance.tfaContributionAfterDeaths(20, 2, 1), 1e-12);
		// unknown deaths count as none
		assertEquals(350, RaidChance.tfaContributionAfterDeaths(350, 2, -1), 1e-12);
		assertEquals(315 / 700.0 / 16, RaidChance.tfaEven(2, 1, RaidChance.TFA_BASE_CHANCE), 1e-12);
	}
}

