		// then 1 solo + 20 kills at a quarter each
		assertEquals((99 + 1 + 20 / 4.0) / 172.0, row(s, "Zaryte vambraces").getExpected(), 1e-9);
		// the pet doesn't scale with the team
		assertEquals(120 / 500.0, row(s, "Nexling").getExpected(), 1e-9);

