		// a part is needed on a combined page, and the count is limited to that part's own
		assertFalse(tracker.addPastDrop("Chambers of Xeric", "Twisted bow", 115));
		assertFalse(tracker.addPastDrop("Chambers of Xeric", "Twisted bow", 21, false, "Challenge Mode"));
		assertFalse(tracker.addPastDrop("Chambers of Xeric", "Twisted bow", 5, false, "Nope"));
		assertTrue(tracker.addPastDrop("Chambers of Xeric", "Twisted bow", 115, false, "Normal"));
		KillEntry kill = tracker.history("Chambers of Xeric").get(0).getKill();
		assertEquals("Normal", kill.getPart());
		assertEquals(115, (int) kill.getPartKc());
		assertTrue(kill.getDrops().get(0).isFirst());
		assertNull(tracker.pastDropNotRankedReason("Chambers of Xeric", "Twisted bow", 115, "Normal"));
		assertEquals(1, tracker.dropsByLuck(true, 5).size());
		// the page's dry streak is left alone
		assertFalse(row(tracker.stats("Chambers of Xeric", RAIDS), "Twisted bow").isStreakExact());
		// again at the same count replaces it
		assertTrue(tracker.addPastDrop("Chambers of Xeric", "Twisted bow", 115, true, "Normal"));
		assertEquals(1, tracker.history("Chambers of Xeric").size());
	}

	@Test
	public void aPartWithUnknownKillsCanStillBePicked()
	{
		tracker.setSettings(RAIDS);
		Map<String, Integer> page = new LinkedHashMap<>();
		page.put("Skull of vet'ion", 1);
		tracker.onClogPage("Vet'ion and Calvar'ion", Collections.singletonList("Vet'ion kills: 300"), page);
		assertEquals(Arrays.asList("Vet'ion", "Calvar'ion"), tracker.pastDropParts("Vet'ion and Calvar'ion", "Skull of vet'ion"));
		assertEquals(300, tracker.pastDropLimit("Vet'ion and Calvar'ion", "Vet'ion"));
		assertEquals(Tracker.UNKNOWN_PART_LIMIT, tracker.pastDropLimit("Vet'ion and Calvar'ion", "Calvar'ion"));
		assertTrue(tracker.addPastDrop("Vet'ion and Calvar'ion", "Skull of vet'ion", 40, false, "Calvar'ion"));
		assertEquals("Calvar'ion", tracker.history("Vet'ion and Calvar'ion").get(0).getKill().getPart());
	}

	@Test
	public void aHandAddedDropIsRefusedBeyondTheCopiesAndUndoneOnRemoval()
	{
		Map<String, Integer> page = new LinkedHashMap<>();
		page.put("Steel ring", 1);
		tracker.onClogPage("Deranged Archaeologist", Collections.singletonList("Deranged Archaeologist kills: 100"), page);
		assertTrue(tracker.addPastDrop("Deranged Archaeologist", "Steel ring", 30));
		// one copy in the log and one entry added by hand: the new count corrects it, History still lists one
		assertTrue(tracker.addPastDrop("Deranged Archaeologist", "Steel ring", 50));
		assertEquals(1, savedUniques("Deranged Archaeologist").size());
		assertEquals(50, ((KillEntry) savedUniques("Deranged Archaeologist").get(0)[0]).getKc());
		assertEquals(50, (int) row(tracker.stats("Deranged Archaeologist", RAIDS), "Steel ring").getStreak());
		// adding it at the same count again replaces it
		assertTrue(tracker.addPastDrop("Deranged Archaeologist", "Steel ring", 50, true));
		assertEquals(1, savedUniques("Deranged Archaeologist").size());
		// removing it from History also takes back the dry streak it set
		Object[] saved = savedUniques("Deranged Archaeologist").get(0);
		assertTrue(tracker.removeFromHistory("Deranged Archaeologist", (KillEntry) saved[0], (KillEntry.DropEntry) saved[1]));
		assertFalse(row(tracker.stats("Deranged Archaeologist", RAIDS), "Steel ring").isStreakExact());
		// and it can be entered again at a corrected count
		assertTrue(tracker.addPastDrop("Deranged Archaeologist", "Steel ring", 60));
		assertEquals(40, (int) row(tracker.stats("Deranged Archaeologist", RAIDS), "Steel ring").getStreak());
	}

	@Test
	public void aHandAddedDropIsRefusedWhenSeveralEntriesAlreadyFillTheCopies()
	{
		Map<String, Integer> page = new LinkedHashMap<>();
		page.put("Steel ring", 2);
		tracker.onClogPage("Deranged Archaeologist", Collections.singletonList("Deranged Archaeologist kills: 100"), page);
		assertTrue(tracker.addPastDrop("Deranged Archaeologist", "Steel ring", 30));
		assertTrue(tracker.addPastDrop("Deranged Archaeologist", "Steel ring", 50));
		// two copies, two entries: which one a third replaces isn't clear, so nothing changes
		assertFalse(tracker.addPastDrop("Deranged Archaeologist", "Steel ring", 70));
		assertEquals(2, savedUniques("Deranged Archaeologist").size());
	}

	@Test
	public void aRaidWaitUsesThePointsForCountedRaidsAndTheSettingForOlderOnes()
	{
		tracker.setSettings(RAIDS);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>100</col>.", now - 1_800_000);
		// raid 101: 43,380 points solo = 5%; raid 102: 8,676 of 17,352 team points = 1%
		tracker.onRaidRecord(RaidRecord.cox(43_380, 43_380, 1), now + 1000);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>101</col>.", now + 2000);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>102</col>.", now + 600_000);
		tracker.onRaidRecord(RaidRecord.cox(8_676, 17_352, 2), now + 601_000);

		// the first one came before On Rate counted points: 100 raids at the setting's 3.5%, twisted bow 2/60 of a purple
		assertTrue(tracker.addPastDrop("Chambers of Xeric", "Twisted bow", 100, true, "Normal"));
		KillEntry.DropEntry first = (KillEntry.DropEntry) savedUniques("Chambers of Xeric").stream()
			.filter(o -> ((KillEntry) o[0]).getPartKc() == 100).findFirst().get()[1];
		assertEquals(100 * 0.035 * 2 / 60, first.getMultiple(), 0.0005);
		// the second one: raids 101 and 102 count at 5% and 1% from their points, not 3.5% each
		assertTrue(tracker.addPastDrop("Chambers of Xeric", "Twisted bow", 102, false, "Normal"));
		KillEntry.DropEntry second = (KillEntry.DropEntry) savedUniques("Chambers of Xeric").stream()
			.filter(o -> ((KillEntry) o[0]).getPartKc() == 102 && ((KillEntry.DropEntry) o[1]).isEntered()).findFirst().get()[1];
		assertEquals((0.05 + 0.01) * 2 / 60, second.getMultiple(), 0.00005);
	}

	@Test
	public void aSingleHandAddedEntryIsCorrectedWhenHistoryHoldsAllTheCopies()
	{
		tracker.setSettings(RAIDS);
		Map<String, Integer> page = new LinkedHashMap<>();
		page.put("Osmumten's fang", 1);
		tracker.onClogPage("Tombs of Amascut", Arrays.asList("Tombs of Amascut: Entry Mode kills: 10",
			"Tombs of Amascut kills: 250", "Tombs of Amascut: Expert Mode kills: 120"), page);
		// saved wrongly at count 1 (the typed number wasn't read), in the wrong mode
		assertTrue(tracker.addPastDrop("Tombs of Amascut", "Osmumten's fang", 1, true, "Entry Mode"));
		// the corrected entry replaces it instead of being refused
		assertTrue(tracker.addPastDrop("Tombs of Amascut", "Osmumten's fang", 200, true, "Normal"));
		List<Object[]> saved = savedUniques("Tombs of Amascut");
		assertEquals(1, saved.size());
		assertEquals("Normal", ((KillEntry) saved.get(0)[0]).getPart());
		assertEquals(200, (int) ((KillEntry) saved.get(0)[0]).getPartKc());
		// the emptied entry is gone, not left behind as a kill
		assertEquals(1, tracker.history("Tombs of Amascut").size());
	}
}

package com.onrate.engine;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.tracking.TripStats;
import com.onrate.engine.tracking.Tracker;
import java.io.Reader;
import java.util.List;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

/** The finished trips the Recent tab lists: when a trip counts as finished, the cap, and what clears them. */
public class TripListTest
{
	private static final long MIN = 60_000L;
	private Tracker tracker;
	private final long start = 1_000_000;

	@Before
	public void setUp() throws Exception
	{
		BossCatalog catalog;
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			catalog = BossCatalog.load(new Gson(), reader);
		}
		tracker = new Tracker(catalog);
		tracker.setSettings(raid -> 0.0);
	}

	/** Kills kc .. kc + count - 1 of the boss, a minute apart from {@code at}; returns the time of the last one. */
	private long kills(String boss, int kc, int count, long at)
	{
		long t = at;
		for (int i = 0; i < count; i++)
		{
			t = at + i * MIN;
			tracker.onChatMessage("Your " + boss + " kill count is: <col=ff0000>" + (kc + i) + "</col>.", t);
		}
		return t;
	}

	@Test
	public void anotherBossEndsTheTripAndItIsListedOnce()
	{
		long last = kills("Vorkath", 100, 5, start);
		assertTrue(tracker.recentTrips(last).isEmpty());
		TripStats live = tracker.tripStats();
		assertNotNull(live);
		kills("Zulrah", 50, 1, last + 5 * MIN);
		List<TripStats> list = tracker.recentTrips(last + 6 * MIN);
		assertEquals(1, list.size());
		assertEquals("Vorkath", list.get(0).getBoss());
		// the numbers are the trip's own, not one kill longer
		assertEquals(live.getKills(), list.get(0).getKills());
		assertEquals(live.getExpected(), list.get(0).getExpected(), 1e-9);
		// more kills elsewhere do not list it again
		kills("Zulrah", 51, 3, last + 7 * MIN);
		assertEquals(1, tracker.recentTrips(last + 20 * MIN).stream().filter(t -> t.getBoss().equals("Vorkath")).count());
	}

	@Test
	public void theIdleLimitIsInclusive()
	{
		long last = kills("Vorkath", 100, 4, start);
		// exactly 30 minutes later the trip goes on
		kills("Vorkath", 104, 1, last + 30 * MIN);
		assertTrue(tracker.recentTrips(last + 30 * MIN).isEmpty());
		long again = last + 30 * MIN;
		// one minute over the limit ends it
		kills("Vorkath", 105, 1, again + 31 * MIN);
		List<TripStats> list = tracker.recentTrips(again + 31 * MIN);
		assertEquals(1, list.size());
		assertEquals("Vorkath", list.get(0).getBoss());
	}

	@Test
	public void anIdleTripIsListedWithoutWaitingForTheNextKill()
	{
		long last = kills("Vorkath", 100, 4, start);
		assertTrue(tracker.recentTrips(last + 30 * MIN).isEmpty());
		assertEquals(1, tracker.recentTrips(last + 31 * MIN).size());
		// the next kill then archives that same trip: still once
		kills("Vorkath", 104, 1, last + 40 * MIN);
		assertEquals(1, tracker.recentTrips(last + 41 * MIN).size());
	}

	@Test
	public void theNewTripButtonListsTheTripOnce()
	{
		long last = kills("Vorkath", 100, 4, start);
		tracker.resetTrip();
		assertEquals(1, tracker.recentTrips(last).size());
		tracker.resetTrip();
		kills("Vorkath", 104, 1, last + MIN);
		assertEquals(1, tracker.recentTrips(last + MIN).size());
	}

	@Test
	public void veryShortTripsAreNotListed()
	{
		long last = kills("Vorkath", 100, 2, start);
		kills("Zulrah", 50, 1, last + MIN);
		assertTrue(tracker.recentTrips(last + 2 * MIN).isEmpty());
	}

	@Test
	public void keepsTheLastFiveNewestFirst()
	{
		long t = start;
		int vorkath = 100;
		int zulrah = 50;
		for (int i = 0; i < 7; i++)
		{
			if (i % 2 == 0)
			{
				t = kills("Vorkath", vorkath, 3, t) + MIN;
				vorkath += 3;
			}
			else
			{
				t = kills("Zulrah", zulrah, 3, t) + MIN;
				zulrah += 3;
			}
		}
		// seven trips were started; six are finished, the seventh (Vorkath) is still going
		List<TripStats> list = tracker.recentTrips(t);
		assertEquals(5, list.size());
		assertEquals("Zulrah", list.get(0).getBoss());
		assertEquals("Vorkath", list.get(1).getBoss());
	}

	@Test
	public void resettingABossDropsItsTrips()
	{
		long last = kills("Vorkath", 100, 4, start);
		last = kills("Zulrah", 50, 4, last + MIN);
		kills("Vorkath", 104, 1, last + MIN);
		assertEquals(2, tracker.recentTrips(last + MIN).size());
		tracker.reset("Vorkath");
		List<TripStats> list = tracker.recentTrips(last + MIN);
		assertEquals(1, list.size());
		assertEquals("Zulrah", list.get(0).getBoss());
	}

	@Test
	public void switchingAccountsClearsTheList()
	{
		long last = kills("Vorkath", 100, 4, start);
		kills("Zulrah", 50, 1, last + MIN);
		assertEquals(1, tracker.recentTrips(last + MIN).size());
		tracker.setState(null);
		assertTrue(tracker.recentTrips(last + 2 * MIN).isEmpty());
		assertTrue(tracker.recentTrips(last + 500 * MIN).isEmpty());
	}
}

package com.onrate.engine;

import static org.junit.Assert.assertEquals;
