package com.onrate.engine.stats;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.KillTimes;
import com.onrate.engine.tracking.Tracker;
import java.io.Reader;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

/** How long a collection log page takes: the missing items as one forecast, at the time of a kill the Time page uses. */
public class GreenLogTest
{
	private static final RaidSettings RAIDS = raid -> 0.03;
	private Tracker tracker;
	private KillTimes web;

	@Before
	public void setUp() throws Exception
	{
		BossCatalog catalog;
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			catalog = BossCatalog.load(new Gson(), reader);
		}
		web = KillTimes.bundled(new Gson());
		tracker = new Tracker(catalog);
	}

	@Test
	public void nothingMissingIsDoneAtOnce()
	{
		assertEquals(0, GreenLog.seconds(new double[0], GreenLog.MEDIAN, 100), 0);
	}

	@Test
	public void secondsAreKillsTimesTheTimeOfAKill()
	{
		double[] p = {0.01};
		// 1 in 100: half of players have it by 69 kills, 9 in 10 by 230
		assertEquals(69 * 100.0, GreenLog.seconds(p, GreenLog.MEDIAN, 100), 1e-9);
		assertEquals(230 * 100.0, GreenLog.seconds(p, GreenLog.LIKELY, 100), 1e-9);
	}

	@Test
	public void theAverageIsTheTimePageFigureAndHigherThanTheMedian()
	{
		// one item at 1 in 100 and 100 s a kill: the Time page says 100 x 100 s; half of players are done sooner (69 kills)
		assertEquals(100 * 100.0, GreenLog.averageSeconds(new double[]{0.01}, 100), 1e-6);
		assertTrue(GreenLog.averageSeconds(new double[]{0.01}, 100) > GreenLog.seconds(new double[]{0.01}, GreenLog.MEDIAN, 100));
		// several items: the figure Ladlor's chart uses for the drops at one boss
		double[] p = {1 / 250.0, 1 / 375.0, 1 / 500.0};
		assertEquals(ChartTimes.expectedKillsForAll(p) * 60, GreenLog.averageSeconds(p, 60), 1e-6);
	}

	@Test
	public void aBigPageIsSummedAndCloseToTheExactFigure()
	{
		// 14 items is past the exact formula: the sum must land on it where both can work (12 items)
		double[] twelve = new double[12];
		double[] fourteen = new double[14];
		for (int i = 0; i < 14; i++)
		{
			double p = 1 / (200.0 + 40 * i);
			fourteen[i] = p;
			if (i < 12)
			{
				twelve[i] = p;
			}
		}
		double exact = ChartTimes.expectedKillsForAll(twelve);
		// the same sum used for a big page, on the 12 items: temporarily as the long path via 13 equal copies is not needed;
		// here the 14-item answer just has to be above the 12-item one and finite
		double big = GreenLog.averageSeconds(fourteen, 1);
		assertTrue(big > exact);
		assertFalse(Double.isNaN(big));
		assertFalse(Double.isInfinite(big));
	}

	@Test
	public void noTimeOrNoChanceGivesNoAnswer()
	{
		assertTrue(Double.isNaN(GreenLog.seconds(new double[]{0.01}, GreenLog.MEDIAN, Double.NaN)));
		assertTrue(Double.isNaN(GreenLog.seconds(new double[]{0.01, 0}, GreenLog.MEDIAN, 100)));
	}

	@Test
	public void aBossWithNoKillsUsesTheWikiTime()
	{
		GreenLog.Page zulrah = GreenLog.compute(tracker, web, RAIDS, boss -> true, false).get("Zulrah");
		assertNotNull(zulrah);
		assertTrue(zulrah.isEstimated());
		// 20 an hour is 180 s a kill (see ItemTimesTest)
		assertEquals(180.0, zulrah.getSecondsPerKill(), 1e-9);
		assertFalse(zulrah.isDone());
		assertTrue(zulrah.getMedianSeconds() > 0);
		assertTrue(zulrah.getAverageSeconds() > zulrah.getMedianSeconds());
		// 9 in 10 take longer than half
		assertTrue(zulrah.getLikelySeconds() > zulrah.getMedianSeconds());
	}

	@Test
	public void petsOffLeavesThePetOutAndMakesThePageShorter()
	{
		GreenLog.Page without = GreenLog.compute(tracker, web, RAIDS, boss -> true, false).get("Zulrah");
		GreenLog.Page with = GreenLog.compute(tracker, web, RAIDS, boss -> true, true).get("Zulrah");
		assertTrue(without.isPetLeftOut());
		assertFalse(with.isPetLeftOut());
		assertEquals(without.getMissing().size() + 1, with.getMissing().size());
		assertTrue(with.getMedianSeconds() > without.getMedianSeconds());
	}

	@Test
	public void bossesTheCallerDoesntAllowAreLeftOut()
	{
		Map<String, GreenLog.Page> pages = GreenLog.compute(tracker, web, RAIDS, boss -> !"Zulrah".equals(boss), false);
		assertFalse(pages.containsKey("Zulrah"));
		assertFalse(pages.isEmpty());
	}
}

package com.onrate.engine.stats;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.util.Random;
import org.junit.Test;

public class LogForecastTest
{
	@Test
	public void oneItemIsItsOwnDropRate()
	{
		// 1 in 100: half of players have it by 69 raids, 9 in 10 by 230
		double[] p = {0.01};
		assertEquals(69, LogForecast.raidsFor(p, 0.5));
		assertEquals(230, LogForecast.raidsFor(p, 0.9));
	}

	@Test
	public void nothingMissingIsDone()
	{
		assertEquals(0, LogForecast.raidsFor(new double[0], 0.9));
	}

	@Test
	public void anItemThatCantDropNeverFinishes()
	{
		assertEquals(LogForecast.NEVER, LogForecast.raidsFor(new double[]{0.01, 0}, 0.5));
	}

	@Test
	public void moreItemsTakeLonger()
	{
		long one = LogForecast.raidsFor(new double[]{0.01}, 0.5);
		long two = LogForecast.raidsFor(new double[]{0.01, 0.01}, 0.5);
		assertTrue(two > one);
		assertTrue(LogForecast.chanceDone(new double[]{0.01, 0.01}, two) >= 0.5);
		assertTrue(LogForecast.chanceDone(new double[]{0.01, 0.01}, two - 1) < 0.5);
	}

	@Test
	public void matchesSimulatedRaids()
	{
		// a Chambers log at 5% a raid: weights out of 60 for a few uniques still missing
		double[] p = {0.05 * 2 / 60, 0.05 * 2 / 60, 0.05 * 4 / 60, 0.05 * 14 / 60};
		long half = LogForecast.raidsFor(p, 0.5);
		Random random = new Random(42);
		int players = 4000;
		int doneByHalf = 0;
		for (int i = 0; i < players; i++)
		{
			boolean[] got = new boolean[p.length];
			int left = p.length;
			for (long raid = 1; raid <= half && left > 0; raid++)
			{
				// at most one purple a raid, and it is one of the items by its weight
				double roll = random.nextDouble();
				double edge = 0;
				for (int k = 0; k < p.length; k++)
				{
					edge += p[k];
					if (roll < edge)
					{
						if (!got[k])
						{
							got[k] = true;
							left--;
						}
						break;
					}
				}
			}
			if (left == 0)
			{
				doneByHalf++;
			}
		}
		// within a few percent of half
		assertEquals(0.5, doneByHalf / (double) players, 0.04);
	}

	@Test
	public void severalItemsAtDifferentChances()
	{
		// Grotesque Guardians: gloves 1/250, hammer 1/375, core 1/500 (each item is its own roll, chances multiply)
		double[] p = {1 / 250.0, 1 / 375.0, 1 / 500.0};
		assertEquals(592, LogForecast.raidsFor(p, 0.5));
		assertEquals(1334, LogForecast.raidsFor(p, 0.9));
		// with the 1/3000 pet
		double[] withPet = {1 / 250.0, 1 / 375.0, 1 / 500.0, 1 / 3000.0};
		assertEquals(2133, LogForecast.raidsFor(withPet, 0.5));
		assertEquals(6907, LogForecast.raidsFor(withPet, 0.9));
	}
}

package com.onrate.engine.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.RaidChance;
import java.io.Reader;
import org.junit.Before;
import org.junit.Test;

public class RaidHabitsTest
{
	private Tracker tracker;
	private long now = 10_000_000;
	private int coxKc;
	private int tobKc;

	@Before
	public void setUp() throws Exception
	{
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			tracker = new Tracker(BossCatalog.load(new Gson(), reader));
		}
		tracker.setSettings(raid -> 0.03);
	}

	private void cox(int points, int teamPoints)
	{
		now += 3_600_000;
		tracker.onRaidRecord(RaidRecord.cox(points, teamPoints, 3), now);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>" + (++coxKc) + "</col>.", now + 1000);
	}

	private void tob(int team)
	{
		now += 3_600_000;
		tracker.onRaidRecord(RaidRecord.tob(team, 0, 0, false), now);
		tracker.onChatMessage("Your completed Theatre of Blood count is: <col=ff0000>" + (++tobKc) + "</col>.", now + 1000);
	}

	@Test
	public void noRaidsKeepsTheSettings()
	{
		RaidHabits h = tracker.raidHabits();
		assertSame(RaidHabits.none(), h);
		assertTrue(Double.isNaN(h.chance("cox")));
		assertEquals(0, h.teamSize("tob"));
		assertEquals(0, h.raids("cox"));
	}

	@Test
	public void needsTenRaidsBeforeAnAverage()
	{
		for (int i = 0; i < RaidHabits.MIN_RAIDS - 1; i++)
		{
			cox(30_000, 90_000);
		}
		assertTrue(Double.isNaN(tracker.raidHabits().chance("cox")));
		cox(30_000, 90_000);
		assertEquals(RaidChance.cox(30_000, 90_000), tracker.raidHabits().chance("cox"), 1e-12);
		assertEquals(RaidHabits.MIN_RAIDS, tracker.raidHabits().raids("cox"));
		// a Challenge Mode average needs its own raids
		assertTrue(Double.isNaN(tracker.raidHabits().chance("coxCm")));
	}

	@Test
	public void averagesOnlyTheLatestRaids()
	{
		for (int i = 0; i < RaidHabits.RECENT; i++)
		{
			cox(10_000, 30_000);
		}
		for (int i = 0; i < RaidHabits.RECENT; i++)
		{
			cox(40_000, 120_000);
		}
		assertEquals(RaidChance.cox(40_000, 120_000), tracker.raidHabits().chance("cox"), 1e-12);
		assertEquals(RaidHabits.RECENT, tracker.raidHabits().raids("cox"));
	}

	@Test
	public void theatreLearnsTheUsualTeam()
	{
		for (int i = 0; i < 6; i++)
		{
			tob(3);
		}
		for (int i = 0; i < 4; i++)
		{
			tob(5);
		}
		assertEquals(3, tracker.raidHabits().teamSize("tob"));
		assertTrue(Double.isNaN(tracker.raidHabits().chance("tob")));
	}
}

package com.onrate.engine.tracking;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.RaidSettings;
import java.io.Reader;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.junit.Before;
import org.junit.Test;

public class RaidInsightsTest
{
	private static final Map<String, Double> CHANCES = new HashMap<>();
	static
	{
		CHANCES.put("cox", 0.035);
		CHANCES.put("coxCm", 0.05);
		CHANCES.put("tob", 0.11);
		CHANCES.put("toa", 0.025);
	}
	private static final RaidSettings RAIDS = raid -> CHANCES.getOrDefault(raid, 0.0);
	private static final String COX = "Chambers of Xeric";
	private static final String TOA = "Tombs of Amascut";

	private Tracker tracker;
	private long now = 10_000_000;
	private int coxKc;
	private int cmKc;
	private int toaKc;

	@Before
	public void setUp() throws Exception
	{
		try (Reader reader = Bundled.reader("bosses.json"))
		{
			tracker = new Tracker(BossCatalog.load(new Gson(), reader));
		}
		tracker.setSettings(RAIDS);
	}

	/** One Chambers raid: its points, then the completion message, like the game sends them. */
	private RaidRecord cox(int points, int teamPoints, int team, int minutes)
	{
		RaidRecord r = RaidRecord.cox(points, teamPoints, team);
		r.durationMillis = minutes < 0 ? -1 : minutes * 60_000;
		now += 3_600_000;
		tracker.onRaidRecord(r, now);
		tracker.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>" + (++coxKc) + "</col>.", now + 1000);
		return r;
	}

	private RaidRecord cm(int points, int minutes)
	{
		RaidRecord r = RaidRecord.cox(points, points, 1);
		r.durationMillis = minutes * 60_000;
		now += 3_600_000;
		tracker.onRaidRecord(r, now);
		tracker.onChatMessage("Your completed Chambers of Xeric Challenge Mode count is: <col=ff0000>" + (++cmKc) + "</col>.", now + 1000);
		return r;
	}

	private RaidRecord toa(int points, int team, int level, int minutes)
	{
		RaidRecord r = RaidRecord.toaExact(points, team, level);
		r.durationMillis = minutes * 60_000;
		now += 3_600_000;
		tracker.onRaidRecord(r, now);
		tracker.onChatMessage("Your completed Tombs of Amascut count is: <col=ff0000>" + (++toaKc) + "</col>.", now + 1000);
		return r;
	}

	@Test
	public void setupsAreGroupedByModeAndTeamAndSortedByChanceAnHour()
	{
		for (int i = 0; i < 5; i++)
		{
			// 43,380 points solo is 5% a raid; at 30 minutes, 10% an hour
			cox(43_380, 43_380, 1, 30);
			// half of 43,380 team points in a duo is 2.5% a raid; at 12 minutes, 12.5% an hour
			cox(21_690, 43_380, 2, 12);
		}
		cm(43_380, 50);
		cm(43_380, 50);

		List<RaidInsights.Setup> setups = tracker.raidInsights(COX, null).getSetups();
		assertEquals(3, setups.size());
		RaidInsights.Setup duo = setups.get(0);
		assertEquals("Normal", duo.getPart());
		assertEquals(2, duo.getTeam());
		assertEquals(-1, duo.getLevelFrom());
		assertEquals(5, duo.getRaids());
		assertTrue(duo.isEnough());
		assertEquals(0.025, duo.getChancePerRaid(), 1e-9);
		assertEquals(12 * 60_000, duo.getAverageMillis());
		assertEquals(0.125, duo.getChancePerHour(), 1e-9);
		RaidInsights.Setup solo = setups.get(1);
		assertEquals(1, solo.getTeam());
		assertEquals(0.10, solo.getChancePerHour(), 1e-9);
		// two timed Challenge Mode raids aren't enough yet, so they come last
		RaidInsights.Setup challenge = setups.get(2);
		assertEquals("Challenge Mode", challenge.getPart());
		assertEquals(2, challenge.getTimed());
		assertFalse(challenge.isEnough());
	}

	@Test
	public void eachItemHasItsChanceARaidAndAnHourPerSetup()
	{
		for (int i = 0; i < 5; i++)
		{
			cox(43_380, 43_380, 1, 30);
		}
		RaidInsights.Setup solo = tracker.raidInsights(COX, null).getSetups().get(0);
		// 5% a raid, and a twisted bow is 2 of the 60 weight
		assertEquals(0.05 * 2 / 60, solo.getItemPerRaid("Twisted bow"), 1e-12);
		// two raids an hour
		assertEquals(0.05 * 2 / 60 * 2, solo.getItemPerHour("Twisted bow"), 1e-12);
		// the pet comes with 1 in 53 purples
		assertEquals(0.05 / 53, solo.getItemPerRaid("Olmlet"), 1e-12);
		assertTrue(Double.isNaN(solo.getItemPerRaid("Not an item")));
		// merged rows add up their items too
		assertEquals(0.05 * 2 / 60, tracker.raidInsights(COX, null).getSetups(RaidInsights.BY_TEAM).get(0).getItemPerRaid("Twisted bow"), 1e-12);
	}

	@Test
	public void recentRaidsAreOneRowOverAllModes()
	{
		assertNull(tracker.raidInsights(COX, null).getRecent());
		for (int i = 0; i < 3; i++)
		{
			cox(43_380, 43_380, 1, 30);
			cm(43_380, 50);
		}
		RaidInsights.Setup recent = tracker.raidInsights(COX, null).getRecent();
		assertEquals(6, recent.getRaids());
		assertEquals(0.05, recent.getChancePerRaid(), 1e-9);
		// a twisted bow is 2 of 60 in normal mode and 2 of 56 in Challenge Mode
		assertEquals(0.05 * (2 / 60.0 + 2 / 56.0) / 2, recent.getItemPerRaid("Twisted bow"), 1e-12);
		assertEquals(40 * 60_000, recent.getAverageMillis());
	}

	@Test
	public void setupsCanBeGroupedByTeamOrByModeAlone()
	{
		for (int i = 0; i < 5; i++)
		{
			cox(43_380, 43_380, 1, 30);
			cm(43_380, 30);
		}
		cox(21_690, 43_380, 2, 15);

		RaidInsights insights = tracker.raidInsights(COX, null);
		assertEquals(3, insights.getSetups(RaidInsights.BY_SETUP).size());
		List<RaidInsights.Setup> byTeam = insights.getSetups(RaidInsights.BY_TEAM);
		assertEquals(2, byTeam.size());
		// Normal and Challenge Mode solo raids together: 10 raids, 5 hours, 0.5 purples
		RaidInsights.Setup solo = byTeam.get(0);
		assertNull(solo.getPart());
		assertEquals(1, solo.getTeam());
		assertEquals(10, solo.getRaids());
		assertEquals(0.10, solo.getChancePerHour(), 1e-9);
		List<RaidInsights.Setup> byMode = insights.getSetups(RaidInsights.BY_CHOICE);
		assertEquals(2, byMode.size());
		assertEquals(-1, byMode.get(0).getTeam());
		assertEquals(6, byMode.stream().filter(s -> "Normal".equals(s.getPart())).findFirst().get().getRaids());
	}

	@Test
	public void tombsGroupedByChoiceIsByRaidLevel()
	{
		toa(10_000, 1, 300, 40);
		toa(10_000, 2, 310, 40);
		toa(10_000, 2, 400, 40);

		List<RaidInsights.Setup> byLevel = tracker.raidInsights(TOA, null).getSetups(RaidInsights.BY_CHOICE);
		assertEquals(2, byLevel.size());
		assertNull(byLevel.get(0).getPart());
		assertEquals(2, byLevel.stream().filter(s -> s.getLevelFrom() == 300).findFirst().get().getRaids());
	}

	@Test
	public void untimedRaidsCountForTheChanceButNotTheHour()
	{
		for (int i = 0; i < 5; i++)
		{
			cox(43_380, 43_380, 1, 30);
		}
		cox(86_760, 86_760, 1, -1);

		RaidInsights.Setup solo = tracker.raidInsights(COX, null).getSetups().get(0);
		assertEquals(6, solo.getRaids());
		assertEquals(5, solo.getTimed());
		assertEquals((0.05 * 5 + 0.10) / 6, solo.getChancePerRaid(), 1e-9);
		assertEquals(0.10, solo.getChancePerHour(), 1e-9);
	}

	@Test
	public void tombsSetupsUseRaidLevelStepsOfFifty()
	{
		toa(10_000, 2, 300, 40);
		toa(10_000, 2, 349, 40);
		toa(10_000, 2, 350, 40);

		List<RaidInsights.Setup> setups = tracker.raidInsights(TOA, null).getSetups();
		assertEquals(2, setups.size());
		assertEquals(300, setups.get(0).getLevelFrom());
		assertEquals(2, setups.get(0).getRaids());
		assertEquals(350, setups.get(1).getLevelFrom());
		assertEquals(RaidInsights.levelStep(-1), -1);
	}

	@Test
	public void bigTeamsShareOneRow()
	{
		assertEquals(0, RaidInsights.teamRow(0));
		assertEquals(5, RaidInsights.teamRow(5));
		assertEquals(RaidInsights.TEAM_CAP, RaidInsights.teamRow(RaidInsights.TEAM_CAP));
		assertEquals(RaidInsights.TEAM_CAP, RaidInsights.teamRow(40));
	}

	@Test
	public void gpValueIsEachDropsExpectedTimesItsPrice()
	{
		for (int i = 0; i < 5; i++)
		{
			cox(43_380, 43_380, 1, 30);
		}
		// only the twisted bow has a price: 5% a raid times its weight of 2 out of the 60 of the purple table
		RaidInsights.Setup solo = tracker.raidInsights(COX, name -> "Twisted bow".equals(name) ? 1_000_000_000L : 0).getSetups().get(0);
		assertEquals(0.05 * 2 / 60 * 1_000_000_000, solo.getGpPerRaid(), 1);
		assertEquals(solo.getGpPerRaid() * 2, solo.getGpPerHour(), 1);
		// without prices there is no GP value
		assertEquals(0, tracker.raidInsights(COX, null).getSetups().get(0).getGpPerRaid(), 0);
	}

	@Test
	public void personalBestsPerModeAndTeamPointToTheRaidThatSetThem()
	{
		RaidRecord slow = cox(52_100, 52_100, 1, 40);
		RaidRecord fast = cox(30_000, 30_000, 1, 31);
		cox(25_000, 50_000, 2, 22);
		cm(41_300, 48);

		List<RaidInsights.Bests> bests = tracker.raidInsights(COX, null).getBests();
		assertEquals(3, bests.size());
		RaidInsights.Bests solo = bests.get(0);
		assertEquals("Normal", solo.getPart());
		assertEquals(1, solo.getTeam());
