/**
 * What the reader makes of the game at the end of a raid: the Chambers points, the Tombs points (the
 * game's exact number or On Rate's estimate), the Theatre board, the Tombs plugin's message and the
 * Fractured Archive's damage share. Driven with a stand-in for the game client, so also with the
 * values missing, malformed or arriving in another order.
 */
public class RaidPointsReaderTest
{
	private static final String COX = "Chambers of Xeric";
	private static final String TOA = "Tombs of Amascut";
	private static final String TOB = "Theatre of Blood";
	private static final String TFA = "The Fractured Archive";

	private final Map<Integer, Integer> varbits = new HashMap<>();
	private final Map<Integer, Integer> varps = new HashMap<>();
	private final Map<Integer, Widget> widgets = new HashMap<>();
	private final List<Player> players = new ArrayList<>();
	private Player me;
	private boolean noWorld;
	private boolean enabled = true;
	private final List<String> changed = new ArrayList<>();
	private Tracker tracker;
	private RaidPointsReader reader;

	@Before
	public void setUp()
	{
		tracker = new Tracker(Bundled.catalog(new Gson()));
		tracker.setSettings(raid -> 0.03);
		me = player("Me Name");
		players.add(me);
		IndexedObjectSet<?> set = Fakes.of(IndexedObjectSet.class, new Fakes.Answers().on("iterator", args -> players.iterator()));
		WorldView view = Fakes.of(WorldView.class, new Fakes.Answers().on("players", set));
		Client client = Fakes.of(Client.class, new Fakes.Answers()
			.on("getVarbitValue", args -> args.length == 1 ? varbits.getOrDefault((Integer) args[0], 0) : 0)
			.on("getVarpValue", args -> varps.getOrDefault((Integer) args[0], 0))
			.on("getWidget", args -> args.length == 1 && args[0] instanceof Integer ? widgets.get(args[0]) : null)
			.on("getLocalPlayer", args -> me)
			.on("getTopLevelWorldView", args -> noWorld ? null : view));
		ClientThread now = new ClientThread()
		{
			@Override
			public void invokeLater(Runnable r)
			{
				r.run();
			}
		};
		reader = new RaidPointsReader(client, now, tracker, changed::add, () -> enabled);
	}

	private static Player player(String name)
	{
		return Fakes.of(Player.class, new Fakes.Answers().on("getName", name));
	}

	private static Widget widget(String text)
	{
		return Fakes.of(Widget.class, new Fakes.Answers().on("getText", text));
	}

	private void chat(ChatMessageType type, String message)
	{
		reader.onChatMessage(new ChatMessage(null, type, "", message, "", 0));
	}

	/** The completion count message, as the plugin hands it to the tracker. */
	private String completion(String counter, int kc)
	{
		return tracker.onChatMessage("Your completed " + counter + " count is: <col=ff0000>" + kc + "</col>.", System.currentTimeMillis());
	}

	// ---- Chambers of Xeric ----

	private void inChambers(int personal, int total, int partySize, int scaledSize)
	{
		varbits.put(VarbitID.RAIDS_CLIENT_INDUNGEON, 1);
		varbits.put(VarbitID.RAIDS_CLIENT_PARTYSCORE, total);
		varps.put(VarPlayerID.RAIDS_PLAYERSCORE, personal);
		varbits.put(VarbitID.RAIDS_CLIENT_PARTYSIZE, partySize);
		varbits.put(VarbitID.RAIDS_CLIENT_PARTYSIZE_SCALED, scaledSize);
	}

	private void chambersDone()
	{
		chat(ChatMessageType.FRIENDSCHATNOTIFICATION, "<col=ef20ff>Congratulations - your raid is complete!</col><br>Team size: <col=ff0000>Solo</col>");
	}

	@Test
	public void chambersPointsAreSavedWithTheScaleAndThePlayersStillInTheRaid()
	{
		// scaled for three, two players still in it (and one the client lists without a name yet)
		inChambers(30_000, 60_000, 2, 3);
		players.add(player("Teammate"));
		players.add(player(null));
		chambersDone();
		assertTrue("the raid's mode isn't known until its completion message", tracker.raidRecords(COX).isEmpty());
		assertEquals(COX, completion("Chambers of Xeric", 5));

		RaidRecord r = tracker.raidRecords(COX).get(0);
		assertEquals(30_000, r.getPersonalPoints());
		assertEquals(60_000, r.getTeamPoints());
		assertEquals(3, r.getTeamSize());
		assertEquals("Normal", r.getPart());
		assertEquals(5, r.getKc());
		RaidInsights.Setup setup = tracker.raidInsights(COX, null).getSetups().get(0);
		assertEquals(3, setup.getTeam());
		assertEquals(2, setup.getPlayers());
	}

	@Test
	public void chambersPointsThatComeAfterTheCompletionMessageStillJoinIt()
	{
		inChambers(25_000, 25_000, 1, 1);
		completion("Chambers of Xeric Challenge Mode", 3);
		assertTrue(changed.isEmpty());
		chambersDone();
		assertEquals(Arrays.asList(COX), changed);
		assertEquals("Challenge Mode", tracker.raidRecords(COX).get(0).getPart());
		assertEquals(25_000, tracker.raidRecords(COX).get(0).getPersonalPoints());
	}

	@Test
	public void chambersIsIgnoredOutsideTheDungeonWithoutPointsOrWithTheSettingOff()
	{
		// the message somewhere else (a friends chat relaying it)
		inChambers(30_000, 60_000, 2, 2);
		varbits.put(VarbitID.RAIDS_CLIENT_INDUNGEON, 0);
		chambersDone();
		// in the dungeon, but the game gave no points
		inChambers(0, 60_000, 2, 2);
		chambersDone();
		inChambers(30_000, 0, 2, 2);
		chambersDone();
		// and with "Use raid points" off
		inChambers(30_000, 60_000, 2, 2);
		enabled = false;
		chambersDone();
		completion("Chambers of Xeric", 1);
		assertTrue(tracker.raidRecords(COX).isEmpty());
		assertTrue(changed.isEmpty());
	}

	@Test
	public void chambersWithoutAPlayerListLeavesThePlayersUnknown()
	{
		inChambers(30_000, 90_000, 3, 3);
		noWorld = true;
		chambersDone();
		completion("Chambers of Xeric", 1);
		RaidInsights.Setup setup = tracker.raidInsights(COX, null).getSetups().get(0);
		assertEquals(3, setup.getTeam());
		assertEquals("not known whether players had left", -1, setup.getPlayers());
	}

	@Test
	public void chambersNeverCountsMorePlayersThanTheRaidScaledFor()
	{
		// a solo raid with an onlooker's alt in view: still solo
		inChambers(30_000, 30_000, 1, 1);
		players.add(player("Someone else"));
		chambersDone();
		completion("Chambers of Xeric", 1);
		RaidInsights.Setup setup = tracker.raidInsights(COX, null).getSetups().get(0);
		assertEquals(1, setup.getTeam());
		assertEquals(1, setup.getPlayers());
	}

	// ---- Tombs of Amascut ----

	private void inTombs(int raidLevel)
	{
		widgets.put(InterfaceID.ToaHud.RAID_STATE, widget(""));
		varbits.put(VarbitID.TOA_CLIENT_RAID_LEVEL, raidLevel);
		reader.onGameTick(new GameTick());
	}

	private void tombsExactPoints(int points)
	{
		VarbitChanged e = new VarbitChanged();
		e.setVarpId(VarPlayerID.TOA_PERSONAL_CONTRIBUTION);
		e.setValue(points);
		reader.onVarbitChanged(e);
	}

	private void tombsStart()
	{
		chat(ChatMessageType.GAMEMESSAGE, "You enter the Tombs of Amascut...");
	}

	private void wardensDone()
	{
		chat(ChatMessageType.GAMEMESSAGE, "Challenge complete: The Wardens. Duration: <col=ef1020>4:01.20</col>");
	}

	@Test
	public void tombsUsesTheGamesExactPointsWhenTheyComeBeforeTheRaidEnds()
	{
		tombsStart();
		inTombs(300);
		tombsExactPoints(21_000);
		wardensDone();
		completion("Tombs of Amascut: Expert Mode", 1);
		RaidRecord r = tracker.raidRecords(TOA).get(0);
		assertEquals(21_000, r.getPersonalPoints());
		assertFalse(r.isEstimated());
		assertEquals(300, r.getRaidLevel());
		assertEquals(1, r.getTeamSize());
		assertEquals("Expert Mode", r.getPart());
	}

	@Test
	public void tombsExactPointsThatComeAfterTheRaidWasSavedReplaceTheEstimate()
	{
		tombsStart();
		inTombs(150);
		wardensDone();
		completion("Tombs of Amascut", 4);
		RaidRecord r = tracker.raidRecords(TOA).get(0);
		assertTrue("On Rate's own estimate so far", r.isEstimated());
		changed.clear();
		tombsExactPoints(18_500);
		assertEquals(Arrays.asList(TOA), changed);
		assertEquals(18_500, r.getPersonalPoints());
		assertFalse(r.isEstimated());
		assertEquals(150, r.getRaidLevel());
	}

	@Test
	public void tombsCountsThePartyFromTheGamesPlayerSlots()
	{
		varbits.put(VarbitID.TOA_CLIENT_P1, 1);
		varbits.put(VarbitID.TOA_CLIENT_P2, 1);
		tombsStart();
		inTombs(200);
		tombsExactPoints(12_000);
		wardensDone();
		completion("Tombs of Amascut", 1);
		assertEquals(3, tracker.raidRecords(TOA).get(0).getTeamSize());
	}

	@Test
	public void tombsIsIgnoredOutsideTheRaidOrWithTheSettingOff()
	{
		// not in the raid: no HUD, no raid room
		tombsStart();
		reader.onGameTick(new GameTick());
		wardensDone();
		completion("Tombs of Amascut", 1);
		assertTrue(tracker.raidRecords(TOA).isEmpty());

		// in the raid with the setting off
		enabled = false;
		tombsStart();
		inTombs(300);
		tombsExactPoints(21_000);
		wardensDone();
		completion("Tombs of Amascut", 2);
		assertTrue(tracker.raidRecords(TOA).isEmpty());
	}

	@Test
	public void tombsExactPointsOfZeroOrLessAreNotPoints()
	{
		tombsStart();
		inTombs(300);
		tombsExactPoints(0);
		tombsExactPoints(-5);
		wardensDone();
		completion("Tombs of Amascut: Expert Mode", 1);
		// saved from the estimate instead (nothing was seen of this raid, so the estimate has no points either)
		assertTrue(tracker.raidRecords(TOA).get(0).isEstimated());
	}

	@Test
	public void loggingInAgainStartsTheRaidStateOver()
	{
		tombsStart();
		inTombs(300);
		tombsExactPoints(21_000);
		GameStateChanged login = new GameStateChanged();
		login.setGameState(GameState.LOGGING_IN);
		reader.onGameStateChanged(login);
		// until the next game tick says so, On Rate no longer takes you to be in the raid
		wardensDone();
		completion("Tombs of Amascut: Expert Mode", 1);
		assertTrue(tracker.raidRecords(TOA).isEmpty());
	}

	/**
	 * Known gap (finding 1.2 in the November 2026 review): when the start of the raid was missed (the
	 * plugin turned on or the client restarted mid-raid) no raid is saved, although the game sent the exact
	 * points. This test says what happens today. A fix is meant to change its last line.
	 */
	@Test
	public void aTombsRaidWhoseStartWasMissedIsNotSavedToday()
	{
		inTombs(300);
		tombsExactPoints(21_000);
		wardensDone();
		completion("Tombs of Amascut: Expert Mode", 1);
		assertTrue(tracker.raidRecords(TOA).isEmpty());
	}

	// ---- the Tombs of Amascut plugin's party points ----

	private static PluginMessage points(String namespace, String name, Object version, Object personal, Object total)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("version", version);
		data.put("personalPoints", personal);
		data.put("totalPoints", total);
		return new PluginMessage(namespace, name, data);
	}

	@Test
	public void theTombsPluginsTotalGoesIntoTheRaidAndAnythingElseIsIgnored()
	{
		varbits.put(VarbitID.TOA_CLIENT_P1, 1);
		tombsStart();
		inTombs(300);
		wardensDone();
		completion("Tombs of Amascut: Expert Mode", 1);
		RaidRecord r = tracker.raidRecords(TOA).get(0);
		changed.clear();

		// another plugin, another message, no data, another version, text where numbers belong, no points
		reader.onPluginMessage(points("some-other-plugin", "raidCompletedPoints", 1, 20_000, 60_000));
		reader.onPluginMessage(points("tombs-of-amascut", "somethingElse", 1, 20_000, 60_000));
		reader.onPluginMessage(new PluginMessage("tombs-of-amascut", "raidCompletedPoints"));
		reader.onPluginMessage(new PluginMessage("tombs-of-amascut", "raidCompletedPoints", new HashMap<>()));
		reader.onPluginMessage(points("tombs-of-amascut", "raidCompletedPoints", 2, 20_000, 60_000));
		reader.onPluginMessage(points("tombs-of-amascut", "raidCompletedPoints", "1", 20_000, 60_000));
		reader.onPluginMessage(points("tombs-of-amascut", "raidCompletedPoints", 1, "20000", "60000"));
		reader.onPluginMessage(points("tombs-of-amascut", "raidCompletedPoints", 1, null, 60_000));
		reader.onPluginMessage(points("tombs-of-amascut", "raidCompletedPoints", 1, 0, 0));
		assertTrue(changed.isEmpty());
		assertEquals(0, r.getTeamPoints());

		reader.onPluginMessage(points("tombs-of-amascut", "raidCompletedPoints", 1, 20_000, 60_000L));
		assertEquals(Arrays.asList(TOA), changed);
		assertEquals(20_000, r.getPersonalPoints());
		assertEquals(60_000, r.getTeamPoints());
	}

	// ---- Theatre of Blood ----

	private static final int[] NAMES = {
		InterfaceID.TobInfoboard.PLAYERNAME0, InterfaceID.TobInfoboard.PLAYERNAME1, InterfaceID.TobInfoboard.PLAYERNAME2,
		InterfaceID.TobInfoboard.PLAYERNAME3, InterfaceID.TobInfoboard.PLAYERNAME4,
	};
	private static final int[] DEATHS = {
		InterfaceID.TobInfoboard.DEATHS0, InterfaceID.TobInfoboard.DEATHS1, InterfaceID.TobInfoboard.DEATHS2,
		InterfaceID.TobInfoboard.DEATHS3, InterfaceID.TobInfoboard.DEATHS4,
	};

	private void boardRow(int row, String name, String deaths)
	{
		widgets.put(NAMES[row], widget(name));
		widgets.put(DEATHS[row], widget(deaths));
	}

	private void openBoard()
	{
		WidgetLoaded loaded = new WidgetLoaded();
		loaded.setGroupId(InterfaceID.TOB_INFOBOARD);
		reader.onWidgetLoaded(loaded);
	}

	@Test
	public void theTheatreBoardGivesTheTeamYourDeathsAndTheMvp()
	{
		boardRow(0, "Alice", "2");
		boardRow(1, "<col=ffffff>Me Name</col>", "1");
		boardRow(2, "-", "-");
		widgets.put(InterfaceID.TobInfoboard.MVP_PLAYER, widget("me name"));
		openBoard();
		assertEquals(TOB, completion("Theatre of Blood", 10));
		RaidRecord r = tracker.raidRecords(TOB).get(0);
		assertEquals(2, r.getTeamSize());
		assertEquals(1, r.getDeaths());
		assertEquals(3, r.getTeamDeaths());
		assertEquals(Boolean.TRUE, r.getMvp());
	}

	@Test
	public void aBoardThatCantBeFullyReadKeepsWhatItCan()
	{
		// deaths that aren't a number count as none; you are not on the board; no MVP shown
		boardRow(0, "Alice", "abc");
		boardRow(1, "Bob", "");
		boardRow(3, "Carol", "4");
		openBoard();
		completion("Theatre of Blood", 1);
		RaidRecord r = tracker.raidRecords(TOB).get(0);
		assertEquals(3, r.getTeamSize());
		assertEquals("your own deaths are unknown", -1, r.getDeaths());
		assertEquals(4, r.getTeamDeaths());
		assertNull(r.getMvp());
	}

	@Test
	public void anEmptyBoardAnotherInterfaceOrTheSettingOffSaveNothing()
	{
		// the board with nobody on it
		boardRow(0, "-", "-");
		openBoard();
		// another interface
		boardRow(0, "Alice", "0");
		WidgetLoaded other = new WidgetLoaded();
		other.setGroupId(InterfaceID.TOB_INFOBOARD + 1);
		reader.onWidgetLoaded(other);
		// the setting off
		enabled = false;
		openBoard();
		completion("Theatre of Blood", 1);
		assertTrue(tracker.raidRecords(TOB).isEmpty());
	}

	@Test
	public void theBoardWithoutALocalPlayerStillCountsTheTeam()
	{
		me = null;
		boardRow(0, "Alice", "1");
		boardRow(1, "Bob", "0");
		widgets.put(InterfaceID.TobInfoboard.MVP_PLAYER, widget("Alice"));
		openBoard();
		completion("Theatre of Blood", 1);
		RaidRecord r = tracker.raidRecords(TOB).get(0);
		assertEquals(2, r.getTeamSize());
		assertEquals(-1, r.getDeaths());
		assertNull(r.getMvp());
	}

	// ---- The Fractured Archive ----

	private void hit(int npcId, int amount, boolean mine)
	{
		HitsplatApplied e = new HitsplatApplied();
		e.setActor(Fakes.of(NPC.class, new Fakes.Answers().on("getId", npcId)));
		e.setHitsplat(Fakes.of(Hitsplat.class, new Fakes.Answers().on("getAmount", amount).on("isMine", mine).on("isOthers", !mine)));
		reader.onHitsplatApplied(e);
	}

	private void archiveDone(int kc)
	{
		chat(ChatMessageType.GAMEMESSAGE, "Your The Fractured Archive completion count is: <col=ff0000>" + kc + "</col>.");
		tracker.onChatMessage("Your The Fractured Archive completion count is: <col=ff0000>" + kc + "</col>.", System.currentTimeMillis());
	}

	@Test
	public void theArchivesDamageShareAndDeathsAreSavedWithTheRaid()
	{
		// the Archive Guardian, Ezekiel, Moia, the Dagon'hai and Ocellus: 30 of every 100 damage is yours
		for (int npc : new int[]{16659, 16652, 16667, 16643, 16672})
		{
			hit(npc, 30, true);
			hit(npc, 70, false);
		}
		// a hit on something that isn't part of the raid changes nothing
		hit(1, 500, true);
		reader.onActorDeath(new ActorDeath(me));
		reader.onActorDeath(new ActorDeath(player("Teammate")));
		archiveDone(1);
		RaidRecord r = tracker.raidRecords(TFA).get(0);
		assertEquals(210, r.getContribution(), 1e-9);
		assertEquals(1, r.getDeaths());
	}

	@Test
	public void anArchiveRaidWithAFightMissedHasNoShare()
	{
		// turned on after the first fight: four of the five fights seen
		for (int npc : new int[]{16652, 16667, 16643, 16672})
		{
			hit(npc, 50, true);
			hit(npc, 50, false);
		}
		tracker.setTeamSizeDetector(() -> 2);
		archiveDone(1);
		RaidRecord r = tracker.raidRecords(TFA).get(0);
		assertEquals("an even share is assumed instead", -1, r.getContribution(), 0);
		assertEquals(2, r.getTeamSize());
	}

	@Test
	public void anArchiveRaidOnRateSawNothingOfSavesNothingByItself()
	{
		archiveDone(1);
		assertTrue(tracker.raidRecords(TFA).isEmpty());
		assertTrue(changed.isEmpty());
	}
}

package com.onrate.game;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.raids.RaidDataImport;
import com.onrate.engine.tracking.Tracker;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import java.util.function.Supplier;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.config.RuneScapeProfileType;
import org.junit.Before;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

/** Raid Data Tracker times are only ever added to the profile they were read for (audit F4). */
public class RaidTimesImportTest
{
	private static final long ME = 123456789L;

	@Rule
	public TemporaryFolder tmp = new TemporaryFolder();

	/** Runs handed-over tasks only when the test says so: the worker, or the client thread. */
	private static final class Tasks
	{
		final List<Runnable> list = new ArrayList<>();

		synchronized void add(Runnable r)
		{
			list.add(r);
		}

		void runAll()
		{
			List<Runnable> now;
			synchronized (this)
			{
				now = new ArrayList<>(list);
				list.clear();
			}
			now.forEach(Runnable::run);
		}
	}

	private Tasks worker;
	private Tasks clientThread;
	private AtomicReference<String> loaded;
	private RaidTimesImport importer;
	private Tracker tracker;
	private List<String> changed;
	private Supplier<RaidDataImport.Times> read;

	@Before
	public void setUp() throws IOException
	{
		worker = new Tasks();
		clientThread = new Tasks();
		loaded = new AtomicReference<>("A");
		importer = new RaidTimesImport(worker::add, clientThread::add, loaded::get);
		tracker = new Tracker(Bundled.catalog(new Gson()));
		changed = new ArrayList<>();
		// two Chambers raids of this account in Raid Data Tracker's log
		File root = tmp.newFolder("raid-data tracker");
		File dir = new File(root, "cox");
		assertTrue(dir.mkdirs());
		Files.write(new File(dir, "raid_tracker_data.log").toPath(), String.join("\n",
			"{\"accountHash\":" + ME + ",\"raidComplete\":true,\"date\":1000000,\"challengeMode\":false,\"raidTime\":1500}",
			"{\"accountHash\":" + ME + ",\"raidComplete\":true,\"date\":2000000,\"challengeMode\":false,\"raidTime\":1800}")
			.getBytes(StandardCharsets.UTF_8));
		read = () -> RaidDataImport.read(net.runelite.client.util.Filepath.Unchecked.getRooted(root.toPath()), ME);
	}

	private int imported()
	{
		return tracker.importedRaidTimes("Chambers of Xeric", null);
	}

	@Test
	public void addedWhenTheSameProfileIsStillLoaded()
	{
		importer.start("A", read, tracker, changed::add);
		assertEquals("nothing happens on the client thread before the files are read", 0, imported());
		worker.runAll();
		assertEquals("nothing is added on the worker thread", 0, imported());
		clientThread.runAll();
		assertEquals(2, imported());
		assertEquals(Collections.singletonList("Chambers of Xeric"), changed);
	}

	@Test
	public void droppedWhenAnotherAccountWasLoadedMeanwhile()
	{
		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		// A logs out and B logs in before the times reach the client thread; the tracker now holds B
		loaded.set("B");
		clientThread.runAll();
		assertEquals(0, imported());
		assertTrue(changed.isEmpty());
	}

	@Test
	public void droppedWhenTheSameAccountMovedToALeaguesProfile()
	{
		importer.start("main", read, tracker, changed::add);
		loaded.set("leagues");
		worker.runAll();
		clientThread.runAll();
		assertEquals(0, imported());
		assertTrue(changed.isEmpty());
	}

	@Test
	public void onlyAStandardProfileTakesImports()
	{
		List<RuneScapeProfile> profiles = Arrays.asList(
			new RuneScapeProfile("Me", RuneScapeProfileType.STANDARD, ME, "main"),
			new RuneScapeProfile("Me", RuneScapeProfileType.RAGING_ECHOES_LEAGUE, ME, "leagues"),
			new RuneScapeProfile("Me", RuneScapeProfileType.DEADMAN, ME, "dmm"));
		assertTrue(RaidTimesImport.importsInto("main", profiles));
		assertFalse("the log can't tell Leagues raids from the main game's", RaidTimesImport.importsInto("leagues", profiles));
		assertFalse(RaidTimesImport.importsInto("dmm", profiles));
		assertFalse("an unknown profile takes nothing", RaidTimesImport.importsInto("other", profiles));
		assertFalse(RaidTimesImport.importsInto(null, profiles));
	}

	@Test
	public void nothingIsAddedOnceThePluginHasStopped()
	{
		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		importer.stop();
		clientThread.runAll();
		assertEquals(0, imported());
		assertTrue(changed.isEmpty());

		// and a read still in progress at shutdown never reaches the client thread
		RaidTimesImport other = new RaidTimesImport(worker::add, clientThread::add, loaded::get);
		other.start("A", read, tracker, changed::add);
		other.stop();
		worker.runAll();
		assertTrue(clientThread.list.isEmpty());
		assertEquals(0, imported());
	}

	@Test
	public void timesAlreadyThereAreNotAddedAgain()
	{
		// one of the two raids was imported before
		tracker.importRaidTimes("Chambers of Xeric", "Normal", Collections.singletonList(new long[]{1000000, 1500_000}));
		assertEquals(1, imported());
		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		clientThread.runAll();
		assertEquals(2, imported());
	}

	@Test
	public void importingTwiceAddsEachTimeOnce()
	{
		// RuneLite loads on login and again when the profile is announced: two imports may overlap
		importer.start("A", read, tracker, changed::add);
		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		clientThread.runAll();
		assertEquals(2, imported());
		assertEquals("only the import that added times reports a change", 1, changed.size());

		importer.start("A", read, tracker, changed::add);
		worker.runAll();
		clientThread.runAll();
		assertEquals(2, imported());
		assertEquals(1, changed.size());
	}
}

package com.onrate.game;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class TeamSpotterTest
{
	@Test
	public void knowsWhichNpcsAreGroupBosses()
	{
		assertEquals("nex", TeamSpotter.fightOf("Nex"));
		assertEquals("yama", TeamSpotter.fightOf("Yama"));
		assertEquals("hueycoatl", TeamSpotter.fightOf("The Hueycoatl"));
		assertEquals("hueycoatl", TeamSpotter.fightOf("Hueycoatl"));
		assertEquals("hueycoatl", TeamSpotter.fightOf("Hueycoatl tail"));
		assertEquals("corporeal beast", TeamSpotter.fightOf("Corporeal Beast"));
		// names that only contain one
		assertNull(TeamSpotter.fightOf("Nexling"));
		assertNull(TeamSpotter.fightOf("Zalcano"));
		assertNull(TeamSpotter.fightOf("Vorkath"));
		assertNull(TeamSpotter.fightOf(null));
	}

	@Test
	public void namesAreMatchedWhateverTheirCaseTagsOrSpaces()
	{
		assertEquals("nex", TeamSpotter.fightOf("<col=ffff00>Nex</col>"));
		assertEquals("nex", TeamSpotter.fightOf("  NEX "));
		assertEquals("hueycoatl", TeamSpotter.fightOf("THE HUEYCOATL"));
		assertEquals("hueycoatl", TeamSpotter.fightOf("<col=ff0000>The Hueycoatl</col> tail"));
		assertEquals("corporeal beast", TeamSpotter.fightOf("corporeal beast"));
		// "the" alone, a boss name cut short, and a boss name inside another word
		assertNull(TeamSpotter.fightOf("The "));
		assertNull(TeamSpotter.fightOf("Ne"));
		assertNull(TeamSpotter.fightOf(""));
		assertNull(TeamSpotter.fightOf("Yamatai"));
		assertNull(TeamSpotter.fightOf("Corporeal"));
		assertNull(TeamSpotter.fightOf("Thenex"));
	}

	@Test
	public void onlyPlayersWhoHitTheBossCount()
	{
		TeamSpotter spotter = new TeamSpotter();
		assertEquals(0, spotter.others("nex", 1_000));
		spotter.onHitting("nex", "Alice", 1_000);
		spotter.onHitting("nex", "Bob", 2_000);
		// the same player hitting again is still one player
		spotter.onHitting("nex", "Alice", 3_000);
		assertEquals(2, spotter.others("nex", 4_000));
		// another boss's fight is separate
		assertEquals(0, spotter.others("yama", 4_000));
	}

	@Test
	public void aPlayerSeenLongAgoNoLongerCounts()
	{
		TeamSpotter spotter = new TeamSpotter();
		spotter.onHitting("corporeal beast", "Alice", 0);
		spotter.onHitting("corporeal beast", "Bob", TeamSpotter.WINDOW_MILLIS);
		assertEquals(2, spotter.others("corporeal beast", TeamSpotter.WINDOW_MILLIS));
		assertEquals(1, spotter.others("corporeal beast", TeamSpotter.WINDOW_MILLIS + 1));
	}

	@Test
	public void theNextKillStartsFresh()
	{
		TeamSpotter spotter = new TeamSpotter();
		spotter.onHitting("nex", "Alice", 1_000);
		spotter.clear("nex");
		assertEquals(0, spotter.others("nex", 2_000));
	}
}

package com.onrate.game.toa;

import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import static org.junit.Assert.assertEquals;
import org.junit.Before;
import org.junit.Test;

/**
 * Checks the Tombs of Amascut points estimate (ported from Raid Data Tracker / the Tombs of
 * Amascut plugin) follows its rules.
 */
public class ToaPointsEstimatorTest
{
	/** Any monster without its own factor counts 1 point per damage. */
	private static final int PLAIN_NPC = 1;

	private ToaPointsEstimator points;

	@Before
	public void setUp()
	{
		points = new ToaPointsEstimator();
		points.onGameMessage(ToaPointsEstimator.START_MESSAGE + ".");
		points.setTeamSize(1);
	}

	@Test
	public void startsAtZeroWithoutTheBasePoints()
	{
		assertEquals(0, points.getPersonalTotalPoints());
	}

	@Test
	public void onlyYourOwnHitsCount()
	{
		points.onHitsplat(PLAIN_NPC, 40, true, RaidRoom.AKKHA);
		points.onHitsplat(PLAIN_NPC, 40, false, RaidRoom.AKKHA);
		points.onHitsplat(PLAIN_NPC, 0, true, RaidRoom.AKKHA);
		assertEquals(40, points.getPersonalTotalPoints());
	}

	@Test
	public void monstersHaveTheirOwnFactor()
	{
		points.onHitsplat(NpcID.TOA_BABA, 50, true, RaidRoom.BABA);             // x2.0
		points.onHitsplat(NpcID.TOA_BABA_BOULDER, 50, true, RaidRoom.BABA);     // x0
		points.onHitsplat(NpcID.TOA_ZEBAK, 10, true, RaidRoom.ZEBAK);           // x1.5
		points.onHitsplat(NpcID.TOA_KEPHRI_GUARDIAN_MELEE, 11, true, RaidRoom.KEPHRI); // x0.5, rounded down
		points.onHitsplat(NpcID.TOA_HET_GOAL_VULNERABLE, 4, true, RaidRoom.HET); // x2.5
		points.onHitsplat(NpcID.TOA_PATH_APMEKEN_BABOON_MELEE_1, 10, true, RaidRoom.BABA); // x1.2
		assertEquals(100 + 0 + 15 + 5 + 10 + 12, points.getPersonalTotalPoints());
	}

	@Test
	public void roomsAreCappedAt20kAndCrondisAt10k()
	{
		for (int i = 0; i < 300; i++)
		{
			points.onHitsplat(PLAIN_NPC, 100, true, RaidRoom.AKKHA);
		}
		assertEquals(20_000, points.getPersonalTotalPoints());

		// a finished room starts a new room cap
		points.onGameMessage(ToaPointsEstimator.ROOM_FINISH_MESSAGE + ": Akkha.");
		for (int i = 0; i < 300; i++)
		{
			points.onHitsplat(PLAIN_NPC, 100, true, RaidRoom.CRONDIS);
		}
		assertEquals(30_000, points.getPersonalTotalPoints());
	}

	@Test
	public void totalIsCappedAt64kIncludingTheBase()
	{
		for (int room = 0; room < 5; room++)
		{
			for (int i = 0; i < 200; i++)
			{
				points.onHitsplat(PLAIN_NPC, 100, true, RaidRoom.WARDENS);
			}
			points.onGameMessage(ToaPointsEstimator.ROOM_FINISH_MESSAGE);
		}
		assertEquals(64_000 - 5_000, points.getPersonalTotalPoints());
	}

	@Test
	public void deathsCost20PercentButAtLeast1000()
	{
		points.onHitsplat(PLAIN_NPC, 10_000, true, RaidRoom.AKKHA);
		// total 15,000 with the base: 20% is 3,000
		points.onGameMessage(ToaPointsEstimator.DEATH_MESSAGE + ".");
		assertEquals(7_000, points.getPersonalTotalPoints());

		ToaPointsEstimator early = new ToaPointsEstimator();
		// 20% of the 5,000 base is less than 1,000, so 1,000 goes
		early.onGameMessage(ToaPointsEstimator.DEATH_MESSAGE);
		assertEquals(-1_000, early.getPersonalTotalPoints());
	}

	@Test
	public void deathKeepsRoomPointsTowardsTheCap()
	{
		points.onHitsplat(PLAIN_NPC, 15_000, true, RaidRoom.AKKHA);
		points.onGameMessage(ToaPointsEstimator.DEATH_MESSAGE);
		// 20,000 - 4,000 = 16,000 total; room points stay at 15,000 so only 5,000 more fit
		points.onHitsplat(PLAIN_NPC, 10_000, true, RaidRoom.AKKHA);
		assertEquals(16_000 + 5_000 - 5_000, points.getPersonalTotalPoints());
	}

	@Test
	public void wardensPhaseTwoStopsCountingAfterThreeDowns()
	{
		points.onHitsplat(NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE, 10, true, RaidRoom.WARDENS); // x2
		for (int i = 0; i < 3; i++)
		{
			points.onWardenDowned(NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE);
		}
		points.onHitsplat(NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE, 10, true, RaidRoom.WARDENS);
		assertEquals(40, points.getPersonalTotalPoints());
		points.onWardenDowned(NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE);
		points.onHitsplat(NpcID.TOA_WARDEN_TUMEKEN_PHASE2_MAGE, 10, true, RaidRoom.WARDENS);
		assertEquals(40, points.getPersonalTotalPoints());
		// phase 3 still counts (x2.5)
		points.onHitsplat(NpcID.TOA_WARDEN_TUMEKEN_PHASE3, 10, true, RaidRoom.WARDENS);
		assertEquals(65, points.getPersonalTotalPoints());
	}

	@Test
	public void failingTheRoomResetsTheDowns()
	{
		for (int i = 0; i < 4; i++)
		{
			points.onWardenDowned(NpcID.TOA_WARDEN_ELIDINIS_PHASE2_RANGE);
		}
		points.onGameMessage(ToaPointsEstimator.ROOM_FAIL_MESSAGE + " The Wardens.");
		points.onHitsplat(NpcID.TOA_WARDEN_ELIDINIS_PHASE2_RANGE, 10, true, RaidRoom.WARDENS);
		assertEquals(20, points.getPersonalTotalPoints());
	}

	@Test
	public void mvpItemsGive300PerPlayerOnce()
	{
		points.setTeamSize(3);
		points.onItemSpawned(ItemID.TOA_ZEBAK_FANG);
		points.onItemSpawned(ItemID.TOA_ZEBAK_FANG);
		points.onItemSpawned(ItemID.TOA_AKKHA_ASHES);
		assertEquals(2 * 900, points.getPersonalTotalPoints());
	}

	@Test
	public void puzzleRoomsGiveFixedPoints()
	{
		points.onRoomLeft(RaidRoom.SCABARAS);
		points.onRoomLeft(RaidRoom.APMEKEN);
		points.onRoomLeft(RaidRoom.CRONDIS);
		points.onRoomLeft(RaidRoom.HET);
		points.onRoomLeft(RaidRoom.WARDENS);
		points.onRoomLeft(RaidRoom.AKKHA);
		points.onRoomLeft(null);
		assertEquals(300 + 450 + 400, points.getPersonalTotalPoints());
		assertEquals(5 * 300, points.getNonPartyPoints());
		assertEquals(1150 + 1500, points.getTotalPoints());
	}

	@Test
	public void startMessageResets()
	{
		points.onHitsplat(PLAIN_NPC, 500, true, RaidRoom.AKKHA);
		points.onRoomLeft(RaidRoom.HET);
		points.onGameMessage(ToaPointsEstimator.START_MESSAGE);
		assertEquals(0, points.getPersonalTotalPoints());
		assertEquals(0, points.getNonPartyPoints());
	}

	@Test
	public void roomsFromRegions()
	{
		assertEquals(RaidRoom.WARDENS, RaidRoom.forRegionId(15184));
		assertEquals(RaidRoom.WARDENS, RaidRoom.forRegionId(15696));
		assertEquals(RaidRoom.CRONDIS, RaidRoom.forRegionId(15698));
		assertEquals(null, RaidRoom.forRegionId(12345));
		assertEquals(RaidRoom.BABA, RaidRoom.forString("Ba-Ba"));
	}
}

package com.onrate.service;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.AccountStats;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.Tracker;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.ToLongFunction;
import org.junit.Test;

public class AccountPrecomputeTest
{
	// preload bundled data with a Gson, as the plugin does at startup (bundled() alone is empty until then)
	static
	{
		com.onrate.engine.data.KillTimes.bundled(new com.google.gson.Gson());
		com.onrate.engine.data.LadlorChart.bundled(new com.google.gson.Gson());
	}

	private static final RaidSettings RAIDS = raid -> 0.03;
	private static final ToLongFunction<String> PRICES = n -> 1000L + Math.abs(n.hashCode() % 5000);

	private static Tracker tracker()
	{
		Tracker t = new Tracker(Bundled.catalog(new Gson()));
		t.onClogPage("Vorkath", Collections.singletonList("Vorkath kills: 500"), Collections.singletonMap("Vorkath's head", 9));
		t.onClogPage("Zulrah", Collections.singletonList("Zulrah kills: 900"), Collections.singletonMap("Tanzanite fang", 1));
		return t;
	}

	/** Swing stand-in: runs handed-over tasks when asked, on the test thread. */
	private static final class Queue
	{
		final List<Runnable> tasks = new ArrayList<>();

		synchronized void add(Runnable r)
		{
			tasks.add(r);
		}

		void runAll()
		{
			List<Runnable> now;
			synchronized (this)
			{
				now = new ArrayList<>(tasks);
				tasks.clear();
			}
			now.forEach(Runnable::run);
		}
	}

	@Test
	public void theDrawItStartsGetsTheSameNumbersThePanelWouldWorkOut() throws Exception
	{
		Tracker t = tracker();
		ExecutorService worker = Executors.newSingleThreadExecutor();
		Queue swing = new Queue();
		AccountPrecompute pre = new AccountPrecompute(t, worker, swing::add);
		AccountStats[] seen = new AccountStats[1];
		pre.request(RAIDS, PRICES, () -> seen[0] = pre.account(true));
		worker.shutdown();
		assertTrue(worker.awaitTermination(20, TimeUnit.SECONDS));
		swing.runAll();
		assertNotNull(seen[0]);
		AccountStats direct = t.accountStats(RAIDS, PRICES);
