	private static Font sans(int style, float size)
	{
		return new Font("Segoe UI", style, 1).deriveFont(style, size);
	}

	private static BufferedImage views(BufferedImage[] panels)
	{
		int gap = 24;
		int w = 0;
		int h = 0;
		for (BufferedImage b : panels)
		{
			w += b.getWidth();
			h = Math.max(h, b.getHeight());
		}
		w += gap * (panels.length + 1);
		String[] names = {"Compact table", "Luck gauge", "Chance rings", "Bars with tabs"};
		int head = 64;
		BufferedImage image = new BufferedImage(w, h + head + gap, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(new Color(18, 18, 18));
		g.fillRect(0, 0, w, image.getHeight());
		int x = gap;
		for (int i = 0; i < panels.length; i++)
		{
			g.setColor(new Color(235, 235, 235));
			g.setFont(sans(Font.BOLD, 28));
			g.drawString(names[i], x, 42);
			g.drawImage(panels[i], x, head, null);
			x += panels[i].getWidth() + gap;
		}
		g.dispose();
		return image;
	}

	private static BufferedImage hero(BufferedImage account, BufferedImage cox, BufferedImage hover)
	{
		int w = 1800;
		int panelsTop = 560;
		int h = panelsTop + Math.max(Math.max(account.getHeight(), cox.getHeight()), hover.getHeight() + 40) + 60;
		BufferedImage image = new BufferedImage(w, h, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g.setColor(new Color(17, 17, 17));
		g.fillRect(0, 0, w, h);
		g.setPaint(new GradientPaint(0, 0, new Color(48, 24, 20), w, 0, new Color(18, 30, 22)));
		g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, 0.55f));
		g.fillRect(0, 0, w, 260);
		g.setComposite(AlphaComposite.SrcOver);

		centered(g, "FREE RUNELITE PLUGIN  ·  NO ACCOUNT  ·  NO WEB REQUESTS", sans(Font.BOLD, 26), new Color(165, 165, 165), w / 2, 84, 5f);
		centered(g, "Are you on rate?", sans(Font.BOLD, 150), Color.WHITE, w / 2, 230, -4f);
		centered(g, "Your real luck at every boss and raid, in one word.", sans(Font.PLAIN, 40), new Color(200, 200, 200), w / 2, 305, 0f);

		// the verdict bar
		int barX = 350;
		int barW = 1100;
		float[] stops = {0f, 0.25f, 0.5f, 0.75f, 1f};
		Color[] colours = {new Color(220, 60, 40), new Color(235, 140, 30), new Color(235, 220, 40), new Color(150, 215, 60), new Color(70, 215, 90)};
		g.setPaint(new LinearGradientPaint(barX, 0, barX + barW, 0, stops, colours));
		g.fillRoundRect(barX, 346, barW, 14, 14, 14);
		g.setFont(sans(Font.BOLD, 22));
		String[] labels = {"Extremely dry", "Dry", "On rate", "Spooned", "Extremely spooned"};
		float[] at = {0.04f, 0.27f, 0.5f, 0.74f, 0.94f};
		Color[] lc = {colours[0], colours[1], Color.WHITE, colours[3], colours[4]};
		for (int i = 0; i < labels.length; i++)
		{
			g.setColor(lc[i]);
			FontMetrics fm = g.getFontMetrics();
			g.drawString(labels[i], barX + (int) (barW * at[i]) - fm.stringWidth(labels[i]) / 2, 392);
		}

		int pad = 40;
		int colW = (w - pad * 4) / 3;
		int x1 = pad;
		int x2 = x1 + account.getWidth() + 44;
		int x3 = x2 + cox.getWidth() + 44;
		column(g, x1, panelsTop, "YOUR WHOLE ACCOUNT", "One verdict, every boss driest first");
		column(g, x2, panelsTop, "EVERY BOSS AND RAID", "Got against expected, drop by drop");
		column(g, x3, panelsTop, "HOVER ANY DROP", "How lucky it was, in plain words");
		g.drawImage(account, x1, panelsTop, null);
		g.drawImage(cox, x2, panelsTop, null);
		g.drawImage(hover, x3, panelsTop, null);
		g.dispose();
		return image;
	}

	private static void column(Graphics2D g, int x, int top, String title, String sub)
	{
		g.setColor(Color.WHITE);
		g.setFont(sans(Font.BOLD, 30));
		g.drawString(title, x, top - 52);
		g.setColor(new Color(170, 170, 170));
		g.setFont(sans(Font.PLAIN, 24));
		g.drawString(sub, x, top - 20);
	}

	private static void centered(Graphics2D g, String text, Font font, Color colour, int cx, int baseline, float tracking)
	{
		g.setFont(font.deriveFont(java.util.Collections.singletonMap(java.awt.font.TextAttribute.TRACKING, tracking / font.getSize2D())));
		g.setColor(colour);
		FontMetrics fm = g.getFontMetrics();
		g.drawString(text, cx - fm.stringWidth(text) / 2, baseline);
	}
}

package com.onrate.store;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.BossStats;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.RaidInsights;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.Tracker;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

/**
 * Saved data as earlier versions of On Rate wrote it (fewer fields, raids inside the main data, a boss
 * that has since left the catalogue) and as a later one might (fields this version doesn't know): it
 * loads, nothing counts as damage, and nothing is lost when it is saved again.
 */
public class OlderSavesTest
{
	private static final RaidSettings RAIDS = raid -> 0.03;
	private static final long NOW = 1_700_000_000_000L;
	private static final String COX = "Chambers of Xeric";
	private static final String COX_RAIDS = "raids.ChambersofXeric";

	/** The settings of one profile; remembers every write, and can refuse some. */
	private static final class Profile implements ProfileStore.Backend
	{
		final Map<String, String> values = new HashMap<>();
		final List<String> writes = new ArrayList<>();
		final Set<String> refuse = new HashSet<>();

		@Override
		public String get(String profile, String key)
		{
			return values.get(key);
		}

		@Override
		public void set(String profile, String key, String value)
		{
			if (refuse.contains(key))
			{
				throw new IllegalStateException("refused");
			}
			values.put(key, value);
			writes.add(key);
		}

		@Override
		public void unset(String profile, String key)
		{
			if (refuse.contains(key))
			{
				throw new IllegalStateException("refused");
			}
			values.remove(key);
			writes.add("-" + key);
		}
	}

	private BossCatalog catalog;
	private Profile saved;

	@Before
	public void setUp()
	{
		catalog = Bundled.catalog(new Gson());
		saved = new Profile();
	}

	private Tracker load(ProfileStore store)
	{
		Tracker t = new Tracker(catalog);
		t.setSettings(RAIDS);
		assertTrue(store.load("main", t));
		return t;
	}

	private Tracker load()
	{
		return load(new ProfileStore(saved, new Gson()));
	}

	private void assertNothingCountedAsDamage()
	{
		for (String key : saved.values.keySet())
		{
			assertFalse(key + " was kept as a damaged copy", key.endsWith(".corrupt"));
		}
	}

	@Test
	public void aRaidFromBeforeTimesDeathsAndPlayersLoadsWithThoseUnknown()
	{
		saved.values.put("progress", "{\"bosses\":{\"Chambers of Xeric\":{\"chatKc\":{\"chambers of xeric\":7}}}}");
		saved.values.put(COX_RAIDS, "[{\"family\":\"cox\",\"part\":\"Normal\",\"kc\":7,\"personalPoints\":25000,"
			+ "\"teamPoints\":50000,\"teamSize\":2}]");
		Tracker t = load();
		assertNothingCountedAsDamage();

		RaidRecord r = t.raidRecords(COX).get(0);
		assertEquals("no time", -1, r.getDurationMillis());
		assertEquals("not a Tombs raid", -1, r.getRaidLevel());
		assertEquals("deaths unknown", -1, r.getDeaths());
		assertEquals("contribution unknown", -1, r.getContribution(), 0);

		// the raid sections count it for the chance, and never as a timed raid, a deathless raid or a best time
		RaidInsights insights = t.raidInsights(COX, null);
		assertEquals(1, insights.getSetups().size());
		RaidInsights.Setup setup = insights.getSetups().get(0);
		assertEquals(1, setup.getRaids());
		assertEquals(0, setup.getTimed());
		assertTrue(Double.isNaN(setup.getChancePerHour()));
		assertEquals("a duo whose players at the end were never read", -1, setup.getPlayers());
		RaidInsights.Bests bests = insights.getBests().get(0);
		assertNull(bests.getFastest());
		assertNull(bests.getHighestLevel());
		assertNull(bests.getBiggestShare());
		assertEquals(0, bests.getDeathsKnown());
		assertEquals(25_000, (int) bests.getMostPoints().getValue());
		assertEquals("when it was saved is unknown", 0, bests.getMostPoints().getSavedMillis());
	}

	@Test
	public void aSaveWithOnlyCountsLoadsAndComesBackTheSame()
	{
		saved.values.put("progress", "{\"bosses\":{\"Vorkath\":{\"chatKc\":{\"vorkath\":50},\"received\":{\"vorkath's head\":1}}}}");
		ProfileStore store = new ProfileStore(saved, new Gson());
		Tracker t = load(store);
		assertNothingCountedAsDamage();
		BossStats stats = t.stats("Vorkath", RAIDS);
		assertEquals(50, stats.getKillCount());
		assertEquals(1, stats.getAnyRow().getReceived());
		// everything added since (the days, the luck graph, shared items) starts empty and works
		assertTrue(t.history().isEmpty());
		// (no point yet: the log page was never opened, so the boss waits out of the account total)
		assertFalse(t.recordHistory(20_000, RAIDS));
		assertNotNull(t.recentDays(7, NOW));
		assertNotNull(t.sharedPools(RAIDS));

		t.onChatMessage("Your Vorkath kill count is: <col=ff0000>51</col>.", NOW);
		store.save(t);
		Tracker again = load();
		assertEquals(51, again.stats("Vorkath", RAIDS).getKillCount());
		assertEquals(1, again.stats("Vorkath", RAIDS).getAnyRow().getReceived());
		assertEquals(1, again.killsSeen("Vorkath"));
	}

	@Test
	public void historyFromBeforeTimesLoads()
	{
		saved.values.put("progress", "{\"bosses\":{\"Vorkath\":{\"chatKc\":{\"vorkath\":6}}}}");
		saved.values.put("kills.Vorkath", "[{\"k\":5,\"t\":1000},{\"k\":6,\"t\":2000,\"d\":[{\"i\":\"Vorkath's head\",\"s\":6}]}]");
		Tracker t = load();
		assertNothingCountedAsDamage();
		assertEquals(2, t.killsSeen("Vorkath"));
		assertNull("no kill has a time", t.killTimes("Vorkath", null));
		assertEquals(1, t.recentDrops(10).size());
		assertEquals("Vorkath's head", t.recentDrops(10).get(0).getDrop().getName());
		assertNull(t.recentDrops(10).get(0).getKill().getDurationMillis());
	}

	@Test
	public void fieldsALaterVersionAddedAreNotDamage()
	{
		saved.values.put("progress", "{\"somethingNew\":{\"a\":1},\"bosses\":{\"Vorkath\":{\"chatKc\":{\"vorkath\":50},"
			+ "\"alsoNew\":[1,2,3]}}}");
		saved.values.put("kills.Vorkath", "[{\"k\":50,\"t\":1000,\"zz\":true}]");
		saved.values.put(COX_RAIDS, "[{\"family\":\"cox\",\"part\":\"Normal\",\"kc\":7,\"personalPoints\":25000,"
			+ "\"teamPoints\":50000,\"teamSize\":2,\"newField\":\"x\"}]");
		Tracker t = load();
		assertNothingCountedAsDamage();
		assertEquals(50, t.stats("Vorkath", RAIDS).getKillCount());
		assertEquals(1, t.killsSeen("Vorkath"));
		assertEquals(1, t.raidRecords(COX).size());
	}

	@Test
	public void aBossThatLeftTheCatalogueKeepsItsSavedData()
	{
		String gone = "\"Some Old Boss\":{\"chatKc\":{\"some old boss\":12},\"received\":{\"old item\":2}}";
		saved.values.put("progress", "{\"bosses\":{" + gone + ",\"Vorkath\":{\"chatKc\":{\"vorkath\":50}}}}");
		saved.values.put("kills.SomeOldBoss", "[{\"k\":12,\"t\":1000}]");
		saved.values.put("raids.SomeOldBoss", "[{\"family\":\"cox\",\"kc\":1}]");
		ProfileStore store = new ProfileStore(saved, new Gson());
		Tracker t = load(store);
		assertNothingCountedAsDamage();
		assertNull("not a boss On Rate shows", t.stats("Some Old Boss", RAIDS));

		t.onChatMessage("Your Vorkath kill count is: <col=ff0000>51</col>.", NOW);
		t.recordHistory(20_000, RAIDS);
		store.save(t);
		// its numbers are still in the main data, and its History and raids were never touched
		assertTrue(saved.values.get("progress"), saved.values.get("progress").contains("\"Some Old Boss\""));
		assertTrue(saved.values.get("progress").contains("\"some old boss\":12"));
		assertTrue(saved.values.get("progress").contains("\"old item\":2"));
		assertEquals("[{\"k\":12,\"t\":1000}]", saved.values.get("kills.SomeOldBoss"));
		assertEquals("[{\"family\":\"cox\",\"kc\":1}]", saved.values.get("raids.SomeOldBoss"));
		assertFalse(saved.writes.contains("kills.SomeOldBoss"));
		assertFalse(saved.writes.contains("-kills.SomeOldBoss"));
		assertFalse(saved.writes.contains("raids.SomeOldBoss"));
		assertFalse(saved.writes.contains("-raids.SomeOldBoss"));
	}

	@Test
	public void moreHistoryThanIsKeptShowsTheNewestAndIsNotCutOnDiskUntilThatBossChanges()
	{
		StringBuilder kills = new StringBuilder("[");
		int count = Tracker.MAX_KILLS + 100;
		for (int kc = 1; kc <= count; kc++)
		{
			kills.append(kc > 1 ? "," : "").append("{\"k\":").append(kc).append(",\"t\":").append(1000L * kc).append("}");
		}
		kills.append("]");
		saved.values.put("progress", "{\"bosses\":{\"Vorkath\":{\"chatKc\":{\"vorkath\":" + count + "}},"
			+ "\"Zulrah\":{\"chatKc\":{\"zulrah\":3}}}}");
		saved.values.put("kills.Vorkath", kills.toString());
		ProfileStore store = new ProfileStore(saved, new Gson());
		Tracker t = load(store);
		assertNothingCountedAsDamage();
		assertEquals(Tracker.MAX_KILLS, t.killsSeen("Vorkath"));
		assertEquals("the newest kill is first", count, t.history("Vorkath").get(0).getKill().getKc());
		assertEquals(101, t.history("Vorkath").get(Tracker.MAX_KILLS - 1).getKill().getKc());

		// a kill somewhere else saves, but Vorkath's longer History stays as it was saved
		t.onChatMessage("Your Zulrah kill count is: <col=ff0000>4</col>.", NOW);
		store.save(t);
		assertEquals(kills.toString(), saved.values.get("kills.Vorkath"));
		assertFalse(saved.writes.contains("kills.Vorkath"));
	}

	@Test
	public void raidsInsideTheMainDataMoveToTheirOwnKeyAndComeBack()
	{
		// how the first versions saved them
		saved.values.put("progress", "{\"bosses\":{\"Chambers of Xeric\":{\"chatKc\":{\"chambers of xeric\":7},"
			+ "\"raids\":[{\"family\":\"cox\",\"part\":\"Normal\",\"kc\":7,\"personalPoints\":25000,"
			+ "\"teamPoints\":50000,\"teamSize\":2}]}}}");
		ProfileStore store = new ProfileStore(saved, new Gson());
		Tracker t = load(store);
		assertNothingCountedAsDamage();
		assertEquals(1, t.raidRecords(COX).size());
		assertEquals(1, t.measuredRaids(COX, "Normal"));

		store.save(t);
		assertTrue(saved.values.get(COX_RAIDS).contains("25000"));
		assertFalse("the main data no longer holds the raid", saved.values.get("progress").contains("25000"));
		assertTrue("the raids are written before the main data drops them",
			saved.writes.indexOf(COX_RAIDS) < saved.writes.indexOf("progress"));

		Tracker again = load();
		assertEquals(1, again.raidRecords(COX).size());
		assertEquals(25_000, again.raidRecords(COX).get(0).getPersonalPoints());
		assertEquals(7, again.raidRecords(COX).get(0).getKc());
	}

	@Test
	public void raidsInsideTheMainDataAreNeverDroppedWhileTheirOwnKeyCannotBeWritten()
	{
		String old = "{\"bosses\":{\"Chambers of Xeric\":{\"chatKc\":{\"chambers of xeric\":7},"
			+ "\"raids\":[{\"family\":\"cox\",\"part\":\"Normal\",\"kc\":7,\"personalPoints\":25000,"
			+ "\"teamPoints\":50000,\"teamSize\":2}]}}}";
		saved.values.put("progress", old);
		ProfileStore store = new ProfileStore(saved, new Gson());
		Tracker t = load(store);
		saved.refuse.add(COX_RAIDS);
		store.save(t);
		assertEquals("the old main data, with the raid in it, is still what is saved", old, saved.values.get("progress"));
		assertNull(saved.values.get(COX_RAIDS));

		// the settings take the write again: now the raid moves, and only then leaves the main data
		saved.refuse.clear();
		store.save(t);
		assertTrue(saved.values.get(COX_RAIDS).contains("25000"));
		assertFalse(saved.values.get("progress").contains("25000"));
	}

	@Test
	public void moreRaidsThanAreKeptLoadTheNewest()
	{
		StringBuilder raids = new StringBuilder("[");
		int count = 5_050;
		for (int kc = 1; kc <= count; kc++)
		{
			raids.append(kc > 1 ? "," : "").append("{\"family\":\"cox\",\"part\":\"Normal\",\"kc\":").append(kc)
				.append(",\"personalPoints\":20000,\"teamPoints\":20000,\"teamSize\":1}");
		}
		raids.append("]");
		saved.values.put("progress", "{\"bosses\":{\"Chambers of Xeric\":{\"chatKc\":{\"chambers of xeric\":" + count + "}}}}");
		saved.values.put(COX_RAIDS, raids.toString());
		Tracker t = load();
		assertNothingCountedAsDamage();
		List<RaidRecord> loaded = t.raidRecords(COX);
		assertEquals(5_000, loaded.size());
		assertEquals(51, loaded.get(0).getKc());
		assertEquals(count, loaded.get(loaded.size() - 1).getKc());
	}
}

package com.onrate.store;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.BossStats;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.Tracker;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

/**
 * Every read and write goes to the profile that was loaded, whichever profile RuneLite has as its
 * current one at that moment (audit F3).
 */
public class ProfileBindingTest
{
	private static final RaidSettings RAIDS = raid -> 0.0;
	private static final long NOW = 1_000_000;

	/**
	 * RuneLite's settings for several RuneScape profiles. {@code active} is RuneLite's current profile
	 * (null at the login screen); the store must never depend on it.
	 */
	private static final class Profiles implements ProfileStore.Backend
	{
		final Map<String, Map<String, String>> data = new HashMap<>();
		final List<String> writes = new ArrayList<>();
		String active;
		/** Keys whose writes fail (the settings refuse them), as profile + "/" + key. */
		final Set<String> refuse = new HashSet<>();

		Map<String, String> of(String profile)
		{
			return data.computeIfAbsent(profile, p -> new HashMap<>());
		}

		@Override
		public String get(String profile, String key)
		{
			return of(profile).get(key);
		}

		@Override
		public void set(String profile, String key, String value)
		{
			if (refuse.contains(profile + "/" + key))
			{
				throw new IllegalStateException("refused");
			}
			of(profile).put(key, value);
			writes.add(profile + "/" + key);
		}

		@Override
		public void unset(String profile, String key)
		{
			if (refuse.contains(profile + "/" + key))
			{
				throw new IllegalStateException("refused");
			}
			of(profile).remove(key);
			writes.add(profile + "/-" + key);
		}
	}

	private BossCatalog catalog;
	private Profiles profiles;
	private ProfileStore store;
	private Tracker tracker;

	@Before
	public void setUp()
	{
		catalog = Bundled.catalog(new Gson());
		profiles = new Profiles();
		store = new ProfileStore(profiles, new Gson());
		tracker = new Tracker(catalog);
	}

	private void vorkathKill(Tracker t, int kc, boolean head)
	{
		t.onChatMessage("Your Vorkath kill count is: <col=ff0000>" + kc + "</col>.", NOW + kc * 1000L);
		if (head)
		{
			t.onLoot("Vorkath", 1, Collections.singletonList(new Tracker.LootItem("Vorkath's head", 1)), NOW + kc * 1000L);
		}
	}

	private void coxRaid(Tracker t, int kc)
	{
		t.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>" + kc + "</col>.", NOW + kc * 1000L);
		t.onRaidRecord(RaidRecord.cox(25_000, 50_000, 2), NOW + kc * 1000L + 500);
	}

	private Tracker reload(String profile)
	{
		Tracker t = new Tracker(catalog);
		assertTrue(new ProfileStore(profiles, new Gson()).load(profile, t));
		return t;
	}

	private void assertOnlyWritesTo(String profile)
	{
		assertFalse(profiles.writes.isEmpty());
		for (String w : profiles.writes)
		{
			assertTrue(w + " went to another profile than " + profile, w.startsWith(profile + "/"));
		}
	}

	@Test
	public void dataLoadedFromAIsAlwaysWrittenToA()
	{
		profiles.active = "A";
		store.load("A", tracker);
		vorkathKill(tracker, 10, true);
		coxRaid(tracker, 3);
		store.save(tracker);
		assertOnlyWritesTo("A");
		assertTrue(profiles.of("A").containsKey("progress"));
		assertTrue(profiles.of("A").containsKey("kills.Vorkath"));
		assertTrue(profiles.of("A").containsKey("raids.ChambersofXeric"));
	}

	@Test
	public void runeLiteSwitchingToBCannotRedirectAsPendingWrites()
	{
		profiles.active = "A";
		store.load("A", tracker);
		vorkathKill(tracker, 10, true);
		store.save(tracker);
		profiles.writes.clear();
		profiles.of("B").put("progress", "{\"bosses\":{}}");
		Map<String, String> bBefore = new HashMap<>(profiles.of("B"));

		// B logs in: RuneLite's current profile is B before On Rate has loaded it, and a save comes then
		vorkathKill(tracker, 11, true);
		profiles.active = "B";
		store.save(tracker);

		assertOnlyWritesTo("A");
		assertEquals("B was not touched", bBefore, profiles.of("B"));
		assertEquals(11, reload("A").stats("Vorkath", RAIDS).getKillCount());
	}

	@Test
	public void savingWhileLoggedOutKeepsThePendingChanges()
	{
		profiles.active = "A";
		store.load("A", tracker);
		vorkathKill(tracker, 41, true);
		vorkathKill(tracker, 42, true);
		store.save(tracker);

		// at the login screen RuneLite has no current profile; a History entry is removed in the panel
		profiles.active = null;
		com.onrate.engine.tracking.KillEntry kill41 = null;
		for (com.onrate.engine.tracking.HistoryRow h : tracker.history("Vorkath"))
		{
			if (h.getKill().getKc() == 41)
			{
				kill41 = h.getKill();
			}
		}
		assertNotNull(kill41);
		assertTrue(tracker.removeFromHistory("Vorkath", kill41, kill41.getDrops().get(0)));
		store.save(tracker);

		// restarting RuneLite later: the removal was kept
		for (com.onrate.engine.tracking.HistoryRow h : reload("A").history("Vorkath"))
		{
			assertTrue("the removed entry came back", h.getKill().getKc() != 41 || h.getKill().getDrops().isEmpty());
		}
	}

	@Test
	public void aFailedHistoryWriteIsTriedAgainOnTheNextSave()
	{
		store.load("A", tracker);
		vorkathKill(tracker, 10, true);
		profiles.refuse.add("A/kills.Vorkath");
		store.save(tracker);
		assertNull(profiles.of("A").get("kills.Vorkath"));
		// the main data is still written: History has nothing to do with it
		assertNotNull(profiles.of("A").get("progress"));

		// nothing new happens, but the next save writes the History that failed
		profiles.refuse.clear();
		store.save(tracker);
		assertNotNull(profiles.of("A").get("kills.Vorkath"));
		assertEquals(1, reload("A").history("Vorkath").size());
	}

	@Test
	public void aFailedRaidsWriteKeepsItsMarkAndHoldsBackTheMainData()
	{
		store.load("A", tracker);
		coxRaid(tracker, 3);
		profiles.refuse.add("A/raids.ChambersofXeric");
		store.save(tracker);
		assertNull(profiles.of("A").get("raids.ChambersofXeric"));
		// raids moved out of older main data must stay in the saved main data until stored on their own
		assertNull(profiles.of("A").get("progress"));

		profiles.refuse.clear();
		store.save(tracker);
		assertNotNull(profiles.of("A").get("raids.ChambersofXeric"));
		assertNotNull(profiles.of("A").get("progress"));
		assertEquals(1, reload("A").raidRecords("Chambers of Xeric").size());
	}

	@Test
	public void aFailedMainDataWriteDoesNotStopTheNextSave()
	{
		store.load("A", tracker);
		vorkathKill(tracker, 10, false);
		profiles.refuse.add("A/progress");
		store.save(tracker);
		assertNull(profiles.of("A").get("progress"));
		profiles.refuse.clear();
		store.save(tracker);
		assertEquals(10, reload("A").stats("Vorkath", RAIDS).getKillCount());
	}

	@Test
	public void theSavedKeysAndJsonAreExactlyWhatTheTrackerHandsOut()
	{
		// the same play on two trackers: one saved through the store, one serialised directly as
		// before this change (Keys + saveData). Every key and value must be identical.
		Tracker viaStore = new Tracker(catalog);
		Tracker direct = new Tracker(catalog);
		store.load("A", viaStore);
		direct.setState(null);
		for (Tracker t : java.util.Arrays.asList(viaStore, direct))
		{
			vorkathKill(t, 7, true);
			coxRaid(t, 2);
		}
		store.save(viaStore);
		com.onrate.engine.tracking.SaveData d = direct.saveData(new Gson()::toJson);
		Map<String, String> expected = new HashMap<>();
		expected.put(Keys.DATA, d.progress);
		d.kills.forEach((boss, json) -> expected.put(Keys.killsKey(boss), json));
		d.raids.forEach((boss, json) -> expected.put(Keys.raidsKey(boss), json));
		assertEquals(expected, profiles.of("A"));

		// and it reads back
		Tracker loaded = reload("A");
		assertEquals(7, loaded.stats("Vorkath", RAIDS).getKillCount());
		assertEquals(1, loaded.history("Vorkath").size());
		assertEquals(25_000, loaded.raidRecords("Chambers of Xeric").get(0).getPersonalPoints());
	}

	@Test
	public void historyAndRaidsStaySeparateAndUntouchedByOtherChanges()
	{
		store.load("A", tracker);
		vorkathKill(tracker, 10, true);
		coxRaid(tracker, 3);
		store.save(tracker);
		String kills = profiles.of("A").get("kills.Vorkath");
		String raids = profiles.of("A").get("raids.ChambersofXeric");

		profiles.writes.clear();
		tracker.onChatMessage("Your Zulrah kill count is: <col=ff0000>5</col>.", NOW);
		store.save(tracker);
		assertFalse(profiles.writes.contains("A/kills.Vorkath"));
		assertFalse(profiles.writes.contains("A/raids.ChambersofXeric"));
		assertEquals(kills, profiles.of("A").get("kills.Vorkath"));
		assertEquals(raids, profiles.of("A").get("raids.ChambersofXeric"));
	}

	@Test
	public void aSeasonalProfileOfTheSameAccountNeverGetsTheMainProfilesData()
	{
		// RuneLite gives a Leagues world its own profile key for the same account
		store.load("main", tracker);
		vorkathKill(tracker, 100, true);
		store.save(tracker);
		Map<String, String> mainSaved = new HashMap<>(profiles.of("main"));
		profiles.writes.clear();

		profiles.active = "leagues";
		assertTrue(store.load("leagues", tracker));
		BossStats vorkath = tracker.stats("Vorkath", RAIDS);
		assertTrue(vorkath == null || vorkath.getKillCount() == 0);
		tracker.onChatMessage("Your Zulrah kill count is: <col=ff0000>3</col>.", NOW);
		store.save(tracker);

		assertOnlyWritesTo("leagues");
		assertEquals(mainSaved, profiles.of("main"));
		assertFalse(profiles.of("leagues").containsKey("kills.Vorkath"));
	}

	@Test
	public void unreadableDataIsBackedUpInTheProfileItCameFrom()
	{
		profiles.of("A").put("progress", "{not json");
		profiles.active = "B";
		store.load("A", tracker);
		assertEquals("{not json", profiles.of("A").get("progress.corrupt"));
		assertFalse(profiles.of("B").containsKey("progress.corrupt"));
	}
}

package com.onrate.store;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonNull;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import com.onrate.engine.data.BossCatalog;
import com.onrate.engine.data.Bundled;
import com.onrate.engine.stats.BossStats;
import com.onrate.engine.stats.RaidSettings;
import com.onrate.engine.tracking.KillEntry;
import com.onrate.engine.tracking.RaidRecord;
import com.onrate.engine.tracking.Tracker;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Before;
import org.junit.Test;

/**
 * Damaged saved data (audit F5): the readable parts load, the damaged parts are left out, the saved
 * text is kept as a backup first, and nothing that wasn't loaded is written over.
 */
public class ProfileRecoveryTest
{
	private static final RaidSettings RAIDS = raid -> 0.0;
	private static final long NOW = 1_000_000;
	private static final String DATA = Keys.DATA;
	private static final String VORKATH = Keys.killsKey("Vorkath");
	private static final String ZULRAH = Keys.killsKey("Zulrah");
	private static final String COX_KILLS = Keys.killsKey("Chambers of Xeric");
	private static final String COX = Keys.raidsKey("Chambers of Xeric");

	/** One profile's saved settings; keys listed in {@link #refuse} can't be written. */
	private static final class Profile implements ProfileStore.Backend
	{
		final Map<String, String> values = new HashMap<>();
		final Set<String> refuse = new HashSet<>();

		@Override
		public String get(String profile, String key)
		{
			return values.get(key);
		}

		@Override
		public void set(String profile, String key, String value)
		{
			if (refuse.contains(key))
			{
				throw new IllegalStateException("refused");
			}
			values.put(key, value);
		}

		@Override
		public void unset(String profile, String key)
		{
			if (refuse.contains(key))
			{
				throw new IllegalStateException("refused");
			}
			values.remove(key);
		}
	}

	private final Gson gson = new Gson();
	private BossCatalog catalog;
	private Profile profile;

	@Before
	public void setUp()
	{
		catalog = Bundled.catalog(gson);
		profile = new Profile();
		// a valid account: Vorkath with History and a head, Zulrah with History, a Chambers raid with points
		Tracker t = new Tracker(catalog);
		ProfileStore store = new ProfileStore(profile, gson);
		store.load("p", t);
		vorkath(t, 41, true);
		vorkath(t, 42, false);
		t.onChatMessage("Your Zulrah kill count is: <col=ff0000>50</col>.", NOW);
		t.onChatMessage("Your completed Chambers of Xeric count is: <col=ff0000>7</col>.", NOW + 5000);
		t.onRaidRecord(RaidRecord.cox(25_000, 50_000, 2), NOW + 5500);
		store.save(t);
		assertNotNull(profile.values.get(VORKATH));
		assertNotNull(profile.values.get(ZULRAH));
		assertNotNull(profile.values.get(COX));
	}

	private static void vorkath(Tracker t, int kc, boolean head)
	{
		t.onChatMessage("Your Vorkath kill count is: <col=ff0000>" + kc + "</col>.", NOW + kc * 1000L);
		if (head)
		{
			t.onLoot("Vorkath", 1, Collections.singletonList(new Tracker.LootItem("Vorkath's head", 1)), NOW + kc * 1000L);
		}
	}

	private JsonObject data()
	{
		return new JsonParser().parse(profile.values.get(DATA)).getAsJsonObject();
	}

	private JsonObject boss(JsonObject data, String name)
	{
		return data.getAsJsonObject("bosses").getAsJsonObject(name);
	}

	/** Saves hand-made JSON as is: unlike Gson, JsonElement.toString keeps the nulls. */
	private void put(String key, JsonElement json)
	{
		profile.values.put(key, json.toString());
	}

	private ProfileStore store;

	private Tracker load()
	{
		Tracker t = new Tracker(catalog);
		store = new ProfileStore(profile, gson);
		assertTrue(store.load("p", t));
		return t;
	}

	private static int kc(Tracker t, String boss)
	{
		BossStats s = t.stats(boss, RAIDS);
		return s == null ? 0 : s.getKillCount();
	}

	private static List<Integer> historyKcs(Tracker t, String boss)
	{
		List<Integer> kcs = new java.util.ArrayList<>();
		t.history(boss).forEach(h -> kcs.add(h.getKill().getKc()));
		return kcs;
	}

	@Test
	public void aNullBossEntryIsLeftOutAndTheRestLoads()
	{
		JsonObject d = data();
		d.getAsJsonObject("bosses").add("Vorkath", JsonNull.INSTANCE);
		put(DATA, d);
		String saved = profile.values.get(DATA);

		Tracker t = load();
		assertEquals(50, kc(t, "Zulrah"));
		assertEquals(7, kc(t, "Chambers of Xeric"));
		// Vorkath's History is under its own key and still loads
		assertEquals(2, historyKcs(t, "Vorkath").size());
		assertEquals("the saved text is kept first", saved, profile.values.get(DATA + Keys.CORRUPT_SUFFIX));

		// a normal save afterwards writes valid data that loads again, with the backup untouched
		t.onChatMessage("Your Zulrah kill count is: <col=ff0000>51</col>.", NOW);
		store.save(t);
		assertEquals(saved, profile.values.get(DATA + Keys.CORRUPT_SUFFIX));
		Tracker again = load();
		assertEquals(51, kc(again, "Zulrah"));
		assertEquals(2, historyKcs(again, "Vorkath").size());
	}

	@Test
	public void aNullHistoryEntryIsLeftOutAndTheOtherKillsStay()
	{
		JsonArray kills = new JsonParser().parse(profile.values.get(VORKATH)).getAsJsonArray();
		int valid = kills.size();
		kills.add(JsonNull.INSTANCE);
		put(VORKATH, kills);
		String saved = profile.values.get(VORKATH);

		Tracker t = load();
		assertEquals(valid, historyKcs(t, "Vorkath").size());
		assertEquals(saved, profile.values.get(VORKATH + Keys.CORRUPT_SUFFIX));

		// the next kill saves every kill that was readable, plus the new one
		vorkath(t, 43, false);
		store.save(t);
		List<KillEntry> persisted = gson.fromJson(profile.values.get(VORKATH),
			new com.google.gson.reflect.TypeToken<List<KillEntry>>() { }.getType());
		assertEquals(valid + 1, persisted.size());
		assertFalse(persisted.contains(null));
